                                                 '  outputs.length = 0;\n'
                                                 "  outputs.push({ id: 'edit_1', kind: 'hero', outcome: "
                                                 "outcomes[0] || 'lifestyle', camera: co ? co.value : '', "
                                                 "light: lo ? LIGHT_KEYS[lo.value] : '', light_label: lo ? "
                                                 "lo.value : '', from: 'base_' + editBase.output_id,\n"
                                                 "    edit_from_result: true, edit_changes: [co ? 'camera' : "
                                                 "'', lo ? 'light' : '', 'edit'].filter(Boolean), "
                                                 'edit_options: editOptions.slice() });\n'
                                                 "  if (dropped.length) notApplied.push('This edit starts "
                                                 "from the approved image ' + editBase.output_id + ', so it "
