                                                 '    const c = m ? Number(m[1]) : 0;\n'
                                                 '    if (m && c > 0 && c < 200) inventory.push({ item: '
                                                 'clean(m[2], 60), count: c });\n'
                                                 '    else notApplied.push(\'Piece count not understood: "\' '
                                                 '+ part + \'". Write one piece per line as "number piece", '
                                                 'for example "2 chairs".\');\n'
                                                 '  }\n'
                                                 '}\n'
                                                 'const exclusions = list(it.exclusions || it.mustNot || '
                                                 'meta.must_not || meta.mustNot, 80);\n'
