                                                 'outcomesHuman(scope.outcomes);\n'
                                                 'function outcomesHuman(v) { return (Array.isArray(v) ? v : '
                                                 '[]).some(x => /human lifestyle/i.test(String(x))); }\n'
                                                 "const people = peopleAsked ? 'one' : 'none';\n"
                                                 '// Fields that A7 does not use are listed back to the '
