                                                 'const typeWords = [brief.product_type, '
                                                 "brief.category].filter(Boolean).join(' ').toLowerCase();\n"
                                                 'const singleItemType = Boolean(brief.product_type) && '
                                                 '!/(\\bset\\b|\\bsuite\\b|\\bcollection\\b|\\bwith\\b|\\band\\b|\\bpieces?\\b|\\bpcs\\b|\\+|&|\\d)/i.test(typeWords);\n'
                                                 'const esc = w => w.replace(/[.*+?^${}()|[\\]\\\\]/g, '
                                                 "'\\\\$&');\n"
                                                 'const writtenSays = w => {\n'
