                                                 'if (ask.length) {\n'
                                                 "  const list = ask.join(', ');\n"
                                                 "  critical.push({ what: 'set_membership', who: 'client', "
                                                 "why: 'No piece count was given, nothing written settles "
                                                 'it, and it is not confirmed whether these belong to the '
                                                 "product: ' + list + '.',\n"
                                                 "    question: 'Please confirm which pieces belong to the "
                                                 "product. We were not sure about: ' + list + '.' });\n"
                                                 '}\n'
                                                 '\n'
                                                 '// Colour: the photo decides colour; swatches and other '
                                                 'colourways are options, kept apart from the photographed '
                                                 'colour.\n'
                                                 'const swatches = arr(eye && eye.signs).filter(x => '
                                                 "String(x.sign).toLowerCase() === 'swatch');\n"
                                                 'const swatchColours = arr(eye && eye.swatch_colours).map(x '
                                                 '=> String(x).slice(0, 60)).filter(Boolean);\n'
                                                 'if (swatches.length || swatchColours.length) '
