                                                 'const s = $input.first().json;\n'
                                                 'const crit = s.critical || [];\n'
                                                 "const c = crit.find(x => x.who === 'owner') || crit[0] || "
                                                 "{ what: 'unknown', why: 'A required fact is missing.' };\n"
                                                 "const forOwner = c.who === 'owner';\n"
                                                 'const v = (s.brief && s.brief.version) || 1;\n'
                                                 "return [{ json: { ...s, status: 'hold', hold_for: forOwner "
                                                 "? 'owner' : 'client', stage: s.plan_stage ? '03 Retrieve & "
                                                 "style' : (s.contract ? '02 Compile scope' : '01 Intake & "
                                                 "observe'), hold_reason: c.why,\n"
                                                 "  client_question: forOwner ? '' : (s.client_question || "
                                                 "''),\n"
                                                 '  next: forOwner\n'
                                                 "    ? (s.plan_stage ? 'Waiting for the owner: the plan "
                                                 'could not be checked or still fails its check, and nothing '
                                                 'goes forward unchecked. The client was not asked anything. '
                                                 "No paid image was made.' : 'Waiting for the owner: run the "
