                                                 'const version = prev + 1;\n'
                                                 'const guidance = '
                                                 '{"baseline_id":"a7-guidance-2026-10-17-v1","sha256":"d173694b13343173ba2a50e60c7797d9832af902a4555dc5a21bc6c4564455f9","reviewed_on":"2026-10-17","compliance":"partial","requirements":["A01","A02","A03","A04","A05","A06","A07","A08","A09","A10","A11","A12","A13","A14","A15","A16","A17","A18","A19","A20","A21","A22","A23","A24","A25","A26"],"owner_overrides":["Owner-only '
