                                                 "  add('compile', '04', 13, s.contract_stamp || '', { "
                                                 'orders: g4.orders, settings_date: g4.settings_date, notes: '
                                                 'g4.notes });\n'
                                                 "  if (g4.operation) add('operation', '04', 15, "
                                                 'g4.operation.operation_key, { ...g4.operation, model: '
                                                 'g4.model, reserve_basis: g4.reserve_basis, guard: '
                                                 'g4.guard, paid_call: g4.paid_call });\n'
                                                 "  if (g4.candidate) add('candidate', '04', 15, "
                                                 'g4.candidate.sha256, g4.candidate);\n'
                                                 '}\n'
                                                 '// Stage 05 events (15 Oct 2026): the review, a repair '
                                                 "order, the go 2 ticket and the owner's go 2 answer. A "
                                                 'review is never an approval.\n'
                                                 "const in05 = String(s.stage || '').indexOf('05') === 0;\n"
                                                 "if (in05 && s.review) add('review', '05', 16, "
                                                 "(s.review.candidate && s.review.candidate.sha256) || '', "
                                                 "s.review, s.review.readers || 'code');\n"
                                                 "if (s.status === 'repair_ordered' && s.repair_orders) "
                                                 "add('repair_order', '05', 16, s.contract_stamp || '', "
                                                 "s.repair_orders, s.go2_route === 'repair' ? 'owner' : "
                                                 "'code');\n"
                                                 "if (s.go2 && s.status === 'awaiting_go_2') "
                                                 "add('go2_ticket', '05', 17, s.contract_stamp || '', "
                                                 's.go2);\n'
                                                 "if (s.go2_last) add('go2_decision', '05', 17, "
                                                 "s.contract_stamp || '', s.go2_last, s.go2_last.by || "
                                                 "'owner');\n"
                                                 '// Stage 06 events (16 Oct 2026): the delivery package and '
                                                 'its identity vault entry. A package is never an approval: '
                                                 "approval is the owner's go 2.\n"
                                                 "const in06 = String(s.stage || '').indexOf('06') === 0;\n"
                                                 "if (in06 && s.package) add('package', '06', 18, "
                                                 "s.package.manifest_sha256 || '', s.package);\n"
                                                 "if (in06 && s.identity) add('identity', '06', 18, "
                                                 "s.identity.identity_key || '', s.identity);\n"
                                                 '// Stage 07 events (16 Oct 2026): the scene ticket (which '
                                                 'scene, which phase, presets, the live prop check and the '
                                                 'images sent).\n'
                                                 "const in07 = String(s.stage || '').indexOf('07') === 0;\n"
                                                 '// Edit phase 2.4 (19 Oct 2026): the approved image an '
                                                 'edit starts from, as E2 checked it against the earlier '
                                                 'run.\n'
                                                 "if (s.edit_base) add('edit_base', '07', 19, "
