                                                 '(s.scenes && s.scenes.queue) || [] });\n'
                                                 '// Step 20 (16 Oct 2026): the delivery files of an '
                                                 'approved scene (jpg and webp at its own shape, short side '
                                                 '1125 px, and a manifest).\n'
                                                 "if (in07 && s.scene_files) add('scene_files', '07', 20, "
                                                 "s.scene_files.manifest_sha256 || '', s.scene_files);\n"
                                                 "if (s.package_release) add('package_release', in06 ? '06' "
                                                 ": '07', in06 ? 18 : 19, s.contract_stamp || '', "
                                                 's.package_release);\n'
                                                 "const st = in07 ? '07' : in06 ? '06' : in05 ? '05' : "
                                                 "(s.stage04 ? '04' : (s.plan_stage ? '03' : (s.contract ? "
                                                 "'02' : '01')));\n"
                                                 "const sp = in07 ? (s.scene_files || (s.status === 'hold' "
                                                 '&& s.hold_step === 20) ? 20 : 19) : in06 ? 18 : in05 ? '
                                                 "(s.status === 'hold' ? (s.hold_step || 16) : (s.status === "
                                                 "'awaiting_go_2' || s.go2_last ? 17 : 16)) : s.stage04 ? "
                                                 "(s.status === 'hold' ? (s.hold_step || 15) : 15) : "
                                                 "(s.plan_stage ? (s.status === 'hold' ? (s.hold_step || 10) "
                                                 ': 12) : (s.contract ? 9 : 5));\n'
                                                 '// P1.8 (16 Oct 2026): the token counts of each text and '
                                                 'vision call since the last vault write. Always written, '
                                                 'whatever vault_only says.\n'
                                                 'for (const c of (Array.isArray(s.text_calls_new) ? '
                                                 's.text_calls_new : [])) ev.push({ ...base, kind: '
                                                 "'text_call', stage: st, step: Number(c.step) || sp, ref: "
                                                 "String(c.node || ''), payload: JSON.stringify(c).slice(0, "
                                                 "60000), actor: String(c.model || 'code') });\n"
                                                 "if (s.status === 'hold') add('hold', st, sp, '', { reason: "
                                                 "s.hold_reason, hold_for: s.hold_for || 'client', question: "
                                                 's.client_question, critical: s.critical });\n'
                                                 "add('status', st, sp, '', { status: s.status, next: s.next "
                                                 '});\n'
                                                 'return [{ json: { ...s, text_calls_new: [], events: ev,\n'
                                                 '  row: { status: s.status, stage: s.stage, hold_reason: '
                                                 "s.hold_reason || '', client_question: s.client_question || "
                                                 "'',\n"
                                                 '    contract_version: s.contract_version || 0, '
                                                 "contract_stamp: s.contract_stamp || '',\n"
                                                 '    required_outputs: JSON.stringify((s.outputs || '
