                                                 "missingPicks.map(c => c.sku + ' ' + c.name).join(', '));\n"
                                                 '// Styling engine per scene shot (stylist skill). Tags '
                                                 'that are not confirmed stay empty, so pillars can be '
                                                 '"unknown".\n'
                                                 "const BASIS_OK = ['vendor_stated', 'catalogue_stated', "
                                                 "'observed_in_photo', 'estimated_from_photo'];\n"
                                                 'const heroCat = txt(st.brief.product_type || '
                                                 "st.observation.category_seen || 'product', "
                                                 '80).toLowerCase();\n'
                                                 'for (const shot of scene) {\n'
                                                 '  if (shot.plan_ok) continue;\n'
                                                 '  const p = shot.plan;\n'
                                                 "  const hero = { id: 'product', name: "
                                                 "st.brief.product_type || 'the product', role: 'hero', "
                                                 'category: heroCat };\n'
                                                 '  const pieces = [hero];\n'
                                                 '  for (const m of p.midas_pieces) {\n'
                                                 '    const c = bySku[m.sku]; const t = c.tags || {};\n'
                                                 "    const piece = { id: 'sku-' + c.sku, name: c.name || "
                                                 "c.kind, role: 'midas_support', category: String(c.kind || "
