                                                 "st.go2.candidate.link : '';\n"
                                                 '// Stage 07 (16 Oct 2026): the same go 2 answers a placed '
                                                 'scene. Its approval is recorded per scene; the white '
                                                 "master's stays as it was.\n"
                                                 'const isScene = Boolean(st.go2 && st.go2.kind === '
                                                 "'scene');\n"
                                                 "const thing = isScene ? 'scene ' + st.go2.output_id : "
                                                 "'white master';\n"
                                                 'function hold(why) {\n'
