                                                 "st.hold_reason = why; st.client_question = ''; "
                                                 'st.hold_step = 17;\n'
                                                 "  st.critical = arr(st.critical).concat([{ what: 'go_2', "
                                                 "who: 'owner', why }]);\n"
                                                 "  st.next = 'Waiting for the owner: ' + why + ' Nothing is "
                                                 "sent again automatically.' + link;\n"
                                                 '}\n'
                                                 'const allowed = Array.isArray(st.go2_allowed) && '
                                                 "st.go2_allowed.length ? st.go2_allowed : ['approve', "
                                                 "'repair', 'stop'];\n"
                                                 "const WITHOUT = 'approved by owner without an automated "
                                                 "review';\n"
                                                 '// Owner, 16 Oct 2026, 19:26: a white master approved by '
                                                 'eye is shown as "Approved by the studio · not reviewed" in '
                                                 'the manifest and the\n'
                                                 "// owner's view. The record above (approval_kind) stays as "
                                                 'the audit wording.\n'
                                                 "const SHOWN_BY_EYE = 'Approved by the studio · not "
