                                                 '  const unknowns = arr(r.unsure).map(x => clean(x.evidence '
                                                 '|| x.name || x, 300));\n'
                                                 '  return { classification: passed ? '
                                                 "'reviewed_owner_approved' : 'owner_exception',\n"
                                                 "    label: passed ? 'Owner approved · review passed' : "
                                                 "(without ? SHOWN_BY_EYE : 'Owner approved · review ' + "
                                                 "clean(bound ? r.result : 'not bound to this candidate', "
                                                 '80)),\n'
                                                 '    catalogue_eligible: passed && Boolean(st.contract && '
                                                 'st.contract.guidance && st.contract.guidance.compliance '
                                                 "=== 'verified'), allowed_use: passed ? 'Owner-approved "
                                                 'reviewed output; full guidance qualification and package '
                                                 "completion are checked separately.' : 'Owner exception "
                                                 "only; not a verified catalogue release.',\n"
                                                 '    run_id: st.run_id, output_id: st.go2.output_id, '
                                                 "candidate_sha256: c.sha256 || '', contract_stamp: "
                                                 "st.contract_stamp || '',\n"
                                                 '    guidance: st.contract && st.contract.guidance || null, '
                                                 "guidance_compliance: 'Not certified: open requirements "
                                                 "remain in the versioned guidance checklist.', "
                                                 "review_bound: bound, review_result: without ? 'not "
                                                 "reviewed' : (bound ? r.result : 'unknown'), defects, "
