                                                 '    if (b.length > 24 && b.readUInt32BE(0) === 0x89504e47) '
                                                 'return [b.readUInt32BE(16), b.readUInt32BE(20)];\n'
                                                 '    if (b.length > 4 && b[0] === 0xff && b[1] === 0xd8) {\n'
                                                 '      let p = 2;\n'
                                                 '      while (p + 9 < b.length) {\n'
                                                 '        if (b[p] !== 0xff) { p++; continue; }\n'
                                                 '        const mk = b[p + 1];\n'
                                                 '        if (mk >= 0xc0 && mk <= 0xcf && [0xc4, 0xc8, '
                                                 '0xcc].indexOf(mk) === -1) return [b.readUInt16BE(p + 7), '
                                                 'b.readUInt16BE(p + 5)];\n'
                                                 '        p += 2 + b.readUInt16BE(p + 2);\n'
                                                 '      }\n'
                                                 '    }\n'
                                                 "    if (b.length > 30 && b.toString('ascii', 0, 4) === "
                                                 "'RIFF' && b.toString('ascii', 8, 12) === 'WEBP') {\n"
                                                 "      const f = b.toString('ascii', 12, 16);\n"
                                                 "      if (f === 'VP8X') return [1 + b.readUIntLE(24, 3), 1 "
                                                 '+ b.readUIntLE(27, 3)];\n'
                                                 "      if (f === 'VP8 ') return [b.readUInt16LE(26) & "
                                                 '0x3fff, b.readUInt16LE(28) & 0x3fff];\n'
                                                 "      if (f === 'VP8L') { const v = b.readUInt32LE(21); "
                                                 'return [1 + (v & 0x3fff), 1 + ((v >> 14) & 0x3fff)]; }\n'
                                                 '    }\n'
                                                 '  } catch (e) { /* not read */ }\n'
                                                 '  return null;\n'
                                                 '}\n'
                                                 '// 1. Identity vault: earlier packages of this product.\n'
                                                 "const idItems = $('18b Load identity').all().map(i => "
                                                 'i.json);\n'
                                                 'const idOk = idItems.length > 0 && idItems.every(r => r && '
                                                 '!r.error && (Object.keys(r).length === 0 || '
                                                 '(r.identity_key && r.id !== undefined)));\n'
