                                                 'if(u.cache_creation_input_tokens!==undefined&&u.cache_creation_input_tokens!==0)return '
                                                 'null;\n'
                                                 '  '
                                                 'if(u.cache_read_input_tokens!==undefined&&!integer(u.cache_read_input_tokens))return '
                                                 'null;\n'
                                                 '  '
                                                 'input=u.input_tokens+(u.cache_read_input_tokens??0);output=u.output_tokens;\n'
                                                 ' }\n'
                                                 ' '
                                                 'if(!integer(input)||!integer(output)||input+output===0)return '
                                                 'null;\n'
                                                 ' return {input,output};\n'
                                                 '}\n'
                                                 'function permissionGranted(response) {\n'
                                                 ' const body=response?.body;\n'
