                                                 "if(kind==='openai'&&u&&integer(u.prompt_tokens)&&integer(u.completion_tokens)) "
                                                 '{\n'
                                                 '   return '
                                                 'u.prompt_tokens+u.completion_tokens>0?{input:u.prompt_tokens,output:u.completion_tokens}:null;\n'
                                                 '  }\n'
                                                 '  '
                                                 'if(!u||!integer(u.input_tokens)||!integer(u.output_tokens))return '
                                                 'null;\n'
                                                 '  // Native A7 calls do not request cache writes. '
                                                 'Unexpected write-priced tokens\n'
                                                 '  // need billing reconciliation, not an assumed '
                                                 'standard-input charge.\n'
                                                 '  '
                                                 'if(u.cache_creation_input_tokens!==undefined&&u.cache_creation_input_tokens!==0)return '
                                                 'null;\n'
                                                 '  '
                                                 'if(u.cache_read_input_tokens!==undefined&&!integer(u.cache_read_input_tokens))return '
                                                 'null;\n'
                                                 '  '
                                                 'input=u.input_tokens+(u.cache_read_input_tokens??0);output=u.output_tokens;\n'
                                                 ' }\n'
                                                 ' '
                                                 'if(!integer(input)||!integer(output)||input+output===0)return '
                                                 'null;\n'
                                                 ' return {input,output};\n'
                                                 '}\n'
                                                 'function permissionGranted(response) {\n'
                                                 ' const body=response?.body;\n'
                                                 ' return response?.statusCode===200&&body?.send===true&&\n'
                                                 '  '
                                                 "/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/.test(body.permit||'')&&\n"
                                                 '  '
                                                 'Number.isSafeInteger(body.reservedMicroUsd)&&body.reservedMicroUsd>0;\n'
                                                 '}\n'
                                                 'function settlementCompleted(response) {\n'
                                                 ' return '
                                                 "response?.statusCode===200&&response.body?.recorded===true&&response.body?.status==='completed';\n"
                                                 '}\n'
                                                 'function budgetHold(state,stage,nodeName,reason) {\n'
                                                 ' return '
                                                 "{...state,status:'hold',stage,hold_for:'owner',hold_step:parseInt(nodeName,10)||1,\n"
                                                 "  hold_reason:'Paid processing paused: '+reason,\n"
                                                 "  client_question:'Review the spending ledger before "
