                                                      "if(pkg&&pkg.outcome==='white_package_ready'&&m&&rel&&rel.run_id===out.runId&&rel.output_id==='white_master'&&['reviewed_owner_approved','owner_exception'].includes(rel.classification)&&/^[A-Za-z0-9_-]{10,200}$/.test(String(m.drive_file_id||''))&&/^[a-f0-9]{64}$/.test(String(m.sha256||''))&&rel.candidate_sha256===m.sha256)\n"
                                                      ' '
                                                      "results.push({outputId:'white_master',kind:'white',driveFileId:m.drive_file_id,sha256:m.sha256,px:typeof "
                                                      "m.px==='string'&&/^\\d{2,5}x\\d{2,5}$/.test(m.px)?m.px:null,fileName:String(m.file_name||'white_master').replace(/https?:\\/\\/\\S+/gi,'').slice(0,160),reviewed:rel.classification==='reviewed_owner_approved',approvedAt:typeof "
