                             {'id': '483f1f6e-e0ad-44d9-8941-42d8f20dc8ca',
                              'name': 'Budget · 09 · Receipt',
                              'type': 'n8n-nodes-base.code',
                              'typeVersion': 2,
                              'position': [3216, 720],
                              'parameters': {'jsCode': 'function answerEnvelope(raw){\n'
                                                       ' if(raw?.statusCode&&raw.statusCode!==200)return '
                                                       "{error:'provider_http_error'};const "
                                                       'r=raw?.body||raw||{};return '
                                                       "Object.fromEntries(['id','status','output','content','candidates','response','usage','usageMetadata','stop_reason','steps','output_image','finishReason','error'].filter(k=>r[k]!==undefined).map(k=>[k,r[k]]));\n"
                                                       '}\n'
                                                       'function operationSlot(state,nodeName,input={}) {\n'
                                                       ' const stage04=input.s04||state.stage04||{};\n'
                                                       ' const current=state.scenes?.current||{};\n'
                                                       ' const '
                                                       "output=input.rv?.output_id||stage04.dispatch?.output_id||stage04.operation?.output_id||current.output_id||'job';\n"
                                                       ' const '
                                                       'slot={client:state.client_run_id,run:state.run_id,node:nodeName,output,\n'
                                                       '  '
                                                       'attempt:input.rv?.attempt??stage04.dispatch?.attempt??stage04.operation?.attempt??current.attempt??0,\n'
                                                       '  '
                                                       "phase:current.phase||'',go1:state.go1_rounds||0,go2:state.go2_round||0,\n"
                                                       '  '
                                                       'plan:state.plan_round||0,rewrite:state.rewrites_used||0,review:state.review_again_count||0};\n'
                                                       ' '
                                                       "if(!/^owner-[a-f0-9-]{36}$/.test(slot.client||'')||!slot.run||typeof "
                                                       "slot.run!=='string')throw "
                                                       "Error('budget_identity_missing');\n"
                                                       ' // Slot identity intentionally excludes the request '
                                                       'hash. A changed request in the\n'
                                                       ' // same slot must conflict, rather than obtain '
                                                       'another permission to spend.\n'
                                                       ' return slot;\n'
                                                       '}\n'
                                                       'function providerUsage(response,kind) {\n'
                                                       ' const integer=v=>Number.isSafeInteger(v)&&v>=0;\n'
                                                       ' let input,output;\n'
                                                       ' const r=response?.body||response;\n'
                                                       ' if(!r||r.error)return null;\n'
                                                       " if(kind==='interaction') {\n"
                                                       '  const u=r.s04?.receipt?.usage||r.usage;\n'
                                                       '  '
                                                       'if(!u||!integer(u.total_input_tokens)||!integer(u.total_output_tokens)||!integer(u.total_thought_tokens))return '
                                                       'null;\n'
                                                       '  // Interactions reports thought tokens separately; '
                                                       'they are billable output.\n'
                                                       '  '
                                                       'input=u.total_input_tokens;output=u.total_output_tokens+u.total_thought_tokens;\n'
                                                       '  '
                                                       'if(u.total_tool_use_tokens!==undefined&&u.total_tool_use_tokens!==0)return '
                                                       'null;\n'
                                                       " }else if(kind==='gemini') {\n"
                                                       '  const '
                                                       'u=r.usageMetadata||r.response?.usageMetadata;\n'
                                                       '  '
                                                       'if(!u||!integer(u.promptTokenCount)||!integer(u.candidatesTokenCount))return '
                                                       'null;\n'
                                                       '  '
                                                       'if(u.thoughtsTokenCount!==undefined&&!integer(u.thoughtsTokenCount))return '
                                                       'null;\n'
                                                       '  '
                                                       'input=u.promptTokenCount;output=u.candidatesTokenCount+(u.thoughtsTokenCount??0);\n'
                                                       ' }else {\n'
                                                       '  const u=r.usage||r.response?.usage;\n'
                                                       '  '
                                                       "if(kind==='openai'&&u&&integer(u.prompt_tokens)&&integer(u.completion_tokens)) "
                                                       '{\n'
                                                       '   return '
                                                       'u.prompt_tokens+u.completion_tokens>0?{input:u.prompt_tokens,output:u.completion_tokens}:null;\n'
                                                       '  }\n'
                                                       '  '
                                                       'if(!u||!integer(u.input_tokens)||!integer(u.output_tokens))return '
                                                       'null;\n'
                                                       '  // Native A7 calls do not request cache writes. '
                                                       'Unexpected write-priced tokens\n'
                                                       '  // need billing reconciliation, not an assumed '
                                                       'standard-input charge.\n'
                                                       '  '
                                                       'if(u.cache_creation_input_tokens!==undefined&&u.cache_creation_input_tokens!==0)return '
                                                       'null;\n'
                                                       '  '
                                                       'if(u.cache_read_input_tokens!==undefined&&!integer(u.cache_read_input_tokens))return '
                                                       'null;\n'
                                                       '  '
                                                       'input=u.input_tokens+(u.cache_read_input_tokens??0);output=u.output_tokens;\n'
                                                       ' }\n'
                                                       ' '
                                                       'if(!integer(input)||!integer(output)||input+output===0)return '
                                                       'null;\n'
                                                       ' return {input,output};\n'
                                                       '}\n'
                                                       'function permissionGranted(response) {\n'
                                                       ' const body=response?.body;\n'
                                                       ' return '
                                                       'response?.statusCode===200&&body?.send===true&&\n'
                                                       '  '
                                                       "/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/.test(body.permit||'')&&\n"
                                                       '  '
                                                       'Number.isSafeInteger(body.reservedMicroUsd)&&body.reservedMicroUsd>0;\n'
                                                       '}\n'
                                                       'function settlementCompleted(response) {\n'
                                                       ' return '
                                                       "response?.statusCode===200&&response.body?.recorded===true&&response.body?.status==='completed';\n"
                                                       '}\n'
                                                       'function budgetHold(state,stage,nodeName,reason) {\n'
                                                       ' return '
                                                       "{...state,status:'hold',stage,hold_for:'owner',hold_step:parseInt(nodeName,10)||1,\n"
                                                       "  hold_reason:'Paid processing paused: '+reason,\n"
                                                       "  client_question:'Review the spending ledger before "
                                                       'continuing. An uncertain provider call must not be '
                                                       "sent again.',\n"
                                                       "  next:'Owner checks budget and provider "
                                                       "receipt',vault_only:['hold','status'],\n"
                                                       '  '
                                                       'budget_hold:{node:nodeName,reason,automatic_resend:false},\n'
                                                       '  '
                                                       "critical:[...(state.critical||[]),{what:'budget',who:'owner',why:reason}],\n"
                                                       '  '
                                                       "trail:[...(state.trail||[]),{step:parseInt(nodeName,10)||1,name:'Budget "
                                                       "guard',note:reason,at:new Date().toISOString()}]};\n"
                                                       '}\n'
                                                       'const it=$input.first();\n'
                                                       'let t;try{t=$("Budget · 09 · '
                                                       'Ticket").first().json;}catch{throw '
                                                       "Error('budget_ticket_missing');}\n"
                                                       'const reservation=$("Budget · 09 · '
                                                       'Reserve").first().json;\n'
                                                       'if(!permissionGranted(reservation))throw '
                                                       "Error('budget_permit_missing');\n"
                                                       'const usage=providerUsage(it.json,"openai");\n'
                                                       'const '
                                                       "candidateRef=it.json.s04?.receipt?.provider_request_id||it.json.body?.id||it.json.id||it.json.response?.id||'';\n"
                                                       'const receiptRef=typeof '
                                                       "candidateRef==='string'&&/^[a-zA-Z0-9_.:-]{1,180}$/.test(candidateRef)?candidateRef:'answer:'+require('crypto').createHash('sha256').update(JSON.stringify(answerEnvelope(it.json))).digest('hex');\n"
                                                       'return '
                                                       '[{json:{budgetRequest:{clientId:t.budgetRequest.clientId,operationKey:t.budgetRequest.operationKey,permit:reservation.body.permit,usage,receiptRef,checkpointRequired:!!usage,...((()=>{const '
                                                       'a=answerEnvelope(it.json);return '
                                                       '!a.error&&(a.output||a.content||a.candidates||a.response?.candidates||a.steps||a.output_image)?{completeAnswer:a}:{}})())},original:it.json},binary:it.binary}];'}},
