                                 {'id': 'c84b3c7c-5795-498e-bdf2-8726217d8907',
                                  'name': 'R9 Pre-order hand rows',
                                  'type': 'n8n-nodes-base.code',
                                  'typeVersion': 2,
                                  'position': [880, 300],
                                  'parameters': {'jsCode': '// Catalogue refresh · R9 Pre-order hand rows '
                                                           '(17 Oct 2026, owner decision 00:36). Code only.\n'
                                                           '// Lists the active hand rows (notes do not '
                                                           'start "Imported") marked "Pre-Order" whose page '
                                                           'is on the Midas Kuwait English site,\n'
                                                           '// so "R10 Read product page" can read each '
                                                           "one's own page (one page every 10 s, "
                                                           'robots.txt).\n'
                                                           '// A row "R4 Plan rows" already decided from the '
                                                           'listing is still read: the product page is '
                                                           'recorded as evidence only.\n'
                                                           "const rows = $('R3 Load catalogue').all().map(i "
                                                           '=> i.json || {}).filter(r => r && r.sku);\n'
                                                           'const isPre = v => '
                                                           '/^\\s*pre[-\\s]?order\\s*$/i.test(String(v || '
                                                           "''));\n"
                                                           'const out = rows\n'
                                                           '  .filter(r => !/^Imported /.test(String(r.notes '
                                                           "|| '')) && r.active !== false && "
                                                           'isPre(r.availability))\n'
                                                           '  .filter(r => '
                                                           '/^https:\\/\\/(www\\.)?midasfurniture\\.com\\/en\\/[^?#]+\\.html$/i.test(String(r.url '
                                                           "|| '')))\n"
                                                           '  .map(r => ({ json: { row_id: r.id, sku: '
                                                           "String(r.sku), name: r.name || '', url: r.url, "
                                                           'availability: r.availability } }));\n'
                                                           'return out;\n'}},
                                 {'id': '1ea0d17f-6453-4dad-812c-195db4bd0da0',
                                  'name': 'R9b Wait 11 s',
                                  'type': 'n8n-nodes-base.wait',
                                  'typeVersion': 1.1,
                                  'position': [1100, 300],
                                  'parameters': {'amount': 11, 'resume': 'timeInterval', 'unit': 'seconds'},
                                  'notes': 'robots.txt: 10 s between Midas pages (after the last listing '
                                           'page).',
                                  'webhookId': '92003bdf-ddc2-442f-8511-86fd9c840f3e'},
