                  "const AMBIENCE_MENU = ['Calm / Restorative', 'Warm / Welcoming', 'Elegant / Formal', "
                  "'Airy / Fresh',\n"
                  "  'Intimate / Cozy', 'Expressive / Vibrant'];\n"
                  "const PRESET_MENU = ['Daylight overview', 'Editorial hero', 'Golden-hour atmosphere', "
                  "'Evening comfort'];\n"
                  '\n'
                  "const ROLES = ['hero', 'midas_support', 'generic_context'];\n"
                  "const WEIGHTS_ = ['light', 'medium', 'heavy'];\n"
                  "const SILS = ['angular', 'curved', 'mixed'];\n"
                  "const FAMILIES = ['wood', 'metal', 'stone', 'glass', 'fabric', 'leather', 'other'];\n"
                  "const UNDERTONES = ['warm', 'cool', 'neutral'];\n"
                  "const TEXTURES = ['smooth', 'medium', 'rough'];\n"
                  "const PALETTE = ['dominant_60', 'secondary_30', 'accent_10'];\n"
                  "const AVAIL = ['in_stock', 'pre_order', 'out_of_stock', 'not_confirmed'];\n"
                  "const BASIS = ['vendor_stated', 'catalogue_stated', 'observed_in_photo', "
                  "'estimated_from_photo'];\n"
                  "const OUTPUTS = ['white_background', 'lifestyle', 'website_package'];\n"
                  "const DESCRIPTIVE = ['style', 'visual_weight', 'silhouette', 'finishes', 'texture', "
                  "'colour_hex', 'dimensions_cm'];\n"
                  "const PILLARS = ['scale_proportion', 'silhouette_lines', 'materials_finishes', "
                  "'colour_distribution',\n"
                  "  'texture_contrast', 'function_practicality', 'focal_point', 'style_cohesion'];\n"
                  'const DEFAULT_W = { scale_proportion: 20, silhouette_lines: 15, materials_finishes: 15, '
                  'colour_distribution: 15,\n'
                  '  texture_contrast: 10, function_practicality: 10, focal_point: 10, style_cohesion: 5 };\n'
                  'const PROFILES = {\n'
                  '  balanced: DEFAULT_W,\n'
                  '  strict_match: { style_cohesion: 30, materials_finishes: 25, silhouette_lines: 10, '
                  'scale_proportion: 15,\n'
                  '    colour_distribution: 10, texture_contrast: 5, function_practicality: 3, focal_point: '
                  '2 },\n'
                  '  eclectic_designer: { style_cohesion: 3, scale_proportion: 25, silhouette_lines: 25, '
                  'texture_contrast: 17,\n'
                  '    colour_distribution: 10, materials_finishes: 10, function_practicality: 5, '
                  'focal_point: 5 },\n'
                  '};\n'
                  'const VALUE = { pass: 1, partial: 0.5, fail: 0 };\n'
                  'const MIN_COVERAGE = 0.6;\n'
                  'const TABLE_TO_SOFA = [0.5, 0.75];\n'
                  "const SCORE_LABEL = 'Styling fit (rule-based judgement, not a measurement; not an "
                  "approval)';\n"
                  '\n'
                  'const isNil = (v) => v === null || v === undefined;\n'
                  'const filled = (v) => (Array.isArray(v) ? v.length > 0 : !isNil(v));\n'
                  '\n'
                  '// ---------------------------------------------------------------- validation\n'
                  'function validate(req) {\n'
                  '  const e = [];\n'
                  '  const oneOf = (v, list, where) => { if (!isNil(v) && !list.includes(v)) '
                  'e.push(`${where}: ${JSON.stringify(v)} is not allowed`); };\n'
                  "  if (!req || typeof req !== 'object') return ['request must be an object'];\n"
                  '  const pieces = Array.isArray(req.pieces) ? req.pieces : [];\n'
                  "  if (pieces.length < 2) e.push('pieces: at least 2 are required');\n"
                  '  const ids = pieces.map((p) => p && p.id);\n'
                  "  if (new Set(ids).size !== ids.length) e.push('piece ids must be unique (a piece shown "
                  "twice in a photo is one piece)');\n"
                  "  if (pieces.filter((p) => p && p.role === 'hero').length !== 1) e.push('exactly one hero "
                  "piece is required');\n"
                  '  pieces.forEach((p, i) => {\n'
                  "    const at = `pieces[${i}]${p && p.id ? ` (${p.id})` : ''}`;\n"
                  "    if (!p || typeof p !== 'object') { e.push(`${at}: must be an object`); return; }\n"
                  "    for (const f of ['id', 'name', 'category']) if (typeof p[f] !== 'string' || !p[f]) "
                  'e.push(`${at}: ${f} is required`);\n'
                  '    oneOf(p.role, ROLES, `${at}.role`); if (isNil(p.role)) e.push(`${at}: role is '
                  'required`);\n'
                  '    oneOf(p.availability, AVAIL, `${at}.availability`);\n'
                  '    oneOf(p.visual_weight, WEIGHTS_, `${at}.visual_weight`);\n'
                  '    oneOf(p.silhouette, SILS, `${at}.silhouette`);\n'
                  '    oneOf(p.texture, TEXTURES, `${at}.texture`);\n'
                  '    if (!isNil(p.style) && !STYLE_MENU.includes(p.style)) e.push(`${at}.style must be on '
                  'the style menu`);\n'
                  '    (p.finishes || []).forEach((f, j) => {\n'
                  '      oneOf(f && f.family, FAMILIES, `${at}.finishes[${j}].family`);\n'
                  '      if (!f || !f.name) e.push(`${at}.finishes[${j}].name is required`);\n'
                  '      oneOf(f && f.undertone, UNDERTONES, `${at}.finishes[${j}].undertone`);\n'
                  '    });\n'
                  "    if (p.dimensions_cm) for (const k of ['width', 'depth', 'height']) {\n"
                  "      const v = p.dimensions_cm[k]; if (!isNil(v) && !(typeof v === 'number' && v > 0)) "
                  'e.push(`${at}.dimensions_cm.${k} must be > 0`);\n'
                  '    }\n'
                  '    if (!isNil(p.colour_hex) && !/^#[0-9a-fA-F]{6}$/.test(String(p.colour_hex).trim())) '
                  'e.push(`${at}.colour_hex must be # followed by 6 hex digits`);\n'
                  "    if (p.role === 'midas_support') {\n"
                  "      const miss = ['sku', 'catalogue_photo', 'retrieved_on'].filter((f) => !p[f]);\n"
                  "      if (miss.length) e.push(`${at}: a Midas supporting piece needs ${miss.join(', ')}; "
                  'without them it can only be generic context`);\n'
                  '    }\n'
                  "    if (p.role === 'generic_context' && p.sku) e.push(`${at}: generic context cannot "
                  'carry a SKU`);\n'
                  '    const basis = p.basis || {};\n'
                  '    for (const [k, v] of Object.entries(basis)) oneOf(v, BASIS, `${at}.basis.${k}`);\n'
                  "    for (const f of DESCRIPTIVE) if (filled(p[f]) && !(f in basis)) e.push(`${at}: '${f}' "
                  'is filled but has no basis; leave it empty (not confirmed) or say where it came from`);\n'
                  "    if (p.colour_hex && basis.colour_hex === 'observed_in_photo') e.push(`${at}: a hex "
                  "read from a photo is an estimate; use basis 'estimated_from_photo'`);\n"
                  '  });\n'
                  '  (req.surfaces || []).forEach((s, i) => {\n'
                  '    if (!s || !s.name || !s.colour) e.push(`surfaces[${i}]: name and colour are '
                  'required`);\n'
                  '    oneOf(s && s.role, PALETTE, `surfaces[${i}].role`);\n'
                  '    if (s && !isNil(s.area_share) && !(s.area_share >= 0 && s.area_share <= 1)) '
                  'e.push(`surfaces[${i}].area_share must be 0 to 1`);\n'
                  '  });\n'
                  "  oneOf(req.output, OUTPUTS, 'output');\n"
                  "  oneOf(req.style, STYLE_MENU, 'style');\n"
                  "  oneOf(req.ambience, AMBIENCE_MENU, 'ambience');\n"
                  "  oneOf(req.preset, PRESET_MENU, 'preset');\n"
                  '  if (!isNil(req.max_midas_pieces) && !(Number.isInteger(req.max_midas_pieces) && '
                  "req.max_midas_pieces >= 0 && req.max_midas_pieces <= 6)) e.push('max_midas_pieces must be "
                  "0 to 6');\n"
                  '  if (req.weights) {\n'
                  '    for (const [k, v] of Object.entries(req.weights)) {\n'
                  '      if (!PILLARS.includes(k)) e.push(`weights.${k} is not a pillar`);\n'
                  '      else if (!(Number.isInteger(v) && v >= 0 && v <= 100)) e.push(`weights.${k} must be '
                  '0 to 100`);\n'
                  '    }\n'
                  '    const w = { ...DEFAULT_W, ...req.weights };\n'
                  "    if (PILLARS.every((k) => w[k] === 0)) e.push('at least one weight must be above 0');\n"
                  '  } else if (!isNil(req.profile) && !(req.profile in PROFILES)) e.push(`unknown profile '
                  '${JSON.stringify(req.profile)}`);\n'
                  '  return e;\n'
                  '}\n'
                  '\n'
                  '// ---------------------------------------------------------------- pillars\n'
                  'const R = (pillar, result, reason, fix = null) => ({ pillar, result, reason, fix });\n'
                  'const known = (ps, a) => ps.filter((p) => !isNil(p[a]));\n'
                  'const pct = (r) => `${Math.round(r * 100)}%`;\n'
                  '\n'
                  'function selectPieces(req, hero) {\n'
                  '  const kept = [hero]; const excluded = []; let midasUsed = 0;\n'
                  '  const max = isNil(req.max_midas_pieces) ? 3 : req.max_midas_pieces;\n'
                  '  for (const p of req.pieces) {\n'
                  '    if (p === hero) continue;\n'
                  "    if (req.output === 'white_background') { excluded.push([p.id, 'white background "
                  "output shows the product alone']); continue; }\n"
                  '    if (p.category === hero.category) { excluded.push([p.id, `same kind as the product '
                  '(${p.category})`]); continue; }\n'
                  "    if (p.role === 'midas_support') {\n"
                  "      if (p.availability === 'out_of_stock') { excluded.push([p.id, `out of stock as read "
                  'on ${p.retrieved_on}`]); continue; }\n'
                  '      if (midasUsed >= max) { excluded.push([p.id, `over the limit of ${max} Midas '
                  'pieces`]); continue; }\n'
                  '      midasUsed += 1;\n'
                  '    }\n'
                  '    kept.push(p);\n'
                  '  }\n'
                  '  return { kept, excluded };\n'
                  '}\n'
                  '\n'
                  'function scaleProportion(ps, hero) {\n'
                  "  const k = known(ps, 'visual_weight'); const notes = []; const res = [];\n"
                  '  if (k.length >= 2) {\n'
                  "    const heavy = k.filter((p) => p.visual_weight === 'heavy').length;\n"
                  "    const light = k.filter((p) => p.visual_weight === 'light').length;\n"
                  "    if (heavy >= 2 && !light) { res.push('fail'); notes.push(`${heavy} heavy pieces and "
                  'nothing light: the group will look crowded`); }\n'
                  "    else if (heavy >= 2) { res.push('partial'); notes.push('two heavy pieces, partly "
                  "offset by a light one'); }\n"
                  "    else { res.push('pass'); notes.push('visual weight is balanced'); }\n"
                  '  }\n'
                  '  const hw = hero.dimensions_cm && hero.dimensions_cm.width;\n'
                  "  if (hero.category.includes('sofa') && hw) {\n"
                  "    for (const t of ps.filter((p) => p !== hero && p.category.includes('table'))) {\n"
                  '      const tw = t.dimensions_cm && t.dimensions_cm.width;\n'
                  '      if (tw) {\n'
                  '        const r = tw / hw; const ok = r >= TABLE_TO_SOFA[0] && r <= TABLE_TO_SOFA[1];\n'
                  "        res.push(ok ? 'pass' : 'partial');\n"
                  "        notes.push(`${t.name} is ${pct(r)} of the sofa width${ok ? '' : ' (rule of thumb: "
                  "about half to three quarters)'}`);\n"
                  '      }\n'
                  '    }\n'
                  '  }\n'
                  "  if (!res.length) return R('scale_proportion', 'unknown', 'visual weight and sizes not "
                  "confirmed');\n"
                  '  const worst = res.reduce((a, b) => (VALUE[b] < VALUE[a] ? b : a));\n'
                  "  return R('scale_proportion', worst, notes.join('; '),\n"
                  "    worst === 'pass' ? null : 'swap one heavy piece for a leggy or glass one, or resize "
                  "the table');\n"
                  '}\n'
                  '\n'
                  'function silhouetteLines(ps) {\n'
                  "  const k = known(ps, 'silhouette'); const s = new Set(k.map((p) => p.silhouette));\n"
                  "  if (k.length < 2) return R('silhouette_lines', 'unknown', 'silhouettes not "
                  "confirmed');\n"
                  "  if (s.has('mixed') || (s.has('angular') && s.has('curved'))) return "
                  "R('silhouette_lines', 'pass', 'straight and curved lines balance each other');\n"
                  "  if (s.size === 1 && s.has('angular')) return R('silhouette_lines', 'partial', 'all "
                  "angular: the room may feel rigid', 'add one rounded piece: a round table, a curved lamp "
                  "or an oval mirror');\n"
                  "  return R('silhouette_lines', 'partial', 'all curved: shapes may read as soft or busy', "
                  "'anchor with one straight-lined piece');\n"
                  '}\n'
                  '\n'
                  'function materialsFinishes(ps) {\n'
                  "  const hard = ps.flatMap((p) => (p.finishes || []).filter((f) => f.family === 'wood' || "
                  "f.family === 'metal')\n"
                  '    .map((f) => ({ fam: f.family, name: f.name.toLowerCase(), u: isNil(f.undertone) ? '
                  'null : f.undertone })));\n'
                  "  if (!hard.length) return R('materials_finishes', 'unknown', 'wood and metal finishes "
                  "not confirmed');\n"
                  '  const distinct = new Set(hard.map((h) => `${h.fam}|${h.name}`)).size;\n'
                  "  const tones = new Set(hard.filter((h) => h.fam === 'wood' && h.u).map((h) => h.u));\n"
                  "  if (distinct > 3) return R('materials_finishes', 'fail', `${distinct} different "
                  "wood/metal finishes; the limit is 3`, 'drop or swap the piece that adds the fourth "
                  "finish');\n"
                  "  if (tones.has('warm') && tones.has('cool')) return R('materials_finishes', 'partial', "
                  "'warm and cool wood undertones are mixed', 'keep wood undertones the same even if "
                  "darkness differs');\n"
                  "  return R('materials_finishes', 'pass', `${distinct} finish(es), undertones "
                  'consistent`);\n'
                  '}\n'
                  '\n'
                  'function colourDistribution(req) {\n'
                  "  if (req.output === 'white_background') return R('colour_distribution', 'unknown', 'no "
                  "scene on a white background');\n"
                  '  const sf = req.surfaces || [];\n'
                  "  if (!sf.length) return R('colour_distribution', 'unknown', 'room surfaces not planned "
                  "yet');\n"
                  '  const roles = new Set(sf.map((s) => s.role));\n'
                  '  const missing = PALETTE.filter((r) => !roles.has(r));\n'
                  "  if (missing.length) return R('colour_distribution', 'partial', `no surface carries "
                  "${missing.join(', ')}`, 'give one surface or textile each role: 60 dominant, 30 "
                  "secondary, 10 accent');\n"
                  '  if (sf.every((s) => !isNil(s.area_share))) {\n'
                  '    const bands = { dominant_60: [0.45, 0.75], secondary_30: [0.15, 0.45], accent_10: '
                  '[0.03, 0.20] };\n'
                  '    const off = [];\n'
                  '    for (const r of PALETTE) {\n'
                  '      const share = sf.filter((s) => s.role === r).reduce((a, s) => a + s.area_share, '
                  '0);\n'
                  '      if (!(share >= bands[r][0] && share <= bands[r][1])) off.push(`${r} at '
                  '${pct(share)}`);\n'
                  '    }\n'
                  "    if (off.length) return R('colour_distribution', 'partial', `split is off: "
                  "${off.join(', ')}`, 'rebalance the rug, curtains or cushions; never recolour the "
                  "product');\n"
                  "    return R('colour_distribution', 'pass', 'roughly 60/30/10 across the planned "
                  "surfaces');\n"
                  '  }\n'
                  "  return R('colour_distribution', 'pass', 'all three roles present; shares not "
                  "estimated');\n"
                  '}\n'
                  '\n'
                  'function textureContrast(ps) {\n'
                  "  const k = known(ps, 'texture'); const s = new Set(k.map((p) => p.texture));\n"
                  "  if (k.length < 2) return R('texture_contrast', 'unknown', 'textures not confirmed');\n"
                  "  if (s.has('smooth') && s.has('rough')) return R('texture_contrast', 'pass', 'smooth and "
                  "textured surfaces sit together');\n"
                  "  return R('texture_contrast', 'partial', `only ${[...s].sort().join(', ')} surfaces`, "
                  "'add one contrasting texture: linen or boucle against glass or lacquer, or the "
                  "reverse');\n"
                  '}\n'
                  '\n'
                  'function functionPracticality(req, ps) {\n'
                  "  if (req.output === 'white_background') return R('function_practicality', 'unknown', 'no "
                  "scene on a white background');\n"
                  "  const support = ps.filter((p) => p.role !== 'hero');\n"
                  "  if (!support.length) return R('function_practicality', 'unknown', 'no supporting pieces "
                  "planned');\n"
                  '  const lacking = support.filter((p) => !(p.purpose && p.rests_on)).map((p) => p.name);\n'
                  "  if (lacking.length) return R('function_practicality', 'partial', `no purpose or support "
                  "surface for: ${lacking.join(', ')}`, 'give every supporting piece a use and a surface it "
                  "stands on');\n"
                  "  return R('function_practicality', 'pass', 'every supporting piece has a use and a "
                  "surface');\n"
                  '}\n'
                  '\n'
                  'function focalPoint(ps, hero) {\n'
                  '  const rank = { light: 0, medium: 1, heavy: 2 };\n'
                  '  const support = ps.filter((p) => p !== hero);\n'
                  "  if (!support.length) return R('focal_point', 'pass', 'the product stands alone');\n"
                  '  const rivals = [];\n'
                  '  const hw = hero.dimensions_cm ? hero.dimensions_cm.width : null;\n'
                  '  for (const p of support) {\n'
                  '    if (hero.visual_weight && p.visual_weight && rank[p.visual_weight] > '
                  'rank[hero.visual_weight]) rivals.push(`${p.name} is visually heavier`);\n'
                  '    const pw = p.dimensions_cm ? p.dimensions_cm.width : null;\n'
                  '    if (hw && pw && pw > hw) rivals.push(`${p.name} is wider (${Math.round(pw)} vs '
                  '${Math.round(hw)} cm)`);\n'
                  '  }\n'
                  "  if (rivals.length) return R('focal_point', 'partial', rivals.join('; '), 'keep the "
                  "product the clear subject: smaller support, or move it back');\n"
                  "  if (isNil(hero.visual_weight) && !hw) return R('focal_point', 'unknown', 'product "
                  "weight and size not confirmed');\n"
                  "  return R('focal_point', 'pass', 'nothing outweighs the product');\n"
                  '}\n'
                  '\n'
                  'function styleCohesion(ps) {\n'
                  "  const k = known(ps, 'style'); const s = [...new Set(k.map((p) => p.style))];\n"
                  "  if (k.length < 2) return R('style_cohesion', 'unknown', 'styles not confirmed');\n"
                  "  if (s.length === 1) return R('style_cohesion', 'pass', `one style: ${s[0]}`);\n"
                  "  if (s.length === 2) return R('style_cohesion', 'partial', `two styles: "
                  "${s.sort().join(' + ')}`, 'fine for an eclectic brief; for a strict brief pick the "
                  "requested style');\n"
                  "  return R('style_cohesion', 'fail', `${s.length} styles in one scene`, 'cut to the "
                  "requested style plus at most one accent style');\n"
                  '}\n'
                  '\n'
                  '// ---------------------------------------------------------------- main\n'
                  'function checkPlan(req) {\n'
                  '  const errors = validate(req);\n'
                  "  if (errors.length) return { status: 'invalid_input', errors, score: null, score_label: "
                  'SCORE_LABEL };\n'
                  "  const hero = req.pieces.find((p) => p.role === 'hero');\n"
                  '  const { kept, excluded } = selectPieces(req, hero);\n'
                  '  const pillars = [scaleProportion(kept, hero), silhouetteLines(kept), '
                  'materialsFinishes(kept), colourDistribution(req),\n'
                  '    textureContrast(kept), functionPracticality(req, kept), focalPoint(kept, hero), '
                  'styleCohesion(kept)];\n'
                  '  const raw = req.weights ? { ...DEFAULT_W, ...req.weights } : PROFILES[req.profile || '
                  "'balanced'];\n"
                  '  const total = PILLARS.reduce((a, k) => a + raw[k], 0);\n'
                  '  const w = Object.fromEntries(PILLARS.map((k) => [k, raw[k] / total]));\n'
                  "  const kn = pillars.filter((p) => p.result !== 'unknown');\n"
                  '  const cov = kn.reduce((a, p) => a + w[p.pillar], 0);\n'
                  '  const clean = (x, d) => Math.round(x * 10 ** d) / 10 ** d; // remove float noise before '
                  'half-up rounding\n'
                  '  const coverage = Math.floor(clean(cov * 1000, 6) + 0.5) / 1000;\n'
                  '  let score = null;\n'
                  '  if (kn.length && coverage >= MIN_COVERAGE) score = Math.floor(clean(100 * kn.reduce((a, '
                  'p) => a + w[p.pillar] * VALUE[p.result], 0) / cov, 9) + 0.5);\n'
                  '  const results = new Set(pillars.map((p) => p.result));\n'
                  "  const status = coverage < MIN_COVERAGE ? 'needs_information'\n"
                  "    : results.has('fail') ? 'plan_needs_change' : results.has('partial') ? "
                  "'plan_ready_with_warnings' : 'plan_ready';\n"
                  '  return {\n'
                  '    status, score, coverage, score_label: SCORE_LABEL,\n'
                  "    profile: req.weights ? 'custom' : (req.profile || 'balanced'),\n"
                  '    kept: kept.map((p) => p.id), excluded, pillars,\n'
                  '    critique: {\n'
                  "      the_win: pillars.filter((p) => p.result === 'pass').map((p) => p.reason).slice(0, "
                  '2),\n'
                  "      the_conflict: pillars.filter((p) => p.result === 'fail' || p.result === "
                  "'partial').map((p) => p.reason),\n"
                  "      the_fix: pillars.filter((p) => p.fix && (p.result === 'fail' || p.result === "
                  "'partial')).map((p) => p.fix),\n"
                  "      not_confirmed: pillars.filter((p) => p.result === 'unknown').map((p) => p.pillar),\n"
                  '    },\n'
                  '  };\n'
                  '}\n'
                  '\n'
                  "// ---- A7 step 11b · Stylist check (wrapper). The engine above is the stylist skill's "
                  'engine, unchanged. ----\n'
                  '// First pass: the input is the planner\'s reply and the state comes from "11a Plan '
                  'ticket".\n'
                  '// Loop pass: the input is the state from "11d Plan verdict" (plan_state = true) with '
                  'rewritten plans.\n'
                  '// Code fixes only what code can fix without inventing anything; everything else goes to '
                  'the plan critic.\n'
                  "// P1.8 (16 Oct 2026): the replies are no longer simplified, so each call's token counts "
                  'can be recorded. bodyOf picks the answer\n'
                  '// part of a reply (so an echoed instruction is never read as the answer); textCall '
                  "records the provider's own token counts.\n"
                  'function bodyOf(o) {\n'
                  "  if (!o || typeof o !== 'object') return o;\n"
                  '  if (Array.isArray(o.output)) return o.output;\n'
                  '  if (Array.isArray(o.candidates)) return o.candidates;\n'
                  '  if (o.content !== undefined) return o.content;\n'
                  '  if (o.message !== undefined) return o.message;\n'
                  '  return o;\n'
                  '}\n'
                  'function usageOf(o) {\n'
                  "  if (!o || typeof o !== 'object') return null;\n"
                  '  const u = o.usage || o.usageMetadata || (o.response && o.response.usage) || null;\n'
                  "  if (!u || typeof u !== 'object') return null;\n"
                  '  const n = v => (Number.isFinite(Number(v)) && Number(v) >= 0 ? Math.round(Number(v)) : '
                  '0);\n'
                  '  if (u.promptTokenCount !== undefined || u.candidatesTokenCount !== undefined) return { '
                  'input: n(u.promptTokenCount), output: n(u.candidatesTokenCount) + n(u.thoughtsTokenCount) '
                  '};\n'
                  '  if (u.input_tokens !== undefined || u.output_tokens !== undefined) return { input: '
                  'n(u.input_tokens) + n(u.cache_read_input_tokens) + n(u.cache_creation_input_tokens), '
                  'output: n(u.output_tokens) };\n'
                  '  if (u.prompt_tokens !== undefined) return { input: n(u.prompt_tokens), output: '
                  'n(u.completion_tokens) };\n'
                  '  return null;\n'
                  '}\n'
                  'function textCall(state, step, node, model, raw) {\n'
                  '  if (!raw) return state;\n'
                  '  const P = state.text_prices || {};\n'
                  '  const u = usageOf(raw);\n'
                  '  const pr = P.models && P.models[model] ? P.models[model] : null;\n'
                  '  const usd = u && pr ? Number(((u.input * pr.input + u.output * pr.output) / '
                  '1e6).toFixed(5)) : null;\n'
                  "  const e = raw.error ? (typeof raw.error === 'string' ? raw.error : String((raw.error && "
                  "raw.error.message) || JSON.stringify(raw.error))).split('\\n')[0].slice(0, 120) : '';\n"
                  '  const rec = { step, node, model, at: new Date().toISOString(), tokens: u, usd, error: '
                  "e, basis: u ? (pr ? 'provider token counts x prices read ' + (P.read_on || '?') + ' (' + "
                  "(pr.source || '') + '); an estimate, not an invoice' : 'provider token counts; no price "
                  "recorded for this model') : 'the provider reported no token counts (the call may still be "
                  "charged)' };\n"
                  '  state.text_calls = (Array.isArray(state.text_calls) ? state.text_calls : '
                  '[]).concat([rec]);\n'
                  '  state.text_calls_new = (Array.isArray(state.text_calls_new) ? state.text_calls_new : '
                  '[]).concat([rec]);\n'
                  '  return state;\n'
                  '}\n'
                  'function findJson(value, marker, depth) {\n'
                  '  depth = depth || 0;\n'
                  '  if (depth > 10 || value === null || value === undefined) return null;\n'
                  "  if (typeof value === 'string') {\n"
                  "    const a = value.indexOf('{'), z = value.lastIndexOf('}');\n"
                  '    if (a === -1 || z <= a) return null;\n'
                  "    try { const p = JSON.parse(value.slice(a, z + 1)); return p && typeof p === 'object' "
                  '&& marker in p ? p : null; } catch (e) { return null; }\n'
                  '  }\n'
                  '  if (Array.isArray(value)) { for (const v of value) { const f = findJson(v, marker, '
                  'depth + 1); if (f) return f; } return null; }\n'
                  "  if (typeof value === 'object') { if (marker in value) return value; for (const k of "
                  'Object.keys(value)) { const f = findJson(value[k], marker, depth + 1); if (f) return f; } '
                  '}\n'
                  '  return null;\n'
                  '}\n'
                  "const txt = (v, n) => (v === null || v === undefined ? '' : String(v)).replace(/\\s+/g, ' "
                  "').trim().slice(0, n || 600);\n"
                  'const arrT = (v, n, max) => (Array.isArray(v) ? v : []).map(x => txt(x, n || '
                  '120)).filter(Boolean).slice(0, max || 8);\n'
                  'const nl = String.fromCharCode(10);\n'
                  'const inp = $input.first().json;\n'
                  'let st;\n'
                  'if (inp && inp.plan_state === true) st = JSON.parse(JSON.stringify(inp));\n'
                  'else {\n'
                  "  st = JSON.parse(JSON.stringify($('11a Plan ticket').first().json));\n"
                  '  st.plan_state = true;\n'
                  "  const reply = findJson(bodyOf(inp), 'shots');\n"
                  "  textCall(st, 11, '11 Stylist plans the scenes', 'gpt-6.1-sol', inp); // P1.8\n"
                  '  const got = reply && Array.isArray(reply.shots) ? reply.shots : [];\n'
                  '  st.plan_readable = got.length > 0;\n'
                  '  st.plan_risks = reply ? arrT(reply.risks, 160, 8) : [];\n'
                  '  st.planner_rejected = reply && Array.isArray(reply.catalogue_rejected) ? '
                  'reply.catalogue_rejected.slice(0, 12).map(x => ({ sku: txt(x && x.sku, 20), reason: txt(x '
                  '&& x.reason, 160) })) : [];\n'
                  '  for (const shot of st.shots) {\n'
                  '    // Match by output_id; fall back to position only when the planner gave no output_id '
                  'at that position.\n'
                  '    const e = got.find(x => x && x.output_id === shot.output_id) || (got[shot.n - 1] && '
                  '!got[shot.n - 1].output_id ? got[shot.n - 1] : null);\n'
                  "    const rm = e && e.room && typeof e.room === 'object' ? e.room : {};\n"
                  '    shot.plan = e ? {\n'
                  '      room_size: txt(e.room_size, 20), room: { walls: txt(rm.walls, 160), floor: '
                  'txt(rm.floor, 160), windows: txt(rm.windows, 160), zone: txt(rm.zone, 160) },\n'
                  '      setting: txt(e.setting), light: txt(e.light, 300), camera: txt(e.camera, 300), '
                  'presentation: txt(e.presentation), person: txt(e.person, 240),\n'
                  '      supporting_props: arrT(e.supporting_props, 120, 8),\n'
                  '      midas_pieces: (Array.isArray(e.midas_pieces) ? e.midas_pieces : []).slice(0, '
                  '6).map(m => ({ sku: txt(m && m.sku, 20), count: Math.max(1, Math.min(2, '
                  'Math.round(Number(m && m.count) || 1))), purpose: txt(m && m.purpose, 160), rests_on: '
                  'txt(m && m.rests_on, 120) })),\n'
                  '      palette_roles: { dominant_60: txt(e.palette_roles && e.palette_roles.dominant_60, '
                  '120), secondary_30: txt(e.palette_roles && e.palette_roles.secondary_30, 120), accent_10: '
                  'txt(e.palette_roles && e.palette_roles.accent_10, 120) },\n'
                  '      rationale: txt(e.rationale, 300)\n'
                  '    } : null;\n'
                  '    shot.plan_ok = false; shot.code_fixes = []; shot.code_findings = []; '
                  'shot.code_warnings = [];\n'
                  '  }\n'
                  "  // A white master the planner left out gets the studio's fixed plan; a scene shot left "
                  'out makes the reply unreadable.\n'
                  "  for (const shot of st.shots) if (!shot.plan && shot.kind === 'white') { shot.plan = { "
                  "room_size: '', room: { walls: '', floor: '', windows: '', zone: '' }, setting: '', light: "
                  "'', camera: '', presentation: '', person: '', supporting_props: [], midas_pieces: [], "
                  "palette_roles: { dominant_60: '', secondary_30: '', accent_10: '' }, rationale: '' }; "
                  "shot.code_fixes.push('the planner gave no entry for the white master; the studio plan is "
                  "used'); }\n"
                  '  const missing = st.shots.filter(x => !x.plan).map(x => x.output_id);\n'
                  '  if (missing.length) st.plan_readable = false;\n'
                  '  if (!st.plan_readable) {\n'
                  "    st.critical = (st.critical || []).concat([{ what: 'plan_unread', who: 'owner', why: "
                  "'The planner did not return a readable plan' + (missing.length && got.length ? ' (no plan "
                  "for: ' + missing.join(', ') + ')' : ' (an error or a cut-off answer)') + '. Run the job "
                  "again; the client was not asked anything.' }]);\n"
                  '    st.hold_step = 11;\n'
                  '  }\n'
                  '}\n'
                  'const short = st.retrieval.shortlist;\n'
                  'const bySku = Object.fromEntries(short.map(c => [c.sku, c]));\n'
                  'const maxMidas = st.retrieval.max_midas;\n'
                  '// The white master: the angle of the vendor photo only (16 Oct 2026, prompt check P3; 13 '
                  'Compile already used it).\n'
                  "const WHITE = { room_size: '', room: { walls: '', floor: '', windows: '', zone: '' }, "
                  "setting: 'Pure white seamless studio background and clean white floor, the product alone, "
                  "with only a natural, subtle contact shadow directly beneath it.', light: 'Soft, even, "
                  "neutral professional studio light that shows the real colour of the product.', camera: "
                  "'The camera angle and perspective of the vendor photo. The whole product in frame with "
                  "white space on every side.', presentation: 'The complete product as arranged in the "
                  "vendor photo, every piece fully visible and countable.', person: '', supporting_props: "
                  "[], midas_pieces: [], palette_roles: { dominant_60: '', secondary_30: '', accent_10: '' "
                  "}, rationale: 'Catalogue master, fixed by the studio.' };\n"
                  '// Stage 07 rules for scene plans (owner decisions 15 Oct 21:50 and 16 Oct 2026, 22-24; '
                  'prompt check P3, P4): Midas pieces only; a lamp or\n'
                  '// rug only as a Midas piece; the light follows the fixed preset; people only when the '
                  'brief asks; the room fields name no furniture.\n'
                  'const LAMP = /\\b(table lamps?|floor lamps?|desk '
                  'lamps?|lamps?|sconces?|lanterns?|candles?|chandeliers?|pendant lights?|pendants?)\\b/i;\n'
                  'const RUG = /\\b(rugs?|carpets?|runners? rug)\\b/i;\n'
                  'const FURNITURE = '
                  '/\\b(sofa|sofas|couch|chair|chairs|armchair|table|tables|desk|bed|beds|bench|stool|ottoman|cabinet|dresser|sideboard|console|shelf '
                  'unit|bookcase|lamp|lamps|rug|rugs|plant|plants|art|artwork|painting|cushion|cushions|vase|books?)\\b/i;\n'
                  'const PRESET_CLASH = { Daylight: /\\b(evening|night|dusk|sunset|candle '
                  "?light|lamplight|after dark)\\b/i, 'Golden afternoon': /\\b(night|after "
                  "dark|midday|noon|overcast|cool daylight)\\b/i, 'Warm evening': "
                  '/\\b(daylight|sunlit|sunny|morning|midday|noon|bright sun)\\b/i };\n'
                  "const presetOf = shot => String(shot.light_preset || 'Daylight').replace(/ \\(studio "
                  "default\\)$/, '');\n"
                  'const PEOPLE = /\\b(person|people|man|woman|men|women|child|children|boy|girl)\\b/i;\n'
                  'const PERSON_PROP = /^(a |an |one |two |the )?(young |older |seated |standing '
                  ")?(person|people|man|woman|men|women|child|children|boy|girl)\\b(?!'s)/i; // a prop that "
                  'IS a person, not "children\'s books"\n'
                  "const NAMES = short.map(c => { const nm = String(c.name || ''); const first = nm.split(' "
                  "')[0]; return { sku: c.sku, words: [nm.length >= 8 ? nm.toLowerCase() : '', "
                  "/^[A-Z]{4,}$/.test(first) ? first.toLowerCase() : ''].filter(Boolean) }; });\n"
                  'const namesMidas = g => { const t = String(g).toLowerCase(); return /\\bmidas\\b/.test(t) '
                  '|| NAMES.some(n => t.indexOf(n.sku) !== -1 || n.words.some(w => t.indexOf(w) !== -1)); '
                  '};\n'
                  '// Job-wide Midas limit: client picks first, then the order the planner used.\n'
                  'const used = [];\n'
                  'for (const c of short) if (c.fixed && used.indexOf(c.sku) === -1) used.push(c.sku); // '
                  'client picks hold their places first\n'
                  "for (const x of st.shots) if (x.plan && x.plan_ok && x.kind !== 'white') for (const m of "
                  'x.plan.midas_pieces) if (used.indexOf(m.sku) === -1) used.push(m.sku);\n'
                  'for (const shot of st.shots) {\n'
                  '  if (!shot.plan || shot.plan_ok) continue;\n'
                  '  const p = shot.plan; const fixes = []; const findings = []; const warnings = [];\n'
                  "  if (shot.kind === 'white') {\n"
                  '    const planned = p.supporting_props.length + p.midas_pieces.length;\n'
                  '    const lightNotNeutral = p.light && !/neutral|studio/i.test(p.light);\n'
                  '    shot.plan = Object.assign({}, WHITE, { camera: p.camera || WHITE.camera });\n'
                  "    if (planned) fixes.push('props and Midas pieces removed from the white master');\n"
                  "    if (lightNotNeutral) fixes.push('light set to neutral studio light (the client "
                  "lighting choice never applies to the white master)');\n"
                  '  } else {\n'
                  '    const keep = [];\n'
                  '    for (const m of p.midas_pieces) {\n'
                  "      if (!bySku[m.sku]) { fixes.push('removed SKU ' + (m.sku || '(blank)') + ': not on "
                  "the shortlist, so it cannot be called a Midas product'); continue; }\n"
                  '      if (used.indexOf(m.sku) === -1) {\n'
                  '        const room = maxMidas - used.length;\n'
                  "        if (room <= 0 && !bySku[m.sku].fixed) { fixes.push('removed SKU ' + m.sku + ': "
                  "over the limit of ' + maxMidas + ' Midas pieces for the job'); continue; }\n"
                  '        used.push(m.sku);\n'
                  '      }\n'
                  "      if (!m.purpose || !m.rests_on) warnings.push('Midas piece ' + m.sku + ' has no ' + "
                  "(!m.purpose ? 'purpose' : 'surface it rests on'));\n"
                  '      keep.push(m);\n'
                  '    }\n'
                  '    p.midas_pieces = keep;\n'
                  '    // Generic props are never used in Studio scenes (owner, 15 Oct 2026, 21:50): they '
                  'are removed here and listed at go 1.\n'
                  '    if (p.supporting_props.length) {\n'
                  "      for (const g of p.supporting_props) if (namesMidas(g)) findings.push('generic prop "
                  '"\' + g + \'" names a Midas product; plan it by SKU in midas_pieces\');\n'
                  "      fixes.push('removed generic props (only Midas pieces appear in Studio scenes): ' + "
                  "p.supporting_props.join('; '));\n"
                  '      shot.generic_removed = p.supporting_props.slice();\n'
                  '      p.supporting_props = [];\n'
                  '    }\n'
                  "    if (st.people_max === 0 && p.person) { fixes.push('removed the person (people: none): "
                  "' + p.person); p.person = ''; }\n"
                  '    if (st.people_max === 0 && PEOPLE.test(p.presentation) && '
                  '/\\b(sit|sits|sitting|stand|stands|standing|holding|reading)\\b/i.test(p.presentation)) '
                  "findings.push('the presentation seems to place a person in the scene; people are not "
                  "allowed');\n"
                  '    if (st.people_max === 1 && p.person && /\\bin front '
                  "of\\b|\\bcover(s|ing)?\\b|\\bblock(s|ing)?\\b/i.test(p.person)) findings.push('the person "
                  'may stand in front of the product or cover a piece; a person stays beside or behind the '
                  "product');\n"
                  '    const midasKinds = p.midas_pieces.map(m => String((bySku[m.sku] && bySku[m.sku].kind) '
                  "|| '').toLowerCase());\n"
                  "    const words = [p.setting, p.light, p.presentation, p.person].join(' ');\n"
                  '    if (LAMP.test(words) && !midasKinds.some(k => '
                  "/lamp|light|sconce|chandelier|lantern|candle/.test(k))) findings.push('a lamp or other "
                  "light fitting is planned that is not a Midas piece; warm light comes from the room\\'s "
                  'built-in light (recessed downlights, a cove light or a plain ceiling fixture), and a lamp '
                  "appears only as a Midas lamp from the shortlist');\n"
                  "    if (RUG.test(words) && !midasKinds.some(k => /rug|carpet/.test(k))) findings.push('a "
                  'rug is planned that is not a Midas piece; only a Midas rug from the shortlist may '
                  "appear');\n"
                  '    const clash = PRESET_CLASH[presetOf(shot)];\n'
                  '    if (clash && clash.test(p.light)) findings.push(\'the light "\' + p.light + \'" does '
                  "not fit the fixed light preset ' + presetOf(shot) + '; the preset of this shot cannot "
                  "change');\n"
                  '    const rr = p.room || {}; // plans made before 16 Oct 2026 have no room fields\n'
                  "    const roomText = [rr.walls, rr.floor, rr.windows, rr.zone].join(' ');\n"
                  "    if (FURNITURE.test(roomText)) findings.push('the room fields name furniture or an "
                  'object ("\' + roomText.match(FURNITURE)[0] + \'"); they describe only the walls, floor, '
                  "windows and the free floor zone');\n"
                  '    if (!p.palette_roles.dominant_60 || !p.palette_roles.secondary_30 || '
                  "!p.palette_roles.accent_10) warnings.push('palette roles for the room (60/30/10) are "
                  "incomplete');\n"
                  '  }\n'
                  '  shot.code_fixes = (shot.code_fixes || []).concat(fixes);\n'
                  '  shot.code_findings = findings;\n'
                  '  shot.code_warnings = warnings;\n'
                  '}\n'
                  '// A shot made from the approved image of another shot repeats its Midas pieces and '
                  "person (19a uses that shot's pieces anyway).\n"
                  'for (const shot of st.shots) {\n'
                  '  if (!shot.plan || shot.plan_ok || !shot.made_from) continue;\n'
                  '  const src = st.shots.find(x => x.output_id === shot.made_from);\n'
                  '  if (!src || !src.plan) continue;\n'
                  '  const same = JSON.stringify(src.plan.midas_pieces) === '
                  "JSON.stringify(shot.plan.midas_pieces) && (src.plan.person || '') === (shot.plan.person "
                  "|| '');\n"
                  '  if (!same) { shot.plan.midas_pieces = '
                  'JSON.parse(JSON.stringify(src.plan.midas_pieces)); shot.plan.person = src.plan.person || '
                  "''; shot.code_fixes = (shot.code_fixes || []).concat(['Midas pieces and person copied "
                  "from ' + src.output_id + ', which this shot is made from']); }\n"
                  '}\n'
                  '// Client picks must appear somewhere in the scene shots.\n'
                  "const scene = st.shots.filter(x => x.kind !== 'white' && x.plan);\n"
                  'const missingPicks = short.filter(c => c.fixed && !scene.some(x => '
                  'x.plan.midas_pieces.some(m => m.sku === c.sku)));\n'
                  'if (missingPicks.length && scene.length) for (const x of scene) if (!x.plan_ok) '
                  "x.code_findings.push('client pick(s) not planned in any scene shot: ' + "
                  "missingPicks.map(c => c.sku + ' ' + c.name).join(', '));\n"
                  '// Styling engine per scene shot (stylist skill). Tags that are not confirmed stay empty, '
                  'so pillars can be "unknown".\n'
                  "const BASIS_OK = ['vendor_stated', 'catalogue_stated', 'observed_in_photo', "
                  "'estimated_from_photo'];\n"
                  "const heroCat = txt(st.brief.product_type || st.observation.category_seen || 'product', "
                  '80).toLowerCase();\n'
                  'for (const shot of scene) {\n'
                  '  if (shot.plan_ok) continue;\n'
                  '  const p = shot.plan;\n'
                  "  const hero = { id: 'product', name: st.brief.product_type || 'the product', role: "
                  "'hero', category: heroCat };\n"
                  '  const pieces = [hero];\n'
                  '  for (const m of p.midas_pieces) {\n'
                  '    const c = bySku[m.sku]; const t = c.tags || {};\n'
                  "    const piece = { id: 'sku-' + c.sku, name: c.name || c.kind, role: 'midas_support', "
                  "category: String(c.kind || 'piece').toLowerCase(), sku: c.sku, catalogue_photo: "
                  'c.catalogue_photo, retrieved_on: c.retrieved_on,\n'
                  '      availability: c.availability, purpose: m.purpose || null, rests_on: m.rests_on || '
                  'null };\n'
                  '    if (BASIS_OK.indexOf(t.basis) !== -1) {\n'
                  '      const basis = {};\n'
                  "      for (const k of ['visual_weight', 'silhouette', 'texture', 'style']) if (t[k]) { "
                  'piece[k] = t[k]; basis[k] = t.basis; }\n'
                  '      piece.basis = basis;\n'
                  '    }\n'
                  '    pieces.push(piece);\n'
                  '  }\n'
                  "  p.supporting_props.forEach((g, i) => pieces.push({ id: 'generic-' + (i + 1), name: g, "
                  "role: 'generic_context', category: 'generic prop', purpose: 'generic context', rests_on: "
                  "'as planned' }));\n"
                  "  const surfaces = ['dominant_60', 'secondary_30', 'accent_10'].filter(k => "
                  'p.palette_roles[k]).map(k => ({ name: k, colour: p.palette_roles[k], role: k }));\n'
                  "  if (pieces.length < 2) { shot.styling = { status: 'not_run', reason: 'nothing planned "
                  "beside the product', score: null, score_label: SCORE_LABEL }; shot.styling_line = "
                  "'Styling fit: not scored (nothing planned beside the product).'; continue; }\n"
                  "  const res = checkPlan({ pieces, surfaces, output: 'lifestyle', max_midas_pieces: "
                  "Math.min(6, Math.max(0, maxMidas)), profile: 'balanced' });\n"
                  '  shot.styling = res;\n'
                  '  shot.styling_line = res.score === null\n'
                  "    ? 'Styling fit: not scored (coverage ' + Math.round((res.coverage || 0) * 100) + '%, "
                  "below 60%). Not confirmed: ' + ((res.critique && res.critique.not_confirmed) || "
                  "[]).join(', ') + '. Rule-based judgement, not a measurement; not an approval.'\n"
                  "    : 'Styling fit: ' + res.score + ' (balanced profile; coverage ' + "
                  "Math.round(res.coverage * 100) + '%). Rule-based judgement, not a measurement; not an "
                  "approval.';\n"
                  "  if (res.status === 'invalid_input') shot.code_warnings.push('styling check could not "
                  "read the plan: ' + (res.errors || []).slice(0, 2).join('; '));\n"
                  '}\n'
                  '// Message for the plan critic (another model family than the planner).\n'
                  'const b = st.brief, o = st.observation;\n'
                  'const pending = st.shots.filter(x => x.plan && !x.plan_ok);\n'
                  'const pref = b.preferences || {};\n'
                  "const choices = [pref.lighting ? 'Lighting: ' + pref.lighting : '', pref.wall ? 'Wall "
                  "paint: ' + pref.wall : '', pref.floor ? 'Floor: ' + pref.floor : ''].filter(Boolean);\n"
                  "const LEAD = { product_leads: 'the product leads: the clear main subject, nothing "
                  "outweighs it', accessory_leads: 'the product is an accessory and leads: the room serves "
                  "it, it stands on a credible surface and does its real job at real scale', "
                  "product_supports: 'the product supports a furniture-led scene: secondary, at true scale, "
                  "still fully visible and countable' };\n"
                  'const lines = [\n'
                  "  'Check the written plan of each photograph below against these facts and return the "
                  "JSON object. No image exists yet.',\n"
                  "  'Product: ' + (b.product_type || o.category_seen || 'not named') + '.',\n"
                  "  'Inventory of the real product, fixed:', st.inventory.map((x, i) => (i + 1) + '. ' + "
                  "x.count + ' x ' + x.item).join(nl),\n"
                  "  'Total product pieces: ' + st.inventory.reduce((t, x) => t + (x.count || 0), 0) + '.',\n"
                  "  'In the vendor photo the product is shown with: ' + ((o.shown_with || []).length ? "
                  "o.shown_with.join('; ') : 'nothing, it is shown bare') + '.',\n"
                  "  'Parts that sit on one side, as seen by a person standing in front of the product. "
                  "Never mirrored: ' + ((o.sided_parts || []).length ? o.sided_parts.join('; ') : 'none "
                  "recorded') + '.',\n"
                  "  'How the pieces of the set stand to each other, to be kept: ' + ((o.relations || "
                  "[]).length ? o.relations.join('; ') : 'not a set, or not recorded') + '.',\n"
                  "  'Must be absent: ' + (st.exclusions.length ? st.exclusions.map(x => x.item).join('; ') "
                  ": 'nothing listed') + '.',\n"
                  "  'Client choices, fixed for scene shots: ' + (choices.length ? choices.join('; ') : "
                  "'none given') + '. ' + (st.people_text || 'People: none in any shot.') + ' ' + "
                  "(st.plant_text || ''),\n"
                  "  'Lead: ' + LEAD[st.lead] + '.',\n"
                  "  'A shot of kind white is the catalogue master, fixed by the studio: the product alone "
                  'on plain white with neutral studio light, at the angle of the vendor photo, no props and '
                  'no room; the client choices do not apply to it. Shots of kind hero, wide and detail show '
                  'one and the same room on purpose. A shot made from another shot repeats its room, '
                  "arrangement, Midas pieces and person on purpose.',\n"
                  "  'Scene rules, fixed by the studio: a scene shows only the product, the room shell "
                  '(walls, floor, ceiling, windows with plain sheer curtains or blinds, doors, fixed '
                  'architectural details and built-in light) and planned Midas pieces. No generic props. '
                  'Each scene shot has a fixed light preset and a fixed camera view (below); the plan '
                  'follows them. Warm or evening light comes from the built-in light; a lamp or a rug '
                  "appears only as a planned Midas piece.',\n"
                  "  'Category guidance (' + st.profile.name + '): ' + (st.profile.guide ? st.profile.guide "
                  "+ ' These are composition guidelines, not evidence of the source inventory. Original "
