                  'const uniq = a => a.filter((x, i) => x && a.findIndex(y => String(y).toLowerCase() === '
                  'String(x).toLowerCase()) === i);\n'
                  "const sha = t => crypto.createHash('sha256').update(String(t)).digest('hex');\n"
                  'const s04 = { started_at: now, settings, orders: [], dispatch: null, go: false, outcome: '
