                  '// the scene, never the product: image 1 still decides the product, so the "match the '
                  'reference exactly" rule above stays true.\n'
                  'const EDIT_RE = /^(requested edit|keep unchanged) \\(owner\\):\\s*/i;\n'
                  'function editLine(out) {\n'
                  '  const ls = arr(out && out.locks).map(String);\n'
                  '  const change = (ls.find(l => /^requested edit \\(owner\\):/i.test(l)) || '
                  "'').replace(EDIT_RE, '').trim();\n"
