                  '}\n'
                  "function stop(why) { s04.go = false; s04.outcome = 'hold'; if (!s04.hold_step) "
                  "s04.hold_step = 13; s04.critical.push({ what: 'stage04', who: 'owner', why }); }\n"
                  '\n'
                  "// Never pay without the owner's recorded go 1 on this run.\n"
                  'const last = s.go1_last || {};\n'
                  "const repairing = s.status === 'repair_ordered' && s.repair_orders && typeof "
