                  '\n'
                  "function sizeOf(v) { const r = String(v || '').toUpperCase(); if (/4K|4096|3840/.test(r)) "
                  "return '4K'; if (/1K|1024/.test(r)) return '1K'; if (/2K|2048/.test(r)) return '2K'; "
                  "return ''; }\n"
                  'const size = sizeOf(s.brief && s.brief.resolution) || sizeOf(settings.image_size) || '
                  "'2K';\n"
