                  "const SCENE_KINDS = ['lifestyle', 'hero', 'wide', 'detail', 'composition', 'scene'];\n"
                  'let settings = null;\n'
                  "try { settings = $('04 Settings').first().json; } catch (e) { settings = null; }\n"
                  'const cfg = settings && settings.scenes ? settings.scenes : null;\n'
                  'function hold(why) {\n'
                  "  st.status = 'hold'; st.hold_for = 'owner'; st.hold_reason = why; st.client_question = "
                  "''; st.hold_step = 19;\n"
                  "  st.critical = arr(st.critical).concat([{ what: 'scenes', who: 'owner', why }]);\n"
                  "  st.next = 'Waiting for the owner: ' + why + ' No scene image was made or paid for in "
