                 '    const notMade = Object.keys(sc.held);\n'
                 '    // Full-job release is computed from the frozen requested outputs, never from the '
                 'count of successes.\n'
                 "    const validHash = x => /^[0-9a-f]{64}$/.test(String(x || ''));\n"
                 '    const expected = arr(st.outputs);\n'
                 '    const matrix = expected.map(o => {\n'
                 "      const white = o.kind === 'white';\n"
                 '      const approval = white ? st.approved : sc.done[o.id];\n'
                 '      const delivery = white ? st.package : approval && approval.files;\n'
                 '      const release = approval && approval.release;\n'
                 '      const candidate = approval && approval.candidate;\n'
                 '      const reasons = [];\n'
                 "      if (!approval || approval.by !== 'owner') reasons.push('no owner approval for this "
