                  '      const changes = eBase ? arr(o.edit_changes) : (shared ? [basePr.view !== pr.view ? '
                  "'camera' : '', basePr.light.preset !== pr.light.preset ? 'light' : ''].filter(Boolean) : "
                  '[]);\n'
                  "      const v = (o.camera === 'Left side' || o.camera === 'Right side') ? "
                  'arr(st.side_views).find(x => x.output_id === id) : null;\n'
                  '      // One thing changes from the approved image (16 Oct 2026, this build): 01 never '
                  'plans both, so both differing is held, not guessed.\n'
                  "      if (!eBase && changes.length > 1) hold('Scene ' + id + ' is made from the approved "
                  "image of ' + baseId + ', but both its camera view (' + basePr.view + ' to ' + pr.view + "
                  "') and its light (' + basePr.light.label + ' to ' + pr.light.label + ') differ from it. "
                  "Only one may change, so this view is not started.');\n"
                  "      else cur = { output_id: id, kind: o.kind, mode: eBase ? 'edit_from_result' : "
                  "(o.mode || 'creative_room'), phase: roomLocked || shared || cfg.architect_room_first !== "
                  "true ? 'place' : 'room', attempt: 1, started_at: now,\n"
                  '        shot: { n: shot.n, frame: shot.frame, plan: shot.plan }, presets: pr, framing: '
                  'framingFor(o.kind, shot.plan), series: o.series || null,\n'
                  '        side: v && v.photo ? { side: v.side, camera: o.camera, photo: v.photo } : null,\n'
