                 '    const isView = VIEW_ORDER.indexOf(o.kind) !== -1 && !o.series;\n'
                 '    const baseId = o.from || sc.queue.find(q => { const x = arr(st.outputs).find(y => y.id '
                 '=== q); return x && VIEW_ORDER.indexOf(x.kind) !== -1 && !x.series; });\n'
                 '    const shared = Boolean(o.edit_from_result) || (!roomLocked && ((o.from && baseId) || '
                 '(cfg.views_share_one_room === true && isView && baseId && baseId !== id)));\n'
