                 '  const band = Math.max(2, Math.round(0.04 * Math.min(w, h)));\n'
                 '  const hist = [new Uint32Array(256), new Uint32Array(256), new Uint32Array(256)];\n'
                 '  let seen = 0, whitish = 0;\n'
                 '  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {\n'
                 '    if (!(y < band || y >= h - band || x < band || x >= w - band)) continue;\n'
                 '    const i = y * w + x, hi = Math.max(R[i], G[i], B[i]), lo = Math.min(R[i], G[i], '
                 'B[i]);\n'
                 '    seen++;\n'
                 '    if (lo >= 205 && hi - lo <= 30) { whitish++; hist[0][R[i]]++; hist[1][G[i]]++; '
                 'hist[2][B[i]]++; }\n'
                 '  }\n'
                 '  const whiteShare = seen ? Math.round(1000 * whitish / seen) / 10 : 0;\n'
                 '  wc.edge_band_near_white_pct = whiteShare;\n'
                 "  if (whiteShare < 50) throw new Error('the edge of the master is not near-white (' + "
                 "whiteShare + '% of it), so its background was left as it is');\n"
                 '  const top = [0, 0, 0], knee = [0, 0, 0], lut = [new Uint8Array(256), new '
                 'Uint8Array(256), new Uint8Array(256)];\n'
                 '  for (let c = 0; c < 3; c++) {\n'
                 '    let acc = 0, v = 205;\n'
                 '    while (v < 255 && acc + hist[c][v] < 0.05 * whitish) { acc += hist[c][v]; v += 1; }\n'
                 '    top[c] = Math.max(228, Math.min(253, v - 2));\n'
                 '    knee[c] = top[c] - 22;\n'
                 '    for (let i = 0; i < 256; i++) lut[c][i] = i >= top[c] ? 255 : (i > knee[c] ? '
                 'Math.round(knee[c] + (i - knee[c]) * (255 - knee[c]) / (top[c] - knee[c])) : i);\n'
                 '  }\n'
                 '  const kneeMin = Math.min(knee[0], knee[1], knee[2]);\n'
                 '  wc.white_from = top; wc.curve_starts_at = knee;\n'
                 '  // 1b. Fit (owner, 20 Oct 2026, run claude-a7-4f80c2bf): a master framed so tight that '
                 'the protected box leaves no safe margin at an\n'
                 '  //     image edge used to hold the package. It is now placed on a white canvas in code: '
                 "scaled down (never up) so the product's longest\n"
                 '  //     side spans the white-master framing setting (FIT_SPAN_PCT), and the product box '
                 'centred. No AI, nothing redrawn: the picture is\n'
                 '  //     resampled once more (bilinear), like the resize before it, and the new canvas is '
                 '255. The white point above was read from the\n'
                 "  //     master's own edge before the canvas is added, so the fill still reaches the "
                 "master's own background. Only a master that would\n"
                 '  //     otherwise hold is fitted; any other keeps its framing.\n'
                 '  const boxPx = bx => {\n'
                 '    const mg0 = MARGIN / 1000;\n'
                 '    return [Math.max(0, Math.floor((bx[1] / 1000 - mg0) * w)), Math.max(0, '
                 'Math.floor((bx[0] / 1000 - mg0) * h)),\n'
                 '      Math.min(w - 1, Math.ceil((bx[3] / 1000 + mg0) * w)), Math.min(h - 1, '
                 'Math.ceil(bx[2] / 1000 * h))];\n'
                 '  };\n'
                 '  const unsafe = bx => { const p = boxPx(bx); return Math.min(p[0], w - 1 - p[2], p[1], h '
                 '- 1 - p[3]) <= GUARD; };\n'
                 '  // Phase 1.3 (FL-5, owner, 22 Oct 2026): only a whole product is fitted, and the '
