                  'const GUARD = 8;    // px of fully white background kept at every image edge, for codec '
                  'edge blocks\n'
                  'const FIT_SPAN_PCT = Number(pk.cfg && pk.cfg.fit_span_pct) || 76; // white-master framing '
                  'setting: the longest side spans 76% of the frame\n'
                  'function bmpInfo(b) {\n'
                  "  if (b.length < 54 || b[0] !== 0x42 || b[1] !== 0x4d) throw new Error('not a BMP "
                  "file');\n"
