                  '  const head = b.readUInt32LE(14);\n'
                  '  const w = b.readInt32LE(18);\n'
                  '  const rawH = b.readInt32LE(22);\n'
                  '  const h = Math.abs(rawH);\n'
                  '  const bits = b.readUInt16LE(28);\n'
                  '  const comp = b.readUInt32LE(30);\n'
                  '  if ((bits !== 24 && bits !== 32) || (comp !== 0 && comp !== 3)) throw new '
                  "Error('unsupported BMP: ' + bits + ' bits, compression ' + comp);\n"
                  '  let ri = 2, gi = 1, bi = 0;\n'
                  '  if (comp === 3 && bits === 32) {\n'
                  '    const at = head >= 52 ? 54 : 14 + head;\n'
                  '    const byteOf = mask => (mask === 0xff ? 0 : (mask === 0xff00 ? 1 : (mask === 0xff0000 '
                  '? 2 : 3)));\n'
                  '    ri = byteOf(b.readUInt32LE(at)); gi = byteOf(b.readUInt32LE(at + 4)); bi = '
                  'byteOf(b.readUInt32LE(at + 8));\n'
                  '  }\n'
                  '  const stride = Math.floor((bits * w + 31) / 32) * 4;\n'
                  "  if (w < 8 || h < 8 || off + stride * h > b.length) throw new Error('BMP size does not "
                  "match its header');\n"
                  '  return { w, h, bytes: bits / 8, off, stride, bottomUp: rawH > 0, ri, gi, bi };\n'
                  '}\n'
                  'function boxOf(v) {\n'
                  '  const b = Array.isArray(v) ? v.map(Number) : [];\n'
                  '  return b.length === 4 && b.every(x => Number.isFinite(x) && x >= 0 && x <= 1000) && '
                  'b[0] < b[2] && b[1] < b[3] && !b.every(x => x <= 1) ? b : null;\n'
                  '}\n'
                  "const wc = { done: false, method: 'background set to 255 in code (no AI): a fill from the "
                  'image border through pixels at or above the white point only, the soft curve of the white '
                  "clean-up workflow on a ' + BAND + ' px band around it, nothing changed inside the product "
                  "box from the review; the contact shadow and the product are not changed (measured)', "
                  'band_px: BAND, box_margin_of_1000: MARGIN, ramp_pct: RAMP_PCT };\n'
                  'let cleanBin = null;\n'
                  'const SKIP = { skip: true };\n'
                  '// Owner, 16 Oct 2026, 19:26 (Phase 1 question 1): with no product box the master is '
                  'still packaged, but the background is NOT cleaned\n'
                  "// (the clean-up could eat into a white or cream product's edges without the box). The "
                  "master's own background is delivered and the\n"
                  "// skip is recorded; 18h measures the saved files' edges and reports them, without the "
                  '255 rule. Every step that needs the box is listed.\n'
                  'const SKIPPED_NO_BOX = [\n'
                  "  { step: 'background set to 255 (the clean-up and its fade around the product)', why: "
                  "'it needs the product box, so the product\\'s edges are not touched without it' },\n"
                  "  { step: 'framing band check (white master 72-80% on the longest side)', why: 'it needs "
                  "the product box; not measured' }\n"
                  '];\n'
                  'try {\n'
                  '  let box = boxOf(pk.product_box_2d);\n'
                  '  wc.product_box_2d = box;\n'
                  "  if (!bin.pix) throw new Error('the master could not be turned into pixels (Edit Image "
                  "gave no BMP' + (item.json && item.json.error ? ': ' + String(item.json.error.message || "
                  "item.json.error).slice(0, 160) : '') + ')');\n"
                  "  const b = await this.helpers.getBinaryDataBuffer(0, 'pix');\n"
                  '  const m = bmpInfo(b);\n'
                  '  const w = m.w, h = m.h, N = w * h;\n'
                  "  if (w !== pk.cfg.size_px || h !== pk.cfg.size_px) throw new Error('the pixels are ' + w "
                  "+ ' x ' + h + ', not ' + pk.cfg.size_px + ' x ' + pk.cfg.size_px);\n"
                  '  if (!box) {\n'
                  '    wc.skipped = true; wc.done = false; wc.cleaned = false;\n'
                  "    wc.skip_reason = 'no usable product box (box_2d) from the review';\n"
                  '    wc.skipped_steps = SKIPPED_NO_BOX;\n'
                  "    wc.method = 'background not cleaned: no product box from the review, so the "
                  "master\\'s own background is delivered unchanged';\n"
                  "    cleanBin = await this.helpers.prepareBinaryData(b, pk.base + '_clean.bmp', "
                  "'image/bmp');\n"
                  '    throw SKIP; // leaves the try block: nothing below runs; the picture goes on '
                  'unchanged\n'
                  '  }\n'
                  '  const R = new Uint8Array(N), G = new Uint8Array(N), B = new Uint8Array(N);\n'
                  '  for (let y = 0; y < h; y++) {\n'
                  '    const base = m.off + (m.bottomUp ? h - 1 - y : y) * m.stride;\n'
                  '    for (let x = 0; x < w; x++) { const p = base + x * m.bytes, i = y * w + x; R[i] = b[p '
                  '+ m.ri]; G[i] = b[p + m.gi]; B[i] = b[p + m.bi]; }\n'
                  '  }\n'
                  "  // 1. The background sample from the outer edge band (as the white clean-up's C9 "
                  'does).\n'
                  '  const band = Math.max(2, Math.round(0.04 * Math.min(w, h)));\n'
                  '  const hist = [new Uint32Array(256), new Uint32Array(256), new Uint32Array(256)];\n'
                  '  let seen = 0, whitish = 0;\n'
                  '  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {\n'
                  '    if (!(y < band || y >= h - band || x < band || x >= w - band)) continue;\n'
                  '    const i = y * w + x, hi = Math.max(R[i], G[i], B[i]), lo = Math.min(R[i], G[i], '
                  'B[i]);\n'
                  '    seen++;\n'
                  '    if (lo >= 205 && hi - lo <= 30) { whitish++; hist[0][R[i]]++; hist[1][G[i]]++; '
                  'hist[2][B[i]]++; }\n'
                  '  }\n'
                  '  const whiteShare = seen ? Math.round(1000 * whitish / seen) / 10 : 0;\n'
                  '  wc.edge_band_near_white_pct = whiteShare;\n'
                  "  if (whiteShare < 50) throw new Error('the edge of the master is not near-white (' + "
                  "whiteShare + '% of it), so its background was left as it is');\n"
                  '  const top = [0, 0, 0], knee = [0, 0, 0], lut = [new Uint8Array(256), new '
                  'Uint8Array(256), new Uint8Array(256)];\n'
                  '  for (let c = 0; c < 3; c++) {\n'
                  '    let acc = 0, v = 205;\n'
                  '    while (v < 255 && acc + hist[c][v] < 0.05 * whitish) { acc += hist[c][v]; v += 1; }\n'
                  '    top[c] = Math.max(228, Math.min(253, v - 2));\n'
                  '    knee[c] = top[c] - 22;\n'
                  '    for (let i = 0; i < 256; i++) lut[c][i] = i >= top[c] ? 255 : (i > knee[c] ? '
                  'Math.round(knee[c] + (i - knee[c]) * (255 - knee[c]) / (top[c] - knee[c])) : i);\n'
                  '  }\n'
                  '  const kneeMin = Math.min(knee[0], knee[1], knee[2]);\n'
                  '  wc.white_from = top; wc.curve_starts_at = knee;\n'
                  '  // 1b. Fit (owner, 20 Oct 2026, run claude-a7-4f80c2bf): a master framed so tight that '
                  'the protected box leaves no safe margin at an\n'
                  '  //     image edge used to hold the package. It is now placed on a white canvas in code: '
                  "scaled down (never up) so the product's longest\n"
                  '  //     side spans the white-master framing setting (FIT_SPAN_PCT), and the product box '
                  'centred. No AI, nothing redrawn: the picture is\n'
                  '  //     resampled once more (bilinear), like the resize before it, and the new canvas is '
                  '255. The white point above was read from the\n'
                  "  //     master's own edge before the canvas is added, so the fill still reaches the "
                  "master's own background. Only a master that would\n"
                  '  //     otherwise hold is fitted; any other keeps its framing.\n'
                  '  const boxPx = bx => {\n'
                  '    const mg0 = MARGIN / 1000;\n'
                  '    return [Math.max(0, Math.floor((bx[1] / 1000 - mg0) * w)), Math.max(0, '
                  'Math.floor((bx[0] / 1000 - mg0) * h)),\n'
                  '      Math.min(w - 1, Math.ceil((bx[3] / 1000 + mg0) * w)), Math.min(h - 1, '
                  'Math.ceil(bx[2] / 1000 * h))];\n'
                  '  };\n'
                  '  const unsafe = bx => { const p = boxPx(bx); return Math.min(p[0], w - 1 - p[2], p[1], h '
                  '- 1 - p[3]) <= GUARD; };\n'
                  '  // Phase 1.3 (FL-5, owner, 22 Oct 2026): only a whole product is fitted, and the '
                  'delivered files keep FIT_SPAN_PCT +/- TOL on the\n'
                  '  // longest side (rule 20). A product that is cut off, or not confirmed whole by a '
                  'review of these bytes, is never scaled or framed in\n'
                  '  // code (rule 17); one below the band is never enlarged. Each of these holds with a '
                  'plain reason.\n'
                  '  const TOL = pk.cfg && Number.isFinite(pk.cfg.fit_tolerance_pts) ? '
                  'pk.cfg.fit_tolerance_pts : 3;\n'
                  '  const spanNow = Math.round(Math.max(box[3] - box[1], box[2] - box[0])) / 10;\n'
                  '  const whole = pk.whole_in_frame || {};\n'
                  '  const needsFit = unsafe(box) || spanNow > FIT_SPAN_PCT + TOL;\n'
                  "  wc.framing_rule = { measure: 'longest side of the product box', target_pct: "
                  'FIT_SPAN_PCT, tolerance_pts: TOL, span_before_pct: spanNow, whole_in_frame: whole };\n'
                  '  if (needsFit && !(whole.known === true && whole.cut_off === false && whole.disagree !== '
                  'true)) {\n'
                  "    wc.hold_kind = 'framing';\n"
                  "    throw new Error(whole.cut_off === true ? 'the review found the product cut off at the "
                  "frame edge, so it is not scaled or framed in code; a cut-off product is never delivered'\n"
                  "      : whole.disagree === true ? 'the review was unsure whether the product is cut off "
                  "at the frame edge, so it is not scaled or framed in code'\n"
                  "      : 'no review of this image confirmed the whole product is in the frame, so it is "
                  "not scaled or framed in code');\n"
                  '  }\n'
                  '  if (!needsFit && spanNow < FIT_SPAN_PCT - TOL) {\n'
                  "    wc.hold_kind = 'framing';\n"
                  "    throw new Error('the product spans ' + spanNow + '% of the frame on its longest side, "
                  "below ' + (FIT_SPAN_PCT - TOL) + '% (the white catalogue framing is ' + FIT_SPAN_PCT + '% "
                  "+/- ' + TOL + '); it is never enlarged');\n"
                  '  }\n'
                  '  if (needsFit) {\n'
                  '    const spanBefore = spanNow;\n'
                  '    const s = Math.min(1, FIT_SPAN_PCT / spanBefore);\n'
                  '    const cx = (box[1] + box[3]) / 2000 * w, cy = (box[0] + box[2]) / 2000 * h;\n'
                  '    const R2 = new Uint8Array(N), G2 = new Uint8Array(N), B2 = new Uint8Array(N);\n'
                  '    for (let Y = 0; Y < h; Y++) for (let X = 0; X < w; X++) {\n'
                  '      const o = Y * w + X;\n'
                  '      const sx = cx + (X + 0.5 - w / 2) / s - 0.5, sy = cy + (Y + 0.5 - h / 2) / s - '
                  '0.5;\n'
                  '      if (sx < -0.5 || sy < -0.5 || sx > w - 0.5 || sy > h - 0.5) { R2[o] = 255; G2[o] = '
                  '255; B2[o] = 255; continue; }\n'
                  '      const x0 = Math.max(0, Math.min(w - 1, Math.floor(sx))), y0 = Math.max(0, '
                  'Math.min(h - 1, Math.floor(sy)));\n'
                  '      const x1 = Math.min(w - 1, x0 + 1), y1 = Math.min(h - 1, y0 + 1);\n'
                  '      const fx = Math.max(0, Math.min(1, sx - x0)), fy = Math.max(0, Math.min(1, sy - '
                  'y0));\n'
                  '      const a = y0 * w + x0, b1 = y0 * w + x1, c = y1 * w + x0, d = y1 * w + x1;\n'
                  '      const mix = A => Math.round((A[a] * (1 - fx) + A[b1] * fx) * (1 - fy) + (A[c] * (1 '
                  '- fx) + A[d] * fx) * fy);\n'
                  '      R2[o] = mix(R); G2[o] = mix(G); B2[o] = mix(B);\n'
                  '    }\n'
                  '    R.set(R2); G.set(G2); B.set(B2);\n'
                  '    const to1000 = (v, side, c0) => Math.round(((v / 1000 * side - c0) * s + side / 2) / '
                  'side * 1000);\n'
                  '    const fitted = [to1000(box[0], h, cy), to1000(box[1], w, cx), to1000(box[2], h, cy), '
                  'to1000(box[3], w, cx)];\n'
                  "    wc.fit = { done: true, why: unsafe(box) ? 'the product box left no safe background "
                  "margin at an image edge' : 'the product spanned ' + spanBefore + '% of the frame, above ' "
                  "+ (FIT_SPAN_PCT + TOL) + '%', scale: Math.round(s * 1000) / 1000,\n"
                  '      span_before_pct: Math.round(spanBefore * 10) / 10, span_after_pct: '
                  'Math.round(spanBefore * s * 10) / 10, target_span_pct: FIT_SPAN_PCT,\n'
                  '      box_2d_before: box, box_2d_after: fitted,\n'
                  "      method: 'scaled by ' + (Math.round(s * 1000) / 1000) + ' (bilinear) and centred on "
                  "a white (255) canvas in code; no AI, nothing redrawn' };\n"
                  '    box = fitted;\n'
                  '    wc.product_box_2d = box;\n'
                  '  }\n'
                  '  // 2. The product box in pixels: widened by MARGIN on the top, left and right; the '
                  'bottom edge (the contact shadow side) is not widened.\n'
                  '  const RAMP = Math.max(8, Math.round(RAMP_PCT / 100 * Math.min(w, h)));\n'
                  '  wc.ramp_px = RAMP;\n'
                  '  const mg = MARGIN / 1000;\n'
                  '  const bx0 = Math.max(0, Math.floor((box[1] / 1000 - mg) * w)), bx1 = Math.min(w - 1, '
                  'Math.ceil((box[3] / 1000 + mg) * w));\n'
                  '  const by0 = Math.max(0, Math.floor((box[0] / 1000 - mg) * h)), by1 = Math.min(h - 1, '
                  'Math.ceil(box[2] / 1000 * h));\n'
                  '  wc.product_box_px = [bx0, by0, bx1, by1];\n'
                  '  const inBox = (x, y) => x >= bx0 && x <= bx1 && y >= by0 && y <= by1;\n'
                  '  // Fit the fade to each available margin. A fixed 68 px fade left narrow borders\n'
                  '  // unfinished. Keep eight fully white background pixels for codec edge blocks.\n'
                  '  const guard = GUARD;\n'
                  '  const gaps = { left: bx0, right: w - 1 - bx1, top: by0, bottom: h - 1 - by1 };\n'
                  "  if (Object.values(gaps).some(v => v <= guard)) throw new Error('the protected product "
                  "box leaves no safe background margin at an image edge');\n"
                  '  const ramps = Object.fromEntries(Object.entries(gaps).map(([k, v]) => [k, '
                  'Math.min(RAMP, v - guard)]));\n'
                  '  wc.edge_guard_px = guard; wc.side_ramps_px = ramps;\n'
                  '  // None inside the box; every fade finishes before the codec edge band.\n'
                  '  const weight = (x, y) => {\n'
                  '    const dx = x < bx0 ? (bx0 - x) / ramps.left : (x > bx1 ? (x - bx1) / ramps.right : '
                  '0);\n'
                  '    const dy = y < by0 ? (by0 - y) / ramps.top : (y > by1 ? (y - by1) / ramps.bottom : '
                  '0);\n'
                  '    return Math.min(1, Math.hypot(dx, dy));\n'
                  '  };\n'
                  '  // 3. The fill from the border, only through pixels at or above the white point (every '
                  'channel), never into the box.\n'
                  '  const white = i => R[i] >= top[0] && G[i] >= top[1] && B[i] >= top[2];\n'
                  '  const region = new Uint8Array(N);\n'
                  '  const stack = new Int32Array(N);\n'
                  '  let sp = 0;\n'
                  '  const tryAdd = (i, x, y) => { if (!region[i] && !inBox(x, y) && white(i)) { region[i] = '
                  '1; stack[sp++] = i; } };\n'
                  '  for (let x = 0; x < w; x++) { tryAdd(x, x, 0); tryAdd((h - 1) * w + x, x, h - 1); }\n'
                  '  for (let y = 0; y < h; y++) { tryAdd(y * w, 0, y); tryAdd(y * w + w - 1, w - 1, y); }\n'
                  '  while (sp) {\n'
                  '    const i = stack[--sp], x = i % w, y = (i - x) / w;\n'
                  '    if (x > 0) tryAdd(i - 1, x - 1, y);\n'
                  '    if (x < w - 1) tryAdd(i + 1, x + 1, y);\n'
                  '    if (y > 0) tryAdd(i - w, x, y - 1);\n'
                  '    if (y < h - 1) tryAdd(i + w, x, y + 1);\n'
                  '  }\n'
                  '  let inRegion = 0;\n'
                  '  for (let i = 0; i < N; i++) inRegion += region[i];\n'
                  '  wc.background_pct = Math.round(1000 * inRegion / N) / 10;\n'
                  "  if (wc.background_pct < 10) throw new Error('only ' + wc.background_pct + '% of the "
                  "image was found as background connected to the border; nothing was changed');\n"
                  '  // 4. The thin band around the fill (BAND px, 8 neighbours per step), outside the box: '
                  'these get the soft curve. Only near-white, low\n'
                  '  //    colour pixels above the knee belong to it (the faint edge of the shadow, soft '
                  'background); a darker or coloured pixel never does.\n'
                  '  const soft = j => { const hi = Math.max(R[j], G[j], B[j]), lo = Math.min(R[j], G[j], '
                  'B[j]); return lo > kneeMin && hi - lo <= 30; };\n'
                  '  const ring = new Uint8Array(N);\n'
                  '  let front = region;\n'
                  '  for (let k = 0; k < BAND; k++) {\n'
                  '    const next = new Uint8Array(N);\n'
                  '    for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {\n'
                  '      const i = y * w + x;\n'
                  '      if (!front[i]) continue;\n'
                  '      for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {\n'
                  '        const xx = x + dx, yy = y + dy;\n'
                  '        if (xx < 0 || yy < 0 || xx >= w || yy >= h) continue;\n'
                  '        const j = yy * w + xx;\n'
                  '        if (!region[j] && !ring[j] && !inBox(xx, yy) && soft(j)) { ring[j] = 1; next[j] = '
                  '1; }\n'
                  '      }\n'
                  '    }\n'
                  '    front = next;\n'
                  '  }\n'
                  '  // 5. Write the picture. Every change is counted where it happens: inside the box, and '
                  'on pixels darker than the knee.\n'
                  '  // Owner, 16 Oct 2026, 19:26 (Phase 1 question 3), the fade is accepted on three '
                  'conditions, each measured here:\n'
                  '  // (a) the fade stays within a small margin outside the box (RAMP px): no pixel farther '
                  'than RAMP from the box is only partly changed;\n'
                  '  // (b) beyond that margin every background pixel is exactly 255; (c) nothing inside the '
                  'product box changes (boxChanged, below).\n'
                  '  // 18h then checks the saved files for a grey halo.\n'
                  '  let changed = 0, ringChanged = 0, boxChanged = 0, darkChanged = 0, white255After = 0, '
                  'beyondNot255 = 0, partialBeyond = 0, fadeMax = 0;\n'
                  '  const stride = Math.floor((24 * w + 31) / 32) * 4;\n'
                  '  const ob = Buffer.alloc(54 + stride * h);\n'
                  "  ob.write('BM', 0, 'latin1'); ob.writeUInt32LE(ob.length, 2); ob.writeUInt32LE(54, 10); "
                  'ob.writeUInt32LE(40, 14);\n'
                  '  ob.writeInt32LE(w, 18); ob.writeInt32LE(h, 22); ob.writeUInt16LE(1, 26); '
                  'ob.writeUInt16LE(24, 28); ob.writeUInt32LE(stride * h, 34);\n'
                  '  ob.writeInt32LE(2835, 38); ob.writeInt32LE(2835, 42);\n'
                  '  for (let y = 0; y < h; y++) {\n'
                  '    const obase = 54 + (h - 1 - y) * stride;\n'
                  '    for (let x = 0; x < w; x++) {\n'
                  '      const i = y * w + x;\n'
                  '      let r = R[i], g = G[i], bl = B[i];\n'
                  '      if (region[i] || ring[i]) {\n'
                  '        const wt = weight(x, y);\n'
                  '        const nr = Math.round(r + (lut[0][r] - r) * wt), ng = Math.round(g + (lut[1][g] - '
                  'g) * wt), nb = Math.round(bl + (lut[2][bl] - bl) * wt);\n'
                  '        if (nr !== r || ng !== g || nb !== bl) {\n'
                  '          changed++;\n'
                  '          if (ring[i]) ringChanged++;\n'
                  '          if (inBox(x, y)) boxChanged++;\n'
                  '          if (Math.min(r, g, bl) <= kneeMin) darkChanged++;\n'
                  '        }\n'
                  '        r = nr; g = ng; bl = nb;\n'
                  '        if (region[i] && r === 255 && g === 255 && bl === 255) white255After++;\n'
                  '        if (wt < 1 && wt > 0 && (nr !== R[i] || ng !== G[i] || nb !== B[i])) { const dx = '
                  'x < bx0 ? bx0 - x : (x > bx1 ? x - bx1 : 0), dy = y < by0 ? by0 - y : (y > by1 ? y - by1 '
                  ': 0); const dd = Math.sqrt(dx * dx + dy * dy); if (dd > fadeMax) fadeMax = dd; if (dd > '
                  'RAMP) partialBeyond++; }\n'
                  '        if (region[i] && wt >= 1 && !(r === 255 && g === 255 && bl === 255)) '
                  'beyondNot255++;\n'
                  '      }\n'
                  '      const q = obase + x * 3;\n'
                  '      ob[q] = bl; ob[q + 1] = g; ob[q + 2] = r;\n'
                  '    }\n'
                  '  }\n'
                  '  wc.pixels_changed_pct = Math.round(1000 * changed / N) / 10;\n'
                  '  wc.band_pixels_changed = ringChanged;\n'
                  '  wc.background_255_after_pct = inRegion ? Math.round(1000 * white255After / inRegion) / '
                  '10 : 0;\n'
                  '  // Measured, not assumed (review finding 1): pixels changed inside the product box, and '
                  'pixels darker than the knee that changed.\n'
                  '  wc.product_box_pixels_changed = boxChanged;\n'
                  '  wc.darker_than_knee_changed = darkChanged;\n'
                  '  wc.fade_margin_px = RAMP;\n'
                  '  wc.fade_reach_px = Math.round(fadeMax);\n'
                  '  wc.partly_changed_beyond_margin = partialBeyond;\n'
                  '  wc.background_beyond_margin_not_255 = beyondNot255;\n'
                  "  if (boxChanged || darkChanged) throw new Error('the clean-up would have changed ' + "
                  "boxChanged + ' pixels inside the product box and ' + darkChanged + ' pixels darker than "
                  "the background; nothing was changed');\n"
                  "  if (partialBeyond || beyondNot255) throw new Error('the fade reached past its ' + RAMP "
                  "+ ' px margin (' + partialBeyond + ' pixels) or left ' + beyondNot255 + ' background "
                  "pixels beyond the margin below 255; nothing was changed');\n"
                  '  wc.done = true; wc.cleaned = true;\n'
                  "  cleanBin = await this.helpers.prepareBinaryData(ob, pk.base + '_clean.bmp', "
                  "'image/bmp');\n"
                  '} catch (e) {\n'
                  '  if (e !== SKIP) { wc.done = false; wc.problem = String((e && e.message) || e).slice(0, '
                  '300); }\n'
                  '}\n'
                  'pk.white_clean = wc;\n'
                  'if (wc.skipped) {\n'
                  '  // Packaged without the clean-up (owner, 19:26): pk.ok stays as it was; the steps that '
                  'need the box are listed as skipped.\n'
