                 '    const okBox = e.length === 4 && e.every(x => Number.isFinite(x) && x >= 0 && x <= 100) '
                 '&& e[0] < e[2] && e[1] < e[3] && !e.every(x => x <= 1); // edges all at or under 1 look '
                 'like fractions, not percentages: not used\n'
                 '    const m = String((rv.candidate && rv.candidate.px) || '
                 "'').match(/^(\\d+)\\s*x\\s*(\\d+)$/);\n"
                 '    const W = m ? Number(m[1]) : 0, H = m ? Number(m[2]) : 0;\n'
                 '    if (okBox) {\n'
                 '      const wPct = e[2] - e[0], hPct = e[3] - e[1];\n'
                 '      const wide = W && H ? wPct * W >= hPct * H : wPct >= hPct;\n'
                 "      out.side = wide ? 'width' : 'height';\n"
                 '      out.measured_share_pct = Math.round(wide ? wPct : hPct);\n'
                 "      out.source = 'the blind count\\'s box' + (ok2 ? ' (box_2d, 0-1000)' : '') + (W && H "
                 "? ' and the image size ' + W + ' x ' + H : ' (image size not recorded: the frame was taken "
                 "as square)');\n"
                 '    } else if (reviewer.share !== null && reviewer.share <= 100) { out.measured_share_pct '
                 "= reviewer.share; out.source = 'the reviewer\\'s estimate (the reviewer is told the "
                 "target; the blind count gave no usable box)'; }\n"
                 '    if (out.measured_share_pct !== null) out.within = out.measured_share_pct >= b[0] && '
                 'out.measured_share_pct <= b[1];\n'
                 "    const dir = out.side ? ' (its ' + out.side + ')' : '';\n"
                 "    out.fix = type === 'white'\n"
                 "      ? 'Reframe the white master: the product\\'s longest side should span about ' + "
                 "(Number(f.white_span_pct) || 76) + '% of the frame, with about ' + "
                 "(Number(f.white_margin_pct) || 12) + '% white margin at each end of that side' + "
                 "(out.measured_share_pct !== null ? '; it spans about ' + out.measured_share_pct + '% now' "
                 ": '') + '.'\n"
                 "      : 'Reframe the ' + type + ' view: the product\\'s longest side' + dir + ' should "
                 "span about ' + b[0] + '-' + b[1] + '% of the frame' + (out.measured_share_pct !== null ? "
                 "'; it spans about ' + out.measured_share_pct + '% now, so move the camera ' + "
                 "(out.measured_share_pct < b[0] ? 'closer' : 'further back') : '') + ', keeping the room, "
                 "the pieces and the light.';\n"
                 '  }\n'
                 "  const view = type === 'white' ? 'white master' : type + ' view';\n"
                 "  if (out.within === true) out.note = 'Framing (' + view + '): about ' + "
                 "out.measured_share_pct + '%, within ' + out.rule_short + '.';\n"
                 "  else if (out.within === false) out.note = 'Framing (' + view + '): about ' + "
                 "out.measured_share_pct + '%' + (out.side ? ' of the frame ' + out.side : '') + '; the rule "
                 "is ' + out.rule_short + '. A styling note: the image is not failed for it. A reframe runs "
                 "only if the owner orders a repair.';\n"
                 "  else out.note = 'Framing (' + view + '): the share could not be read from the review. A "
                 "styling note, not a failure.';\n"
                 '  return out;\n'
                 '}\n'
                 "const st = JSON.parse(JSON.stringify($('V1 Vault events').first().json));\n"
                 'delete st.events; delete st.row;\n'
                 "const rv = $('16a Review ticket').first().json.rv;\n"
                 "const isScene = rv.kind === 'scene';\n"
                 '// Edit phase 1 (19 Oct 2026): an owner edit adds its own check (16a asks it only then); a '
                 'fail fails the image like any other check.\n'
                 "const CHECKS = (isScene ? SCENE_CHECKS : WHITE_CHECKS).concat(rv.edit ? ['edit_applied'] : "
                 "[], rv.edit_base ? ['unchanged_from_base'] : []);\n"
                 "NAMES.edit_applied = 'requested edit applied, kept parts unchanged';\n"
                 '// Edit phase 2.4 (19 Oct 2026): an edit of an approved image is also checked against that '
                 'image (16a sends it last); counted like edit_applied.\n'
                 "NAMES.unchanged_from_base = 'everything the edit does not name is as in the approved "
                 "image';\n"
                 "if (isScene) NAMES.framing = 'framing (' + ((rv.scene && rv.scene.framing) || 'hero') + ' "
                 "view as ordered)';\n"
                 "const CODE_ONLY = isScene ? ['whole_in_frame'] : []; // set by code only (the blind "
                 'count), never asked of the reviewer for a scene\n'
                 'let settings = {};\n'
                 "try { settings = $('04 Settings').first().json || {}; } catch (e) { settings = {}; }\n"
                 '// "Nothing repairs itself" (owner, 16 Oct 2026, D5): a repair runs only when the owner '
                 'orders it at go 2, whatever 04 Settings says.\n'
                 'const autoRepair = false;\n'
                 'const now = new Date().toISOString();\n'
                 'const attempt = Number(rv.attempt) || 1;\n'
                 'const obs = st.observation || {};\n'
                 '// Keep the category focus with the exact candidate review; existing verdict policy still '
                 'decides.\n'
                 "const categoryRequirements = arr(rv.category_checks).filter(x => typeof x === 'string');\n"
                 'const review = { output_id: rv.output_id, attempt, at: now, candidate: rv.candidate, '
                 "category_requirements: categoryRequirements, result: '', checks: {}, defects: [], unsure: "
                 "[], counts: {}, framing: null, styling_notes: [], scores: null, score_label: 'Reviewer "
                 "judgement, not a measurement. Never the 90 to 95 fidelity target.', summary: '', readers: "
                 "'claude-sonnet-5-5 (review against the vendor photo) + gemini-3.8-flash (blind count) + "
                 "code' };\n"
                 '// Review again (D3): one per candidate image, that is per output and attempt (review '
                 'finding 12: a repair makes a new candidate, which\n'
                 '// may have its own review again). It is recorded in the state when the owner orders it '
                 '(G2).\n'
                 'const ra = st.review_again && st.review_again.output_id === rv.output_id && '
                 'Number(st.review_again.attempt) === attempt ? st.review_again : null;\n'
                 "if (ra) review.review_again = { ordered_at: ra.ordered_at || '', by: 'owner' };\n"
                 "// Token counts of this round's calls (P1.8). Prices: st.text_prices, written at intake "
                 '(01 Intent & scope).\n'
                 'const P = st.text_prices || {};\n'
                 'function textCall(node, model, raw) {\n'
                 '  if (!raw) return;\n'
                 '  const u = usageOf(raw);\n'
                 '  const pr = P.models && P.models[model] ? P.models[model] : null;\n'
                 '  const usd = u && pr ? Number(((u.input * pr.input + u.output * pr.output) / '
                 '1e6).toFixed(5)) : null;\n'
                 '  const rec = { step: 16, node, model, output_id: rv.output_id, attempt, at: now, tokens: '
                 "u, usd, error: raw.error ? short(raw.error, 120) : '', basis: u ? (pr ? 'provider token "
                 "counts x prices read ' + (P.read_on || '?') + ' (' + (pr.source || '') + '); an estimate, "
                 "not an invoice' : 'provider token counts; no price recorded for this model') : 'the "
                 "provider reported no token counts (the call may still be charged)' };\n"
                 '  st.text_calls = arr(st.text_calls).concat([rec]);\n'
                 '  st.text_calls_new = arr(st.text_calls_new).concat([rec]);\n'
                 '}\n'
                 "let fail = '';\n"
                 'if (!rv.ready) fail = rv.why;\n'
                 "let critic = null, blind = null, oneAnswered = '';\n"
                 'if (!fail) {\n'
                 "  const rawC = out('16 Critic review');\n"
                 "  const c = reading(rawC, 'The reviewer');\n"
                 "  // Fallback blind count (owner, 16 Oct 2026): gpt-6.1-sol counts only when Gemini's "
                 'blind count of this round returned an error.\n'
                 "  const bMain = out('16x Blind count');\n"
                 "  const bBack = bMain && bMain.error ? out('16xb Blind count fallback (OpenAI)') : null;\n"
                 "  const b = bBack ? reading(bBack, 'The fallback blind count (gpt-6.1-sol, after Gemini "
                 "did not answer)') : reading(bMain, 'The blind count');\n"
                 "  textCall('16 Critic review', 'claude-sonnet-5-5', rawC);\n"
                 "  textCall('16x Blind count', 'gemini-3.8-flash', bMain);\n"
                 "  if (bBack) textCall('16xb Blind count fallback (OpenAI)', 'gpt-6.1-sol', bBack);\n"
                 "  review.blind_reader = bBack ? 'gpt-6.1-sol (fallback; Gemini did not answer)' : "
                 "'gemini-3.8-flash';\n"
                 "  if (bBack) review.readers = 'claude-sonnet-5-5 (review against the vendor photo) + "
                 "gpt-6.1-sol (blind count, fallback after Gemini did not answer) + code';\n"
                 "  if (c.fail || b.fail) fail = [c.fail, b.fail].filter(Boolean).join(' ') + ' The "
                 "candidate is not reviewed.';\n"
                 '  critic = c.data; blind = b.data;\n'
                 "  if (fail && (critic || blind)) oneAnswered = critic ? 'reviewer' : 'blind count';\n"
                 '}\n'
                 "const isDetail = Boolean(isScene && rv.scene && rv.scene.framing === 'detail');\n"
                 "// D6: where the blind count's box lies against the frame (box_2d [ymin, xmin, ymax, xmax] "
                 'on 0-1000).\n'
                 'function boxEdge(b) {\n'
                 '  const b2 = b && Array.isArray(b.box_2d) ? b.box_2d.map(Number) : [];\n'
                 '  if (!(b2.length === 4 && b2.every(x => Number.isFinite(x) && x >= 0 && x <= 1000) && '
                 'b2[0] < b2[2] && b2[1] < b2[3] && !b2.every(x => x <= 1))) return null;\n'
                 '  return Math.min(b2[0], b2[1], 1000 - b2[2], 1000 - b2[3]);\n'
                 '}\n'
                 "// P1.10: the reviewer's checks are written into the record whenever the reviewer "
                 'answered, even when the round is not reviewed.\n'
                 'function fillChecks(c) {\n'
                 "  const checks = c && typeof c.checks === 'object' && c.checks ? c.checks : {};\n"
                 '  for (const k of CHECKS) {\n'
                 "    const x = checks[k] && typeof checks[k] === 'object' ? checks[k] : null;\n"
                 "    const r = x ? clean(x.result, 10).toLowerCase() : '';\n"
                 "    review.checks[k] = { result: ['pass', 'fail', 'unsure'].indexOf(r) !== -1 ? r : 'not "
                 "answered', evidence: x ? clean(x.evidence, 240) : '' };\n"
                 '  }\n'
                 '  return checks;\n'
                 '}\n'
                 'if (fail && critic) {\n'
                 '  const checks = fillChecks(critic);\n'
                 '  review.counts = { contract: Number(rv.total) || 0, reviewer: num(checks.piece_count && '
                 'checks.piece_count.seen), blind: null };\n'
                 '  // Review finding 8 (16 Oct 2026): the D5 note-only checks (light, camera level, '
                 'realism, framing) stay notes here too, never defects.\n'
                 '  const noteOnlyP = isScene ? SCENE_NOTE_ONLY : [];\n'
                 '  review.notes_only = [];\n'
                 '  for (const k of CHECKS) {\n'
                 '    const r = review.checks[k].result;\n'
                 "    if (noteOnlyP.indexOf(k) !== -1 && r !== 'pass') { review.notes_only.push({ check: k, "
                 "name: NAMES[k], result: r, evidence: review.checks[k].evidence, fix: '' }); continue; }\n"
                 "    if (r === 'fail') review.defects.push({ check: k, name: NAMES[k], what: "
                 "review.checks[k].evidence, where: '', fix: '' }); else if (r !== 'pass') "
                 'review.unsure.push({ check: k, name: NAMES[k], result: r, evidence: '
                 'review.checks[k].evidence });\n'
                 '  }\n'
                 "  const sc = critic.scores && typeof critic.scores === 'object' ? critic.scores : null;\n"
                 "  if (sc) { review.scores = {}; for (const k of ['fidelity', 'integrity', 'drift', "
                 "'data_loss']) { const v = num(sc[k]); review.scores[k] = v !== null && v <= 100 ? v : "
                 'null; } }\n'
                 "  review.score_label = 'From an incomplete review (the blind count did not answer): the "
                 "reviewer\\'s judgement only, not a measurement, not a passed review, and never the 90 to "
                 "95 fidelity target.';\n"
                 '  review.summary = clean(critic.summary, 300);\n'
                 "  review.partial = 'Only the reviewer answered; the blind count did not. These findings "
                 "are kept for the record; the candidate is not reviewed.';\n"
                 '}\n'
                 'if (fail && !critic && blind) {\n'
                 '  review.counts = { contract: Number(rv.total) || 0, reviewer: null, blind: '
                 'num(blind.total) };\n'
                 "  review.partial = 'Only the blind count answered (' + (num(blind.total) === null ? 'no "
                 "count' : num(blind.total) + ' pieces') + '); the reviewer did not. The candidate is not "
                 "reviewed.';\n"
                 '}\n'
                 "if (fail) review.result = 'not reviewed';\n"
                 'if (!fail) {\n'
                 '  const checks = fillChecks(critic);\n'
                 '  // Counts: the contract, the reviewer (who knew the contract) and the blind count (who '
                 'did not). Code compares them.\n'
                 '  const expected = Number(rv.total) || 0;\n'
                 '  const criticSeen = num(checks.piece_count && checks.piece_count.seen);\n'
                 '  const blindSeen = num(blind && blind.total);\n'
                 '  review.counts = { contract: expected, reviewer: criticSeen, blind: blindSeen };\n'
                 '  const fixes = {};\n'
                 '  for (const d of arr(critic && critic.defects).slice(0, 12)) {\n'
                 '    const k = clean(d && d.check, 40);\n'
                 '    if (!k) continue;\n'
                 '    fixes[k] = { what: clean(d.what, 240), where: clean(d.where, 120), fix: clean(d.fix, '
                 '240) };\n'
                 '  }\n'
                 '  function codeDefect(k, what, fix) {\n'
                 "    review.checks[k] = { result: 'fail', evidence: (review.checks[k] && "
                 "review.checks[k].result === 'fail' ? review.checks[k].evidence + ' ' : '') + 'Code: ' + "
                 'what };\n'
                 "    if (!fixes[k]) fixes[k] = { what, where: '', fix };\n"
                 '  }\n'
                 '  // A detail view need not show the whole product (owner, 16 Oct 2026, 04:16): fewer '
                 'pieces in the frame is not a defect; more is.\n'
                 '  review.counts.detail_view = isDetail;\n'
                 '  const countWrong = n => n !== null && (isDetail ? n > expected : n !== expected);\n'
                 "  const countFix = isDetail ? 'Show no more than the ' + expected + ' product pieces of "
                 "the vendor photo, with none duplicated or invented; a detail view may show fewer.' : 'Show "
                 "exactly ' + expected + ' product pieces, as in the vendor photo: no more and no fewer.';\n"
                 "  if (countWrong(blindSeen)) codeDefect('piece_count', 'the blind count found ' + "
                 "blindSeen + ' product pieces; the contract holds ' + expected + (isDetail ? ' (a detail "
                 "view may show fewer, never more)' : '') + '.', countFix);\n"
                 "  if (countWrong(criticSeen)) codeDefect('piece_count', 'the reviewer counted ' + "
                 "criticSeen + ' product pieces; the contract holds ' + expected + (isDetail ? ' (a detail "
                 "view may show fewer, never more)' : '') + '.', countFix);\n"
                 "  if (!isScene && blind && blind.background_white === false) codeDefect('background', 'the "
                 "blind count reports a background that is not pure white.', 'Make the background pure white "
                 "(#FFFFFF) at every edge, with no grey tone, gradient, floor line or horizon.');\n"
                 "  if (blind && blind.text_or_logo === true) codeDefect('no_text_or_logo', 'the blind count "
                 "reports text, a logo or a watermark.', 'Remove all text, logos and watermarks.');\n"
                 '  // D6 (owner, 16 Oct 2026): cut off by the frame is decided in code from the blind '
                 'count\'s box where it gives one; its "cropped" flag\n'
                 '  // alone decides only when no usable box came back. Not in a detail view (the whole '
                 'product is not required there).\n'
                 '  if (!isDetail) {\n'
                 '    const edge = boxEdge(blind);\n'
                 '    const flagged = Boolean(blind && blind.cropped === true);\n'
                 '    const cut = edge !== null ? edge <= EDGE : flagged;\n'
                 '    review.crop = { box_edge: edge, edge_limit: EDGE, reader_flag: flagged, decided_by: '
                 "edge !== null ? 'code, from the blind count\\'s box (0-1000)' : (blind ? 'the blind "
                 "count\\'s flag (no usable box)' : 'not known'), cut_off: cut, hidden: blind && "
                 'Array.isArray(blind.hidden) ? blind.hidden.slice(0, 12).map(x => String(x).slice(0, 160)) '
                 ': [] };\n'
                 "    if (cut) codeDefect('whole_in_frame', edge !== null ? 'the product\\'s box reaches the "
                 "frame edge (' + edge + ' of 1000 from it; the limit is ' + EDGE + '), so part of the "
                 "product is cut off by the frame.' : 'the blind count reports the product cut off by the "
                 "frame and gave no usable box.', isScene ? 'Show the whole product inside the frame.' : "
                 "'Show the whole product inside the frame with white space on every side.');\n"
                 '    else if (flagged) {\n'
                 '      // Review finding 5 (16 Oct 2026): the box and the flag disagree, so the check is '
                 '"unsure" (not passed), never a quiet note. The\n'
                 '      // owner still decides at go 2. A piece hidden behind another may be what the reader '
                 'meant; that is not a crop.\n'
                 '      review.crop.disagree = true;\n'
                 '      const ev = \'Code: the blind count said "cropped", but its box is \' + edge + \' of '
                 "1000 from the nearest frame edge (the limit is ' + EDGE + '). The two disagree, so this is "
                 'unsure, not passed. A piece hidden behind another is not a crop; please look at the frame '
                 "edges.';\n"
                 '      if (!(review.checks.whole_in_frame && review.checks.whole_in_frame.result === '
                 "'fail')) review.checks.whole_in_frame = { result: 'unsure', evidence: ev };\n"
                 '    }\n'
                 '  }\n'
                 "  review.framing = framingReading(checks.framing && typeof checks.framing === 'object' ? "
                 'checks.framing : null, blind);\n'
                 '  if (review.framing.within === false || review.framing.within === null) '
                 'review.styling_notes.push(review.framing.note);\n'
                 '  const noteOnly = isScene ? SCENE_NOTE_ONLY : [];\n'
                 '  review.notes_only = [];\n'
                 '  for (const k of CHECKS.concat(CODE_ONLY.filter(k => review.checks[k]))) {\n'
                 '    const r = review.checks[k].result;\n'
                 "    if (noteOnly.indexOf(k) !== -1 && r !== 'pass') {\n"
                 '      // D5: noted, never a failure. Its fix goes into the proposed repair the owner may '
                 'order.\n'
                 '      review.notes_only.push({ check: k, name: NAMES[k], result: r, evidence: '
                 "review.checks[k].evidence, fix: (fixes[k] && fixes[k].fix) || '' });\n"
                 "      review.styling_notes.push('Styling note (' + NAMES[k] + ', ' + r + '): ' + "
                 "(review.checks[k].evidence || 'no evidence given') + ' A note only: the image is not "
                 "failed for it.');\n"
                 '      continue;\n'
                 '    }\n'
                 "    if (r === 'fail') review.defects.push({ check: k, name: NAMES[k], what: (fixes[k] && "
                 "fixes[k].what) || review.checks[k].evidence, where: (fixes[k] && fixes[k].where) || '', "
                 "fix: (fixes[k] && fixes[k].fix) || '' });\n"
                 "    else if (r !== 'pass') review.unsure.push({ check: k, name: NAMES[k], result: r, "
                 'evidence: review.checks[k].evidence });\n'
                 '  }\n'
                 "  const sc = critic && critic.scores && typeof critic.scores === 'object' ? critic.scores "
                 ': null;\n'
                 "  if (sc) { review.scores = {}; for (const k of ['fidelity', 'integrity', 'drift', "
                 "'data_loss']) { const v = num(sc[k]); review.scores[k] = v !== null && v <= 100 ? v : "
                 'null; } }\n'
                 '  review.summary = clean(critic && critic.summary, 300);\n'
                 "  review.result = review.defects.length ? 'failed' : (review.unsure.length ? 'unsure' : "
                 "'passed');\n"
                 '}\n'
                 "// Review finding 1 (16 Oct 2026): the blind count's product box is kept with the review, "
                 'so the delivery files (18e3) can leave the\n'
                 '// product untouched. Recorded whenever the blind count answered with a usable box, '
                 'reviewed or not.\n'
                 'if (blind && boxEdge(blind) !== null) { review.product_box_2d = blind.box_2d.map(Number); '
                 'review.product_box_flagged = blind.cropped === true; } // flag: Phase 1.3 follow-up\n'
                 '// What a scene repair keeps of the room. A view made from the approved base view keeps '
                 'its room, pieces and light, not its camera.\n'
                 'function roomKeep() {\n'
                 '  const sc0 = st.scene || {};\n'
                 "  const r = arr(sc0.refs).find(x => x.role === 'room');\n"
                 '  const n = r && r.n ? r.n : 3;\n'
                 '  // Edit phase 2.4: an edit keeps everything in the approved image it starts from except '
                 "what the owner's edit names.\n"
                 "  if (sc0.room && sc0.room.content === 'approved view' && sc0.room.edit) { const ch = "
                 "arr(sc0.room.changes); return 'everything in the approved image ' + (sc0.room.from_output "
                 "|| '') + ' of the earlier version (image ' + n + ' of the scene request) except what the "
                 "owner-requested edit names' + (ch.indexOf('camera') !== -1 ? ' and the camera view' : '') "
                 "+ (ch.indexOf('light') !== -1 ? ' and the light' : ''); }\n"
                 '  // A series image changes one thing from the approved image it is made from (16 Oct '
                 '2026): the light, or the camera.\n'
                 "  if (sc0.room && sc0.room.content === 'approved view' && "
                 "arr(sc0.room.changes).indexOf('light') !== -1 && arr(sc0.room.changes).indexOf('camera') "
                 "=== -1) return 'the room, every Midas piece where it stands, and the camera of the "
                 "approved image of ' + (sc0.room.from_output || 'the base view') + ' (image ' + n + ' of "
                 "the scene request); only the light differs';\n"
                 "  if (sc0.room && sc0.room.content === 'approved view') return 'the room, every Midas "
                 "piece where it stands, and the light of the approved ' + (sc0.room.from_kind || 'base') + "
                 "' view (image ' + n + ' of the scene request); only the camera differs';\n"
                 "  return 'the room as it is (image ' + n + ' of the scene request)';\n"
                 '}\n'
                 '// The repair order: corrections from the review, written against the vendor photo, plus '
                 'what must not change.\n'
                 "// withNotes: the owner may order a repair for a styling note too (framing, and D5's "
                 'light, camera level and realism); never automatic.\n'
                 'function repairOrder(withNotes) {\n'
                 "  const corr = review.defects.map(d => d.fix || ('Correct the ' + d.name + ': ' + "
                 'd.what)).filter(Boolean).map(t => clean(t, 300)).slice(0, 8);\n'
                 '  if (withNotes && review.framing && review.framing.within === false && '
                 'review.framing.fix) corr.push(review.framing.fix);\n'
                 '  if (withNotes) for (const x of arr(review.notes_only)) corr.push(clean(x.fix || '
                 "('Correct the ' + x.name + ': ' + x.evidence), 300));\n"
                 "  const preserve = ['the exact inventory: ' + arr(st.inventory).map(x => x.count + ' x ' + "
                 "x.item).join('; ')]\n"
                 "    .concat(isScene ? [roomKeep()].concat(arr(st.scene && st.scene.props).map(p => 'the "
                 "Midas piece ' + p.name + ' (SKU ' + p.sku + ') exactly as catalogued')) : [])\n"
                 "    .concat(obs.colour_observed ? ['the colour as in the vendor photo (' + "
                 "clean(obs.colour_observed, 120) + ')'] : [])\n"
                 "    .concat(arr(obs.sided_parts).map(sidedText).filter(Boolean).map(x => 'handedness: ' + "
                 'clean(x, 120)))\n'
                 '    .concat(arr(obs.design_locks).slice(0, 8).map(x => clean(x, 160)))\n'
                 '    .concat(review.checks ? Object.keys(review.checks).filter(k => review.checks[k].result '
                 "=== 'pass').map(k => NAMES[k] + ' (passed in the review)') : []);\n"
