                                                 'const clientRunId = clean(p.clientRunId || '
                                                 'p.client_run_id, 90);\n'
                                                 'if (clientRunId.length < 8 || clientRunId.length > 80) '
                                                 "problems.push('The job id must be 8 to 80 characters.');\n"
                                                 "// Phase 1.5 (FL-2, owner, 22 Oct 2026): every paid step's "
