                                                 '// part of a reply (so an echoed instruction is never read '
                                                 "as the answer); textCall records the provider's own token "
                                                 'counts.\n'
                                                 'function bodyOf(o) {\n'
                                                 "  if (!o || typeof o !== 'object') return o;\n"
                                                 '  if (Array.isArray(o.output)) return o.output;\n'
                                                 '  if (Array.isArray(o.candidates)) return o.candidates;\n'
                                                 '  if (o.content !== undefined) return o.content;\n'
                                                 '  if (o.message !== undefined) return o.message;\n'
                                                 '  return o;\n'
                                                 '}\n'
                                                 'function usageOf(o) {\n'
                                                 "  if (!o || typeof o !== 'object') return null;\n"
                                                 '  const u = o.usage || o.usageMetadata || (o.response && '
                                                 'o.response.usage) || null;\n'
                                                 "  if (!u || typeof u !== 'object') return null;\n"
                                                 '  const n = v => (Number.isFinite(Number(v)) && Number(v) '
                                                 '>= 0 ? Math.round(Number(v)) : 0);\n'
                                                 '  if (u.promptTokenCount !== undefined || '
                                                 'u.candidatesTokenCount !== undefined) return { input: '
                                                 'n(u.promptTokenCount), output: n(u.candidatesTokenCount) + '
                                                 'n(u.thoughtsTokenCount) };\n'
                                                 '  if (u.input_tokens !== undefined || u.output_tokens !== '
                                                 'undefined) return { input: n(u.input_tokens) + '
                                                 'n(u.cache_read_input_tokens) + '
                                                 'n(u.cache_creation_input_tokens), output: '
                                                 'n(u.output_tokens) };\n'
                                                 '  if (u.prompt_tokens !== undefined) return { input: '
                                                 'n(u.prompt_tokens), output: n(u.completion_tokens) };\n'
                                                 '  return null;\n'
                                                 '}\n'
                                                 'function textCall(state, step, node, model, raw) {\n'
                                                 '  if (!raw) return state;\n'
                                                 '  const P = state.text_prices || {};\n'
                                                 '  const u = usageOf(raw);\n'
                                                 '  const pr = P.models && P.models[model] ? P.models[model] '
                                                 ': null;\n'
                                                 '  const usd = u && pr ? Number(((u.input * pr.input + '
                                                 'u.output * pr.output) / 1e6).toFixed(5)) : null;\n'
                                                 "  const e = raw.error ? (typeof raw.error === 'string' ? "
                                                 'raw.error : String((raw.error && raw.error.message) || '
                                                 "JSON.stringify(raw.error))).split('\\n')[0].slice(0, 120) "
                                                 ": '';\n"
                                                 '  const rec = { step, node, model, at: new '
                                                 'Date().toISOString(), tokens: u, usd, error: e, basis: u ? '
                                                 "(pr ? 'provider token counts x prices read ' + (P.read_on "
                                                 "|| '?') + ' (' + (pr.source || '') + '); an estimate, not "
                                                 "an invoice' : 'provider token counts; no price recorded "
