                                                 "it stays fully visible and countable.');\n"
                                                 'for (const x of scene) for (const w of (x.code_warnings || '
                                                 "[])) warnings.push('Shot ' + x.n + ': ' + w);\n"
                                                 'for (const n of (s.retrieval.notes || [])) '
                                                 'warnings.push(n);\n'
                                                 'const midas = [];\n'
