                                                 'stage 04 only.\n'
                                                 'function stage04Precheck() {\n'
                                                 '  const arrX = v => (Array.isArray(v) ? v : []);\n'
                                                 '  const inv = arrX(s.inventory);\n'
                                                 '  const total = inv.reduce((t, x) => t + (Number(x.count) '
                                                 '|| 0), 0);\n'
                                                 '  const obs0 = s.observation || {};\n'
                                                 '  const holds = [];\n'
                                                 "  if (!inv.length || !total) holds.push('the contract has "
                                                 "no inventory');\n"
                                                 "  if (obs0.cropped === true) holds.push('the vendor photo "
                                                 "is cropped (part of the product is outside the frame)');\n"
                                                 "  const SYN = { 'bedside table': 'nightstand', 'night "
                                                 "stand': 'nightstand', 'side table': 'table', lamp: "
                                                 "'light', chandelier: 'light', pendant: 'light', sconce: "
                                                 "'light', lantern: 'light' };\n"
                                                 '  const sing = w => { const x = String(w || '
                                                 "'').toLowerCase(); if (/(ches|shes|xes)$/.test(x)) return "
                                                 'x.slice(0, -2); if (/[^s]s$/.test(x)) return x.slice(0, '
                                                 '-1); return x; };\n'
                                                 '  const headOf = v => {\n'
