                                                 "  'Intimate / Cozy', 'Expressive / Vibrant'];\n"
                                                 "const PRESET_MENU = ['Daylight overview', 'Editorial "
                                                 "hero', 'Golden-hour atmosphere', 'Evening comfort'];\n"
                                                 '\n'
                                                 "const ROLES = ['hero', 'midas_support', "
                                                 "'generic_context'];\n"
                                                 "const WEIGHTS_ = ['light', 'medium', 'heavy'];\n"
                                                 "const SILS = ['angular', 'curved', 'mixed'];\n"
