                                                 "'fabric', 'leather', 'other'];\n"
                                                 "const UNDERTONES = ['warm', 'cool', 'neutral'];\n"
                                                 "const TEXTURES = ['smooth', 'medium', 'rough'];\n"
                                                 "const PALETTE = ['dominant_60', 'secondary_30', "
                                                 "'accent_10'];\n"
                                                 "const AVAIL = ['in_stock', 'pre_order', 'out_of_stock', "
                                                 "'not_confirmed'];\n"
                                                 "const BASIS = ['vendor_stated', 'catalogue_stated', "
                                                 "'observed_in_photo', 'estimated_from_photo'];\n"
                                                 "const OUTPUTS = ['white_background', 'lifestyle', "
                                                 "'website_package'];\n"
                                                 "const DESCRIPTIVE = ['style', 'visual_weight', "
                                                 "'silhouette', 'finishes', 'texture', 'colour_hex', "
                                                 "'dimensions_cm'];\n"
                                                 "const PILLARS = ['scale_proportion', 'silhouette_lines', "
                                                 "'materials_finishes', 'colour_distribution',\n"
                                                 "  'texture_contrast', 'function_practicality', "
                                                 "'focal_point', 'style_cohesion'];\n"
