                                                 "    if (p.dimensions_cm) for (const k of ['width', "
                                                 "'depth', 'height']) {\n"
                                                 '      const v = p.dimensions_cm[k]; if (!isNil(v) && '
                                                 "!(typeof v === 'number' && v > 0)) "
                                                 'e.push(`${at}.dimensions_cm.${k} must be > 0`);\n'
                                                 '    }\n'
                                                 '    if (!isNil(p.colour_hex) && '
