                                                 '    if (!s || !s.name || !s.colour) '
                                                 'e.push(`surfaces[${i}]: name and colour are required`);\n'
                                                 '    oneOf(s && s.role, PALETTE, `surfaces[${i}].role`);\n'
                                                 '    if (s && !isNil(s.area_share) && !(s.area_share >= 0 '
                                                 '&& s.area_share <= 1)) e.push(`surfaces[${i}].area_share '
                                                 'must be 0 to 1`);\n'
                                                 '  });\n'
                                                 "  oneOf(req.output, OUTPUTS, 'output');\n"
                                                 "  oneOf(req.style, STYLE_MENU, 'style');\n"
                                                 "  oneOf(req.ambience, AMBIENCE_MENU, 'ambience');\n"
                                                 "  oneOf(req.preset, PRESET_MENU, 'preset');\n"
                                                 '  if (!isNil(req.max_midas_pieces) && '
                                                 '!(Number.isInteger(req.max_midas_pieces) && '
                                                 'req.max_midas_pieces >= 0 && req.max_midas_pieces <= 6)) '
                                                 "e.push('max_midas_pieces must be 0 to 6');\n"
                                                 '  if (req.weights) {\n'
                                                 '    for (const [k, v] of Object.entries(req.weights)) {\n'
                                                 '      if (!PILLARS.includes(k)) e.push(`weights.${k} is '
                                                 'not a pillar`);\n'
                                                 '      else if (!(Number.isInteger(v) && v >= 0 && v <= '
                                                 '100)) e.push(`weights.${k} must be 0 to 100`);\n'
                                                 '    }\n'
                                                 '    const w = { ...DEFAULT_W, ...req.weights };\n'
                                                 "    if (PILLARS.every((k) => w[k] === 0)) e.push('at least "
                                                 "one weight must be above 0');\n"
                                                 '  } else if (!isNil(req.profile) && !(req.profile in '
                                                 'PROFILES)) e.push(`unknown profile '
                                                 '${JSON.stringify(req.profile)}`);\n'
                                                 '  return e;\n'
                                                 '}\n'
                                                 '\n'
                                                 '// '
                                                 '---------------------------------------------------------------- '
                                                 'pillars\n'
                                                 'const R = (pillar, result, reason, fix = null) => ({ '
                                                 'pillar, result, reason, fix });\n'
                                                 'const known = (ps, a) => ps.filter((p) => !isNil(p[a]));\n'
                                                 'const pct = (r) => `${Math.round(r * 100)}%`;\n'
                                                 '\n'
                                                 'function selectPieces(req, hero) {\n'
                                                 '  const kept = [hero]; const excluded = []; let midasUsed '
                                                 '= 0;\n'
