                                                 '  const n = v => (Number.isFinite(Number(v)) && Number(v) '
                                                 '>= 0 ? Math.round(Number(v)) : 0);\n'
                                                 '  if (u.promptTokenCount !== undefined || '
                                                 'u.candidatesTokenCount !== undefined) return { input: '
                                                 'n(u.promptTokenCount), output: n(u.candidatesTokenCount) + '
                                                 'n(u.thoughtsTokenCount) };\n'
                                                 '  if (u.input_tokens !== undefined || u.output_tokens !== '
                                                 'undefined) return { input: n(u.input_tokens) + '
                                                 'n(u.cache_read_input_tokens) + '
                                                 'n(u.cache_creation_input_tokens), output: '
                                                 'n(u.output_tokens) };\n'
                                                 '  if (u.prompt_tokens !== undefined) return { input: '
                                                 'n(u.prompt_tokens), output: n(u.completion_tokens) };\n'
                                                 '  return null;\n'
                                                 '}\n'
                                                 'function deepText(o) {\n'
                                                 "  if (o === null || o === undefined) return '';\n"
                                                 "  if (typeof o === 'string') return o.indexOf('{') !== -1 "
                                                 "? o : '';\n"
                                                 '  if (Array.isArray(o)) { for (const x of o) { const t = '
                                                 "deepText(x); if (t) return t; } return ''; }\n"
                                                 "  if (typeof o === 'object') {\n"
                                                 "    if (typeof o.text === 'string' && o.text.indexOf('{') "
                                                 '!== -1) return o.text;\n'
                                                 '    for (const k of Object.keys(o)) { const t = '
                                                 'deepText(o[k]); if (t) return t; }\n'
                                                 '  }\n'
                                                 "  return '';\n"
                                                 '}\n'
                                                 'function parse(t) { if (!t) return null; const a = '
                                                 "t.indexOf('{'), b = t.lastIndexOf('}'); if (a < 0 || b < "
                                                 'a) return null; try { return JSON.parse(t.slice(a, b + '
                                                 '1)); } catch (e) { return null; } }\n'
                                                 'function out(name) { try { return $(name).first().json; } '
                                                 'catch (e) { return null; } }\n'
                                                 "function short(v, n) { const t = typeof v === 'string' ? v "
                                                 ': (v && v.message) ? String(v.message) : '
                                                 'JSON.stringify(v); return String(t || '
                                                 "'').split('\\n')[0].slice(0, n); }\n"
                                                 'function clean(v, n) { return v === null || v === '
                                                 "undefined ? '' : String(v).replace(/\\s+/g, ' "
                                                 "').trim().slice(0, n || 300); }\n"
                                                 'function num(v) { const n = Math.round(Number(v)); return '
                                                 'Number.isFinite(n) && n >= 0 ? n : null; }\n'
                                                 'const arr = v => (Array.isArray(v) ? v : []);\n'
                                                 'function reading(raw, label) {\n'
                                                 "  if (!raw) return { data: null, fail: label + ' did not "
                                                 "answer.' };\n"
                                                 "  if (raw.error) return { data: null, fail: label + ' did "
                                                 "not answer (' + short(raw.error, 120) + ').' };\n"
                                                 '  const data = parse(deepText(bodyOf(raw)));\n'
                                                 "  if (!data) return { data: null, fail: label + ' "
                                                 "answered, but not in the expected format.' };\n"
                                                 "  return { data, fail: '' };\n"
                                                 '}\n'
                                                 'const MAX_ATTEMPT = 3; // the first try and at most two '
                                                 'repairs\n'
                                                 "const WHITE_CHECKS = ['piece_count', 'pieces_match', "
                                                 "'shape', 'colour', 'material_texture', 'details', "
                                                 "'handedness', 'not_mirrored', 'nothing_added', "
                                                 "'excluded_absent', 'context_removed', 'background', "
                                                 "'contact_shadow', 'whole_in_frame', 'no_text_or_logo', "
                                                 "'realism'];\n"
                                                 '// Stage 07 (16 Oct 2026): a placed scene has its own '
                                                 'checks (see 16a).\n'
                                                 '// 16 Oct 2026 (owner decisions 22 and 23): people_ok and '
                                                 'no_unplanned_lamp; a fail on either fails the image like '
                                                 'any other check.\n'
                                                 "const SCENE_CHECKS = ['piece_count', 'pieces_match', "
                                                 "'shape', 'colour', 'material_texture', 'details', "
                                                 "'handedness', 'not_mirrored', 'nothing_added', "
                                                 "'excluded_absent', 'only_listed_props', "
                                                 "'midas_pieces_match', 'people_ok', 'no_unplanned_lamp', "
                                                 "'scale', 'grounding', 'camera_level', 'light', "
                                                 "'no_text_or_logo', 'realism'];\n"
                                                 '// D5 (owner, 16 Oct 2026, 11:45): in a scene these are '
                                                 'notes only. A fail or unsure on them never fails the '
                                                 'image; it is shown at go 2\n'
                                                 '// and goes into the proposed repair, which runs only if '
                                                 'the owner orders it.\n'
                                                 "const SCENE_NOTE_ONLY = ['camera_level', 'light', "
                                                 "'realism'];\n"
                                                 'const EDGE = 15; // D6: a box edge within 15 of 1000 of '
                                                 'the frame edge counts as cut off by the frame (as in 04-06 '
                                                 'Evidence, fix 3)\n'
                                                 "const NAMES = { piece_count: 'piece count', pieces_match: "
                                                 "'each piece present once', shape: 'shape', colour: "
                                                 "'colour', material_texture: 'material and texture', "
                                                 "details: 'identifying details', handedness: 'left/right "
                                                 "handedness', not_mirrored: 'not mirrored', nothing_added: "
                                                 "'nothing invented or added', excluded_absent: 'excluded "
                                                 "pieces absent', context_removed: 'room context left out', "
                                                 "background: 'pure white background', contact_shadow: "
                                                 "'subtle contact shadow', whole_in_frame: 'whole product in "
                                                 "frame', framing: 'framing (about 12% white margin, about "
                                                 "76% span)', no_text_or_logo: 'no text, logo or watermark', "
                                                 "realism: 'photographic realism',\n"
                                                 "  only_listed_props: 'only the product, the listed Midas "
                                                 "pieces and the room shell', midas_pieces_match: 'Midas "
                                                 "pieces exactly as catalogued', people_ok: 'people as "
                                                 'ordered (none, or one adult beside or behind the '
                                                 "product)', no_unplanned_lamp: 'no lamp except a listed "
                                                 "Midas lamp', scale: 'plausible scale', grounding: "
                                                 "'grounded, natural contact shadows', camera_level: 'camera "
                                                 "as ordered, straight verticals', light: 'consistent light' "
                                                 '};\n'
                                                 '\n'
                                                 '// Framing reading (owner, 16 Oct 2026, 04:16): the '
                                                 "product's bounding box on its longest side, against the "
                                                 "frame's side in the same\n"
                                                 "// direction. The share comes from the blind count's box "
                                                 "(it is not told the target) and the candidate's pixel "
                                                 "size; the reviewer's\n"
                                                 '// own share is kept beside it. Both are model readings of '
                                                 'the image, not a pixel measurement.\n'
                                                 'function framingReading(crit, blind) {\n'
                                                 '  const f = settings.framing || {};\n'
                                                 '  const fr = rv.framing || { type: isScene ? ((rv.scene && '
                                                 "rv.scene.framing) || 'hero') : 'white' };\n"
                                                 "  const type = fr.type || (isScene ? 'hero' : 'white');\n"
                                                 '  const bandOf = (v, d) => { const a = arr(v).map(Number); '
                                                 'return a.length === 2 && a.every(Number.isFinite) && a[0] '
                                                 '< a[1] ? a : d; };\n'
                                                 '  const reviewer = crit ? { result: clean(crit.result, '
                                                 "10).toLowerCase() || 'not answered', evidence: "
                                                 'clean(crit.evidence, 240), share: num(crit.share) } : { '
                                                 "result: 'not answered', evidence: '', share: null };\n"
                                                 "  const out = { view: type, rule: '', rule_short: '', "
                                                 'band_pct: null, min_pct: null, measured_share_pct: null, '
                                                 "side: '', source: '', within: null, reviewer, note: '', "
                                                 "fix: '', label: 'A reading of the image by the review "
                                                 'models, not a pixel measurement. Framing is a styling '
                                                 "check: it never fails the image on its own.' };\n"
                                                 "  if (type === 'detail') {\n"
                                                 '    const min = Number(fr.min_pct) || '
                                                 'Number(f.detail_min_pct) || 50;\n'
                                                 "    out.min_pct = min; out.rule = 'the named detail (' + "
                                                 "(fr.detail || 'not named') + ') fills most of the frame, "
                                                 "more than ' + min + '%'; out.rule_short = 'more than ' + "
                                                 "min + '%';\n"
                                                 '    if (reviewer.share !== null && reviewer.share <= 100) '
                                                 '{ out.measured_share_pct = reviewer.share; out.source = '
                                                 "'the reviewer\\'s estimate (the reviewer is told the "
                                                 "target)'; out.within = reviewer.share > min; }\n"
                                                 "    out.fix = 'Reframe the detail view: move the camera "
                                                 'closer so the named detail fills most of the frame (more '
                                                 "than ' + min + '%), keeping the room, the pieces and the "
                                                 "light.';\n"
                                                 '  } else {\n'
                                                 "    const b = type === 'white' ? "
                                                 'bandOf(f.white_note_band_pct, [72, 80]) : '
                                                 "bandOf(fr.band_pct, type === 'wide' ? "
                                                 'bandOf(f.wide_span_pct, [40, 55]) : '
                                                 'bandOf(f.hero_span_pct, [60, 70]));\n'
                                                 '    out.band_pct = b;\n'
                                                 "    out.rule = (type === 'white' ? 'white master: about ' "
                                                 "+ (Number(f.white_span_pct) || 76) + '% (a note outside ' "
                                                 "+ b[0] + '-' + b[1] + '%)' : type + ' view: ' + b[0] + '-' "
                                                 "+ b[1] + '%') + ' of the frame, on the product\\'s longest "
                                                 "side';\n"
                                                 "    out.rule_short = b[0] + '-' + b[1] + '%';\n"
                                                 '    // S6 (prompt check, 16 Oct 2026): the blind count now '
                                                 'gives "box_2d" [ymin, xmin, ymax, xmax] on 0-1000 '
                                                 "(Gemini's own format);\n"
                                                 '    // it is turned into left, top, right, bottom '
                                                 'percentages here. The older percentage box is still read '
                                                 'when box_2d is missing.\n'
                                                 '    const b2 = blind && Array.isArray(blind.box_2d) ? '
                                                 'blind.box_2d.map(Number) : [];\n'
                                                 '    const ok2 = b2.length === 4 && b2.every(x => '
                                                 'Number.isFinite(x) && x >= 0 && x <= 1000) && b2[0] < '
                                                 'b2[2] && b2[1] < b2[3] && !b2.every(x => x <= 1);\n'
                                                 '    const bx = ok2 ? null : (blind && blind.box && typeof '
                                                 "blind.box === 'object' ? blind.box : null);\n"
                                                 '    const e = ok2 ? [b2[1] / 10, b2[0] / 10, b2[3] / 10, '
                                                 "b2[2] / 10] : (bx ? ['left', 'top', 'right', "
                                                 "'bottom'].map(k => Number(bx[k])) : []);\n"
                                                 '    const okBox = e.length === 4 && e.every(x => '
                                                 'Number.isFinite(x) && x >= 0 && x <= 100) && e[0] < e[2] '
                                                 '&& e[1] < e[3] && !e.every(x => x <= 1); // edges all at '
                                                 'or under 1 look like fractions, not percentages: not used\n'
                                                 '    const m = String((rv.candidate && rv.candidate.px) || '
                                                 "'').match(/^(\\d+)\\s*x\\s*(\\d+)$/);\n"
                                                 '    const W = m ? Number(m[1]) : 0, H = m ? Number(m[2]) : '
                                                 '0;\n'
                                                 '    if (okBox) {\n'
                                                 '      const wPct = e[2] - e[0], hPct = e[3] - e[1];\n'
                                                 '      const wide = W && H ? wPct * W >= hPct * H : wPct >= '
                                                 'hPct;\n'
                                                 "      out.side = wide ? 'width' : 'height';\n"
                                                 '      out.measured_share_pct = Math.round(wide ? wPct : '
                                                 'hPct);\n'
                                                 "      out.source = 'the blind count\\'s box' + (ok2 ? ' "
                                                 "(box_2d, 0-1000)' : '') + (W && H ? ' and the image size ' "
                                                 "+ W + ' x ' + H : ' (image size not recorded: the frame "
                                                 "was taken as square)');\n"
                                                 '    } else if (reviewer.share !== null && reviewer.share '
                                                 '<= 100) { out.measured_share_pct = reviewer.share; '
                                                 "out.source = 'the reviewer\\'s estimate (the reviewer is "
                                                 "told the target; the blind count gave no usable box)'; }\n"
                                                 '    if (out.measured_share_pct !== null) out.within = '
                                                 'out.measured_share_pct >= b[0] && out.measured_share_pct '
                                                 '<= b[1];\n'
                                                 "    const dir = out.side ? ' (its ' + out.side + ')' : "
                                                 "'';\n"
                                                 "    out.fix = type === 'white'\n"
                                                 "      ? 'Reframe the white master: the product\\'s longest "
                                                 "side should span about ' + (Number(f.white_span_pct) || "
                                                 "76) + '% of the frame, with about ' + "
                                                 "(Number(f.white_margin_pct) || 12) + '% white margin at "
                                                 "each end of that side' + (out.measured_share_pct !== null "
                                                 "? '; it spans about ' + out.measured_share_pct + '% now' : "
                                                 "'') + '.'\n"
                                                 "      : 'Reframe the ' + type + ' view: the product\\'s "
                                                 "longest side' + dir + ' should span about ' + b[0] + '-' + "
                                                 "b[1] + '% of the frame' + (out.measured_share_pct !== null "
                                                 "? '; it spans about ' + out.measured_share_pct + '% now, "
                                                 "so move the camera ' + (out.measured_share_pct < b[0] ? "
                                                 "'closer' : 'further back') : '') + ', keeping the room, "
                                                 "the pieces and the light.';\n"
                                                 '  }\n'
                                                 "  const view = type === 'white' ? 'white master' : type + "
                                                 "' view';\n"
                                                 "  if (out.within === true) out.note = 'Framing (' + view + "
                                                 "'): about ' + out.measured_share_pct + '%, within ' + "
                                                 "out.rule_short + '.';\n"
                                                 "  else if (out.within === false) out.note = 'Framing (' + "
                                                 "view + '): about ' + out.measured_share_pct + '%' + "
                                                 "(out.side ? ' of the frame ' + out.side : '') + '; the "
                                                 "rule is ' + out.rule_short + '. A styling note: the image "
                                                 'is not failed for it. A reframe runs only if the owner '
                                                 "orders a repair.';\n"
                                                 "  else out.note = 'Framing (' + view + '): the share could "
                                                 'not be read from the review. A styling note, not a '
                                                 "failure.';\n"
                                                 '  return out;\n'
                                                 '}\n'
                                                 "const st = JSON.parse(JSON.stringify($('V1 Vault "
                                                 "events').first().json));\n"
                                                 'delete st.events; delete st.row;\n'
                                                 "const rv = $('16a Review ticket').first().json.rv;\n"
                                                 "const isScene = rv.kind === 'scene';\n"
                                                 '// Edit phase 1 (19 Oct 2026): an owner edit adds its own '
                                                 'check (16a asks it only then); a fail fails the image like '
                                                 'any other check.\n'
                                                 'const CHECKS = (isScene ? SCENE_CHECKS : '
                                                 "WHITE_CHECKS).concat(rv.edit ? ['edit_applied'] : [], "
                                                 "rv.edit_base ? ['unchanged_from_base'] : []);\n"
                                                 "NAMES.edit_applied = 'requested edit applied, kept parts "
                                                 "unchanged';\n"
                                                 '// Edit phase 2.4 (19 Oct 2026): an edit of an approved '
                                                 'image is also checked against that image (16a sends it '
                                                 'last); counted like edit_applied.\n'
                                                 "NAMES.unchanged_from_base = 'everything the edit does not "
                                                 "name is as in the approved image';\n"
                                                 "if (isScene) NAMES.framing = 'framing (' + ((rv.scene && "
                                                 "rv.scene.framing) || 'hero') + ' view as ordered)';\n"
                                                 "const CODE_ONLY = isScene ? ['whole_in_frame'] : []; // "
                                                 'set by code only (the blind count), never asked of the '
                                                 'reviewer for a scene\n'
                                                 'let settings = {};\n'
                                                 "try { settings = $('04 Settings').first().json || {}; } "
                                                 'catch (e) { settings = {}; }\n'
                                                 '// "Nothing repairs itself" (owner, 16 Oct 2026, D5): a '
                                                 'repair runs only when the owner orders it at go 2, '
                                                 'whatever 04 Settings says.\n'
                                                 'const autoRepair = false;\n'
                                                 'const now = new Date().toISOString();\n'
                                                 'const attempt = Number(rv.attempt) || 1;\n'
                                                 'const obs = st.observation || {};\n'
                                                 '// Keep the category focus with the exact candidate '
                                                 'review; existing verdict policy still decides.\n'
                                                 'const categoryRequirements = '
                                                 'arr(rv.category_checks).filter(x => typeof x === '
                                                 "'string');\n"
                                                 'const review = { output_id: rv.output_id, attempt, at: '
                                                 'now, candidate: rv.candidate, category_requirements: '
                                                 "categoryRequirements, result: '', checks: {}, defects: [], "
                                                 'unsure: [], counts: {}, framing: null, styling_notes: [], '
                                                 "scores: null, score_label: 'Reviewer judgement, not a "
                                                 "measurement. Never the 90 to 95 fidelity target.', "
                                                 "summary: '', readers: 'claude-sonnet-5-5 (review against "
                                                 "the vendor photo) + gemini-3.8-flash (blind count) + code' "
                                                 '};\n'
                                                 '// Review again (D3): one per candidate image, that is per '
                                                 'output and attempt (review finding 12: a repair makes a '
                                                 'new candidate, which\n'
                                                 '// may have its own review again). It is recorded in the '
                                                 'state when the owner orders it (G2).\n'
                                                 'const ra = st.review_again && st.review_again.output_id '
                                                 '=== rv.output_id && Number(st.review_again.attempt) === '
                                                 'attempt ? st.review_again : null;\n'
                                                 'if (ra) review.review_again = { ordered_at: ra.ordered_at '
                                                 "|| '', by: 'owner' };\n"
                                                 "// Token counts of this round's calls (P1.8). Prices: "
                                                 'st.text_prices, written at intake (01 Intent & scope).\n'
                                                 'const P = st.text_prices || {};\n'
                                                 'function textCall(node, model, raw) {\n'
                                                 '  if (!raw) return;\n'
                                                 '  const u = usageOf(raw);\n'
                                                 '  const pr = P.models && P.models[model] ? P.models[model] '
                                                 ': null;\n'
                                                 '  const usd = u && pr ? Number(((u.input * pr.input + '
                                                 'u.output * pr.output) / 1e6).toFixed(5)) : null;\n'
                                                 '  const rec = { step: 16, node, model, output_id: '
                                                 'rv.output_id, attempt, at: now, tokens: u, usd, error: '
                                                 "raw.error ? short(raw.error, 120) : '', basis: u ? (pr ? "
                                                 "'provider token counts x prices read ' + (P.read_on || "
                                                 "'?') + ' (' + (pr.source || '') + '); an estimate, not an "
                                                 "invoice' : 'provider token counts; no price recorded for "
                                                 "this model') : 'the provider reported no token counts (the "
                                                 "call may still be charged)' };\n"
                                                 '  st.text_calls = arr(st.text_calls).concat([rec]);\n'
                                                 '  st.text_calls_new = '
                                                 'arr(st.text_calls_new).concat([rec]);\n'
                                                 '}\n'
                                                 "let fail = '';\n"
                                                 'if (!rv.ready) fail = rv.why;\n'
                                                 "let critic = null, blind = null, oneAnswered = '';\n"
                                                 'if (!fail) {\n'
                                                 "  const rawC = out('16 Critic review');\n"
                                                 "  const c = reading(rawC, 'The reviewer');\n"
                                                 '  // Fallback blind count (owner, 16 Oct 2026): '
                                                 "gpt-6.1-sol counts only when Gemini's blind count of this "
                                                 'round returned an error.\n'
                                                 "  const bMain = out('16x Blind count');\n"
                                                 "  const bBack = bMain && bMain.error ? out('16xb Blind "
                                                 "count fallback (OpenAI)') : null;\n"
                                                 "  const b = bBack ? reading(bBack, 'The fallback blind "
                                                 "count (gpt-6.1-sol, after Gemini did not answer)') : "
                                                 "reading(bMain, 'The blind count');\n"
                                                 "  textCall('16 Critic review', 'claude-sonnet-5-5', "
                                                 'rawC);\n'
                                                 "  textCall('16x Blind count', 'gemini-3.8-flash', bMain);\n"
                                                 "  if (bBack) textCall('16xb Blind count fallback "
                                                 "(OpenAI)', 'gpt-6.1-sol', bBack);\n"
                                                 "  review.blind_reader = bBack ? 'gpt-6.1-sol (fallback; "
                                                 "Gemini did not answer)' : 'gemini-3.8-flash';\n"
                                                 "  if (bBack) review.readers = 'claude-sonnet-5-5 (review "
                                                 'against the vendor photo) + gpt-6.1-sol (blind count, '
                                                 "fallback after Gemini did not answer) + code';\n"
                                                 '  if (c.fail || b.fail) fail = [c.fail, '
                                                 "b.fail].filter(Boolean).join(' ') + ' The candidate is not "
                                                 "reviewed.';\n"
                                                 '  critic = c.data; blind = b.data;\n'
                                                 '  if (fail && (critic || blind)) oneAnswered = critic ? '
                                                 "'reviewer' : 'blind count';\n"
                                                 '}\n'
                                                 'const isDetail = Boolean(isScene && rv.scene && '
                                                 "rv.scene.framing === 'detail');\n"
                                                 "// D6: where the blind count's box lies against the frame "
                                                 '(box_2d [ymin, xmin, ymax, xmax] on 0-1000).\n'
                                                 'function boxEdge(b) {\n'
                                                 '  const b2 = b && Array.isArray(b.box_2d) ? '
                                                 'b.box_2d.map(Number) : [];\n'
                                                 '  if (!(b2.length === 4 && b2.every(x => '
                                                 'Number.isFinite(x) && x >= 0 && x <= 1000) && b2[0] < '
                                                 'b2[2] && b2[1] < b2[3] && !b2.every(x => x <= 1))) return '
                                                 'null;\n'
                                                 '  return Math.min(b2[0], b2[1], 1000 - b2[2], 1000 - '
                                                 'b2[3]);\n'
                                                 '}\n'
                                                 "// P1.10: the reviewer's checks are written into the "
                                                 'record whenever the reviewer answered, even when the round '
                                                 'is not reviewed.\n'
                                                 'function fillChecks(c) {\n'
                                                 "  const checks = c && typeof c.checks === 'object' && "
                                                 'c.checks ? c.checks : {};\n'
                                                 '  for (const k of CHECKS) {\n'
                                                 "    const x = checks[k] && typeof checks[k] === 'object' ? "
                                                 'checks[k] : null;\n'
                                                 "    const r = x ? clean(x.result, 10).toLowerCase() : '';\n"
                                                 "    review.checks[k] = { result: ['pass', 'fail', "
                                                 "'unsure'].indexOf(r) !== -1 ? r : 'not answered', "
                                                 "evidence: x ? clean(x.evidence, 240) : '' };\n"
                                                 '  }\n'
                                                 '  return checks;\n'
                                                 '}\n'
                                                 'if (fail && critic) {\n'
                                                 '  const checks = fillChecks(critic);\n'
                                                 '  review.counts = { contract: Number(rv.total) || 0, '
                                                 'reviewer: num(checks.piece_count && '
                                                 'checks.piece_count.seen), blind: null };\n'
                                                 '  // Review finding 8 (16 Oct 2026): the D5 note-only '
                                                 'checks (light, camera level, realism, framing) stay notes '
                                                 'here too, never defects.\n'
                                                 '  const noteOnlyP = isScene ? SCENE_NOTE_ONLY : [];\n'
                                                 '  review.notes_only = [];\n'
                                                 '  for (const k of CHECKS) {\n'
                                                 '    const r = review.checks[k].result;\n'
                                                 "    if (noteOnlyP.indexOf(k) !== -1 && r !== 'pass') { "
                                                 'review.notes_only.push({ check: k, name: NAMES[k], result: '
                                                 "r, evidence: review.checks[k].evidence, fix: '' }); "
                                                 'continue; }\n'
                                                 "    if (r === 'fail') review.defects.push({ check: k, "
                                                 'name: NAMES[k], what: review.checks[k].evidence, where: '
                                                 "'', fix: '' }); else if (r !== 'pass') "
                                                 'review.unsure.push({ check: k, name: NAMES[k], result: r, '
                                                 'evidence: review.checks[k].evidence });\n'
                                                 '  }\n'
                                                 '  const sc = critic.scores && typeof critic.scores === '
                                                 "'object' ? critic.scores : null;\n"
                                                 '  if (sc) { review.scores = {}; for (const k of '
                                                 "['fidelity', 'integrity', 'drift', 'data_loss']) { const v "
                                                 '= num(sc[k]); review.scores[k] = v !== null && v <= 100 ? '
                                                 'v : null; } }\n'
                                                 "  review.score_label = 'From an incomplete review (the "
                                                 "blind count did not answer): the reviewer\\'s judgement "
                                                 'only, not a measurement, not a passed review, and never '
                                                 "the 90 to 95 fidelity target.';\n"
                                                 '  review.summary = clean(critic.summary, 300);\n'
                                                 "  review.partial = 'Only the reviewer answered; the blind "
                                                 'count did not. These findings are kept for the record; the '
                                                 "candidate is not reviewed.';\n"
                                                 '}\n'
                                                 'if (fail && !critic && blind) {\n'
                                                 '  review.counts = { contract: Number(rv.total) || 0, '
                                                 'reviewer: null, blind: num(blind.total) };\n'
                                                 "  review.partial = 'Only the blind count answered (' + "
                                                 "(num(blind.total) === null ? 'no count' : num(blind.total) "
                                                 "+ ' pieces') + '); the reviewer did not. The candidate is "
                                                 "not reviewed.';\n"
                                                 '}\n'
                                                 "if (fail) review.result = 'not reviewed';\n"
                                                 'if (!fail) {\n'
                                                 '  const checks = fillChecks(critic);\n'
                                                 '  // Counts: the contract, the reviewer (who knew the '
                                                 'contract) and the blind count (who did not). Code compares '
                                                 'them.\n'
                                                 '  const expected = Number(rv.total) || 0;\n'
                                                 '  const criticSeen = num(checks.piece_count && '
                                                 'checks.piece_count.seen);\n'
                                                 '  const blindSeen = num(blind && blind.total);\n'
                                                 '  review.counts = { contract: expected, reviewer: '
                                                 'criticSeen, blind: blindSeen };\n'
                                                 '  const fixes = {};\n'
                                                 '  for (const d of arr(critic && critic.defects).slice(0, '
                                                 '12)) {\n'
                                                 '    const k = clean(d && d.check, 40);\n'
                                                 '    if (!k) continue;\n'
                                                 '    fixes[k] = { what: clean(d.what, 240), where: '
                                                 'clean(d.where, 120), fix: clean(d.fix, 240) };\n'
                                                 '  }\n'
                                                 '  function codeDefect(k, what, fix) {\n'
                                                 "    review.checks[k] = { result: 'fail', evidence: "
                                                 "(review.checks[k] && review.checks[k].result === 'fail' ? "
                                                 "review.checks[k].evidence + ' ' : '') + 'Code: ' + what "
                                                 '};\n'
                                                 "    if (!fixes[k]) fixes[k] = { what, where: '', fix };\n"
                                                 '  }\n'
                                                 '  // A detail view need not show the whole product (owner, '
                                                 '16 Oct 2026, 04:16): fewer pieces in the frame is not a '
                                                 'defect; more is.\n'
                                                 '  review.counts.detail_view = isDetail;\n'
                                                 '  const countWrong = n => n !== null && (isDetail ? n > '
                                                 'expected : n !== expected);\n'
                                                 "  const countFix = isDetail ? 'Show no more than the ' + "
                                                 "expected + ' product pieces of the vendor photo, with none "
                                                 "duplicated or invented; a detail view may show fewer.' : "
                                                 "'Show exactly ' + expected + ' product pieces, as in the "
                                                 "vendor photo: no more and no fewer.';\n"
                                                 "  if (countWrong(blindSeen)) codeDefect('piece_count', "
                                                 "'the blind count found ' + blindSeen + ' product pieces; "
                                                 "the contract holds ' + expected + (isDetail ? ' (a detail "
                                                 "view may show fewer, never more)' : '') + '.', countFix);\n"
                                                 "  if (countWrong(criticSeen)) codeDefect('piece_count', "
                                                 "'the reviewer counted ' + criticSeen + ' product pieces; "
                                                 "the contract holds ' + expected + (isDetail ? ' (a detail "
                                                 "view may show fewer, never more)' : '') + '.', countFix);\n"
                                                 '  if (!isScene && blind && blind.background_white === '
                                                 "false) codeDefect('background', 'the blind count reports a "
                                                 "background that is not pure white.', 'Make the background "
                                                 'pure white (#FFFFFF) at every edge, with no grey tone, '
                                                 "gradient, floor line or horizon.');\n"
                                                 '  if (blind && blind.text_or_logo === true) '
                                                 "codeDefect('no_text_or_logo', 'the blind count reports "
                                                 "text, a logo or a watermark.', 'Remove all text, logos and "
                                                 "watermarks.');\n"
                                                 '  // D6 (owner, 16 Oct 2026): cut off by the frame is '
                                                 "decided in code from the blind count's box where it gives "
                                                 'one; its "cropped" flag\n'
                                                 '  // alone decides only when no usable box came back. Not '
                                                 'in a detail view (the whole product is not required '
                                                 'there).\n'
                                                 '  if (!isDetail) {\n'
                                                 '    const edge = boxEdge(blind);\n'
                                                 '    const flagged = Boolean(blind && blind.cropped === '
                                                 'true);\n'
                                                 '    const cut = edge !== null ? edge <= EDGE : flagged;\n'
                                                 '    review.crop = { box_edge: edge, edge_limit: EDGE, '
                                                 "reader_flag: flagged, decided_by: edge !== null ? 'code, "
                                                 "from the blind count\\'s box (0-1000)' : (blind ? 'the "
                                                 "blind count\\'s flag (no usable box)' : 'not known'), "
                                                 'cut_off: cut, hidden: blind && Array.isArray(blind.hidden) '
                                                 '? blind.hidden.slice(0, 12).map(x => String(x).slice(0, '
                                                 '160)) : [] };\n'
                                                 "    if (cut) codeDefect('whole_in_frame', edge !== null ? "
                                                 "'the product\\'s box reaches the frame edge (' + edge + ' "
                                                 "of 1000 from it; the limit is ' + EDGE + '), so part of "
                                                 "the product is cut off by the frame.' : 'the blind count "
                                                 'reports the product cut off by the frame and gave no '
                                                 "usable box.', isScene ? 'Show the whole product inside the "
                                                 "frame.' : 'Show the whole product inside the frame with "
                                                 "white space on every side.');\n"
                                                 '    else if (flagged) {\n'
                                                 '      // Review finding 5 (16 Oct 2026): the box and the '
                                                 'flag disagree, so the check is "unsure" (not passed), '
                                                 'never a quiet note. The\n'
                                                 '      // owner still decides at go 2. A piece hidden '
                                                 'behind another may be what the reader meant; that is not a '
                                                 'crop.\n'
                                                 '      review.crop.disagree = true;\n'
                                                 '      const ev = \'Code: the blind count said "cropped", '
                                                 "but its box is ' + edge + ' of 1000 from the nearest frame "
                                                 "edge (the limit is ' + EDGE + '). The two disagree, so "
                                                 'this is unsure, not passed. A piece hidden behind another '
                                                 "is not a crop; please look at the frame edges.';\n"
                                                 '      if (!(review.checks.whole_in_frame && '
                                                 "review.checks.whole_in_frame.result === 'fail')) "
                                                 "review.checks.whole_in_frame = { result: 'unsure', "
                                                 'evidence: ev };\n'
                                                 '    }\n'
                                                 '  }\n'
                                                 '  review.framing = framingReading(checks.framing && typeof '
                                                 "checks.framing === 'object' ? checks.framing : null, "
                                                 'blind);\n'
                                                 '  if (review.framing.within === false || '
                                                 'review.framing.within === null) '
                                                 'review.styling_notes.push(review.framing.note);\n'
                                                 '  const noteOnly = isScene ? SCENE_NOTE_ONLY : [];\n'
                                                 '  review.notes_only = [];\n'
                                                 '  for (const k of CHECKS.concat(CODE_ONLY.filter(k => '
                                                 'review.checks[k]))) {\n'
                                                 '    const r = review.checks[k].result;\n'
                                                 "    if (noteOnly.indexOf(k) !== -1 && r !== 'pass') {\n"
                                                 '      // D5: noted, never a failure. Its fix goes into the '
                                                 'proposed repair the owner may order.\n'
                                                 '      review.notes_only.push({ check: k, name: NAMES[k], '
                                                 'result: r, evidence: review.checks[k].evidence, fix: '
                                                 "(fixes[k] && fixes[k].fix) || '' });\n"
                                                 "      review.styling_notes.push('Styling note (' + "
                                                 "NAMES[k] + ', ' + r + '): ' + (review.checks[k].evidence "
                                                 "|| 'no evidence given') + ' A note only: the image is not "
                                                 "failed for it.');\n"
                                                 '      continue;\n'
                                                 '    }\n'
                                                 "    if (r === 'fail') review.defects.push({ check: k, "
                                                 'name: NAMES[k], what: (fixes[k] && fixes[k].what) || '
                                                 'review.checks[k].evidence, where: (fixes[k] && '
                                                 "fixes[k].where) || '', fix: (fixes[k] && fixes[k].fix) || "
                                                 "'' });\n"
                                                 "    else if (r !== 'pass') review.unsure.push({ check: k, "
                                                 'name: NAMES[k], result: r, evidence: '
                                                 'review.checks[k].evidence });\n'
                                                 '  }\n'
                                                 '  const sc = critic && critic.scores && typeof '
                                                 "critic.scores === 'object' ? critic.scores : null;\n"
                                                 '  if (sc) { review.scores = {}; for (const k of '
                                                 "['fidelity', 'integrity', 'drift', 'data_loss']) { const v "
                                                 '= num(sc[k]); review.scores[k] = v !== null && v <= 100 ? '
                                                 'v : null; } }\n'
                                                 '  review.summary = clean(critic && critic.summary, 300);\n'
                                                 "  review.result = review.defects.length ? 'failed' : "
                                                 "(review.unsure.length ? 'unsure' : 'passed');\n"
                                                 '}\n'
                                                 "// Review finding 1 (16 Oct 2026): the blind count's "
                                                 'product box is kept with the review, so the delivery files '
                                                 '(18e3) can leave the\n'
                                                 '// product untouched. Recorded whenever the blind count '
                                                 'answered with a usable box, reviewed or not.\n'
                                                 'if (blind && boxEdge(blind) !== null) { '
                                                 'review.product_box_2d = blind.box_2d.map(Number); '
                                                 'review.product_box_flagged = blind.cropped === true; } // '
                                                 'flag: Phase 1.3 follow-up\n'
                                                 '// What a scene repair keeps of the room. A view made from '
                                                 'the approved base view keeps its room, pieces and light, '
                                                 'not its camera.\n'
                                                 'function roomKeep() {\n'
                                                 '  const sc0 = st.scene || {};\n'
                                                 "  const r = arr(sc0.refs).find(x => x.role === 'room');\n"
                                                 '  const n = r && r.n ? r.n : 3;\n'
                                                 '  // Edit phase 2.4: an edit keeps everything in the '
                                                 "approved image it starts from except what the owner's edit "
                                                 'names.\n'
                                                 "  if (sc0.room && sc0.room.content === 'approved view' && "
                                                 'sc0.room.edit) { const ch = arr(sc0.room.changes); return '
                                                 "'everything in the approved image ' + "
                                                 "(sc0.room.from_output || '') + ' of the earlier version "
                                                 "(image ' + n + ' of the scene request) except what the "
                                                 "owner-requested edit names' + (ch.indexOf('camera') !== -1 "
                                                 "? ' and the camera view' : '') + (ch.indexOf('light') !== "
                                                 "-1 ? ' and the light' : ''); }\n"
                                                 '  // A series image changes one thing from the approved '
                                                 'image it is made from (16 Oct 2026): the light, or the '
                                                 'camera.\n'
                                                 "  if (sc0.room && sc0.room.content === 'approved view' && "
                                                 "arr(sc0.room.changes).indexOf('light') !== -1 && "
                                                 "arr(sc0.room.changes).indexOf('camera') === -1) return "
                                                 "'the room, every Midas piece where it stands, and the "
                                                 "camera of the approved image of ' + (sc0.room.from_output "
                                                 "|| 'the base view') + ' (image ' + n + ' of the scene "
                                                 "request); only the light differs';\n"
                                                 "  if (sc0.room && sc0.room.content === 'approved view') "
                                                 "return 'the room, every Midas piece where it stands, and "
                                                 "the light of the approved ' + (sc0.room.from_kind || "
                                                 "'base') + ' view (image ' + n + ' of the scene request); "
                                                 "only the camera differs';\n"
                                                 "  return 'the room as it is (image ' + n + ' of the scene "
                                                 "request)';\n"
                                                 '}\n'
                                                 '// The repair order: corrections from the review, written '
                                                 'against the vendor photo, plus what must not change.\n'
                                                 '// withNotes: the owner may order a repair for a styling '
                                                 "note too (framing, and D5's light, camera level and "
                                                 'realism); never automatic.\n'
                                                 'function repairOrder(withNotes) {\n'
                                                 "  const corr = review.defects.map(d => d.fix || ('Correct "
                                                 "the ' + d.name + ': ' + d.what)).filter(Boolean).map(t => "
                                                 'clean(t, 300)).slice(0, 8);\n'
                                                 '  if (withNotes && review.framing && review.framing.within '
                                                 '=== false && review.framing.fix) '
                                                 'corr.push(review.framing.fix);\n'
                                                 '  if (withNotes) for (const x of arr(review.notes_only)) '
                                                 "corr.push(clean(x.fix || ('Correct the ' + x.name + ': ' + "
                                                 'x.evidence), 300));\n'
                                                 "  const preserve = ['the exact inventory: ' + "
                                                 "arr(st.inventory).map(x => x.count + ' x ' + "
                                                 "x.item).join('; ')]\n"
                                                 '    .concat(isScene ? [roomKeep()].concat(arr(st.scene && '
                                                 "st.scene.props).map(p => 'the Midas piece ' + p.name + ' "
                                                 "(SKU ' + p.sku + ') exactly as catalogued')) : [])\n"
                                                 "    .concat(obs.colour_observed ? ['the colour as in the "
                                                 "vendor photo (' + clean(obs.colour_observed, 120) + ')'] : "
                                                 '[])\n'
                                                 '    '
                                                 '.concat(arr(obs.sided_parts).map(sidedText).filter(Boolean).map(x '
                                                 "=> 'handedness: ' + clean(x, 120)))\n"
                                                 '    .concat(arr(obs.design_locks).slice(0, 8).map(x => '
                                                 'clean(x, 160)))\n'
                                                 '    .concat(review.checks ? '
                                                 'Object.keys(review.checks).filter(k => '
                                                 "review.checks[k].result === 'pass').map(k => NAMES[k] + ' "
                                                 "(passed in the review)') : []);\n"
                                                 '  return { attempt: attempt + 1, corrections: '
                                                 'corr.slice(0, 10), preserve, from_review_at: now };\n'
                                                 '}\n'
                                                 '// The estimated cost of one "review again" (D3), shown on '
                                                 'the go 2 ticket before the owner orders it. An upper '
                                                 'bound, not a quote.\n'
                                                 'function reviewAgainCost() {\n'
                                                 '  const m = P.models || {};\n'
                                                 "  const c = m['claude-sonnet-5-5'], g = "
                                                 "m['gemini-3.8-flash'], o = m['gpt-6.1-sol'];\n"
                                                 '  if (!c || !g || !o) return { up_to_usd: null, basis: '
                                                 "'not known: no text prices were recorded at intake for "
                                                 "this run.' };\n"
                                                 '  const imgTok = Number(P.assumed_image_tokens) || 1600;\n'
                                                 '  const cap = P.output_caps || {};\n'
                                                 '  const nImg = String(rv.binary_names || '
                                                 "'vendor,candidate').split(',').filter(Boolean).length;\n"
                                                 '  const critIn = nImg * imgTok + '
                                                 "Math.ceil(String(rv.critic_text || '').length / 4);\n"
                                                 '  const blindIn = imgTok + Math.ceil(String(rv.blind_text '
                                                 "|| '').length / 4);\n"
                                                 '  const usd = (critIn * c.input + (Number(cap.review) || '
                                                 '4000) * c.output + blindIn * g.input + (Number(cap.blind) '
                                                 '|| 8000) * g.output + blindIn * o.input + '
                                                 '(Number(cap.blind_fallback) || 8000) * o.output) / 1e6;\n'
                                                 "  return { up_to_usd: Number(usd.toFixed(3)), calls: '1 "
                                                 'review (claude-sonnet-5-5) and 1 blind count '
                                                 '(gemini-3.8-flash); the fallback blind count (gpt-6.1-sol) '
                                                 "only if Gemini does not answer. No image call.', basis: "
                                                 "'upper bound: about ' + imgTok + ' tokens per image (an "
                                                 "assumption), the prompt length / 4, and each call\\'s full "
                                                 "output cap, at prices read ' + (P.read_on || '?') + '; an "
                                                 "estimate, not a quote' };\n"
                                                 '}\n'
                                                 'st.review = review;\n'
                                                 'st.review_log = arr(st.review_log).concat([{ attempt, '
                                                 "result: review.result || 'not reviewed', defects: "
                                                 'review.defects.length, unsure: review.unsure.length, '
                                                 'notes: arr(review.notes_only).length, review_again: '
                                                 'Boolean(ra), at: now, file: rv.candidate ? '
                                                 "rv.candidate.file_name : '' }]);\n"
                                                 "st.stage = '05 Review & go 2';\n"
                                                 'st.hold_step = 16;\n'
                                                 "st.go2_route = '';\n"
                                                 "const link = rv.candidate && rv.candidate.link ? ' "
                                                 "Candidate: ' + rv.candidate.link : '';\n"
                                                 'function hold(why) {\n'
                                                 "  st.status = 'hold'; st.hold_for = 'owner'; "
                                                 "st.hold_reason = why; st.client_question = '';\n"
                                                 '  st.critical = arr(st.critical).concat([{ what: '
                                                 "'stage05', who: 'owner', why }]);\n"
                                                 "  st.next = 'Waiting for the owner: ' + why + ' Nothing is "
                                                 "sent again automatically.' + link;\n"
                                                 '}\n'
                                                 "const thing = isScene ? 'scene ' + rv.output_id : 'white "
                                                 "master';\n"
                                                 '// A candidate that was stored but not reviewed (a reader '
                                                 'did not answer) goes to the owner instead of ending the '
                                                 'run (D3).\n'
                                                 '// Review finding 2 (16 Oct 2026): only when 16a was '
                                                 'ready, so the readers were called. A ticket that was not '
                                                 'ready (for example a\n'
                                                 '// missing image) would fail the same way on a review '
                                                 'again, so it holds instead.\n'
                                                 'const notReviewed = Boolean(rv.ready && fail && '
                                                 'rv.candidate);\n'
                                                 'if (fail && !notReviewed) hold(fail);\n'
                                                 "else if (!fail && review.result === 'failed' && attempt >= "
                                                 "MAX_ATTEMPT) hold('The review found ' + "
                                                 "review.defects.length + ' problem(s) on attempt ' + "
                                                 "attempt + ', and the two repairs for this image are used: "
                                                 "' + review.defects.map(d => d.name).join(', ') + '. The "
                                                 "image is held; it is not approved.');\n"
                                                 "if (st.status !== 'hold') {\n"
                                                 '  // Every candidate goes to the owner. Passed, unsure, '
                                                 'failed and not reviewed all wait for go 2; nothing is '
                                                 'released without it.\n'
                                                 '  // A styling note alone (framing, light, camera level, '
                                                 'realism) gives a proposed repair too; it runs only if the '
                                                 'owner orders it.\n'
                                                 '  const noteMiss = Boolean((review.framing && '
                                                 'review.framing.within === false) || '
                                                 'arr(review.notes_only).length);\n'
                                                 '  const proposed = !notReviewed && (review.result === '
                                                 "'failed' || noteMiss) ? repairOrder(true) : null;\n"
                                                 "  st.status = 'awaiting_go_2'; st.hold_reason = ''; "
                                                 "st.client_question = ''; st.hold_for = '';\n"
                                                 '  st.go2_round = attempt;\n'
                                                 '  st.go2_token = '
                                                 "require('crypto').randomBytes(16).toString('hex');\n"
                                                 '  st.go2_proposed_repair = proposed;\n'
                                                 "  const can = notReviewed ? (ra ? ['approve_unreviewed', "
                                                 "'stop'] : ['review_again', 'stop']) : ['approve', "
                                                 "'stop'].concat(attempt < MAX_ATTEMPT ? ['repair'] : []);\n"
                                                 '  st.go2_allowed = can;\n'
                                                 '  // Scenes of one series (or of one job) are shown '
                                                 'together for consistency (owner, 16 Oct 2026, decision '
                                                 '29); each is approved on its own.\n'
                                                 '  let together = null;\n'
                                                 '  if (isScene) {\n'
                                                 '    const me = arr(st.outputs).find(o => o.id === '
                                                 'rv.output_id) || {};\n'
                                                 '    const scn = st.scenes || {};\n'
                                                 '    const group = arr(st.outputs).filter(o => o.kind !== '
                                                 "'white' && o.kind !== 'variation' && (me.series ? o.series "
                                                 '&& o.series.name === me.series.name : true));\n'
                                                 '    // Review fix (16 Oct 2026): an image already certain '
                                                 'to be held (a side view with no photo of that side, or one '
                                                 'made from such an image)\n'
                                                 '    // says so now, as 19a will hold it, instead of "not '
                                                 'made yet".\n'
                                                 '    const willHold = (o, depth) => {\n'
                                                 "      if (!o || depth > 12) return '';\n"
                                                 '      const h = (scn.held || {})[o.id]; if (h) return '
                                                 'clean(h.why, 200);\n'
                                                 "      if (o.camera === 'Left side' || o.camera === 'Right "
                                                 "side') { const v = arr(st.side_views).find(x => "
                                                 "x.output_id === o.id); if (!v || !v.photo) return 'no "
                                                 "supplied photo shows the product\\'s ' + (o.camera === "
                                                 "'Left side' ? 'left' : 'right') + ' side'; }\n"
                                                 '      if (o.from) { const f = arr(st.outputs).find(x => '
                                                 "x.id === o.from); if (f && o.mode === 'room_locked' && "
                                                 'st.room_key && o.light && f.light && o.light !== f.light) '
                                                 "return 'the scene uses the client\\'s room photo, which "
                                                 "keeps the light it was photographed in'; if (f && "
                                                 '!(scn.done || {})[f.id] && willHold(f, depth + 1)) return '
                                                 "'it is made from ' + f.id + ', which is held'; }\n"
                                                 "      return '';\n"
                                                 '    };\n'
                                                 '    together = group.map(o => { const d = (scn.done || '
                                                 '{})[o.id]; const h = (scn.held || {})[o.id]; const w = !d '
                                                 "&& !h && o.id !== rv.output_id ? willHold(o, 0) : '';\n"
                                                 "      return { output_id: o.id, camera: o.camera || '', "
                                                 "light: o.light_label || o.light || '', status: o.id === "
                                                 "rv.output_id ? 'this image: waiting for your go 2' : (d ? "
                                                 "(d.without_review ? (d.shown_as || 'Approved by the studio "
                                                 "· not reviewed') : 'approved by the owner') : (h ? 'held: "
                                                 "' + clean(h.why, 200) : (w ? 'will be held: ' + w : 'not "
                                                 "made yet'))), link: d && d.candidate ? d.candidate.link || "
                                                 "'' : '' }; });\n"
                                                 '  }\n'
                                                 '  const raCost = notReviewed && !ra ? reviewAgainCost() : '
                                                 'null;\n'
                                                 '  const resultLine = notReviewed\n'
                                                 "    ? 'not reviewed: ' + fail + (review.partial ? ' ' + "
                                                 "review.partial : '')\n"
                                                 "    : (review.result === 'passed' ? 'passed: a reviewed "
                                                 "candidate, not an approval' : (review.result === 'unsure' "
                                                 "? 'not passed: the reviewer was unsure on ' + "
                                                 "review.unsure.length + ' check(s)' : 'failed: ' + "
                                                 "review.defects.length + ' problem(s) found: ' + "
                                                 "review.defects.map(d => d.name).join(', ')));\n"
                                                 '  const needed = notReviewed\n'
                                                 "    ? (ra ? 'go 2: the review again did not answer either. "
                                                 "Look at the ' + thing + ' yourself: approve it by eye "
                                                 '(recorded as "approved by owner without an automated '
                                                 'review", never as a passed review), or stop.\'\n'
                                                 "          : 'go 2: this ' + thing + ' was not reviewed. "
                                                 'Order one review again (one per candidate image; review '
                                                 'and blind count of the stored image, no image call; up to '
                                                 "about USD ' + (raCost && raCost.up_to_usd !== null ? "
                                                 "raCost.up_to_usd : '?') + '), or stop.')\n"
                                                 "    : 'go 2: approve this ' + thing + ', ' + (attempt < "
                                                 "MAX_ATTEMPT ? 'order a repair, ' : '') + 'or stop. "
                                                 "Approval is yours only; the review is not an approval.';\n"
                                                 '  st.go2 = {\n'
                                                 "    for: 'owner', output_id: rv.output_id, attempt, label: "
                                                 "notReviewed ? 'Generated image. Candidate: not reviewed, "
                                                 "not approved.' : 'Generated image. Candidate: reviewed, "
                                                 "not approved.',\n"
                                                 "    kind: isScene ? 'scene' : 'white', scene: rv.scene || "
