                                                 'ap.product_box_2d : null,\n'
                                                 '  // Phase 1.3 (FL-5, owner, 22 Oct 2026): whether the '
                                                 'review of these exact bytes found the whole product in the '
                                                 'frame.\n'
                                                 '  whole_in_frame: (() => { const r = st.review || {}, c = '
                                                 'r.crop || null; const bound = Boolean(cand && r.candidate '
                                                 '&& r.candidate.sha256 === cand.sha256);\n'
                                                 '    if (bound && !c && Array.isArray(r.product_box_2d) && '
                                                 'r.product_box_2d.length === 4 && typeof '
                                                 "r.product_box_flagged === 'boolean') {\n"
                                                 '      // Phase 1.3 follow-up: no review result (approved '
                                                 "without a review), so the review's own code test (D6) on "
                                                 "the blind count's box.\n"
                                                 '      // Only when 16b recorded the flag beside the box; a '
                                                 'box from another path without it stays unknown (review '
                                                 'fix, 22 Oct 2026).\n'
                                                 '      const b = r.product_box_2d.map(Number), edge = '
                                                 'Math.min(b[0], b[1], 1000 - b[2], 1000 - b[3]), flagged = '
                                                 'r.product_box_flagged === true;\n'
                                                 '      if (b.every(Number.isFinite)) return { known: true, '
                                                 'cut_off: edge <= 15, disagree: edge > 15 && flagged, '
                                                 "decided_by: 'code, from the blind count\\'s box (no review "
                                                 "result): ' + edge + ' of 1000 from the nearest frame edge, "
                                                 'limit 15\' + (flagged ? \', flagged "cropped"\' : \'\') '
