                                                 '    const isView = VIEW_ORDER.indexOf(o.kind) !== -1 && '
                                                 '!o.series;\n'
                                                 '    const baseId = o.from || sc.queue.find(q => { const x '
                                                 '= arr(st.outputs).find(y => y.id === q); return x && '
                                                 'VIEW_ORDER.indexOf(x.kind) !== -1 && !x.series; });\n'
                                                 '    const shared = Boolean(o.edit_from_result) || '
                                                 '(!roomLocked && ((o.from && baseId) || '
                                                 '(cfg.views_share_one_room === true && isView && baseId && '
                                                 'baseId !== id)));\n'
                                                 '    const base = shared ? (o.edit_from_result ? eBase : '
                                                 'sc.done[baseId]) : null;\n'
                                                 '    const baseKind = shared ? (eBase ? eBase.kind : '
                                                 '((arr(st.outputs).find(y => y.id === baseId) || {}).kind '
                                                 "|| '')) : '';\n"
                                                 "    if (!shot || !shot.plan) hold('Scene ' + id + ' has no "
                                                 "checked plan from go 1, so it is not started.');\n"
                                                 '    else if (o.edit_from_result && !(base && base.by === '
                                                 "'owner' && base.candidate && "
                                                 "/^[0-9a-f]{64}$/.test(String(base.candidate.sha256 || '')) "
