                                                 '/\\b(Dia(?:meter)?|[WDHL])\\s*[:.]?\\s*(\\d+(?:[.,]\\d+)?)/gi;\n'
                                                 '  let m;\n'
                                                 '  while ((m = re.exec(t)) && pairs.length < 4) '
