                                                 '  if (/\\bpre[-\\s]?order\\b/i.test(text) && /add to '
                                                 'cart|pre[-\\s]?order now/i.test(text)) '
                                                 "signals.push('pre_order');\n"
                                                 '  const uniq = Array.from(new Set(signals));\n'
                                                 '  const stock = uniq.length === 1 ? uniq[0] : (uniq.length '
                                                 "? 'conflicting' : 'not_found');\n"
                                                 '  const size = text.match(/Product '
                                                 'Size\\s*:?\\s*(.{3,160}?)(?=\\s+(?:Product Colou?r|Family '
                                                 'Colou?r|Colou?r|Combination|Material|Fabric|Warranty|SKU|Delivery|Description|Specifications?|Qty|Quantity|Add '
                                                 'to Cart|Add to Wishlist|Add Wishlist|Buy '
                                                 'Now|Share)\\b|$)/i);\n'
                                                 '  const sku = '
                                                 'text.match(/\\bSKU\\s*:?\\s*([A-Za-z0-9-]{3,20})\\b/);\n'
                                                 '  return { stock, signals: uniq, size: size ? '
                                                 "sizeOnly(size[1]) : '', sku_on_page: sku ? sku[1] : '' };\n"
                                                 '}\n'
                                                 'const kept = [], dropped = [];\n'
                                                 'props.forEach((p, i) => {\n'
                                                 '  const k = asked.findIndex(a => a.sku === p.sku && a.url '
                                                 '=== p.url);\n'
                                                 '  const page = k === -1 ? null : pages[k];\n'
                                                 '  const status = page ? Number(page.statusCode) || 0 : 0;\n'
                                                 "  const body = page ? (typeof page.body === 'string' ? "
                                                 "page.body : (typeof page.data === 'string' ? page.data : "
                                                 "'')) : '';\n"
                                                 '  if (!page) { dropped.push({ sku: p.sku, name: p.name, '
                                                 "why: 'its page was not read' }); return; }\n"
                                                 '  if (status !== 200 || !body) { dropped.push({ sku: '
                                                 "p.sku, name: p.name, why: 'its Midas page did not answer "
                                                 "(status ' + (status || (page.error ? 'error' : 'none')) + "
                                                 "')' }); return; }\n"
                                                 '  const r = read(body);\n'
                                                 '  if (r.sku_on_page && r.sku_on_page !== String(p.sku)) { '
                                                 "dropped.push({ sku: p.sku, name: p.name, why: 'the page "
                                                 "shows another SKU (' + r.sku_on_page + ')' }); return; }\n"
                                                 '  // A lamp or other light fitting appears only when its '
                                                 'page says in stock (owner, 16 Oct 2026, decision 23); '
                                                 'pre-order is not enough for it.\n'
                                                 '  // Every other piece on pre-order is left out too '
                                                 '(owner, 16 Oct 2026, D10, which settles decision 28), a '
                                                 'few lines below.\n'
                                                 '  // The same lamp words as 13 and 16a (review fix, 16 Oct '
                                                 '2026), so a "ceiling light" is held to the same rule.\n'
                                                 "  if (r.stock === 'pre_order' && "
                                                 '/\\b(lamps?|lights?|lighting|sconces?|chandeliers?|lanterns?|pendants?)\\b/i.test(String(p.kind '
                                                 "|| ''))) { dropped.push({ sku: p.sku, name: p.name, why: "
                                                 "'a lamp appears only when its Midas page says in stock; it "
                                                 "says pre-order today' }); return; }\n"
                                                 '  if '
                                                 '(!/^https:\\/\\/(www\\.)?midasfurniture\\.com\\/en\\//i.test(String(p.url '
                                                 "|| ''))) { dropped.push({ sku: p.sku, name: p.name, why: "
                                                 "'its page is not on the Midas Kuwait English site "
                                                 "(midasfurniture.com/en/)' }); return; }\n"
                                                 "  if (r.stock === 'pre_order') { dropped.push({ sku: "
                                                 "p.sku, name: p.name, why: 'its Midas page says pre-order "
                                                 "today; only pieces in stock are used' }); return; }\n"
                                                 "  if (r.stock === 'in_stock') kept.push(Object.assign({}, "
                                                 'p, { live: { stock: r.stock, read_at: now, size_on_page: '
                                                 "r.size || 'not confirmed', page: p.url } }));\n"
                                                 '  else dropped.push({ sku: p.sku, name: p.name, why: '
                                                 "r.stock === 'out_of_stock' ? 'out of stock on its Midas "
                                                 "page today' : (r.stock === 'conflicting' ? 'its page gives "
                                                 "conflicting stock signals (' + r.signals.join(', ') + ')' "
                                                 ": 'its page does not show the stock status') });\n"
                                                 '});\n'
                                                 'st.scene.props = kept;\n'
                                                 'st.scene.props_left_out = '
                                                 'arr(st.scene.props_left_out).concat(dropped.map(d => ({ '
                                                 "sku: d.sku, why: d.why + '; the spot stays empty' })));\n"
                                                 "st.scene.prop_check = { at: now, source: 'live Midas "
                                                 "product pages', asked: props.length, kept: kept.length, "
