                                                 '// Either the empty room made in this stage (downloaded '
                                                 'from Drive, checked against its receipt checksum) or the '
                                                 "client's room photo\n"
                                                 "// from intake (checked at intake). The client's room is "
                                                 'used as it is: it is never redrawn before the placement.\n'
                                                 "const crypto = require('crypto');\n"
                                                 "const st = $('19c Prop verdict').first().json;\n"
                                                 'const r = (st.scene && st.scene.room) || null;\n'
                                                 "const kind = b => (!b || b.length < 12 ? '' : "
                                                 "(b.readUInt32BE(0) === 0x89504e47 ? 'image/png' : (b[0] "
                                                 "=== 0xff && b[1] === 0xd8 ? 'image/jpeg' : "
                                                 "(b.toString('ascii', 0, 4) === 'RIFF' && "
                                                 "b.toString('ascii', 8, 12) === 'WEBP' ? 'image/webp' : "
                                                 "''))));\n"
                                                 "const room = { ok: false, source: r ? r.source : '', key: "
                                                 "'', sha256: '', bytes: 0, mime: '', name: '', why: '' };\n"
                                                 "if (!r) room.why = 'the scene has no room recorded';\n"
                                                 "else if (r.source === 'client room photo') {\n"
                                                 '  const ref = (st.references || []).find(x => x.key === '
                                                 'r.key && x.sha256);\n'
                                                 "  if (!ref) room.why = 'the client room photo is not among "
                                                 "this run\\'s checked files';\n"
                                                 '  else Object.assign(room, { ok: true, key: ref.key, '
                                                 'sha256: ref.sha256, bytes: ref.bytes || 0, mime: ref.mime '
                                                 "|| '', name: ref.name || 'client room photo' });\n"
                                                 '} else {\n'
                                                 '  const item = $input.first() || {};\n'
                                                 '  let buf = null;\n'
                                                 '  if (item.binary && item.binary.data) { try { buf = await '
                                                 "this.helpers.getBinaryDataBuffer(0, 'data'); } catch (e) { "
                                                 'buf = null; } }\n'
                                                 "  if (!buf || !buf.length) room.why = 'the empty room "
                                                 "could not be downloaded from Google Drive' + (item.json && "
                                                 "item.json.error ? ' (' + String(item.json.error.message || "
                                                 "item.json.error).slice(0, 160) + ')' : '');\n"
                                                 '  else {\n'
