                                                 '    const it = items[i] || {};\n'
                                                 '    let buf = null;\n'
                                                 '    if (it.binary && it.binary.data) { try { buf = await '
                                                 "this.helpers.getBinaryDataBuffer(i, 'data'); } catch (e) { "
                                                 'buf = null; } }\n'
                                                 '    const mime = kind(buf);\n'
                                                 '    photos.push({ i, sku: list[i].sku, ok: Boolean(buf && '
