                                                 '    const mb = n => (n / 1048576).toFixed(1);\n'
                                                 '    sc.ref_resized = [];\n'
                                                 '    const resizer = this.helpers && typeof '
                                                 "this.helpers.midasResizeReference === 'function' ? "
                                                 'this.helpers.midasResizeReference : null;\n'
                                                 "    if (st.status !== 'hold' && total > cap && resizer) {\n"
                                                 '      let ingest = {};\n'
                                                 "      try { ingest = $('02 Ingest files').first().binary "
                                                 '|| {}; } catch (e) { ingest = {}; }\n'
                                                 '      for (const vendorPass of [false, true]) {\n'
                                                 '        for (const r of refs) {\n'
                                                 '          if (total <= cap) break;\n'
                                                 "          if ((r.role === 'vendor photo') !== vendorPass) "
                                                 'continue;\n'
                                                 '          const src = out.binary[r.key] || ingest[r.key] '
                                                 '|| null;\n'
                                                 '          if (!src) continue;\n'
                                                 '          let res = null;\n'
                                                 '          try { res = await resizer(src, RESIZE_PX); } '
                                                 "catch (e) { res = null; notes.push('The ' + r.role + ' (' "
                                                 "+ r.name + ') could not be resized in code (' + String((e "
                                                 "&& e.message) || e).slice(0, 200) + ').'); }\n"
                                                 '          if (!res || !res.resized || !res.binary) '
                                                 'continue;\n'
                                                 '          const before = Number(r.bytes) || '
                                                 'Number(res.from_bytes) || 0;\n'
                                                 '          sc.ref_resized.push({ role: r.role, key: r.key, '
                                                 'name: r.name, from_px: res.from_px, to_px: res.to_px, '
                                                 'from_bytes: before, to_bytes: res.to_bytes, from_sha256: '
                                                 "r.sha256, to_sha256: res.sha256, mime: res.mime, how: 'in "
                                                 "code, without AI: long side to ' + RESIZE_PX + ' px, "
                                                 "aspect kept, JPEG quality 90' });\n"
