                                                 '  '
                                                 "/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/.test(body.permit||'')&&\n"
                                                 '  '
                                                 'Number.isSafeInteger(body.reservedMicroUsd)&&body.reservedMicroUsd>0;\n'
                                                 '}\n'
                                                 'function settlementCompleted(response) {\n'
                                                 ' return '
                                                 "response?.statusCode===200&&response.body?.recorded===true&&response.body?.status==='completed';\n"
                                                 '}\n'
                                                 'function budgetHold(state,stage,nodeName,reason) {\n'
                                                 ' return '
                                                 "{...state,status:'hold',stage,hold_for:'owner',hold_step:parseInt(nodeName,10)||1,\n"
                                                 "  hold_reason:'Paid processing paused: '+reason,\n"
                                                 "  client_question:'Review the spending ledger before "
