                                                       "this.helpers.getBinaryDataBuffer(0,key);refs.push({key,name,role,sha256:crypto.createHash('sha256').update(bytes).digest('hex'),mime:f.mimeType,image:String(f.mimeType||'').startsWith('image/')});}\n"
                                                       'const '
                                                       "product=refs.filter(r=>r.role==='product'&&r.image),room=refs.filter(r=>r.role==='room'&&r.image);\n"
                                                       "if(product.length!==1||product[0].sha256!==p.sourceSha256||room.length>1||Boolean(room.length)!==Boolean(p.roomSha256)||room.length&&room[0].sha256!==p.roomSha256||refs.some(r=>r.role==='unassigned'))throw "
                                                       "Error('analysis_source_mismatch');\n"
