                                                           "  const body = typeof p.body === 'string' ? "
                                                           "p.body : (typeof p.data === 'string' ? p.data : "
                                                           "'');\n"
                                                           '  const base = { row_id: a.row_id, sku: a.sku, '
                                                           'url: a.url };\n'
                                                           '  const write = (action, note, extra) => { '
                                                           'out.push({ json: Object.assign({ action }, base, '
                                                           "{ row: Object.assign({ stock_checked: STAMP + '; "
                                                           "' + note }, extra || {}) }) }); "
                                                           'log.push(Object.assign({ verdict: action, note '
                                                           '}, base)); };\n'
                                                           '  if (doneByListing.has(String(a.sku))) { '
                                                           "log.push(Object.assign({ verdict: 'listing "
                                                           "decided this run; page not used for a write', "
                                                           'page_status: status }, base)); return; }\n'
                                                           '  if (status === 404) {\n'
