                                                           '  if (status !== 200 || !body) return '
                                                           "write('hand_note', 'product page did not answer "
                                                           "(status ' + (status || 'none') + '); no change; "
                                                           "FLAG for the owner');\n"
                                                           '  const r = read(body);\n'
