# --- src/midas_a7/config.py ---
"""Settings and credentials, read from the environment only. No secret is stored in the repo."""







config__REPO_ROOT = config__Path(__file__).resolve().parent
config__PACKAGE_DIR = config__Path(__file__).resolve().parent


def config___env(name: str, default: str = "") -> str:
    return config__os.environ.get(name, default)


@config__dataclass(frozen=True)
class config__HeaderCredential:
    header: str
    value: str


@config__dataclass(frozen=True)
class config__Settings:
    database_url: str = config__field(default_factory=lambda: config___env("DATABASE_URL", "sqlite:///./midas_a7.db"))
    # Public address of this service; resume URLs and webhook URLs are built from it.
    public_base_url: str = config__field(default_factory=lambda: config___env("PUBLIC_BASE_URL", "http://localhost:8080").rstrip("/"))
    # Addresses the flows still name for their own webhooks (the former n8n host). Calls to them stay in process.
    self_aliases: tuple[str, ...] = config__field(default_factory=lambda: tuple(
        a.strip().rstrip("/") for a in config___env("SELF_BASE_ALIASES", "https://ibrahimnewaeon.app.n8n.cloud").split(",") if a.strip()))
    resume_secret: str = config__field(default_factory=lambda: config___env("RESUME_SIGNING_SECRET"))
    # Signs the private file links (BE-6, PR A). While it is not set, file links keep using RESUME_SIGNING_SECRET.
    file_link_secret: str = config__field(default_factory=lambda: config___env("FILE_LINK_SECRET"))
    schedules_enabled: bool = config__field(default_factory=lambda: config___env("SCHEDULES_ENABLED", "false").lower() == "true")
    data_tables_path: config__Path = config__field(default_factory=lambda: config__Path(config___env("DATA_TABLES_PATH", str(config__PACKAGE_DIR / "data" / "data-tables.json"))))
    seeds_dir: config__Path = config__field(default_factory=lambda: config__Path(config___env("SEEDS_DIR", str(config__PACKAGE_DIR / "data" / "seeds"))))


# Credential names used by the flows -> environment variables holding their values.
config__HEADER_CREDENTIALS = {
    # Owner site (Netlify) <-> this service, both directions. Same value as the site's A7_READ_AUTHORIZATION.
    "A7 GPT bridge inbound": ("A7_BRIDGE_HEADER_NAME", "Authorization", "A7_BRIDGE_HEADER_VALUE"),
    # Main intake and analysis-only intake.
    "Claude · Midas client header": ("MIDAS_CLIENT_HEADER_NAME", "X-Midas-Key", "MIDAS_CLIENT_HEADER_VALUE"),
    # Owner decision intake.
    "Claude · Midas owner header": ("MIDAS_OWNER_HEADER_NAME", "X-Midas-Owner-Key", "MIDAS_OWNER_HEADER_VALUE"),
}

config__API_KEYS = {
    "openAiApi": "OPENAI_API_KEY",
    "googlePalmApi": "GEMINI_API_KEY",
    "anthropicApi": "ANTHROPIC_API_KEY",
}


class config__MissingCredential(Exception):
    pass


class config__Credentials:
    """Looks up a node's credential by the name it had in n8n, else by its type."""

    def header(self, name: str) -> config__HeaderCredential:
        spec = config__HEADER_CREDENTIALS.get(name)
        if not spec:
            raise config__MissingCredential(f"Unknown header credential '{name}'")
        header_env, header_default, value_env = spec
        value = config___env(value_env)
        if not value:
            raise config__MissingCredential(f"Credential '{name}' is not configured (set {value_env})")
        return config__HeaderCredential(config___env(header_env, header_default), value)

    def api_key(self, cred_type: str) -> str:
        env = config__API_KEYS.get(cred_type)
        if not env:
            raise config__MissingCredential(f"Unknown credential type '{cred_type}'")
        value = config___env(env)
        if not value:
            raise config__MissingCredential(f"Credential '{cred_type}' is not configured (set {env})")
        return value

    def configured(self) -> dict[str, bool]:
        """Which credentials are set, for /health. Never returns values."""
        out = {name: bool(config___env(spec[2])) for name, spec in config__HEADER_CREDENTIALS.items()}
        out.update({t: bool(config___env(env)) for t, env in config__API_KEYS.items()})
        # Not a secret, but an organisation-level Anthropic key is useless without it, so /health says whether it is set.
        out["anthropicWorkspaceId"] = bool(config___env("ANTHROPIC_WORKSPACE_ID").strip())
        # File links have their own secret once it is set (BE-6); until then they use the resume secret.
        out["fileLinkSecret"] = bool(config___env("FILE_LINK_SECRET"))
        return out


# --- src/midas_a7/store.py ---
"""Database: parked runs, binary files of live runs, and the rows of A7's data tables.

SQLite for local work and tests, Postgres in production (DATABASE_URL). Calls are synchronous;
async code runs them with asyncio.to_thread.
"""



















store__metadata = store__MetaData()

store__executions = store__Table(
    "executions", store__metadata,
    store__Column("id", store__Integer, primary_key=True, autoincrement=True),
    store__Column("flow_id", store__String(64), nullable=False, index=True),
    store__Column("status", store__String(16), nullable=False, index=True),
    store__Column("state", store__JSON, nullable=True),
    store__Column("wait_till", store__DateTime(timezone=True), nullable=True, index=True),
    store__Column("wait_kind", store__String(16), nullable=True),
    store__Column("error", store__JSON, nullable=True),
    store__Column("created_at", store__DateTime(timezone=True), nullable=False),
    store__Column("updated_at", store__DateTime(timezone=True), nullable=False),
)

store__binaries = store__Table(
    "binaries", store__metadata,
    store__Column("id", store__String(64), primary_key=True),
    store__Column("execution_id", store__String(64), nullable=False, index=True),
    store__Column("data", store__LargeBinary, nullable=False),
    store__Column("mime_type", store__String(255), nullable=True),
    store__Column("file_name", store__Text, nullable=True),
    store__Column("size", store__Integer, nullable=False),
    store__Column("created_at", store__DateTime(timezone=True), nullable=False),
)

# Files the flows keep (generated images, packages, manifests). Replaces Google Drive (owner, 20 Oct 2026).
store__files = store__Table(
    "files", store__metadata,
    store__Column("id", store__String(64), primary_key=True),
    store__Column("name", store__Text, nullable=False),
    store__Column("mime_type", store__String(255), nullable=False),
    store__Column("parent_id", store__String(255), nullable=True, index=True),
    store__Column("is_folder", store__Integer, nullable=False, default=0),
    store__Column("data", store__LargeBinary, nullable=True),
    store__Column("size", store__Integer, nullable=False, default=0),
    store__Column("sha256", store__String(64), nullable=True),
    store__Column("md5", store__String(32), nullable=True),
    store__Column("created_at", store__DateTime(timezone=True), nullable=False),
)

store__dt_rows = store__Table(
    "dt_rows", store__metadata,
    store__Column("id", store__Integer, primary_key=True, autoincrement=True),
    store__Column("table_id", store__String(64), nullable=False, index=True),
    store__Column("data", store__JSON, nullable=False),
    store__Column("created_at", store__DateTime(timezone=True), nullable=False),
    store__Column("updated_at", store__DateTime(timezone=True), nullable=False),
)


def store__now() -> store__datetime:
    return store__datetime.now(store__timezone.utc)


def store__iso(dt: store__datetime) -> str:
    return dt.astimezone(store__timezone.utc).isoformat(timespec="milliseconds").replace("+00:00", "Z")


def store___serialized(method):
    """SQLite shares one connection between threads here; run one statement group at a time."""
    @store__functools.wraps(method)
    def wrapper(self, *args, **kwargs):
        with self._lock:
            return method(self, *args, **kwargs)
    return wrapper


class store__Store:
    def __init__(self, url: str):
        if url.startswith("postgres://"):
            url = "postgresql+psycopg://" + url[len("postgres://"):]
        elif url.startswith("postgresql://"):
            url = "postgresql+psycopg://" + url[len("postgresql://"):]
        kwargs: dict[str, store__Any] = {"future": True}
        if url.startswith("sqlite"):
            kwargs["connect_args"] = {"check_same_thread": False}
            if url in ("sqlite://", "sqlite:///:memory:"):
                kwargs["poolclass"] = store__StaticPool
        else:
            kwargs["pool_pre_ping"] = True
        self.engine: store__Engine = store__create_engine(url, **kwargs)
        # Postgres runs concurrent calls on separate pooled connections; SQLite calls go one at a time.
        self._lock = store__threading.RLock() if url.startswith("sqlite") else store__contextlib.nullcontext()
        store__metadata.create_all(self.engine)

    # ---------- executions ----------
    @store___serialized
    def create_execution(self, flow_id: str) -> str:
        with self.engine.begin() as c:
            res = c.execute(store__insert(store__executions).values(flow_id=flow_id, status="running", created_at=store__now(), updated_at=store__now()))
            return str(res.inserted_primary_key[0])

    @store___serialized
    def save_execution(self, execution_id: str, status: str, state: dict | None, wait_till: store__datetime | None = None,
                       wait_kind: str | None = None, error: dict | None = None) -> None:
        with self.engine.begin() as c:
            c.execute(store__update(store__executions).where(store__executions.c.id == int(execution_id)).values(
                status=status, state=state, wait_till=wait_till, wait_kind=wait_kind, error=error, updated_at=store__now()))

    @store___serialized
    def load_execution(self, execution_id: str) -> dict | None:
        with self.engine.connect() as c:
            row = c.execute(store__select(store__executions).where(store__executions.c.id == int(execution_id))).mappings().first()
            return dict(row) if row else None

    @store___serialized
    def due_waits(self, at: store__datetime) -> list[str]:
        with self.engine.connect() as c:
            rows = c.execute(store__select(store__executions.c.id).where(store__and_(
                store__executions.c.status == "waiting", store__executions.c.wait_till.is_not(None), store__executions.c.wait_till <= at)))
            return [str(r[0]) for r in rows]

    @store___serialized
    def claim_waiting(self, execution_id: str) -> dict | None:
        """Atomically move a waiting run to running so it is resumed once only."""
        with self.engine.begin() as c:
            res = c.execute(store__update(store__executions).where(store__and_(
                store__executions.c.id == int(execution_id), store__executions.c.status == "waiting")).values(status="running", updated_at=store__now()))
            if res.rowcount != 1:
                return None
            row = c.execute(store__select(store__executions).where(store__executions.c.id == int(execution_id))).mappings().first()
            return dict(row) if row else None

    @store___serialized
    def run_summary(self, limit: int = 20) -> dict[str, store__Any]:
        """What /status shows: runs by status, the runs still active or waiting, and the latest failures (no run state)."""
        cols = [store__executions.c.id, store__executions.c.flow_id, store__executions.c.status, store__executions.c.wait_kind, store__executions.c.wait_till,
                store__executions.c.error, store__executions.c.created_at, store__executions.c.updated_at]
        with self.engine.connect() as c:
            counts = {row[0]: int(row[1]) for row in c.execute(
                store__select(store__executions.c.status, store__func.count()).group_by(store__executions.c.status))}

            def rows(*where, order):
                q = store__select(*cols).where(*where).order_by(order).limit(limit)
                return [dict(r) for r in c.execute(q).mappings()]
            return {
                "counts": counts,
                "running": rows(store__executions.c.status == "running", order=store__executions.c.created_at.asc()),
                "waiting": rows(store__executions.c.status == "waiting", order=store__executions.c.wait_till.asc()),
                "failed": rows(store__executions.c.status.in_(("error", "crashed")), order=store__executions.c.updated_at.desc()),
            }

    @store___serialized
    def fail_interrupted(self) -> int:
        """Runs left 'running' by a stopped process cannot continue; record them as failed."""
        with self.engine.begin() as c:
            res = c.execute(store__update(store__executions).where(store__executions.c.status == "running").values(
                status="crashed", state=None, error={"message": "process stopped while the run was active"}, updated_at=store__now()))
            return res.rowcount or 0

    # ---------- binaries ----------
    @store___serialized
    def put_binary(self, execution_id: str, data: bytes, mime_type: str | None, file_name: str | None) -> str:
        bid = "bin:" + store__uuid.uuid4().hex
        with self.engine.begin() as c:
            c.execute(store__insert(store__binaries).values(id=bid, execution_id=execution_id, data=data, mime_type=mime_type,
                                              file_name=file_name, size=len(data), created_at=store__now()))
        return bid

    @store___serialized
    def get_binary(self, binary_id: str) -> bytes | None:
        with self.engine.connect() as c:
            row = c.execute(store__select(store__binaries.c.data).where(store__binaries.c.id == binary_id)).first()
            return bytes(row[0]) if row else None

    @store___serialized
    def delete_binaries(self, execution_id: str) -> None:
        with self.engine.begin() as c:
            c.execute(store__delete(store__binaries).where(store__binaries.c.execution_id == execution_id))

    # ---------- files ----------
    @store___serialized
    def file_create(self, file_id: str, name: str, mime_type: str, parent_id: str | None, data: bytes | None,
                    sha256: str | None = None, md5: str | None = None) -> dict[str, store__Any]:
        row = {"id": file_id, "name": name, "mime_type": mime_type, "parent_id": parent_id,
               "is_folder": 1 if data is None else 0, "data": data, "size": len(data or b""),
               "sha256": sha256, "md5": md5, "created_at": store__now()}
        with self.engine.begin() as c:
            c.execute(store__insert(store__files).values(**row))
        return {k: v for k, v in row.items() if k != "data"}

    @store___serialized
    def file_get(self, file_id: str, with_data: bool = True) -> dict[str, store__Any] | None:
        cols = [store__files] if with_data else [c for c in store__files.c if c.name != "data"]
        with self.engine.connect() as c:
            row = c.execute(store__select(*cols).where(store__files.c.id == file_id)).mappings().first()
            return dict(row) if row else None

    # ---------- data tables ----------
    @staticmethod
    def _row(r: store__Any) -> dict[str, store__Any]:
        data = r.data if isinstance(r.data, dict) else store__json.loads(r.data)
        return {"id": r.id, **data, "createdAt": store__iso(r.created_at), "updatedAt": store__iso(r.updated_at)}

    @store___serialized
    def dt_select(self, table_id: str, equals: dict[str, str] | None = None) -> list[dict[str, store__Any]]:
        """Rows of a table in id order. `equals` narrows by string columns in SQL; callers filter exactly."""
        q = store__select(store__dt_rows).where(store__dt_rows.c.table_id == table_id)
        for key, value in (equals or {}).items():
            q = q.where(store__dt_rows.c.data[key].as_string() == value)
        with self.engine.connect() as c:
            return [self._row(r) for r in c.execute(q.order_by(store__dt_rows.c.id))]

    @store___serialized
    def dt_insert(self, table_id: str, data: dict[str, store__Any]) -> dict[str, store__Any]:
        t = store__now()
        with self.engine.begin() as c:
            res = c.execute(store__insert(store__dt_rows).values(table_id=table_id, data=data, created_at=t, updated_at=t))
            rid = res.inserted_primary_key[0]
            r = c.execute(store__select(store__dt_rows).where(store__dt_rows.c.id == rid)).first()
            return self._row(r)

    @store___serialized
    def dt_update(self, table_id: str, ids: store__Iterable[int], changes: dict[str, store__Any]) -> list[dict[str, store__Any]]:
        out = []
        with self.engine.begin() as c:
            for rid in ids:
                r = c.execute(store__select(store__dt_rows).where(store__and_(store__dt_rows.c.id == rid, store__dt_rows.c.table_id == table_id))).first()
                if r is None:
                    continue
                data = r.data if isinstance(r.data, dict) else store__json.loads(r.data)
                data = {**data, **changes}
                c.execute(store__update(store__dt_rows).where(store__dt_rows.c.id == rid).values(data=data, updated_at=store__now()))
                out.append(self._row(c.execute(store__select(store__dt_rows).where(store__dt_rows.c.id == rid)).first()))
        return out

    @store___serialized
    def dt_delete(self, table_id: str, ids: store__Iterable[int]) -> int:
        ids = list(ids)
        if not ids:
            return 0
        with self.engine.begin() as c:
            res = c.execute(store__delete(store__dt_rows).where(store__and_(store__dt_rows.c.table_id == table_id, store__dt_rows.c.id.in_(ids))))
            return res.rowcount or 0

    @store___serialized
    def dt_count(self, table_id: str) -> int:
        with self.engine.connect() as c:
            return int(c.execute(store__select(store__func.count()).select_from(store__dt_rows).where(store__dt_rows.c.table_id == table_id)).scalar() or 0)

    @store___serialized
    def dt_seed(self, table_id: str, rows: list[dict[str, store__Any]], columns: list[str]) -> int:
        """Load reference rows (model registry, handling profiles, catalogue) into an empty table."""
        if self.dt_count(table_id):
            return 0
        n = 0
        with self.engine.begin() as c:
            for row in rows:
                data = {k: row.get(k) for k in columns}
                t = store__now()
                c.execute(store__insert(store__dt_rows).values(table_id=table_id, data=data, created_at=t, updated_at=t))
                n += 1
        return n


def store__load_schemas(path: store__Path) -> dict[str, dict[str, store__Any]]:
    """Data-table schemas frozen from n8n: {table_id: {"name": ..., "columns": [{"name", "type"}]}}."""
    raw = store__json.loads(path.read_text(encoding="utf-8"))
    return {t["id"]: t for t in raw["tables"]}


# --- src/midas_a7/engine/model.py ---
"""Flow definitions: the nodes and connections of each A7 flow, as committed in src/midas_a7/flows."""










engine_model__Item = dict[str, engine_model__Any]  # {"json": {...}, "binary": {key: ref}}

engine_model___LITERAL_REF = engine_model__re.compile(r"""\$\(\s*(['"])((?:(?!\1).)+)\1\s*\)""")
engine_model___ANY_REF = engine_model__re.compile(r"\$\(")


@engine_model__dataclass(frozen=True)
class engine_model__NodeDef:
    name: str
    type: str
    type_version: float
    parameters: dict[str, engine_model__Any]
    position: tuple[float, float] = (0.0, 0.0)
    credentials: dict[str, engine_model__Any] = engine_model__field(default_factory=dict)
    on_error: str = "stopWorkflow"
    always_output_data: bool = False
    execute_once: bool = False
    retry_on_fail: bool = False
    max_tries: int = 3
    wait_between_tries_ms: int = 1000
    disabled: bool = False
    webhook_id: str | None = None

    @property
    def kind(self) -> str:
        """Short node type, e.g. 'code', 'httpRequest', 'openAi'."""
        return self.type.rsplit(".", 1)[-1]

    @property
    def continue_on_fail(self) -> bool:
        return self.on_error in ("continueRegularOutput", "continueErrorOutput")

    @engine_model__cached_property
    def referenced_nodes(self) -> tuple[frozenset[str], bool]:
        """Nodes this node reads with $('Name'); the flag is True when a name is computed at run time.

        Every `$(` that is not one whole quoted literal counts as computed: `$(name)`, a template literal, or a
        concatenation such as `$('Budget · '+n+' · Ticket')`. Such a node is given every executed node, as n8n does.
        The parameters are scanned as written (not JSON-escaped), so a double-quoted name inside the script stays literal.
        """
        text = "\n".join(engine_model___strings(self.parameters))
        names: set[str] = set()
        dynamic = False
        for ref in engine_model___ANY_REF.finditer(text):
            literal = engine_model___LITERAL_REF.match(text, ref.start())
            if literal:
                names.add(literal.group(2))
            else:
                dynamic = True
        return frozenset(names), dynamic

    @engine_model__cached_property
    def has_expressions(self) -> bool:
        return engine_model___has_expr({k: v for k, v in self.parameters.items() if k != "jsCode"})


def engine_model___has_expr(v: engine_model__Any) -> bool:
    if isinstance(v, str):
        return v.startswith("=")
    if isinstance(v, dict):
        return any(engine_model___has_expr(x) for x in v.values())
    if isinstance(v, list):
        return any(engine_model___has_expr(x) for x in v)
    return False


def engine_model___strings(v: engine_model__Any):
    """Every string in a parameter tree (the code as written, not JSON-escaped)."""
    if isinstance(v, str):
        yield v
    elif isinstance(v, dict):
        for x in v.values():
            yield from engine_model___strings(x)
    elif isinstance(v, list):
        for x in v:
            yield from engine_model___strings(x)


@engine_model__dataclass
class engine_model__Flow:
    id: str
    name: str
    version_id: str
    settings: dict[str, engine_model__Any]
    nodes: dict[str, engine_model__NodeDef]
    # connections[source][output_index] -> [(target, input_index), ...]
    connections: dict[str, list[list[tuple[str, int]]]]

    @engine_model__cached_property
    def parents(self) -> dict[str, list[tuple[str, int, int]]]:
        out: dict[str, list[tuple[str, int, int]]] = {n: [] for n in self.nodes}
        for src, outputs in self.connections.items():
            for oi, targets in enumerate(outputs):
                for dst, ii in targets:
                    out.setdefault(dst, []).append((src, oi, ii))
        return out

    def input_count(self, name: str) -> int:
        node = self.nodes[name]
        if node.kind == "merge":
            return int(node.parameters.get("numberInputs", 2))
        ins = [ii for _, _, ii in self.parents.get(name, [])]
        return (max(ins) + 1) if ins else 1

    def children(self, name: str, output: int) -> list[tuple[str, int]]:
        outs = self.connections.get(name, [])
        return list(outs[output]) if output < len(outs) else []

    @engine_model__cached_property
    def _reach(self) -> dict[str, set[str]]:
        reach: dict[str, set[str]] = {}

        def visit(n: str, seen: set[str]) -> set[str]:
            if n in reach:
                return reach[n]
            acc: set[str] = set()
            seen.add(n)
            for targets in self.connections.get(n, []):
                for dst, _ in targets:
                    acc.add(dst)
                    if dst not in seen:
                        acc |= visit(dst, seen)
            reach[n] = acc
            return acc

        for n in self.nodes:
            visit(n, set())
        return reach

    @engine_model__cached_property
    def parallel_regions(self) -> dict[str, dict[str, frozenset[str]]]:
        """settings.parallelFanOut: for each listed node, the region each of its children owns, keyed by that child.

        A region holds the child and every node all of whose parents are already in it; it stops at a node with
        several inputs (a Merge), at a node reached from elsewhere, and at Wait, Respond and trigger nodes. The
        executor runs the regions of one fan-out at the same time and leaves every node outside them to the
        normal order. Regions that overlap, or that read each other's nodes with $('Name'), are refused.
        """
        stop = {"wait", "respondToWebhook", "webhook"}
        out: dict[str, dict[str, frozenset[str]]] = {}
        for fan in self.settings.get("parallelFanOut") or []:
            if fan not in self.nodes:
                raise ValueError(f"parallelFanOut: no node named {fan!r}")
            heads = [c for targets in self.connections.get(fan, []) for c, _ in targets]
            regions: dict[str, frozenset[str]] = {}
            for head in heads:
                if self.input_count(head) > 1 or self.nodes[head].kind in stop or len(self.parents[head]) != 1:
                    continue
                own = {head}
                grown = True
                while grown:
                    grown = False
                    for n in list(own):
                        for targets in self.connections.get(n, []):
                            for c, _ in targets:
                                if (c not in own and self.input_count(c) == 1 and self.nodes[c].kind not in stop
                                        and all(p in own for p, _, _ in self.parents[c])):
                                    own.add(c)
                                    grown = True
                regions[head] = frozenset(own)
            for a, ra in regions.items():
                for b, rb in regions.items():
                    if a == b:
                        continue
                    if ra & rb:
                        raise ValueError(f"parallelFanOut {fan!r}: the branches of {a!r} and {b!r} overlap")
                    for n in ra:
                        names, dynamic = self.nodes[n].referenced_nodes
                        if names & rb or dynamic:
                            raise ValueError(f"parallelFanOut {fan!r}: {n!r} reads nodes of the {b!r} branch")
            out[fan] = regions
        return out

    def output_towards(self, source: str, target: str) -> int:
        """Which output of `source` leads to `target` (n8n uses it for $('source') lookups); 0 if none."""
        for oi, targets in enumerate(self.connections.get(source, [])):
            for dst, _ in targets:
                if dst == target or target in self._reach.get(dst, set()):
                    return oi
        return 0

    def webhook_nodes(self) -> list[engine_model__NodeDef]:
        return [n for n in self.nodes.values() if n.kind == "webhook" and not n.disabled]

    def trigger_nodes(self) -> list[engine_model__NodeDef]:
        kinds = {"webhook", "scheduleTrigger", "manualTrigger", "executeWorkflowTrigger"}
        return [n for n in self.nodes.values() if n.kind in kinds and not n.disabled]


def engine_model__flow_from_definition(defn: dict[str, engine_model__Any], code_dir: engine_model__Path | None = None) -> engine_model__Flow:
    """Build a Flow from a definition dict as written by tools/n8n_to_flow.py.

    Code nodes keep their JavaScript in code_dir/<file>; the definition names the file in
    parameters["jsCodeFile"], and the file text becomes parameters["jsCode"] byte for byte.
    """
    nodes: dict[str, engine_model__NodeDef] = {}
    for raw in defn["nodes"]:
        params = dict(raw.get("parameters") or {})
        code_file = params.pop("jsCodeFile", None)
        if code_file:
            if code_dir is None:
                raise ValueError(f"node {raw['name']} needs a code directory")
            params["jsCode"] = (code_dir / code_file).read_text(encoding="utf-8")
        pos = raw.get("position") or [0, 0]
        nodes[raw["name"]] = engine_model__NodeDef(
            name=raw["name"],
            type=raw["type"],
            type_version=float(raw.get("typeVersion", 1)),
            parameters=params,
            position=(float(pos[0]), float(pos[1])),
            credentials=raw.get("credentials") or {},
            on_error=raw.get("onError") or ("continueRegularOutput" if raw.get("continueOnFail") else "stopWorkflow"),
            always_output_data=bool(raw.get("alwaysOutputData")),
            execute_once=bool(raw.get("executeOnce")),
            retry_on_fail=bool(raw.get("retryOnFail")),
            max_tries=int(raw.get("maxTries") or 3),
            wait_between_tries_ms=int(raw.get("waitBetweenTries") if raw.get("waitBetweenTries") is not None else 1000),
            disabled=bool(raw.get("disabled")),
            webhook_id=raw.get("webhookId"),
        )
    connections: dict[str, list[list[tuple[str, int]]]] = {}
    for src, by_type in (defn.get("connections") or {}).items():
        main = by_type.get("main") or []
        connections[src] = [[(c["node"], int(c.get("index", 0))) for c in (outs or [])] for outs in main]
    return engine_model__Flow(
        id=defn["id"], name=defn["name"], version_id=defn.get("versionId", ""),
        settings=defn.get("settings") or {}, nodes=nodes, connections=connections,
    )


def engine_model__load_flow(module_name: str) -> engine_model__Flow:
    """Load a committed flow package, e.g. 'midas_a7.flows.a7_main'."""
    mod = engine_model__importlib.import_module(module_name)
    code_dir = engine_model__Path(mod.__file__).with_name("code")
    return engine_model__flow_from_definition(mod.FLOW, code_dir)


# --- src/midas_a7/engine/binary.py ---
"""Binary files of a run (photos, images, manifests). Items carry references; bytes live in the store."""








engine_binary__FILE_TYPES = {"image": "image", "video": "video", "audio": "audio", "text": "text"}


def engine_binary__sniff_mime(data: bytes) -> str | None:
    if data.startswith(b"\x89PNG\r\n\x1a\n"):
        return "image/png"
    if data.startswith(b"\xff\xd8\xff"):
        return "image/jpeg"
    if data[:4] == b"RIFF" and data[8:12] == b"WEBP":
        return "image/webp"
    if data[:6] in (b"GIF87a", b"GIF89a"):
        return "image/gif"
    if data[:2] == b"BM":
        return "image/bmp"
    if data.startswith(b"%PDF"):
        return "application/pdf"
    return None


def engine_binary__pretty_size(n: int) -> str:
    """Same style as n8n's fileSize, e.g. '2.24 MB'."""
    if n < 1000:
        return f"{n} B"
    for unit in ("kB", "MB", "GB", "TB"):
        n_f = n / 1000.0
        if n_f < 1000 or unit == "TB":
            return f"{float(f'{n_f:.3g}'):g} {unit}"
        n = int(n_f)
    return f"{n} B"


def engine_binary__make_ref(binary_id: str, data: bytes, mime_type: str | None, file_name: str | None,
             file_extension: str | None = None) -> dict[str, engine_binary__Any]:
    mime = mime_type or engine_binary__sniff_mime(data) or (engine_binary__mimetypes.guess_type(file_name or "")[0] if file_name else None) or "application/octet-stream"
    ext = file_extension
    if not ext and file_name and "." in file_name:
        ext = file_name.rsplit(".", 1)[1].lower()
    if not ext:
        guessed = engine_binary__mimetypes.guess_extension(mime) or ""
        ext = {".jpe": "jpg", ".jpeg": "jpg"}.get(guessed, guessed.lstrip("."))
    ref: dict[str, engine_binary__Any] = {"mimeType": mime}
    major = mime.split("/", 1)[0]
    if mime == "application/json":
        ref["fileType"] = "json"
    elif mime == "application/pdf":
        ref["fileType"] = "pdf"
    elif major in engine_binary__FILE_TYPES:
        ref["fileType"] = engine_binary__FILE_TYPES[major]
    if ext:
        ref["fileExtension"] = ext
    if file_name:
        ref["fileName"] = file_name
    ref.update({"id": binary_id, "fileSize": engine_binary__pretty_size(len(data)), "bytes": len(data), "data": "filesystem-v2"})
    return ref


class engine_binary__BinaryStore:
    def __init__(self, store: engine_binary__Any):
        self.store = store

    async def put(self, execution_id: str, data: bytes, mime_type: str | None = None, file_name: str | None = None,
                  file_extension: str | None = None) -> dict[str, engine_binary__Any]:
        bid = await engine_binary__asyncio.to_thread(self.store.put_binary, execution_id, data, mime_type, file_name)
        return engine_binary__make_ref(bid, data, mime_type, file_name, file_extension)

    async def get(self, ref: dict[str, engine_binary__Any]) -> bytes:
        bid = (ref or {}).get("id")
        inline = (ref or {}).get("data")
        if not str(bid or "").startswith("bin:") and isinstance(inline, str) and inline != "filesystem-v2":
            return engine_binary__base64.b64decode(inline)  # bytes carried inline, as n8n allows
        if not bid:
            raise KeyError("binary reference has no id")
        data = await engine_binary__asyncio.to_thread(self.store.get_binary, bid)
        if data is None:
            raise KeyError(f"binary {bid} not found")
        return data


# --- src/midas_a7/engine/services.py ---
"""Shared services handed to every node handler."""














@engine_services__dataclass
class engine_services__Services:
    settings: config__Settings
    store: store__Store
    js: engine_jsrunner__JsRunner
    binaries: engine_binary__BinaryStore
    credentials: config__Credentials
    schemas: dict[str, dict[str, engine_services__Any]]
    http: engine_services__httpx.AsyncClient
    # In-process client for this service's own webhooks (set once the web app exists).
    self_http: engine_services__httpx.AsyncClient | None = None
    extra: dict[str, engine_services__Any] = engine_services__field(default_factory=dict)

    def route(self, url: str) -> tuple[engine_services__httpx.AsyncClient, str]:
        """Calls to this service's own addresses (incl. the former n8n host) stay in process."""
        for base in (self.settings.public_base_url, *self.settings.self_aliases):
            if base and (url == base or url.startswith(base + "/")) and self.self_http is not None:
                return self.self_http, url[len(base):] or "/"
        return self.http, url


# --- src/midas_a7/engine/jsrunner.py ---
"""Client for the Node sidecar (js/runner.mjs) that runs Code-node logic and ={{ }} expressions."""












engine_jsrunner__log = engine_jsrunner__logging.getLogger(__name__)

# An engine helper a Code node may call while it runs (Phase 1.6): it gets the request's payload and returns plain JSON data.
engine_jsrunner__Callback = engine_jsrunner__Callable[[dict[str, engine_jsrunner__Any]], engine_jsrunner__Awaitable[engine_jsrunner__Any]]

engine_jsrunner__RUNNER = engine_jsrunner__Path(__file__).with_name("js") / "runner.mjs"
engine_jsrunner___LINE_LIMIT = 1 << 30  # replies can carry large binaries as base64


class engine_jsrunner__JsError(Exception):
    """Raised when the code or expression throws inside the sidecar."""

    def __init__(self, message: str, name: str = "Error", stack: str = ""):
        super().__init__(message)
        self.name = name
        self.stack = stack


class engine_jsrunner__JsRunner:
    def __init__(self, node_bin: str | None = None, timeout_s: float = 300.0):
        self._node = node_bin or engine_jsrunner__os.environ.get("MIDAS_NODE_BIN") or engine_jsrunner__shutil.which("node") or "node"
        self._timeout = timeout_s
        self._proc: engine_jsrunner__asyncio.subprocess.Process | None = None
        self._pending: dict[int, engine_jsrunner__asyncio.Future] = {}
        self._callbacks: dict[int, dict[str, engine_jsrunner__Callback]] = {}
        self._tasks: set[engine_jsrunner__asyncio.Task] = set()
        self._ids = engine_jsrunner__itertools.count(1)
        self._write_lock = engine_jsrunner__asyncio.Lock()
        self._start_lock = engine_jsrunner__asyncio.Lock()
        self._reader: engine_jsrunner__asyncio.Task | None = None
        self._stderr: engine_jsrunner__asyncio.Task | None = None

    async def _ensure(self) -> None:
        async with self._start_lock:
            if self._proc and self._proc.returncode is None:
                return
            self._proc = await engine_jsrunner__asyncio.create_subprocess_exec(
                self._node, str(engine_jsrunner__RUNNER),
                stdin=engine_jsrunner__asyncio.subprocess.PIPE, stdout=engine_jsrunner__asyncio.subprocess.PIPE, stderr=engine_jsrunner__asyncio.subprocess.PIPE,
                limit=engine_jsrunner___LINE_LIMIT, cwd=str(engine_jsrunner__RUNNER.parent),
            )
            self._reader = engine_jsrunner__asyncio.create_task(self._read_loop(self._proc))
            self._stderr = engine_jsrunner__asyncio.create_task(self._stderr_loop(self._proc))

    async def _read_loop(self, proc: engine_jsrunner__asyncio.subprocess.Process) -> None:
        assert proc.stdout
        while True:
            line = await proc.stdout.readline()
            if not line:
                break
            try:
                msg = engine_jsrunner__json.loads(line)
            except engine_jsrunner__json.JSONDecodeError:
                engine_jsrunner__log.error("js runner sent a line that is not JSON")
                continue
            if "callback" in msg:
                # The running code asks the engine for a helper (e.g. resizing a reference photo); its reply goes back on stdin.
                # The reply goes back to this process only: after a restart the new runner numbers its callbacks from 1
                # again, so a late answer sent to it could resolve another run's request.
                task = engine_jsrunner__asyncio.create_task(self._answer_callback(msg, proc))
                self._tasks.add(task)
                task.add_done_callback(self._tasks.discard)
                continue
            fut = self._pending.pop(msg.get("id"), None)
            if fut and not fut.done():
                fut.set_result(msg)
        err = engine_jsrunner__JsError("js runner stopped")
        for fut in self._pending.values():
            if not fut.done():
                fut.set_exception(err)
        self._pending.clear()

    async def _stderr_loop(self, proc: engine_jsrunner__asyncio.subprocess.Process) -> None:
        assert proc.stderr
        while True:
            line = await proc.stderr.readline()
            if not line:
                break
            engine_jsrunner__log.info("js: %s", line.decode(errors="replace").rstrip())

    async def _send(self, message: dict[str, engine_jsrunner__Any], proc: engine_jsrunner__asyncio.subprocess.Process | None = None) -> None:
        proc = proc or self._proc
        if not proc or not proc.stdin or proc is not self._proc:
            raise engine_jsrunner__JsError("js runner stopped")
        data = engine_jsrunner__json.dumps(message, ensure_ascii=False, separators=(",", ":"))
        async with self._write_lock:
            proc.stdin.write(data.encode() + b"\n")
            await proc.stdin.drain()

    async def _answer_callback(self, msg: dict[str, engine_jsrunner__Any], proc: engine_jsrunner__asyncio.subprocess.Process) -> None:
        """Run the engine helper a Code node asked for and send its answer back (the node's promise resolves or rejects)."""
        op = str(msg.get("op") or "")
        fn = self._callbacks.get(msg.get("id"), {}).get(op)
        reply: dict[str, engine_jsrunner__Any] = {"op": "callbackResult", "callback": msg.get("callback")}
        if fn is None:
            reply.update(ok=False, error={"message": f"the engine helper {op!r} is not available to this node"})
        else:
            try:
                reply.update(ok=True, result=await fn(msg.get("payload") or {}))
            except Exception as exc:  # the node decides what a failed helper means
                engine_jsrunner__log.warning("engine helper %s failed: %s", op, exc)
                reply.update(ok=False, error={"message": str(exc) or exc.__class__.__name__})
        try:
            await self._send(reply, proc)
        except (engine_jsrunner__JsError, OSError, ConnectionError):
            pass  # the runner stopped; the call that asked fails on its own

    async def call(self, op: str, callbacks: dict[str, engine_jsrunner__Callback] | None = None, **payload: engine_jsrunner__Any) -> engine_jsrunner__Any:
        """Send one request. `callbacks` are the engine helpers the code may call while this request runs."""
        await self._ensure()
        assert self._proc and self._proc.stdin
        rid = next(self._ids)
        fut: engine_jsrunner__asyncio.Future = engine_jsrunner__asyncio.get_running_loop().create_future()
        self._pending[rid] = fut
        if callbacks:
            self._callbacks[rid] = callbacks
        try:
            await self._send({"id": rid, "op": op, **payload})
            msg = await engine_jsrunner__asyncio.wait_for(fut, self._timeout)
        except engine_jsrunner__asyncio.TimeoutError:
            self._pending.pop(rid, None)
            await self.close()  # a stuck script must not block later work
            raise engine_jsrunner__JsError(f"Code ran longer than {self._timeout:.0f} s and was stopped")
        finally:
            self._callbacks.pop(rid, None)
        if not msg.get("ok"):
            e = msg.get("error") or {}
            raise engine_jsrunner__JsError(e.get("message", "unknown error"), e.get("name", "Error"), e.get("stack", ""))
        return msg["result"]

    async def close(self) -> None:
        proc, self._proc = self._proc, None
        if proc and proc.returncode is None:
            proc.kill()
            await proc.wait()
        for task in (self._reader, self._stderr):
            if task:
                task.cancel()


# --- src/midas_a7/engine/executor.py ---
"""Runs a flow the way n8n's v1 execution order does.

The order matters because Code nodes read other nodes' latest output with $('Name'):
- depth first: after a node runs, its children go to the front of the stack, top-most first
  (then left-most), so one branch finishes before the next starts;
- a node with several inputs (Merge) waits until every input has data, or until nothing else
  is left to run;
- a node only runs when it receives at least one item;
- `alwaysOutputData` turns an empty first output into one empty item, `executeOnce` keeps only
  the first input item, `retryOnFail` re-runs a node that throws, and `onError` decides whether
  a failure stops the run or passes on.
A Wait node parks the run: its state is saved and it resumes later from the resume URL or a timer.
One deliberate exception (owner, 20 Oct 2026): a node listed in the flow's settings.parallelFanOut starts its
branches at the same time (see _run_parallel and Flow.parallel_regions).
"""













engine_executor__log = engine_executor__logging.getLogger(__name__)


class engine_executor__NodeError(Exception):
    """A node failed. `description` and `http_code` mirror n8n's NodeApiError fields."""

    def __init__(self, message: str, description: str | None = None, http_code: str | None = None):
        super().__init__(message)
        self.description = description
        self.http_code = http_code


def engine_executor__describe_failure(message: str, description: str | None = None, http_code: str | None = None) -> str:
    """One log line for a failed call: n8n's message, the status, then the provider's own words (never the request)."""
    text = message
    if http_code:
        text += f" [{http_code}]"
    if description and description != message:
        text += f": {description[:300]}"
    return text


def engine_executor__describe_error(exc: BaseException) -> str:
    message = str(exc) or exc.__class__.__name__
    if isinstance(exc, engine_executor__NodeError):
        return engine_executor__describe_failure(message, exc.description, exc.http_code)
    return message


@engine_executor__dataclass
class engine_executor__WaitRequest:
    """Returned by a Wait node: park the run until resumed (webhook) or until the time passes."""

    kind: str  # "webhook" | "time"
    till: engine_executor__datetime | None
    passthrough: list[engine_model__Item]


@engine_executor__dataclass
class engine_executor__Response:
    status: int = 200
    body: engine_executor__Any = None
    headers: dict[str, str] = engine_executor__field(default_factory=dict)
    raw: bytes | None = None
    content_type: str | None = None


engine_executor__NodeOutput = list[list[engine_model__Item]]
engine_executor__Handler = engine_executor__Callable[["engine_executor__NodeContext"], engine_executor__Awaitable["engine_executor__NodeOutput | engine_executor__WaitRequest"]]


@engine_executor__dataclass
class engine_executor__Execution:
    """Everything needed to continue a run; saved as JSON while the run waits."""

    id: str
    flow_id: str
    mode: str = "production"
    status: str = "new"
    started_at: float = engine_executor__field(default_factory=engine_executor__time.time)
    stack: list[dict[str, engine_executor__Any]] = engine_executor__field(default_factory=list)
    waiting: dict[str, list[list[list[engine_model__Item] | None]]] = engine_executor__field(default_factory=dict)
    run_data: dict[str, list[dict[str, engine_executor__Any]]] = engine_executor__field(default_factory=dict)
    last_node: str | None = None
    error: dict[str, engine_executor__Any] | None = None
    wait: dict[str, engine_executor__Any] | None = None
    resume_url: str = ""
    resume_generation: int = 0
    # Set while a webhook caller is waiting for a "Respond to Webhook" node.
    responder: engine_executor__asyncio.Future | None = None

    def to_state(self) -> dict[str, engine_executor__Any]:
        return {
            "id": self.id, "flow_id": self.flow_id, "mode": self.mode, "status": self.status,
            "started_at": self.started_at, "stack": self.stack, "waiting": self.waiting,
            "run_data": self.run_data, "last_node": self.last_node, "error": self.error,
            "wait": self.wait, "resume_url": self.resume_url, "resume_generation": self.resume_generation,
        }

    @classmethod
    def from_state(cls, state: dict[str, engine_executor__Any]) -> "engine_executor__Execution":
        ex = cls(id=state["id"], flow_id=state["flow_id"])
        for k in ("mode", "status", "started_at", "stack", "waiting", "run_data", "last_node", "error", "wait", "resume_url", "resume_generation"):
            if k in state:
                setattr(ex, k, state[k])
        return ex

    def latest_output(self, name: str, output: int = 0) -> list[engine_model__Item] | None:
        runs = self.run_data.get(name)
        if not runs:
            return None
        data = runs[-1].get("data") or []
        return data[output] if output < len(data) and data[output] is not None else []

    def run_index(self, name: str) -> int:
        return len(self.run_data.get(name, []))


class engine_executor__Executor:
    """Runs flows. `handlers` maps a node kind (e.g. 'code') to its async handler."""

    def __init__(self, services: engine_executor__Any, handlers: dict[str, engine_executor__Handler]):
        self.services = services
        self.handlers = handlers

    # ---------- public entry points ----------
    async def start(self, flow: engine_model__Flow, execution: engine_executor__Execution, trigger: engine_model__NodeDef, items: list[engine_model__Item]) -> engine_executor__Execution:
        execution.status = "running"
        self._record(execution, trigger.name, [items], source=None)
        self._schedule_children(flow, execution, trigger.name, [items])
        await self._loop(flow, execution)
        return execution

    async def resume(self, flow: engine_model__Flow, execution: engine_executor__Execution, output: list[engine_model__Item]) -> engine_executor__Execution:
        """Continue a parked run: the Wait node outputs `output` (the resume request, or its input on timeout)."""
        wait = execution.wait or {}
        node_name = wait.get("node")
        if not node_name:
            raise RuntimeError("execution is not waiting")
        execution.status = "running"
        execution.wait = None
        runs = execution.run_data.setdefault(node_name, [])
        if runs and runs[-1].get("status") == "waiting":
            runs[-1].update({"status": "success", "data": [output]})
        else:
            runs.append({"status": "success", "data": [output], "start": engine_executor__time.time()})
        self._schedule_children(flow, execution, node_name, [output])
        await self._loop(flow, execution)
        return execution

    # ---------- main loop ----------
    async def _loop(self, flow: engine_model__Flow, execution: engine_executor__Execution) -> None:
        if await self._drain(flow, execution, execution.stack) == "done":
            execution.status = "success"

    async def _drain(self, flow: engine_model__Flow, execution: engine_executor__Execution, stack: list[dict[str, engine_executor__Any]],
                     region: frozenset[str] | None = None, deferred: list[tuple] | None = None) -> str:
        """Run nodes from `stack` until it is empty: "done", "error" or "waiting".

        In a parallel branch (`region` set) a child outside the region is not run but put in `deferred`, and
        an empty stack ends the branch instead of releasing a waiting Merge.
        """
        while True:
            if not stack:
                if region is not None or not self._release_partial_merge(flow, execution):
                    return "done"
            entry = stack.pop(0)
            node = flow.nodes[entry["node"]]
            inputs: list[list[engine_model__Item]] = entry["inputs"]
            if node.disabled:
                out = [inputs[0] if inputs else []]
                self._record(execution, node.name, out, source=entry.get("source"))
                self._schedule_children(flow, execution, node.name, out, stack, region, deferred)
                continue
            if node.execute_once:
                inputs = [i[:1] for i in inputs]
            execution.last_node = node.name
            try:
                result = await self._run_node(flow, execution, node, inputs)
            except engine_executor__NodeError as exc:
                engine_executor__log.warning("node %s failed; the run %s: %s [run %s, %s]", node.name, "continues" if node.continue_on_fail else "stops",
                            engine_executor__describe_error(exc), execution.id, flow.name)
                if node.continue_on_fail:
                    # n8n passes the input on when a node throws and the node is set to continue.
                    out = [list(inputs[0]) if inputs else []]
                    self._record(execution, node.name, out, source=entry.get("source"), error=str(exc))
                    self._schedule_children(flow, execution, node.name, out, stack, region, deferred)
                    continue
                self._record(execution, node.name, None, source=entry.get("source"), error=str(exc))
                execution.status = "error"
                if execution.error is None:  # in parallel branches the first failure is the one reported
                    execution.error = {"node": node.name, "message": str(exc), "description": exc.description}
                self._fail_responder(execution)
                return "error"
            if isinstance(result, engine_executor__WaitRequest):
                if result.kind == "time" and result.till is not None:
                    delay = (result.till - engine_executor__datetime.now(engine_executor__timezone.utc)).total_seconds()
                    if delay <= 65:
                        await engine_executor__asyncio.sleep(max(0.0, delay))
                        out = [result.passthrough]
                        self._record(execution, node.name, out, source=entry.get("source"))
                        self._schedule_children(flow, execution, node.name, out, stack, region, deferred)
                        continue
                if region is not None:  # regions never hold a Wait node (model.parallel_regions)
                    raise RuntimeError(f"{node.name} cannot park the run inside a parallel branch")
                execution.run_data.setdefault(node.name, []).append(
                    {"status": "waiting", "data": [result.passthrough], "start": engine_executor__time.time(), "source": entry.get("source")})
                execution.status = "waiting"
                execution.wait = {
                    "node": node.name, "kind": result.kind,
                    "till": result.till.isoformat() if result.till else None,
                }
                return "waiting"
            out = result
            if node.always_output_data and (not out or not out[0]):
                out = list(out) if out else [[]]
                out[0] = [{"json": {}}]
            self._record(execution, node.name, out, source=entry.get("source"))
            if region is None and node.name in flow.parallel_regions:
                if not await self._run_parallel(flow, execution, node.name, out):
                    return "error"
                continue
            self._schedule_children(flow, execution, node.name, out, stack, region, deferred)

    async def _run_parallel(self, flow: engine_model__Flow, execution: engine_executor__Execution, name: str, out: engine_executor__NodeOutput) -> bool:
        """settings.parallelFanOut: the branches of `name` run at the same time (model.parallel_regions).

        Each branch runs in n8n's order inside itself. What a branch passes out of its region (a Merge, a node
        reached from elsewhere) waits and joins the normal order once every branch has finished, branch by
        branch, top-most first. A failing branch does not stop the others: each finishes its paid call and its
        budget settlement, and the run then stops with the first failure.
        """
        regions = flow.parallel_regions[name]
        heads: list[tuple[engine_model__NodeDef, int, int]] = []
        for oi, items in enumerate(out):
            if items:
                heads.extend((flow.nodes[c], oi, ii) for c, ii in flow.children(name, oi))
        branches = [h for h in heads if h[0].name in regions]
        if len(branches) < 2:
            self._schedule_children(flow, execution, name, out)
            return True
        heads.sort(key=lambda t: (t[0].position[1], t[0].position[0]))
        deferred: dict[str, list[tuple]] = {child.name: [] for child, _, _ in branches}

        async def branch(child: engine_model__NodeDef, oi: int) -> str:
            stack = [{"node": child.name, "inputs": [engine_executor__copy.deepcopy(out[oi])], "source": {"node": name, "output": oi}}]
            return await self._drain(flow, execution, stack, regions[child.name], deferred[child.name])

        results = await engine_executor__asyncio.gather(*(branch(child, oi) for child, oi, _ in heads if child.name in regions))
        if "error" in results:
            return False
        later: list[tuple] = []
        for child, oi, ii in heads:
            if child.name in regions:
                later.extend(deferred[child.name])
            else:
                later.append((child.name, ii, engine_executor__copy.deepcopy(out[oi]), {"node": name, "output": oi}))
        for target, ii, items, source in reversed(later):
            self._add(flow, execution, target, ii, items, source)
        return True

    async def _run_node(self, flow: engine_model__Flow, execution: engine_executor__Execution, node: engine_model__NodeDef, inputs: list[list[engine_model__Item]]):
        handler = self.handlers.get(node.kind)
        if handler is None:
            raise engine_executor__NodeError(f"Node type '{node.type}' is not supported by this engine")
        tries, wait_ms = engine_executor__retry_params(node)
        last: engine_executor__NodeError | None = None
        for attempt in range(tries):
            if attempt and wait_ms:
                await engine_executor__retry_pause(wait_ms / 1000.0)
            ctx = engine_executor__NodeContext(self, flow, execution, node, inputs)
            try:
                result = await handler(ctx)
            except engine_executor__NodeError as exc:
                last = exc
                if attempt < tries - 1:
                    engine_executor__log.warning("node %s failed (attempt %d of %d, retrying): %s [run %s, %s]", node.name, attempt + 1, tries,
                                engine_executor__describe_error(exc), execution.id, flow.name)
                continue
            except engine_executor__asyncio.CancelledError:
                raise
            except Exception as exc:  # unexpected failures behave like node errors
                engine_executor__log.exception("node %s failed [run %s, %s]", node.name, execution.id, flow.name)
                last = engine_executor__NodeError(str(exc) or exc.__class__.__name__)
                continue
            # n8n also retries a node that returns an error item (continue-on-fail), not only one that throws.
            if isinstance(result, engine_executor__WaitRequest) or attempt == tries - 1 or not engine_executor___first_item_failed(result):
                return result
            engine_executor__log.warning("node %s returned an error item (attempt %d of %d, retrying) [run %s, %s]", node.name, attempt + 1, tries,
                        execution.id, flow.name)
        assert last is not None
        raise last

    # ---------- bookkeeping ----------
    def _record(self, execution: engine_executor__Execution, name: str, out: engine_executor__NodeOutput | None, source: engine_executor__Any, error: str | None = None) -> None:
        run: dict[str, engine_executor__Any] = {"status": "error" if error and out is None else "success", "data": out, "start": engine_executor__time.time(), "source": source}
        if error:
            run["error"] = error
        execution.run_data.setdefault(name, []).append(run)

    def _schedule_children(self, flow: engine_model__Flow, execution: engine_executor__Execution, name: str, out: engine_executor__NodeOutput,
                           stack: list[dict[str, engine_executor__Any]] | None = None, region: frozenset[str] | None = None,
                           deferred: list[tuple] | None = None) -> None:
        to_add: list[tuple[engine_model__NodeDef, int, int]] = []
        for oi, items in enumerate(out):
            if not items:
                continue
            for child, ii in flow.children(name, oi):
                to_add.append((flow.nodes[child], oi, ii))
        # Top-most first, then left-most; added in reverse to the front of the stack.
        to_add.sort(key=lambda t: (t[0].position[1], t[0].position[0]))
        if region is not None and deferred is not None:
            for child, oi, ii in to_add:
                if child.name not in region:
                    deferred.append((child.name, ii, engine_executor__copy.deepcopy(out[oi]), {"node": name, "output": oi}))
            to_add = [t for t in to_add if t[0].name in region]
        for child, oi, ii in reversed(to_add):
            self._add(flow, execution, child.name, ii, engine_executor__copy.deepcopy(out[oi]), {"node": name, "output": oi}, stack)

    def _add(self, flow: engine_model__Flow, execution: engine_executor__Execution, name: str, input_index: int, items: list[engine_model__Item], source: dict,
             stack: list[dict[str, engine_executor__Any]] | None = None) -> None:
        n_inputs = flow.input_count(name)
        if n_inputs <= 1:
            (execution.stack if stack is None else stack).insert(0, {"node": name, "inputs": [items], "source": source})
            return
        rounds = execution.waiting.setdefault(name, [])
        slot = next((r for r in rounds if r[input_index] is None), None)
        if slot is None:
            slot = [None] * n_inputs
            rounds.append(slot)
        slot[input_index] = items
        if all(s is not None for s in slot):
            rounds.remove(slot)
            if not rounds:
                execution.waiting.pop(name, None)
            execution.stack.insert(0, {"node": name, "inputs": [s or [] for s in slot], "source": source})

    def _release_partial_merge(self, flow: engine_model__Flow, execution: engine_executor__Execution) -> bool:
        """When nothing else can run, a waiting Merge runs with the inputs it has (n8n v1 does the same)."""
        for name, rounds in list(execution.waiting.items()):
            if rounds:
                slot = rounds.pop(0)
                if not rounds:
                    execution.waiting.pop(name, None)
                execution.stack.insert(0, {"node": name, "inputs": [s or [] for s in slot], "source": None})
                return True
            execution.waiting.pop(name, None)
        return False

    def _fail_responder(self, execution: engine_executor__Execution) -> None:
        fut = execution.responder
        if fut is not None and not fut.done():
            fut.set_result(engine_executor__Response(status=500, body={"code": 0, "message": "Error in workflow"}))


class engine_executor__NodeContext:
    """What a node handler sees: its node, its input items, resolved parameters and the services."""

    def __init__(self, executor: engine_executor__Executor, flow: engine_model__Flow, execution: engine_executor__Execution, node: engine_model__NodeDef, inputs: list[list[engine_model__Item]]):
        self.executor = executor
        self.flow = flow
        self.execution = execution
        self.node = node
        self.inputs = inputs
        self.services = executor.services
        self.run_index = execution.run_index(node.name)

    @property
    def items(self) -> list[engine_model__Item]:
        return self.inputs[0] if self.inputs else []

    @property
    def continue_on_fail(self) -> bool:
        return self.node.continue_on_fail

    # ---------- data other nodes produced ----------
    def referenced_node_data(self) -> dict[str, dict[str, engine_executor__Any]]:
        names, dynamic = self.node.referenced_nodes
        if dynamic:
            names = frozenset(self.execution.run_data.keys())
        out: dict[str, dict[str, engine_executor__Any]] = {}
        for name in names:
            if name not in self.flow.nodes or not self.execution.run_data.get(name):
                continue
            oi = self.flow.output_towards(name, self.node.name)
            items = self.execution.latest_output(name, oi)
            if items is None:
                continue
            out[name] = {"items": items}
        return out

    def js_context(self) -> dict[str, engine_executor__Any]:
        return {
            "nodes": self.referenced_node_data(),
            "execution": {"id": self.execution.id, "mode": self.execution.mode, "resumeUrl": self.execution.resume_url},
            "workflow": {"id": self.flow.id, "name": self.flow.name, "active": True},
            "runIndex": self.run_index,
            "timezone": self.flow.settings.get("timezone") or "UTC",
        }

    async def params(self, items: list[engine_model__Item] | None = None) -> list["engine_executor__Params"]:
        """Node parameters with ={{ }} expressions resolved for each input item (n8n resolves per item)."""
        items = self.items if items is None else items
        raw = {k: v for k, v in self.node.parameters.items() if k != "jsCode"}
        count = max(1, len(items))
        if not self.node.has_expressions:
            return [engine_executor__Params(engine_executor__copy.deepcopy(raw), self.node.name) for _ in range(count)]
        res = await self.services.js.call(
            "resolve", params=raw, items=[engine_executor__strip_binary_data(i) for i in items] or [{"json": {}}], **self.js_context())
        return [engine_executor__Params(p, self.node.name) for p in res["perItem"]]

    # ---------- responses to the webhook caller ----------
    def respond(self, response: engine_executor__Response) -> bool:
        fut = self.execution.responder
        if fut is None or fut.done():
            return False
        fut.set_result(response)
        return True


class engine_executor__ExpressionError(engine_executor__NodeError):
    pass


class engine_executor__Params:
    """Resolved parameters of one item. Reading a value whose expression failed raises, like n8n."""

    def __init__(self, data: dict[str, engine_executor__Any], node_name: str):
        self._data = data
        self._node = node_name

    def get(self, path: str, default: engine_executor__Any = None) -> engine_executor__Any:
        cur: engine_executor__Any = self._data
        for part in path.split("."):
            if isinstance(cur, dict) and part in cur:
                cur = cur[part]
            else:
                return default
        return self._check(cur)

    def raw(self) -> dict[str, engine_executor__Any]:
        return self._data

    def _check(self, v: engine_executor__Any) -> engine_executor__Any:
        if isinstance(v, dict):
            if "__exprError__" in v and len(v) == 1:
                raise engine_executor__ExpressionError(f"Expression error in node '{self._node}': {v['__exprError__']}")
            if v.get("__rl") is True and "value" in v:
                return {**v, "value": self._check(v["value"])}
            return {k: self._check(x) for k, x in v.items()}
        if isinstance(v, list):
            return [self._check(x) for x in v]
        return v

    def rl(self, path: str, default: engine_executor__Any = None) -> engine_executor__Any:
        """Value of a resource-locator parameter ({__rl, mode, value}) or a plain value."""
        v = self.get(path, default)
        if isinstance(v, dict) and "value" in v:
            return v["value"]
        return v


async def engine_executor__retry_pause(seconds: float) -> None:
    """Wait between tries (a separate function so tests can skip the wait)."""
    await engine_executor__asyncio.sleep(seconds)


def engine_executor__retry_params(node: engine_model__NodeDef) -> tuple[int, int]:
    """n8n's WorkflowExecute.getRetryParams: tries clamped to 2..5, wait to 0..5000 ms (unset or 0 means 1000)."""
    if not node.retry_on_fail:
        return 1, 0
    return min(5, max(2, node.max_tries or 3)), min(5000, max(0, node.wait_between_tries_ms or 1000))


def engine_executor___first_item_failed(result: engine_executor__Any) -> bool:
    """n8n's checkFailure: the first item of the first output carries an error (anything but undefined/null/false)."""
    try:
        err = result[0][0]["json"].get("error")
    except (IndexError, KeyError, TypeError, AttributeError):
        return False
    return err is not None and err is not False


def engine_executor__strip_binary_data(item: engine_model__Item) -> engine_model__Item:
    """Items as the JS side sees them: binary references keep their metadata, never their bytes."""
    if "binary" not in item:
        return item
    return {**item, "binary": {k: {kk: vv for kk, vv in (v or {}).items() if kk != "content"} for k, v in item["binary"].items()}}


def engine_executor__utcnow() -> engine_executor__datetime:
    return engine_executor__datetime.now(engine_executor__timezone.utc)


def engine_executor__wait_until(hours: float = 0, seconds: float = 0) -> engine_executor__datetime:
    return engine_executor__utcnow() + engine_executor__timedelta(hours=hours, seconds=seconds)


# --- src/midas_a7/nodes/core.py ---
"""Control-flow nodes: Code, IF, Switch, Merge, No-op, Respond to Webhook, Wait and the triggers."""















# ---------- Code ----------
async def nodes_core__code(ctx: engine_executor__NodeContext):
    params = ctx.node.parameters
    if params.get("language", "javaScript") != "javaScript":
        raise engine_executor__NodeError("Only JavaScript Code nodes are supported")
    if params.get("mode", "runOnceForAllItems") != "runOnceForAllItems":
        raise engine_executor__NodeError("Only 'Run Once for All Items' Code nodes are supported")
    source = params["jsCode"]
    items = ctx.items
    binaries: dict[str, str] = {}
    if "getBinaryDataBuffer" in source or "binaryToBuffer" in source:
        for item in items:
            for ref in (item.get("binary") or {}).values():
                if isinstance(ref, dict) and ref.get("id") and ref["id"] not in binaries:
                    try:
                        binaries[ref["id"]] = nodes_core__base64.b64encode(await ctx.services.binaries.get(ref)).decode()
                    except KeyError:
                        pass  # the code gets n8n's "not available" error if it asks for it
    # Phase 1.6 (FL-10): a node that shrinks reference photos gets the engine helper for it (the runner has no image library).
    callbacks = {"resizeReference": lambda payload: nodes_core___resize_reference(ctx, payload)} if "midasResizeReference" in source else None
    try:
        res = await ctx.services.js.call(
            "code", callbacks=callbacks, code=source, items=[engine_executor__strip_binary_data(i) for i in items], binaries=binaries,
            **ctx.js_context())
    except engine_jsrunner__JsError as exc:
        raise engine_executor__NodeError(str(exc)) from exc
    out_items: list[engine_model__Item] = res["items"]
    new = res.get("newBinaries") or {}
    if new:
        stored: dict[str, dict[str, nodes_core__Any]] = {}
        for temp_id, b64 in new.items():
            stored[temp_id] = {"bytes": nodes_core__base64.b64decode(b64)}
        await nodes_core___store_new_binaries(ctx, out_items, stored)
    await nodes_core___store_inline_binaries(ctx, out_items)
    return [out_items]


async def nodes_core___resize_reference(ctx: engine_executor__NodeContext, payload: dict[str, nodes_core__Any]) -> dict[str, nodes_core__Any]:
    """this.helpers.midasResizeReference(ref, longSide): shrink a stored image to longSide px on its long side (no AI).

    Answers {resized: false, px, bytes, why} when the image is already small enough or cannot be read, else the new file's
    stored reference (`binary`) with from_px/to_px, from_bytes/to_bytes, its sha256 and its type.
    """
    ref = payload.get("ref")
    if not isinstance(ref, dict) or not ref.get("id"):
        raise engine_executor__NodeError("midasResizeReference needs a stored binary reference")
    long_side = int(payload.get("longSide") or nodes_claude_reference_resize__LONG_SIDE_PX)
    data = await ctx.services.binaries.get(ref)
    res = await nodes_core__asyncio.to_thread(nodes_claude_reference_resize__resize_reference, data, long_side)
    if not res["resized"]:
        return res
    stem = str(ref.get("fileName") or "reference").rsplit(".", 1)[0]
    stored = await ctx.services.binaries.put(ctx.execution.id, res.pop("data"), "image/jpeg", f"{stem}_{long_side}px.jpg")
    return {**res, "binary": stored}


async def nodes_core___store_inline_binaries(ctx: engine_executor__NodeContext, items: list[engine_model__Item]) -> None:
    """Code may build a binary entry by hand with the bytes inline ({data: <base64>, mimeType, fileName}),
    as n8n allows (the owner bridge does). Store those bytes and keep a normal reference."""
    for item in items:
        binary = item.get("binary")
        if not isinstance(binary, dict):
            continue
        for key, ref in list(binary.items()):
            if not isinstance(ref, dict):
                continue
            data = ref.get("data")
            if not isinstance(data, str) or data == "filesystem-v2" or str(ref.get("id", "")).startswith("bin:"):
                continue
            try:
                raw = nodes_core__base64.b64decode(data, validate=True)
            except ValueError as exc:
                raise engine_executor__NodeError(f"Binary data in field '{key}' is not valid base64") from exc
            stored = await ctx.services.binaries.put(
                ctx.execution.id, raw, ref.get("mimeType"), ref.get("fileName"), ref.get("fileExtension"))
            binary[key] = {**{k: v for k, v in ref.items() if k not in ("data", "id")}, **stored}


async def nodes_core___store_new_binaries(ctx: engine_executor__NodeContext, items: list[engine_model__Item], stored: dict[str, dict[str, nodes_core__Any]]) -> None:
    refs: dict[str, dict[str, nodes_core__Any]] = {}

    async def fix(value: nodes_core__Any) -> nodes_core__Any:
        if isinstance(value, dict):
            vid = value.get("id")
            if isinstance(vid, str) and vid in stored:
                if vid not in refs:
                    meta = value
                    refs[vid] = await ctx.services.binaries.put(
                        ctx.execution.id, stored[vid]["bytes"], meta.get("mimeType"), meta.get("fileName"), meta.get("fileExtension"))
                return {**{k: v for k, v in value.items() if k not in ("id", "bytes", "data")}, **refs[vid]}
            return {k: await fix(v) for k, v in value.items()}
        if isinstance(value, list):
            return [await fix(v) for v in value]
        return value

    for i, item in enumerate(items):
        items[i] = await fix(item)


# ---------- conditions (IF v2, Switch v3) ----------
class nodes_core___TypeError(engine_executor__NodeError):
    pass


def nodes_core___to_bool(value: nodes_core__Any, strict: bool) -> bool | None:
    if value is None:
        return None
    if isinstance(value, bool):
        return value
    if strict:
        raise nodes_core___TypeError(f"Wrong type: '{value}' is a {nodes_core___js_type(value)} but was expecting a boolean")
    if isinstance(value, (int, float)) and value in (0, 1):
        return bool(value)
    if isinstance(value, str) and value.strip().lower() in ("true", "false", "1", "0"):
        return value.strip().lower() in ("true", "1")
    raise nodes_core___TypeError(f"Wrong type: '{value}' is a {nodes_core___js_type(value)} but was expecting a boolean")


def nodes_core___to_str(value: nodes_core__Any, strict: bool) -> str | None:
    if value is None:
        return None
    if isinstance(value, str):
        return value
    if strict:
        raise nodes_core___TypeError(f"Wrong type: '{value}' is a {nodes_core___js_type(value)} but was expecting a string")
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (dict, list)):
        return nodes_core__json.dumps(value, separators=(",", ":"))
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def nodes_core___to_num(value: nodes_core__Any, strict: bool) -> float | None:
    if value is None:
        return None
    if isinstance(value, bool):
        if strict:
            raise nodes_core___TypeError(f"Wrong type: '{value}' is a boolean but was expecting a number")
        return float(value)
    if isinstance(value, (int, float)):
        return float(value)
    if strict:
        raise nodes_core___TypeError(f"Wrong type: '{value}' is a {nodes_core___js_type(value)} but was expecting a number")
    try:
        return float(str(value).strip())
    except ValueError as exc:
        raise nodes_core___TypeError(f"Wrong type: '{value}' cannot be converted to a number") from exc


def nodes_core___js_type(v: nodes_core__Any) -> str:
    if isinstance(v, bool):
        return "boolean"
    if isinstance(v, (int, float)):
        return "number"
    if isinstance(v, str):
        return "string"
    if isinstance(v, list):
        return "array"
    return "object"


def nodes_core__evaluate_condition(cond: dict[str, nodes_core__Any], strict: bool, case_sensitive: bool) -> bool:
    op = cond.get("operator") or {}
    typ, operation = op.get("type"), op.get("operation")
    left, right = cond.get("leftValue"), cond.get("rightValue")
    if operation == "exists":
        return left is not None
    if operation == "notExists":
        return left is None
    if typ == "boolean":
        lv = nodes_core___to_bool(left, strict)
        if operation == "true":
            return lv is True
        if operation == "false":
            return lv is False
        rv = nodes_core___to_bool(right, strict)
        if operation == "equals":
            return lv == rv
        if operation == "notEquals":
            return lv != rv
    elif typ == "string":
        if operation == "empty":
            return left in (None, "")
        if operation == "notEmpty":
            return left not in (None, "")
        lv, rv = nodes_core___to_str(left, strict), nodes_core___to_str(right, strict)
        if lv is None:
            lv = ""
        if rv is None:
            rv = ""
        if not case_sensitive:
            lv, rv = lv.lower(), rv.lower()
        ops = {
            "equals": lambda: lv == rv, "notEquals": lambda: lv != rv,
            "contains": lambda: rv in lv, "notContains": lambda: rv not in lv,
            "startsWith": lambda: lv.startswith(rv), "notStartsWith": lambda: not lv.startswith(rv),
            "endsWith": lambda: lv.endswith(rv), "notEndsWith": lambda: not lv.endswith(rv),
        }
        if operation in ops:
            return ops[operation]()
    elif typ == "number":
        lv, rv = nodes_core___to_num(left, strict), nodes_core___to_num(right, strict)
        ops = {
            "equals": lambda: lv == rv, "notEquals": lambda: lv != rv,
            "gt": lambda: lv is not None and rv is not None and lv > rv,
            "lt": lambda: lv is not None and rv is not None and lv < rv,
            "gte": lambda: lv is not None and rv is not None and lv >= rv,
            "lte": lambda: lv is not None and rv is not None and lv <= rv,
        }
        if operation in ops:
            return ops[operation]()
    raise engine_executor__NodeError(f"Condition operator {typ}.{operation} is not supported")


def nodes_core__evaluate_filter(conditions: dict[str, nodes_core__Any], loose_override: bool = False) -> bool:
    options = conditions.get("options") or {}
    strict = (options.get("typeValidation", "strict") == "strict") and not loose_override
    case_sensitive = options.get("caseSensitive", True)
    results = [nodes_core__evaluate_condition(c, strict, case_sensitive) for c in conditions.get("conditions") or []]
    if (conditions.get("combinator") or "and") == "or":
        return any(results)
    return all(results)


async def nodes_core__if_(ctx: engine_executor__NodeContext):
    items = ctx.items
    params = await ctx.params()
    true_items: list[engine_model__Item] = []
    false_items: list[engine_model__Item] = []
    for item, p in zip(items, params):
        loose = bool(p.get("looseTypeValidation", False))
        try:
            ok = nodes_core__evaluate_filter(p.get("conditions") or {}, loose)
        except nodes_core___TypeError as exc:
            raise engine_executor__NodeError(str(exc) + " [condition 0, item 0]") from exc
        (true_items if ok else false_items).append(item)
    return [true_items, false_items]


async def nodes_core__switch(ctx: engine_executor__NodeContext):
    items = ctx.items
    params = await ctx.params()
    first = params[0] if params else None
    if first is None or first.get("mode", "rules") != "rules":
        raise engine_executor__NodeError("Only Switch nodes in 'Rules' mode are supported")
    rules = (first.get("rules") or {}).get("values") or []
    options = first.get("options") or {}
    fallback = options.get("fallbackOutput", "none")
    all_matching = bool(options.get("allMatchingOutputs", False))
    n_out = len(rules) + (1 if fallback == "extra" else 0)
    outputs: list[list[engine_model__Item]] = [[] for _ in range(max(1, n_out))]
    for item, p in zip(items, params):
        matched = False
        loose = bool(p.get("looseTypeValidation", False))
        for ri, rule in enumerate((p.get("rules") or {}).get("values") or []):
            if nodes_core__evaluate_filter(rule.get("conditions") or {}, loose):
                outputs[ri].append(item)
                matched = True
                if not all_matching:
                    break
        if not matched:
            if fallback == "extra":
                outputs[len(rules)].append(item)
            elif isinstance(fallback, int) or (isinstance(fallback, str) and fallback.isdigit()):
                outputs[int(fallback)].append(item)
    return outputs


# ---------- Merge, No-op ----------
async def nodes_core__merge(ctx: engine_executor__NodeContext):
    mode = ctx.node.parameters.get("mode", "append")
    if mode != "append":
        raise engine_executor__NodeError(f"Merge mode '{mode}' is not supported")
    out: list[engine_model__Item] = []
    for items in ctx.inputs:
        out.extend(items or [])
    return [out]


async def nodes_core__no_op(ctx: engine_executor__NodeContext):
    return [ctx.items]


async def nodes_core__passthrough(ctx: engine_executor__NodeContext):
    return [ctx.items]


# ---------- Respond to Webhook ----------
async def nodes_core__respond_to_webhook(ctx: engine_executor__NodeContext):
    items = ctx.items
    params = (await ctx.params(items[:1] or [{"json": {}}]))[0]
    respond_with = params.get("respondWith", "firstIncomingItem")
    options = params.get("options") or {}
    status = int(options.get("responseCode") or 200)
    headers: dict[str, str] = {}
    for entry in ((options.get("responseHeaders") or {}).get("entries") or []):
        if entry.get("name"):
            headers[str(entry["name"])] = str(entry.get("value", ""))
    first = items[0] if items else {"json": {}}
    response = engine_executor__Response(status=status, headers=headers)
    if respond_with == "json":
        body = params.get("responseBody")
        if isinstance(body, str):
            try:
                body = nodes_core__json.loads(body) if body.strip() else {}
            except nodes_core__json.JSONDecodeError as exc:
                raise engine_executor__NodeError("Invalid JSON in 'Response Body' field") from exc
        response.body = body
    elif respond_with == "text":
        response.raw = str(params.get("responseBody") or "").encode()
        response.content_type = "text/html; charset=utf-8"
    elif respond_with == "firstIncomingItem":
        response.body = first.get("json", {})
    elif respond_with == "allIncomingItems":
        response.body = [i.get("json", {}) for i in items]
    elif respond_with == "noData":
        response.raw = b""
    elif respond_with == "binary":
        key = options.get("responseDataSource") == "set" and params.get("inputFieldName") or "data"
        ref = (first.get("binary") or {}).get(key)
        if not ref:
            raise engine_executor__NodeError(f"No binary data with field {key} found.")
        response.raw = await ctx.services.binaries.get(ref)
        response.content_type = ref.get("mimeType")
    else:
        raise engine_executor__NodeError(f"Respond with '{respond_with}' is not supported")
    ctx.respond(response)
    return [items]


# ---------- Wait ----------
nodes_core___UNITS = {"seconds": 1, "minutes": 60, "hours": 3600, "days": 86400}


async def nodes_core__wait(ctx: engine_executor__NodeContext):
    items = ctx.items
    p = (await ctx.params(items[:1] or [{"json": {}}]))[0]
    resume = p.get("resume", "timeInterval")
    now = nodes_core__datetime.now(nodes_core__timezone.utc)
    if resume == "webhook":
        till = None
        if p.get("limitWaitTime"):
            if p.get("limitType", "afterTimeInterval") == "afterTimeInterval":
                amount = float(p.get("resumeAmount", 1))
                till = now + nodes_core__timedelta(seconds=amount * nodes_core___UNITS[p.get("resumeUnit", "hours")])
            else:
                till = nodes_core__datetime.fromisoformat(str(p.get("maxDateAndTime")).replace("Z", "+00:00"))
        return engine_executor__WaitRequest("webhook", till, items)
    if resume == "timeInterval":
        # Wait v1.1 defaults to seconds (v1 defaulted to hours).
        default_unit = "seconds" if ctx.node.type_version >= 1.1 else "hours"
        amount = float(p.get("amount", 5 if ctx.node.type_version >= 1.1 else 1))
        return engine_executor__WaitRequest("time", now + nodes_core__timedelta(seconds=amount * nodes_core___UNITS[p.get("unit", default_unit)]), items)
    if resume == "specificTime":
        till = nodes_core__datetime.fromisoformat(str(p.get("dateTime")).replace("Z", "+00:00"))
        if till.tzinfo is None:
            till = till.replace(tzinfo=nodes_core__timezone.utc)
        return engine_executor__WaitRequest("time", till, items)
    raise engine_executor__NodeError(f"Wait mode '{resume}' is not supported")


nodes_core__HANDLERS = {
    "code": nodes_core__code,
    "if": nodes_core__if_,
    "switch": nodes_core__switch,
    "merge": nodes_core__merge,
    "noOp": nodes_core__no_op,
    "respondToWebhook": nodes_core__respond_to_webhook,
    "wait": nodes_core__wait,
    "webhook": nodes_core__passthrough,
    "manualTrigger": nodes_core__passthrough,
    "scheduleTrigger": nodes_core__passthrough,
}


# --- src/midas_a7/nodes/http_request.py ---
"""HTTP Request node (n8n-nodes-base.httpRequest, typeVersion 4.1, 4.2 and 4.5 as the A7 flows use it).

Behaviour follows n8n's source (read at master, with the 1.123 request layer where it has since moved):
- packages/nodes-base/nodes/HttpRequest/V3/HttpRequestV3.node.ts      parameters, batching, output shapes
- packages/nodes-base/nodes/HttpRequest/GenericFunctions.ts           multipart / key-value bodies, binary content types
- packages/nodes-base/nodes/HttpRequest/V3/utils/{binaryData,parse,buffer-decoding,error-details}.ts
- packages/core/.../request-helpers (parseRequestObject, proxyRequestToAxios)   what goes on the wire, axios errors
- packages/core/.../utils/binary-helper-functions.ts                  prepareBinaryData, assertBinaryData
- packages/workflow/src/errors/{node-api.error,abstract/node.error}.ts   NodeApiError texts
- packages/nodes-base/credentials/OpenAiApi.credentials.ts            Authorization: Bearer <key>
- packages/@n8n/nodes-langchain/credentials/GooglePalmApi.credentials.ts   query string `key=<key>`

Supported: method, url, authentication none / header auth (the node's credential by name) / OpenAI / Google
Gemini(PaLM); body as JSON (text or object), key/value, multipart form data (text fields and n8n binary files),
form-urlencoded, raw and binary; headers; query string; options timeout, redirects, batching and response
(fullResponse, neverError, responseFormat autodetect|json|text|file, outputPropertyName). Options the flows do not
use and that cannot be done safely here (pagination, proxy, SSL client certificates, "ignore SSL issues", OAuth and
other credential types) raise a clear error instead of being ignored.

Output per input item (see `_format`): fullResponse -> {body, headers, statusCode, statusMessage} (text: the body
under outputPropertyName, file: the body as binary); otherwise the body itself, an array body giving one item per
element. Each input item is one request; the requests of a batch start together and `batchInterval` ms pass between
the starts of batches (n8n does not wait for an answer before it starts the next batch).
"""
























