# ---------- JavaScript-compatible serialisation ----------
def nodes_http_request___js_number(x: float) -> str:
    """Number.prototype.toString for a float (JSON.stringify prints 1.0 as 1 and 0.000001 as 0.000001)."""
    if x != x or x in (float("inf"), float("-inf")):
        return "null"
    if x == 0:
        return "0"
    sign = "-" if x < 0 else ""
    t = nodes_http_request__Decimal(repr(abs(x))).as_tuple()
    all_digits = "".join(map(str, t.digits))
    digits = all_digits.rstrip("0") or "0"
    exp = t.exponent + len(all_digits)  # value = 0.<digits> x 10^exp
    k = len(digits)
    if k <= exp <= 21:
        return sign + digits + "0" * (exp - k)
    if 0 < exp <= 21:
        return sign + digits[:exp] + "." + digits[exp:]
    if -6 < exp <= 0:
        return sign + "0." + "0" * (-exp) + digits
    e = exp - 1
    return f"{sign}{digits[0]}{'.' + digits[1:] if k > 1 else ''}e{'+' if e >= 0 else '-'}{abs(e)}"


def nodes_http_request__js_stringify(v: nodes_http_request__Any) -> str:
    """JSON.stringify(v): compact, non-ASCII kept, numbers printed the JavaScript way."""
    if v is None:
        return "null"
    if v is True:
        return "true"
    if v is False:
        return "false"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        return nodes_http_request___js_number(v)
    if isinstance(v, str):
        return nodes_http_request__json.dumps(v, ensure_ascii=False)
    if isinstance(v, (list, tuple)):
        return "[" + ",".join(nodes_http_request__js_stringify(x) for x in v) + "]"
    if isinstance(v, dict):
        return "{" + ",".join(nodes_http_request__json.dumps(str(k), ensure_ascii=False) + ":" + nodes_http_request__js_stringify(x) for k, x in v.items()) + "}"
    return nodes_http_request__json.dumps(str(v), ensure_ascii=False)


def nodes_http_request___reject_constant(name: str) -> nodes_http_request__Any:
    raise ValueError(f"{name} is not valid JSON")


def nodes_http_request__js_json_parse(text: str) -> nodes_http_request__Any:
    """JSON.parse: raises ValueError for what JavaScript would reject too (NaN, Infinity, empty text)."""
    return nodes_http_request__json.loads(text, parse_constant=nodes_http_request___reject_constant)


def nodes_http_request___truthy(v: nodes_http_request__Any) -> bool:
    """JavaScript truthiness ([] and {} are truthy)."""
    return not (v is None or v is False or v == "" or (isinstance(v, (int, float)) and not isinstance(v, bool) and v == 0))


def nodes_http_request___text(v: nodes_http_request__Any) -> str:
    """A parameter value as the text n8n would put in a form field or query string."""
    if isinstance(v, str):
        return v
    if v is True:
        return "true"
    if v is False:
        return "false"
    if v is None:
        return ""
    return nodes_http_request__js_stringify(v) if isinstance(v, (dict, list, float)) else str(v)


def nodes_http_request___js_type(v: nodes_http_request__Any) -> str:
    return "undefined" if v is None else "boolean" if isinstance(v, bool) else "number" if isinstance(v, (int, float)) else "object"


# ---------- bodies, query strings, names ----------
def nodes_http_request___set_path(target: dict[str, nodes_http_request__Any], path: str, value: nodes_http_request__Any) -> None:
    """lodash.set: 'a.b' makes nested objects, 'a[0]' arrays."""
    tokens = nodes_http_request__re.findall(r"[^.\[\]]+", path)
    cur: nodes_http_request__Any = target
    for i, tok in enumerate(tokens):
        key: nodes_http_request__Any = int(tok) if isinstance(cur, list) and tok.isdigit() else tok
        if isinstance(cur, list):
            while len(cur) <= key:
                cur.append(None)
            existing = cur[key]
        else:
            existing = cur.get(key)
        if i == len(tokens) - 1:
            cur[key] = value
            return
        if not isinstance(existing, (dict, list)):
            existing = [] if tokens[i + 1].isdigit() else {}
            cur[key] = existing
        cur = existing


def nodes_http_request___enc(s: str) -> str:
    return nodes_http_request__quote(s, safe="-_.!~*'()")


def nodes_http_request___serialize_qs(params: dict[str, nodes_http_request__Any], array_format: str = "indices") -> str:
    """qs.stringify: nested values as a[b]=c, arrays as a[0]=x (default), a[]=x or repeated keys."""
    parts: list[str] = []

    def walk(key: str, value: nodes_http_request__Any) -> None:
        if value is None:
            return
        if isinstance(value, dict):
            for k, v in value.items():
                walk(f"{key}[{k}]", v)
        elif isinstance(value, (list, tuple)):
            for i, v in enumerate(value):
                walk(key if array_format == "repeat" else f"{key}[]" if array_format == "brackets" else f"{key}[{i}]", v)
        else:
            parts.append(f"{nodes_http_request___enc(key)}={nodes_http_request___enc(nodes_http_request___text(value))}")

    for k, v in params.items():
        walk(str(k), v)
    return "&".join(parts)


def nodes_http_request___add_param(target: dict[str, nodes_http_request__Any], name: str, value: nodes_http_request__Any, version: float) -> None:
    """updadeQueryParameterConfig: before 4.3 the last value wins, later versions collect repeats into a list."""
    if version < 4.3 or name not in target:
        target[name] = value
    elif isinstance(target[name], list):
        target[name].append(value)
    else:
        target[name] = [target[name], value]


def nodes_http_request___path_parse(path: str) -> tuple[str, str]:
    """(base, extension without the dot) like Node's path.parse."""
    base = path.rstrip("/").rsplit("/", 1)[-1] if path else ""
    dot = base.rfind(".")
    return base, (base[dot + 1:] if dot > 0 else "")


def nodes_http_request___mime_part(content_type: str | None) -> str | None:
    """mimeTypeFromResponse: 'image/jpeg; charset=x' -> 'image/jpeg'."""
    return content_type.split(" ")[0].split(";")[0] if content_type else None


def nodes_http_request___content_disposition_filename(value: str | None) -> str | None:
    if not value:
        return None
    m = nodes_http_request__re.search(r"filename\*\s*=\s*[^']*'[^']*'([^;]+)", value, nodes_http_request__re.I)
    if m:
        return nodes_http_request__unquote(m.group(1).strip().strip('"'))
    m = nodes_http_request__re.search(r'filename\s*=\s*(?:"([^"]*)"|([^;]+))', value, nodes_http_request__re.I)
    if m:
        return (m.group(1) if m.group(1) is not None else m.group(2)).strip()
    return None


def nodes_http_request___decode(data: bytes, content_type: str | None = None) -> str:
    """Text of a response: the charset of the Content-Type when it names one, else UTF-8; a BOM is dropped."""
    enc = "utf-8"
    m = nodes_http_request__re.search(r"charset=([^;,\s]+)", content_type or "", nodes_http_request__re.I)
    if m:
        try:
            enc = nodes_http_request__codecs.lookup(m.group(1).strip("'\"").lower()).name
        except LookupError:
            enc = "utf-8"
    text = data.decode(enc, errors="replace")
    return text[1:] if text.startswith(nodes_http_request__BOM) else text


# ---------- failures ----------
class nodes_http_request__RequestFailure(Exception):
    """A request that axios would have rejected: network error, timeout, or a status outside 2xx (neverError off)."""

    def __init__(self, message: str, code: str | None = None, status: int | None = None, status_text: str = "",
                 headers: dict[str, nodes_http_request__Any] | None = None, body: nodes_http_request__Any = None, has_body: bool = False):
        if status == 429:  # HttpRequestV3 rewrites the message of a 429 before anything reads it
            message = "Try spacing your requests out using the batching settings under 'Options'"
        super().__init__(message)
        self.message = message
        self.code = code
        self.status = status
        self.status_text = status_text
        self.headers = headers or {}
        self.body = body
        self.has_body = has_body

    def axios_error(self, url: str, method: str) -> dict[str, nodes_http_request__Any]:
        """What n8n puts in `json.error` when the node continues on fail (request headers and body left out: they hold secrets)."""
        out: dict[str, nodes_http_request__Any] = {"message": self.message, "name": "AxiosError"}
        if self.code:
            out["code"] = self.code
        if self.status is not None:
            out.update({"status": self.status, "statusCode": self.status})
            if self.has_body:
                out["error"] = self.body
            out["response"] = {"headers": self.headers, "status": self.status, "statusText": self.status_text}
        out["options"] = {"url": url, "method": method.lower()}
        return out


def nodes_http_request___find_property(obj: dict[str, nodes_http_request__Any], keys: tuple[str, ...], traversal: tuple[str, ...] = ()) -> str | None:
    """NodeError.findProperty: the first message-like (or status-like) text in an error object, depth first."""
    for key in keys:
        value = obj.get(key)
        if not nodes_http_request___truthy(value):
            continue
        if isinstance(value, str):
            try:
                value = nodes_http_request__js_json_parse(value)
            except ValueError:
                return value
            if isinstance(value, str):
                return value
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            return nodes_http_request___text(value)
        if isinstance(value, list):
            found: list[str] = []
            for el in value:
                if isinstance(el, str):
                    found.append(el)
                elif isinstance(el, (int, float)) and not isinstance(el, bool):
                    found.append(nodes_http_request___text(el))
                elif isinstance(el, dict) and el:
                    sub = nodes_http_request___find_property(el, keys)
                    if sub is not None:
                        found.append(sub)
            return " | ".join(found) if found else None
        if isinstance(value, dict) and value:
            prop = nodes_http_request___find_property(value, keys)
            if prop:
                return prop
    for key in traversal:
        value = obj.get(key)
        if isinstance(value, dict) and value:
            prop = nodes_http_request___find_property(value, keys, traversal)
            if prop:
                return prop
    return None


def nodes_http_request__api_error_fields(failure: nodes_http_request__RequestFailure) -> tuple[str, str | None, str | None]:
    """(message, description, http_code) as NodeApiError builds them from an axios error."""
    reason: dict[str, nodes_http_request__Any] = {"message": failure.message}
    if failure.code:
        reason["code"] = failure.code
    if failure.status is not None:
        reason.update({"statusCode": failure.status, "status": failure.status, "response": {
            "headers": failure.headers, "status": failure.status, "statusText": failure.status_text}})
        if failure.has_body:
            reason["error"] = failure.body
    message = reason["message"] or ""
    http_code = str(failure.status) if failure.status is not None else nodes_http_request___find_property(
        reason, nodes_http_request__POSSIBLE_ERROR_STATUS_KEYS, nodes_http_request__POSSIBLE_NESTED_ERROR_OBJECT_KEYS)
    description = nodes_http_request___find_property(reason, nodes_http_request__POSSIBLE_ERROR_MESSAGE_KEYS, nodes_http_request__POSSIBLE_NESTED_ERROR_OBJECT_KEYS)
    # setDefaultStatusCodeMessage
    if http_code and http_code in nodes_http_request__STATUS_CODE_MESSAGES:
        message = nodes_http_request__STATUS_CODE_MESSAGES[http_code]
    elif http_code and http_code[0] == "4":
        message = nodes_http_request__STATUS_CODE_MESSAGES["4XX"]
    elif http_code and http_code[0] == "5":
        message = nodes_http_request__STATUS_CODE_MESSAGES["5XX"]
    elif not message:
        message, description = (description, None) if description else (nodes_http_request__UNKNOWN_ERROR_MESSAGE, nodes_http_request__UNKNOWN_ERROR_DESCRIPTION)
    if message == description:
        description = None
    # setDescriptiveErrorMessage
    code = (http_code or failure.code or "").upper()
    if code in nodes_http_request__COMMON_ERRORS:
        message = nodes_http_request__COMMON_ERRORS[code]
    else:
        for known, text in nodes_http_request__COMMON_ERRORS.items():
            if known in message.upper():
                message = text
                break
    return message, description, http_code


# ---------- one request ----------
@nodes_http_request__dataclass
class nodes_http_request__Prepared:
    method: str
    url: str  # with the credential's query string
    safe_url: str  # without it: for error items and file names
    headers: dict[str, str]
    content: bytes | None
    timeout_ms: float
    follow_redirects: bool
    never_error: bool
    secrets: tuple[str, ...] = ()  # values that must never appear in an error text


@nodes_http_request__dataclass
class nodes_http_request__RawResponse:
    status: int
    reason: str
    headers: dict[str, nodes_http_request__Any]
    body: bytes
    url: str


def nodes_http_request___opt(options: nodes_http_request__Any, *path: str) -> nodes_http_request__Any:
    cur = options
    for part in path:
        if not isinstance(cur, dict):
            return None
        cur = cur.get(part)
    return cur


def nodes_http_request___has_header(headers: dict[str, str], name: str) -> bool:
    return any(k.lower() == name for k in headers)


def nodes_http_request___drop_header(headers: dict[str, str], name: str) -> None:
    for k in [k for k in headers if k.lower() == name]:
        del headers[k]


async def nodes_http_request___binary_bytes(ctx: engine_executor__NodeContext, ref: dict[str, nodes_http_request__Any]) -> bytes:
    if ref.get("id"):
        try:
            return await ctx.services.binaries.get(ref)
        except KeyError as exc:
            raise engine_executor__NodeError(f"The binary data of '{ref.get('fileName') or ref['id']}' is not available") from exc
    data = ref.get("data")
    return nodes_http_request__base64.b64decode(data) if isinstance(data, str) and data and data != "filesystem-v2" else b""


def nodes_http_request___assert_binary(item: engine_model__Item, name: nodes_http_request__Any, idx: int) -> dict[str, nodes_http_request__Any]:
    """this.helpers.assertBinaryData: the binary reference called `name` on the input item."""
    if not isinstance(name, str):
        raise engine_executor__NodeError("Provided parameter is not a string or binary data object.",
                        description='Specify the property name of the binary data in input item or use an expression to '
                                    'access the binary data in previous nodes, e.g. "{{ $(_target_node_).item.binary[_binary_property_name_] }}"')
    binary = item.get("binary")
    if binary is None:
        raise engine_executor__NodeError(f"This operation expects the node's input data to contain a binary file '{name}', but none was found [item {idx}]",
                        description="Make sure that the previous node outputs a binary file")
    if binary.get(name) is None:
        raise engine_executor__NodeError(f"The item has no binary field '{name}' [item {idx}]",
                        description="Check that the parameter where you specified the input binary field name is correct, "
                                    "and that it matches a field in the binary input")
    return binary[name]


def nodes_http_request___multipart(fields: list[tuple[str, nodes_http_request__Any]]) -> tuple[bytes, str]:
    """A multipart/form-data body laid out like the form-data package writes it: a field value is text, or a
    (bytes, file_name, content_type) tuple for a file."""
    boundary = "--------------------------" + "".join(str(nodes_http_request__random.randrange(10)) for _ in range(24))
    out = bytearray()
    for name, value in fields:
        out += f"--{boundary}\r\n".encode()
        if isinstance(value, tuple):
            data, file_name, content_type = value
            out += f'Content-Disposition: form-data; name="{name}"; filename="{file_name}"\r\n'.encode()
            out += f"Content-Type: {content_type}\r\n\r\n".encode() + data
        else:
            out += f'Content-Disposition: form-data; name="{name}"\r\n\r\n'.encode() + nodes_http_request___text(value).encode()
        out += b"\r\n"
    out += f"--{boundary}--\r\n".encode()
    return bytes(out), f"multipart/form-data; boundary={boundary}"


def nodes_http_request___credentials(ctx: engine_executor__NodeContext, p: engine_executor__Params, auth: str | None, generic_type: str | None) -> tuple[nodes_http_request__Any, str | None, str | None]:
    """(header credential, api-key type, api key) for the node's authentication; the secrets come from the environment."""
    try:
        if auth == "genericCredentialType":
            if generic_type != "httpHeaderAuth":
                raise engine_executor__NodeError(f"Authentication '{generic_type}' is not supported by this engine")
            name = ((ctx.node.credentials or {}).get("httpHeaderAuth") or {}).get("name")
            if not name:
                raise engine_executor__NodeError('Node does not have any credentials set for "httpHeaderAuth"')
            return ctx.services.credentials.header(name), None, None
        if auth == "predefinedCredentialType":
            cred_type = p.get("nodeCredentialType")
            if cred_type not in ("openAiApi", "googlePalmApi"):
                raise engine_executor__NodeError(f"Credential type '{cred_type}' is not supported by this engine")
            return None, cred_type, ctx.services.credentials.api_key(cred_type)
    except config__MissingCredential as exc:
        raise engine_executor__NodeError(str(exc)) from exc
    return None, None, None


async def nodes_http_request___prepare(ctx: engine_executor__NodeContext, idx: int, p: engine_executor__Params, item: engine_model__Item, auth: str | None, generic_type: str | None) -> nodes_http_request__Prepared:
    """Everything HttpRequestV3 does to build the request of one item."""
    version = ctx.node.type_version
    header_cred, key_type, api_key = nodes_http_request___credentials(ctx, p, auth, generic_type)

    url = p.get("url")
    if not isinstance(url, str):
        raise engine_executor__NodeError(f"URL parameter must be a string, got {nodes_http_request___js_type(url)}")
    url = url.strip()
    if not url:
        raise engine_executor__NodeError("URL parameter cannot be empty")
    if not url.startswith(("http://", "https://")):
        raise engine_executor__NodeError(f'Invalid URL: {url}. URL must start with "http" or "https".')

    options = p.get("options", {}) or {}
    for unsupported, what in (("proxy", "The proxy option"), ("allowUnauthorizedCerts", "Ignoring SSL issues"),
                              ("provideSslCertificates", "SSL client certificates")):
        if options.get(unsupported) or (unsupported == "provideSslCertificates" and p.get(unsupported, False)):
            raise engine_executor__NodeError(f"{what} is not supported by this engine")
    method = str(p.get("method", "GET")).upper()
    send_body = bool(p.get("sendBody", False))
    response_opts = nodes_http_request___opt(options, "response", "response") or {}
    response_format = response_opts.get("responseFormat") or "autodetect"
    if options.get("redirect") is None:
        follow = version >= 4
    else:
        follow = bool((nodes_http_request___opt(options, "redirect", "redirect") or {}).get("followRedirects", True))

    # ----- body -----
    content_type = p.get("contentType", "json") if send_body else ""
    specify_body = p.get("specifyBody", "keypair" if content_type == "json" else "")
    body_params = p.get("bodyParameters.parameters", []) or []
    body: nodes_http_request__Any = None
    fields: list[tuple[str, nodes_http_request__Any]] = []
    if send_body:
        if content_type == "multipart-form-data":
            for entry in body_params:
                name, value = str(entry.get("name")), entry.get("value")
                if entry.get("parameterType") == "formBinaryData":
                    field = entry.get("inputDataFieldName")
                    if not field:
                        continue  # an empty binary field name is skipped
                    ref = nodes_http_request___assert_binary(item, field, idx)
                    file_name = (ref.get("fileName") or "file").replace("\\", "/").rsplit("/", 1)[-1]
                    mime = ref.get("mimeType") or nodes_http_request__mimetypes.guess_type(file_name)[0] or "application/octet-stream"
                    value = (await nodes_http_request___binary_bytes(ctx, ref), file_name, mime)
                if version < 4.2:  # a plain object before 4.2: one entry per name, the last value wins
                    fields = [(n, value if n == name else v) for n, v in fields] if any(n == name for n, _ in fields) \
                        else fields + [(name, value)]
                else:
                    fields.append((name, value))
        elif specify_body == "json":
            raw = p.get("jsonBody", "")
            if isinstance(raw, (dict, list)):
                body = raw  # an expression that already gave an object
            else:
                try:
                    body = nodes_http_request__js_json_parse(raw if isinstance(raw, str) else "")
                except ValueError as exc:
                    raise engine_executor__NodeError('The value in the "JSON Body" field is not valid JSON', description=str(exc)) from exc
        elif specify_body == "string":
            body = dict(nodes_http_request__parse_qsl(str(p.get("body", "")), keep_blank_values=True))
        elif specify_body == "keypair" or content_type in ("json", "form-urlencoded"):
            body = {}
            for entry in body_params:
                if content_type == "json" and version >= 4:
                    nodes_http_request___set_path(body, str(entry.get("name", "")), entry.get("value"))
                else:
                    nodes_http_request___add_param(body, str(entry.get("name", "")), entry.get("value"), version)

    # the content type a body brings, and whether it replaces a header the user set
    content: bytes | None = None
    body_ct: tuple[str, bool] | None = None
    if send_body and method not in nodes_http_request__BODYLESS_METHODS:
        if content_type == "multipart-form-data":
            content, ct = nodes_http_request___multipart(fields)
            body_ct = (ct, True)
        elif content_type == "form-urlencoded":
            content = nodes_http_request___serialize_qs(body if isinstance(body, dict) else {}).encode()
            body_ct = ("application/x-www-form-urlencoded", True)
        elif content_type == "binaryData":
            ref = nodes_http_request___assert_binary(item, p.get("inputDataFieldName"), idx)
            content = await nodes_http_request___binary_bytes(ctx, ref)
            body_ct = (ref.get("mimeType") or "application/octet-stream", False)
        elif content_type == "raw":
            content = str(p.get("body", "")).encode()
            body_ct = (str(p.get("rawContentType", "")), True)
        elif body is not None:
            content = body.encode() if isinstance(body, str) else nodes_http_request__js_stringify(body).encode()
            body_ct = ("application/json", False)

    # ----- query string -----
    qs: dict[str, nodes_http_request__Any] = {}
    if p.get("sendQuery", False):
        if p.get("specifyQuery", "keypair") == "keypair":
            for entry in p.get("queryParameters.parameters", []) or []:
                nodes_http_request___add_param(qs, str(entry.get("name", "")), entry.get("value"), version)
        else:
            qs = nodes_http_request___json_param(p.get("jsonQuery", ""), "JSON Query Parameters")

    # ----- headers -----
    headers: dict[str, str] = {}
    if p.get("sendHeaders", False):
        if p.get("specifyHeaders", "keypair") == "keypair":
            extra: dict[str, nodes_http_request__Any] = {}
            for entry in p.get("headerParameters.parameters", []) or []:
                if entry.get("name"):
                    nodes_http_request___add_param(extra, str(entry["name"]), entry.get("value"), version)
        else:
            extra = nodes_http_request___json_param(p.get("jsonHeaders", ""), "JSON Headers")
        lowercase = options.get("lowercaseHeaders")
        for k, v in extra.items():
            k = str(k).lower() if lowercase is None or lowercase else str(k)
            nodes_http_request___drop_header(headers, k.lower())
            headers[k] = nodes_http_request___text(v)
    if body_ct is not None and (body_ct[1] or not nodes_http_request___has_header(headers, "content-type")):
        nodes_http_request___drop_header(headers, "content-type")
        headers["content-type"] = body_ct[0]

    # ----- credentials -----
    credential_qs: dict[str, nodes_http_request__Any] = {}
    if header_cred is not None:
        nodes_http_request___drop_header(headers, header_cred.header.lower())
        headers[header_cred.header] = header_cred.value
    elif key_type == "openAiApi":
        nodes_http_request___drop_header(headers, "authorization")
        headers["Authorization"] = f"Bearer {api_key}"
    elif key_type == "googlePalmApi":
        credential_qs["key"] = api_key

    if not nodes_http_request___has_header(headers, "accept"):
        headers["accept"] = nodes_http_request__ACCEPT_JSON if response_format == "json" else nodes_http_request__ACCEPT_TEXT if response_format == "text" else nodes_http_request__ACCEPT_ANY
    if not nodes_http_request___has_header(headers, "user-agent"):
        headers["user-agent"] = nodes_http_request__USER_AGENT

    def with_query(params: dict[str, nodes_http_request__Any]) -> str:
        base = url.split("#", 1)[0]
        text = nodes_http_request___serialize_qs(params, options.get("queryParameterArrays") or "indices")
        return base + ("&" if "?" in base else "?") + text if text else base

    return nodes_http_request__Prepared(method=method, url=with_query({**qs, **credential_qs}), safe_url=with_query(qs), headers=headers,
                    content=content, timeout_ms=float(options.get("timeout") or nodes_http_request__DEFAULT_TIMEOUT_MS), follow_redirects=follow,
                    never_error=bool(response_opts.get("neverError", False)), secrets=(api_key,) if api_key else ())


def nodes_http_request___json_param(raw: nodes_http_request__Any, field: str) -> dict[str, nodes_http_request__Any]:
    try:
        value = raw if isinstance(raw, dict) else nodes_http_request__js_json_parse(raw)
    except (ValueError, TypeError) as exc:
        raise engine_executor__NodeError(f'The value in the "{field}" field is not valid JSON', description=str(exc)) from exc
    return value if isinstance(value, dict) else {}


def nodes_http_request___response_headers(response: nodes_http_request__httpx.Response) -> dict[str, nodes_http_request__Any]:
    """Lower-cased names like Node's; repeated headers are joined, set-cookie stays a list."""
    out: dict[str, nodes_http_request__Any] = {}
    for key, value in response.headers.multi_items():
        key = key.lower()
        if key == "set-cookie":
            out.setdefault(key, []).append(value)
        else:
            out[key] = f"{out[key]}, {value}" if key in out else value
    if str(out.get("content-encoding", "")).lower() in ("gzip", "compress", "deflate", "br", "zstd"):
        del out["content-encoding"]  # axios decompresses and then drops the header
    return out


async def nodes_http_request___send(ctx: engine_executor__NodeContext, req: nodes_http_request__Prepared) -> nodes_http_request__RawResponse:
    """Run the request; addresses of this service go to the app's own client. Failures are shaped like axios errors."""
    client, url = ctx.services.route(req.url)
    ms = int(req.timeout_ms) if float(req.timeout_ms).is_integer() else req.timeout_ms
    try:
        resp = await client.request(req.method, url, headers=req.headers, content=req.content,
                                    timeout=nodes_http_request__httpx.Timeout(req.timeout_ms / 1000.0), follow_redirects=req.follow_redirects)
    except nodes_http_request__httpx.TimeoutException as exc:
        raise nodes_http_request__RequestFailure(f"timeout of {ms}ms exceeded", "ECONNABORTED") from exc
    except nodes_http_request__httpx.TooManyRedirects as exc:
        raise nodes_http_request__RequestFailure("Maximum number of redirects exceeded", "ERR_FR_TOO_MANY_REDIRECTS") from exc
    except nodes_http_request__httpx.TransportError as exc:
        raise nodes_http_request___transport_failure(exc, req) from exc
    except Exception as exc:  # whatever else a transport raises is a failure of this one request
        text = str(exc) or exc.__class__.__name__
        for secret in req.secrets:
            text = text.replace(secret, "[removed]")
        raise nodes_http_request__RequestFailure(text) from exc
    return nodes_http_request__RawResponse(status=resp.status_code, reason=resp.reason_phrase or "", headers=nodes_http_request___response_headers(resp),
                       body=resp.content, url=str(resp.url))


def nodes_http_request___transport_failure(exc: nodes_http_request__httpx.TransportError, req: nodes_http_request__Prepared) -> nodes_http_request__RequestFailure:
    """Node-style codes (ENOTFOUND, ECONNREFUSED, ECONNRESET) from what httpx/anyio report, found along the cause chain."""
    parts = nodes_http_request__urlsplit(req.safe_url)
    target = f"{parts.hostname}:{parts.port or (443 if parts.scheme == 'https' else 80)}"
    chain: list[BaseException] = []
    cur: BaseException | None = exc
    while cur is not None and cur not in chain and len(chain) < 8:
        chain.append(cur)
        cur = cur.__cause__ or cur.__context__
    code: str | None = None
    for e in chain:
        if isinstance(e, nodes_http_request__socket.gaierror):
            code = "ENOTFOUND"
        elif isinstance(e, ConnectionRefusedError) or (isinstance(e, OSError) and "All connection attempts failed" in str(e)):
            code = "ECONNREFUSED"
        elif isinstance(e, (ConnectionResetError, BrokenPipeError)):
            code = "ECONNRESET"
        if code:
            break
    if code is None and isinstance(exc, nodes_http_request__httpx.RemoteProtocolError):
        code = "ECONNRESET"
    message = {"ENOTFOUND": f"getaddrinfo ENOTFOUND {parts.hostname}", "ECONNREFUSED": f"connect ECONNREFUSED {target}",
               "ECONNRESET": "socket hang up"}.get(code or "")
    if message is None:
        message = str(exc) or exc.__class__.__name__
        for secret in req.secrets:
            message = message.replace(secret, "[removed]")
    return nodes_http_request__RequestFailure(message, code)


# ---------- the answer ----------
def nodes_http_request___axios_parse(text: str) -> nodes_http_request__Any:
    """axios' default transformResponse: text that is JSON becomes data, anything else stays text; empty is undefined."""
    if text == "":
        return None
    try:
        return nodes_http_request__js_json_parse(text)
    except ValueError:
        return text


def nodes_http_request___failure_for_status(raw: nodes_http_request__RawResponse, parse_json: bool) -> nodes_http_request__RequestFailure:
    """The axios error for a status outside 2xx: message '<status> - <JSON of the body>'."""
    text = nodes_http_request___decode(raw.body, raw.headers.get("content-type"))
    body: nodes_http_request__Any = text
    if parse_json:
        try:
            body = nodes_http_request__js_json_parse(text)
        except ValueError:
            body = text
    code = {4: "ERR_BAD_REQUEST", 5: "ERR_BAD_RESPONSE"}.get(raw.status // 100)
    return nodes_http_request__RequestFailure(f"{raw.status} - {nodes_http_request__js_stringify(body)}", code, raw.status, raw.reason, raw.headers, body, True)


def nodes_http_request___as_json_object(value: nodes_http_request__Any) -> dict[str, nodes_http_request__Any]:
    if value is None:
        return {}
    if isinstance(value, dict):
        return value
    raise engine_executor__NodeError("A 'json' property isn't an object", description="In the returned data, every key named 'json' must point to an object.")


async def nodes_http_request___store_file(ctx: engine_executor__NodeContext, raw: nodes_http_request__RawResponse, req: nodes_http_request__Prepared, output_name: str) -> dict[str, nodes_http_request__Any]:
    """prepareBinaryData for a downloaded stream, then HttpRequestV3's setFilename."""
    mime = nodes_http_request___mime_part(raw.headers.get("content-type"))
    path = nodes_http_request___content_disposition_filename(raw.headers.get("content-disposition")) or nodes_http_request__urlsplit(raw.url).path[1:]
    if not mime and path:
        mime = nodes_http_request__mimetypes.guess_type(path)[0]
    mime = mime or "text/plain"
    ext = nodes_http_request__MIME_EXTENSIONS.get(mime) or (nodes_http_request__mimetypes.guess_extension(mime) or "").lstrip(".") or None
    file_name: str | None = None
    if path:
        file_name, path_ext = nodes_http_request___path_parse(path)
        ext = path_ext or ext
    if not file_name and ext:
        uri = req.safe_url.split("?", 1)[0]
        file_name = uri.split("/")[-1] if uri.endswith(ext) else f"{output_name or 'data'}.{ext}"
    return await ctx.services.binaries.put(ctx.execution.id, raw.body, mime, file_name or None, ext)


async def nodes_http_request___format(ctx: engine_executor__NodeContext, item: engine_model__Item, raw: nodes_http_request__RawResponse, req: nodes_http_request__Prepared, p0: engine_executor__Params) -> list[engine_model__Item]:
    """The item(s) HttpRequestV3 returns for one answer."""
    response_opts = nodes_http_request___opt(p0.get("options", {}) or {}, "response", "response") or {}
    full = bool(response_opts.get("fullResponse", False))
    fmt = response_opts.get("responseFormat") or "autodetect"
    out_name = response_opts.get("outputPropertyName") or "data"
    never_error = bool(response_opts.get("neverError", False))
    content_type = raw.headers.get("content-type") or ""

    body: nodes_http_request__Any
    if fmt in ("autodetect", "file"):
        body = raw.body  # a stream in n8n
        if fmt == "autodetect":
            if "application/json" in content_type:
                fmt = "json"
                text = nodes_http_request___decode(raw.body, content_type)
                try:
                    body = nodes_http_request__js_json_parse(text) if text.strip() else {}
                except ValueError:
                    if not never_error:
                        raise engine_executor__NodeError("Invalid JSON in response body") from None
                    body = {}
            elif any(t in content_type for t in nodes_http_request__BINARY_CONTENT_TYPES):
                fmt = "file"
            else:
                fmt = "text"
                body = nodes_http_request___decode(raw.body, content_type) or None
    else:  # json and text: axios already turned JSON text into data
        body = nodes_http_request___axios_parse(raw.body.decode("utf-8", errors="replace").removeprefix(nodes_http_request__BOM))

    meta = {"headers": raw.headers, "statusCode": raw.status, "statusMessage": raw.reason}

    if fmt == "file":
        binary = dict(item.get("binary") or {})
        binary[out_name] = await nodes_http_request___store_file(ctx, raw, req, out_name)
        return [{"json": meta if full else nodes_http_request__copy.deepcopy(item.get("json") or {}), "binary": binary}]

    if fmt == "text":
        text_value = nodes_http_request__js_stringify(body) if isinstance(body, (dict, list)) else body
        data = {} if text_value is None else {out_name: text_value}
        return [{"json": {**data, **meta} if full else data}]

    # json
    if isinstance(body, str):
        try:
            body = {} if not body.strip() else nodes_http_request__js_json_parse(body)
        except ValueError:
            raise engine_executor__NodeError('Response body is not valid JSON. Change "Response Format" to "Text"') from None
    if full:
        return [{"json": ({} if body is None else {"body": body}) | meta}]
    if isinstance(body, list):
        return [{"json": nodes_http_request___as_json_object(el)} for el in body]
    return [{"json": nodes_http_request___as_json_object(body)}]


# ---------- the node ----------
async def nodes_http_request__handler(ctx: engine_executor__NodeContext):
    items = ctx.items
    if not items:
        return [[]]
    params = await ctx.params()
    version = ctx.node.type_version
    p0 = params[0]
    try:
        auth = p0.get("authentication", "none")
    except engine_executor__NodeError:
        auth = None
    generic_type = p0.get("genericAuthType") if auth == "genericCredentialType" else None
    pagination = p0.get("options.pagination.pagination")
    if isinstance(pagination, dict) and pagination.get("paginationMode", "off") != "off":
        raise engine_executor__NodeError("Pagination is not supported by this engine")

    tasks: dict[int, nodes_http_request__asyncio.Task[nodes_http_request__RawResponse]] = {}
    prepared: dict[int, nodes_http_request__Prepared] = {}
    errors: dict[int, str] = {}
    try:
        for idx, item in enumerate(items):
            try:
                # Batching: before each batch but the first, wait batchInterval; a request is not awaited before the next starts.
                batching = nodes_http_request___opt(params[idx].get("options", {}) or {}, "batching", "batch")
                if batching is not None:
                    size, interval = batching.get("batchSize", 50), batching.get("batchInterval", 1000)
                    size = size if isinstance(size, (int, float)) and size > 0 else 1
                    if idx > 0 and isinstance(interval, (int, float)) and interval > 0 and idx % size == 0:
                        await nodes_http_request__asyncio.sleep(interval / 1000.0)
                prepared[idx] = await nodes_http_request___prepare(ctx, idx, params[idx], item, auth, generic_type)
            except Exception as exc:  # like n8n: any failure while building a request is that item's error
                if not ctx.continue_on_fail:
                    raise
                nodes_http_request__log.warning("%s: item %d could not be prepared: %s", ctx.node.name, idx, engine_executor__describe_error(exc))
                errors[idx] = str(exc)
                continue
            tasks[idx] = nodes_http_request__asyncio.ensure_future(nodes_http_request___send(ctx, prepared[idx]))
        results = dict(zip(tasks, await nodes_http_request__asyncio.gather(*tasks.values(), return_exceptions=True)))
    except BaseException:
        for t in tasks.values():
            t.cancel()
        await nodes_http_request__asyncio.gather(*tasks.values(), return_exceptions=True)
        raise

    parse_error_body = (nodes_http_request___opt(p0.get("options", {}) or {}, "response", "response", "responseFormat") or "autodetect") in ("json", "text")
    out: list[engine_model__Item] = []
    for idx, item in enumerate(items):
        if idx in errors:
            out.append({"json": {"error": errors[idx]}})
            continue
        req, result = prepared[idx], results[idx]
        failure: nodes_http_request__RequestFailure | None = None
        if isinstance(result, nodes_http_request__RequestFailure):
            failure = result
        elif isinstance(result, BaseException):
            raise result
        elif not req.never_error and not 200 <= result.status < 300:
            failure = nodes_http_request___failure_for_status(result, parse_error_body)
        if failure is not None:
            message, description, http_code = nodes_http_request__api_error_fields(failure)
            if not ctx.continue_on_fail:
                raise engine_executor__NodeError(message, description, http_code)
            nodes_http_request__log.warning("%s: item %d failed: %s", ctx.node.name, idx, engine_executor__describe_failure(message, description, http_code))
            error_json: dict[str, nodes_http_request__Any] ={"error": failure.axios_error(req.safe_url, req.method)}
            if version >= 4.5:
                details: dict[str, nodes_http_request__Any] = {"message": message}
                if description:
                    details["description"] = description
                details["httpCode"] = http_code
                if failure.has_body:
                    details["body"] = failure.body
                details["context"] = {"itemIndex": idx}
                error_json["details"] = details
            out.append({"json": error_json})
            continue
        try:
            out.extend(await nodes_http_request___format(ctx, item, result, req, p0))
        except Exception as exc:
            if not ctx.continue_on_fail:
                raise
            nodes_http_request__log.warning("%s: item %d answered but the response could not be read: %s", ctx.node.name, idx, engine_executor__describe_error(exc))
            out.append({"json": {"error": str(exc)}})
    return [out]


