# --- src/midas_a7/nodes/data_table.py ---
"""Data Table node (n8n-nodes-base.dataTable, typeVersion 1 and 1.1) on the SQL table dt_rows.

Behaviour follows n8n master: packages/nodes-base/nodes/DataTable (router, row operations, common/*) for the
node itself and packages/cli/src/modules/data-table (service, rows repository, sql-utils) plus
packages/workflow/src/type-validation.ts for what the table does to values and filters.

What matters for the A7 flows:
- `operation` defaults to insert, `matchType` to anyCondition (OR), `condition` to eq, `limit` to 50,
  `orderByDirection` to DESC (n8n fills parameter defaults when it loads a workflow).
- Insert (with a fixed table id) is one bulk call for all input items; every other operation runs per item.
- Values are coerced to the column type the way the table service does it (see `_coerce_cell`); columns that
  are not given are NULL on insert; update sets exactly the columns given (an expression that is undefined/null
  sets NULL).
- Output rows are {<columns in table order>, id, createdAt, updatedAt}, one item per row.
"""
















nodes_data_table__SYSTEM_COLUMNS = ("id", "createdAt", "updatedAt")
nodes_data_table__SYSTEM_TYPES = {"id": "number", "createdAt": "date", "updatedAt": "date"}
nodes_data_table__ANY_CONDITION, nodes_data_table__ALL_CONDITIONS = "anyCondition", "allConditions"
nodes_data_table__ROWS_LIMIT_DEFAULT = 50
nodes_data_table__VALIDATION_PREFIX = "Validation error with data table request: "
nodes_data_table___LUXON_DOCS = "https://moment.github.io/luxon/api-docs/index.html#datetimefromformat"

# Reference tables that A7 reads and never writes; loaded from data/seeds/<tableId>.json into empty tables.
nodes_data_table__SEEDED_TABLES = ("eso9cF84jXYIGu5S", "AgXKkFbIj5dQAnvn", "lwJbRv4TVqlFTILl")


class nodes_data_table___DtError(Exception):
    """A failure of this node. `node_error` mirrors n8n's NodeOperationError (shown on the item when the node
    continues on fail); the validation errors of the table service are plain errors and carry no item error."""

    def __init__(self, message: str, description: str | None = None, node_error: bool = True):
        super().__init__(message)
        self.description = description
        self.node_error = node_error


def nodes_data_table___validation(message: str) -> nodes_data_table___DtError:
    return nodes_data_table___DtError(nodes_data_table__VALIDATION_PREFIX + message, node_error=False)


@nodes_data_table__dataclass
class nodes_data_table___Table:
    id: str
    name: str
    columns: list[tuple[str, str]]  # (name, type) in table order

    @property
    def types(self) -> dict[str, str]:
        return dict(self.columns)

    @property
    def all_types(self) -> dict[str, str]:
        return {**nodes_data_table__SYSTEM_TYPES, **self.types}


@nodes_data_table__dataclass
class nodes_data_table___Filter:
    column: str
    condition: str
    value: nodes_data_table__Any
    ctype: str | None


@nodes_data_table__dataclass
class nodes_data_table___FilterSet:
    kind: str  # "and" | "or"
    filters: list[nodes_data_table___Filter]


# ---------- JavaScript value semantics the table service relies on ----------
nodes_data_table___NUMBER_RE = nodes_data_table__re.compile(r"[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?")


def nodes_data_table___js_str(v: nodes_data_table__Any) -> str:
    """String(v) for the scalar values a cell can hold."""
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        if v != v:
            return "NaN"
        if v in (float("inf"), float("-inf")):
            return "Infinity" if v > 0 else "-Infinity"
        if v.is_integer() and abs(v) < 1e21:
            return str(int(v))
        return repr(v)
    return str(v)


def nodes_data_table___js_number(v: nodes_data_table__Any) -> float | None:
    """Number(v); None stands for NaN. Empty or blank strings are 0, like in JavaScript."""
    if isinstance(v, bool):
        return 1.0 if v else 0.0
    if isinstance(v, (int, float)):
        return None if v != v else float(v)
    s = str(v).strip()
    if s == "":
        return 0.0
    if nodes_data_table___NUMBER_RE.fullmatch(s):
        return float(s)
    m = nodes_data_table__re.fullmatch(r"0([xXoObB])([0-9a-fA-F]+)", s)
    if m:
        base = {"x": 16, "o": 8, "b": 2}[m.group(1).lower()]
        try:
            return float(int(m.group(2), base))
        except ValueError:
            return None
    if s in ("Infinity", "+Infinity"):
        return float("inf")
    if s == "-Infinity":
        return float("-inf")
    return None


def nodes_data_table___num_out(f: float) -> int | float:
    return int(f) if f.is_integer() and abs(f) < 2**53 else f


def nodes_data_table___describe(v: nodes_data_table__Any) -> str:
    """getValueDescription from type-validation.ts."""
    if isinstance(v, (dict, list)):
        return "array" if isinstance(v, list) else "object"
    return f"'{nodes_data_table___js_str(v)}'"


def nodes_data_table___parse_datetime(value: nodes_data_table__Any) -> nodes_data_table__datetime | None:
    """A date the way luxon (ISO, HTTP, RFC2822, SQL) and Date.parse read it. Zone-less values are UTC."""
    if isinstance(value, nodes_data_table__datetime):
        dt = value
    else:
        s = str(value).strip()
        dt = None
        if s:
            try:
                dt = nodes_data_table__datetime.fromisoformat(s)
            except ValueError:
                try:
                    dt = nodes_data_table__parsedate_to_datetime(s)
                except (TypeError, ValueError, IndexError):
                    dt = None
            if dt is None:
                for fmt in ("%b %d, %Y %H:%M:%S", "%b %d, %Y", "%B %d, %Y %H:%M:%S", "%B %d, %Y", "%m/%d/%Y %H:%M:%S", "%m/%d/%Y",
                            "%d %b %Y %H:%M:%S", "%d %B %Y"):
                    try:
                        dt = nodes_data_table__datetime.strptime(s, fmt)
                        break
                    except ValueError:
                        continue
    if dt is None:
        return None
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=nodes_data_table__timezone.utc)
    return dt.astimezone(nodes_data_table__timezone.utc)


def nodes_data_table___iso_ms(dt: nodes_data_table__datetime) -> str:
    return store__iso(dt)


# ---------- values -> column types (DataTableService.validateAndTransformCell) ----------
def nodes_data_table___coerce_cell(key: str, cell: nodes_data_table__Any, ctype: str | None, skip_date_transform: bool = False) -> nodes_data_table__Any:
    if cell is None or ctype is None:
        return cell
    if ctype == "string":
        return cell  # parseStrings is off: whatever arrives is kept (the database turns numbers into text)
    if ctype == "number":
        n = nodes_data_table___js_number(cell)
        if n is None or n in (float("inf"), float("-inf")):
            raise nodes_data_table___validation(f"value '{nodes_data_table___js_str(cell)}' does not match column type 'number': "
                              f"'{key}' expects a number but we got {nodes_data_table___describe(cell)}")
        return nodes_data_table___num_out(n)
    if ctype == "boolean":
        return nodes_data_table___parse_boolean(key, cell)
    if ctype == "date":
        dt = nodes_data_table___parse_datetime(cell)
        if dt is None:
            raise nodes_data_table___validation(f"value '{nodes_data_table___js_str(cell)}' does not match column type 'date': "
                              f"'{key}' expects a dateTime but we got {nodes_data_table___describe(cell)} <br/><br/> Consider using "
                              f'<a href="{nodes_data_table___LUXON_DOCS}" target="_blank"><code>DateTime.fromFormat</code></a> '
                              "to work with custom date formats.")
        return dt if skip_date_transform else nodes_data_table___iso_ms(dt)
    return cell


def nodes_data_table___parse_boolean(key: str, cell: nodes_data_table__Any) -> bool:
    if isinstance(cell, bool):
        return cell
    if isinstance(cell, str) and cell.lower() in ("true", "false"):
        return cell.lower() == "true"
    if not (isinstance(cell, str) and cell.strip() == ""):
        n = nodes_data_table___js_number(cell)
        if n == 0:
            return False
        if n == 1:
            return True
    raise nodes_data_table___validation(f"value '{nodes_data_table___js_str(cell)}' does not match column type 'boolean': "
                      f"'{key}' expects a boolean but we got {nodes_data_table___describe(cell)}")


def nodes_data_table___to_storage(value: nodes_data_table__Any, ctype: str | None) -> nodes_data_table__Any:
    """What the database keeps for a coerced value: text columns hold the text of numbers and booleans."""
    if ctype == "string" and value is not None and not isinstance(value, str):
        return nodes_data_table___js_str(value)
    return value


def nodes_data_table___api_input(data: nodes_data_table__Any, index: int) -> dict[str, nodes_data_table__Any]:
    """dataObjectToApiInput: undefined and null become null; arrays and objects are refused."""
    if data is None:
        raise nodes_data_table___DtError("Cannot convert undefined or null to object")
    out: dict[str, nodes_data_table__Any] = {}
    for k, v in dict(data).items():
        if isinstance(v, list):
            raise nodes_data_table___DtError(f"unexpected array input '{nodes_data_table___dumps(v)}' in row {index}")
        if isinstance(v, dict):
            raise nodes_data_table___DtError(f"unexpected object input '{nodes_data_table___dumps(v)}' in row {index}")
        out[k] = v
    return out


def nodes_data_table___dumps(v: nodes_data_table__Any) -> str:
    return nodes_data_table__json.dumps(v, separators=(",", ":"), ensure_ascii=False)


def nodes_data_table___get_add_row(params: nodes_data_table__Any, item: engine_model__Item, index: int) -> dict[str, nodes_data_table__Any]:
    """getAddRow: the columns.value map (defineBelow) or the input item itself without the system columns."""
    mode = params.get("columns.mappingMode", "defineBelow")
    if mode == "autoMapInputData":
        data = {k: v for k, v in (item.get("json") or {}).items() if k not in nodes_data_table__SYSTEM_COLUMNS}
    else:
        data = params.get("columns.value", {})
        if data is None:
            raise nodes_data_table___DtError("Cannot convert undefined or null to object")
    return nodes_data_table___api_input(data, index)


def nodes_data_table___coerce_row(row: dict[str, nodes_data_table__Any], tbl: nodes_data_table___Table) -> dict[str, nodes_data_table__Any]:
    """validateAndTransformRows for one row: unknown columns are refused, values are coerced to the column type."""
    types = tbl.types
    out: dict[str, nodes_data_table__Any] = {}
    for key, value in row.items():
        if key not in types:
            raise nodes_data_table___validation(f"unknown column name '{key}'")
        out[key] = nodes_data_table___coerce_cell(key, value, types[key])
    return out


def nodes_data_table___stored(row: dict[str, nodes_data_table__Any], tbl: nodes_data_table___Table) -> dict[str, nodes_data_table__Any]:
    types = tbl.types
    return {k: nodes_data_table___to_storage(v, types.get(k)) for k, v in row.items()}


# ---------- tables and rows ----------
def nodes_data_table___resolve_table(ctx: engine_executor__NodeContext, params: nodes_data_table__Any) -> nodes_data_table___Table:
    rl = params.get("dataTableId")
    if isinstance(rl, dict) and "value" in rl:
        mode, value = rl.get("mode", "list"), rl["value"]
    else:
        mode, value = "id", rl
    schemas = ctx.services.schemas
    if mode == "name":
        for tid, t in schemas.items():
            if str(t.get("name", "")).lower() == str(value).lower():
                value = tid
                break
        else:
            raise nodes_data_table___DtError(f'Data table with name "{value}" not found')
    schema = schemas.get(str(value))
    if schema is None:
        raise nodes_data_table___DtError(f"Data table with ID '{value}' could not be found in this project",
                       "It may have been deleted, or skipped when the workflow was imported. "
                       "Choose an existing data table in the node.")
    return nodes_data_table___Table(str(value), schema.get("name", ""), [(c["name"], c["type"]) for c in schema["columns"]])


def nodes_data_table___read_value(v: nodes_data_table__Any, ctype: str) -> nodes_data_table__Any:
    """normalizeRows: 0/1 become booleans, dates come back as UTC ISO strings."""
    if ctype == "boolean":
        if v in (1, "1") and not isinstance(v, bool):
            return True
        if v in (0, "0") and not isinstance(v, bool):
            return False
    elif ctype == "date" and v is not None:
        dt = nodes_data_table___parse_datetime(v)
        return nodes_data_table___iso_ms(dt) if dt else v
    return v


def nodes_data_table___present(row: dict[str, nodes_data_table__Any], tbl: nodes_data_table___Table) -> dict[str, nodes_data_table__Any]:
    """A stored row as n8n returns it: the table's columns in order (NULL when absent), then id, createdAt, updatedAt."""
    out = {name: nodes_data_table___read_value(row.get(name), ctype) for name, ctype in tbl.columns}
    out["id"], out["createdAt"], out["updatedAt"] = row["id"], row["createdAt"], row["updatedAt"]
    return out


# ---------- filters (getSelectFilter, buildGetManyFilter, validateAndTransformFilters) ----------
def nodes_data_table___node_filters(params: nodes_data_table__Any, tbl: nodes_data_table___Table, force_eq: bool = False) -> tuple[str, list[nodes_data_table___Filter]]:
    """getSelectFilter + buildGetManyFilter: what the node itself checks and maps, before the table service sees it."""
    fields = params.get("filters.conditions", [])
    match_type = params.get("matchType", nodes_data_table__ANY_CONDITION)
    if match_type not in (nodes_data_table__ANY_CONDITION, nodes_data_table__ALL_CONDITIONS):
        raise nodes_data_table___DtError("unexpected match type")
    if not isinstance(fields, list) or not all(isinstance(f, dict) and "keyName" in f for f in fields):
        raise nodes_data_table___DtError("unexpected fields input")
    types = tbl.all_types
    if fields:
        invalid = [f["keyName"] for f in fields if not types.get(f["keyName"])]
        if invalid:
            raise nodes_data_table___DtError(
                f'Filter validation failed: Column(s) "{", ".join(str(i) for i in invalid)}" do not exist in the selected '
                "table. This often happens when switching between tables with different schemas. "
                "Please update your filter conditions.")
    return ("and" if match_type == nodes_data_table__ALL_CONDITIONS else "or"), [nodes_data_table___node_filter(f, types, force_eq) for f in fields]


def nodes_data_table___service_filters(kind: str, filters: list[nodes_data_table___Filter], tbl: nodes_data_table___Table) -> nodes_data_table___FilterSet:
    """DataTableService.validateAndTransformFilters."""
    return nodes_data_table___FilterSet(kind, [nodes_data_table___transform_filter(f, tbl.all_types) for f in filters])


def nodes_data_table___node_filter(f: dict[str, nodes_data_table__Any], types: dict[str, str], force_eq: bool) -> nodes_data_table___Filter:
    name = f["keyName"]
    ctype = types.get(name)
    cond = None if force_eq else f.get("condition")
    if cond == "isEmpty":
        return nodes_data_table___Filter(name, "isEmpty" if ctype == "string" else "eq", None, ctype)
    if cond == "isNotEmpty":
        return nodes_data_table___Filter(name, "isNotEmpty" if ctype == "string" else "neq", None, ctype)
    if cond in ("isTrue", "isFalse"):
        return nodes_data_table___Filter(name, "eq", cond == "isTrue", ctype)
    value = f.get("keyValue", "")
    if ctype == "date" and isinstance(value, str):
        parsed = nodes_data_table___parse_datetime(value)
        if parsed is None:
            raise nodes_data_table___DtError(f"Invalid date string '{value}' for column '{name}'")
        value = parsed
    return nodes_data_table___Filter(name, cond or "eq", value, ctype)


def nodes_data_table___transform_filter(flt: nodes_data_table___Filter, types: dict[str, str]) -> nodes_data_table___Filter:
    value = nodes_data_table___coerce_cell(flt.column, flt.value, flt.ctype, skip_date_transform=True)
    cond = flt.condition
    if flt.ctype != "string":
        if cond == "isEmpty":
            return nodes_data_table___Filter(flt.column, "eq", None, flt.ctype)
        if cond == "isNotEmpty":
            return nodes_data_table___Filter(flt.column, "neq", None, flt.ctype)
    if cond in ("like", "ilike"):
        if value is None:
            raise nodes_data_table___validation(f"{cond.upper()} filter value cannot be null or undefined")
        if not isinstance(value, str):
            raise nodes_data_table___validation(f"{cond.upper()} filter value must be a string")
        value = value if "%" in value else f"%{value}%"
    elif cond in ("gt", "gte", "lt", "lte"):
        if value is None:
            raise nodes_data_table___validation(f"{cond.upper()} filter value cannot be null or undefined")
    elif cond not in ("eq", "neq", "isEmpty", "isNotEmpty"):
        raise nodes_data_table___DtError(f"Unsupported filter condition: {cond}")
    return nodes_data_table___Filter(flt.column, cond, value, flt.ctype)


def nodes_data_table___comparable(v: nodes_data_table__Any, ctype: str | None) -> nodes_data_table__Any:
    """A cell or filter value in a form that compares like the database compares it; None when it cannot."""
    if v is None:
        return None
    if ctype == "number":
        n = nodes_data_table___js_number(v)
        return n
    if ctype == "date":
        return nodes_data_table___parse_datetime(v)
    if ctype == "boolean":
        try:
            return nodes_data_table___parse_boolean("", v)
        except nodes_data_table___DtError:
            return None
    return v if isinstance(v, str) else nodes_data_table___js_str(v)


def nodes_data_table___like_regex(pattern: str, ignore_case: bool) -> nodes_data_table__re.Pattern[str]:
    # Only % is a wildcard; every other character, '_' and '*' included, is literal.
    body = ".*".join(nodes_data_table__re.escape(p) for p in pattern.split("%"))
    return nodes_data_table__re.compile(body, nodes_data_table__re.DOTALL | (nodes_data_table__re.IGNORECASE if ignore_case else 0))


def nodes_data_table___matches_one(row: dict[str, nodes_data_table__Any], f: nodes_data_table___Filter) -> bool:
    cur = row.get(f.column)
    cond = f.condition
    if cond == "isEmpty":
        return cur is None or cur == ""
    if cond == "isNotEmpty":
        return cur is not None and cur != ""
    if f.value is None and cond in ("eq", "neq"):
        return (cur is None) if cond == "eq" else (cur is not None)
    if cur is None:
        return cond == "neq"  # (col != value OR col IS NULL); every other comparison with NULL is false
    if cond in ("like", "ilike"):
        return nodes_data_table___like_regex(f.value, cond == "ilike").fullmatch(cur if isinstance(cur, str) else nodes_data_table___js_str(cur)) is not None
    a, b = nodes_data_table___comparable(cur, f.ctype), nodes_data_table___comparable(f.value, f.ctype)
    if a is None or b is None:
        return cond == "neq"
    if cond == "eq":
        return a == b
    if cond == "neq":
        return a != b
    return {"gt": a > b, "gte": a >= b, "lt": a < b, "lte": a <= b}[cond]


def nodes_data_table___matches(row: dict[str, nodes_data_table__Any], fs: nodes_data_table___FilterSet) -> bool:
    if not fs.filters:
        return True
    if len(fs.filters) == 1 or fs.kind == "and":
        return all(nodes_data_table___matches_one(row, f) for f in fs.filters)
    return any(nodes_data_table___matches_one(row, f) for f in fs.filters)


def nodes_data_table___prefilter(fs: nodes_data_table___FilterSet) -> dict[str, str]:
    """Equality tests on string columns that the SQL side may apply early (they are re-checked in Python)."""
    if not (len(fs.filters) == 1 or fs.kind == "and"):
        return {}
    equals: dict[str, str] = {}
    for f in fs.filters:
        if f.condition == "eq" and f.ctype == "string" and isinstance(f.value, str) and f.column not in equals:
            equals[f.column] = f.value
    return equals


async def nodes_data_table___select(ctx: engine_executor__NodeContext, tbl: nodes_data_table___Table, fs: nodes_data_table___FilterSet) -> list[dict[str, nodes_data_table__Any]]:
    equals = nodes_data_table___prefilter(fs)
    rows = await nodes_data_table__asyncio.to_thread(ctx.services.store.dt_select, tbl.id, equals or None)
    shown = [nodes_data_table___present(r, tbl) for r in rows]
    return [r for r in shown if nodes_data_table___matches(r, fs)]


def nodes_data_table___sort(rows: list[dict[str, nodes_data_table__Any]], column: str, direction: str, ctype: str | None) -> list[dict[str, nodes_data_table__Any]]:
    """ORDER BY column direction, id ASC. NULLs sort last ascending and first descending (Postgres)."""
    def key(row: dict[str, nodes_data_table__Any]):
        c = nodes_data_table___comparable(row.get(column), ctype)
        return (1, 0) if c is None else (0, c)

    ordered = sorted(rows, key=lambda r: r["id"])
    return sorted(ordered, key=key, reverse=direction == "DESC")


def nodes_data_table___truthy(v: nodes_data_table__Any) -> bool:
    if isinstance(v, str):
        return v.strip().lower() == "true"
    return bool(v)


# ---------- row operations ----------
async def nodes_data_table___op_get(ctx: engine_executor__NodeContext, tbl: nodes_data_table___Table, params: nodes_data_table__Any, index: int) -> list[dict[str, nodes_data_table__Any]]:
    sort: tuple[str, str] | None = None
    if nodes_data_table___truthy(params.get("orderBy", False)):
        column = params.get("orderByColumn", "createdAt")
        if column:
            if column not in nodes_data_table__SYSTEM_COLUMNS and column not in tbl.types:
                raise nodes_data_table___DtError("Specified column does not exist")
            sort = (column, str(params.get("orderByDirection", "DESC")).upper())
    kind, filters = nodes_data_table___node_filters(params, tbl)
    rows = await nodes_data_table___select(ctx, tbl, nodes_data_table___service_filters(kind, filters, tbl))
    if sort:
        rows = nodes_data_table___sort(rows, sort[0], sort[1], tbl.all_types.get(sort[0]))
    limit: nodes_data_table__Any = 0 if nodes_data_table___truthy(params.get("returnAll", False)) else params.get("limit", nodes_data_table__ROWS_LIMIT_DEFAULT)
    if limit:
        try:
            n = int(float(limit))
        except (TypeError, ValueError) as exc:
            raise nodes_data_table___DtError(f"unexpected limit {nodes_data_table___js_str(limit)}") from exc
        if n > 0:
            rows = rows[:n]
    return rows


async def nodes_data_table___op_exists(ctx: engine_executor__NodeContext, tbl: nodes_data_table___Table, params: nodes_data_table__Any, index: int, wanted: bool) -> bool:
    # The condition field is hidden for these two operations, so every condition is "equals".
    kind, filters = nodes_data_table___node_filters(params, tbl, force_eq=True)
    return bool(await nodes_data_table___select(ctx, tbl, nodes_data_table___service_filters(kind, filters, tbl))) == wanted


def nodes_data_table___dry_run_rows(before: dict[str, nodes_data_table__Any] | None, after: dict[str, nodes_data_table__Any] | None) -> list[dict[str, nodes_data_table__Any]]:
    template = before if before is not None else after
    null_row = {"id": None, "createdAt": None, "updatedAt": None, **{k: None for k in (template or {})}}
    return [{**(before if before is not None else null_row), "dryRunState": "before"},
            {**(after if after is not None else null_row), "dryRunState": "after"}]


async def nodes_data_table___prepared_update(ctx: engine_executor__NodeContext, tbl: nodes_data_table___Table, params: nodes_data_table__Any, index: int, item: engine_model__Item):
    """The shared start of update and upsert: row data and filter, validated like the table service does."""
    row = nodes_data_table___get_add_row(params, item, index)
    kind, filters = nodes_data_table___node_filters(params, tbl)
    if not filters:
        raise nodes_data_table___DtError("At least one condition is required")
    if not tbl.columns:
        raise nodes_data_table___validation("No columns found for this data table or data table not found")
    if not row:
        raise nodes_data_table___validation("Data columns must not be empty")
    data = nodes_data_table___coerce_row(row, tbl)
    return data, nodes_data_table___service_filters(kind, filters, tbl)


async def nodes_data_table___update_rows(ctx: engine_executor__NodeContext, tbl: nodes_data_table___Table, data: dict[str, nodes_data_table__Any], fs: nodes_data_table___FilterSet, dry_run: bool) -> list[dict[str, nodes_data_table__Any]]:
    matched = await nodes_data_table___select(ctx, tbl, fs)
    changes = nodes_data_table___stored(data, tbl)
    if dry_run:
        stamp = nodes_data_table___iso_ms(store__now())
        return [r for original in matched for r in nodes_data_table___dry_run_rows(original, {**original, **changes, "updatedAt": stamp})]
    if not matched:
        return []
    rows = await nodes_data_table__asyncio.to_thread(ctx.services.store.dt_update, tbl.id, [r["id"] for r in matched], changes)
    return [nodes_data_table___present(r, tbl) for r in rows]


async def nodes_data_table___insert_rows(ctx: engine_executor__NodeContext, tbl: nodes_data_table___Table, rows: list[dict[str, nodes_data_table__Any]]) -> list[dict[str, nodes_data_table__Any]]:
    """Insert already coerced rows; columns that are not given are NULL."""
    full = [{name: nodes_data_table___to_storage(row.get(name), ctype) for name, ctype in tbl.columns} for row in rows]

    def run() -> list[dict[str, nodes_data_table__Any]]:
        store: store__Store = ctx.services.store
        return [store.dt_insert(tbl.id, r) for r in full]

    return [nodes_data_table___present(r, tbl) for r in await nodes_data_table__asyncio.to_thread(run)]


async def nodes_data_table___op_update(ctx: engine_executor__NodeContext, tbl: nodes_data_table___Table, params: nodes_data_table__Any, index: int, item: engine_model__Item) -> list[dict[str, nodes_data_table__Any]]:
    dry_run = nodes_data_table___dry_run(params)
    data, fs = await nodes_data_table___prepared_update(ctx, tbl, params, index, item)
    return await nodes_data_table___update_rows(ctx, tbl, data, fs, dry_run)


async def nodes_data_table___op_upsert(ctx: engine_executor__NodeContext, tbl: nodes_data_table___Table, params: nodes_data_table__Any, index: int, item: engine_model__Item) -> list[dict[str, nodes_data_table__Any]]:
    dry_run = nodes_data_table___dry_run(params)
    data, fs = await nodes_data_table___prepared_update(ctx, tbl, params, index, item)
    updated = await nodes_data_table___update_rows(ctx, tbl, data, fs, dry_run)
    if updated:
        return updated
    if dry_run:
        stamp = nodes_data_table___iso_ms(store__now())
        return nodes_data_table___dry_run_rows(None, {"id": 0, "createdAt": stamp, "updatedAt": stamp, **nodes_data_table___stored(data, tbl)})
    return await nodes_data_table___insert_rows(ctx, tbl, [data])


async def nodes_data_table___op_delete(ctx: engine_executor__NodeContext, tbl: nodes_data_table___Table, params: nodes_data_table__Any, index: int) -> list[dict[str, nodes_data_table__Any]]:
    dry_run = nodes_data_table___dry_run(params)
    kind, filters = nodes_data_table___node_filters(params, tbl)
    if not filters:
        raise nodes_data_table___DtError("At least one condition is required")
    matched = await nodes_data_table___select(ctx, tbl, nodes_data_table___service_filters(kind, filters, tbl))
    if dry_run:
        return [r for row in matched for r in nodes_data_table___dry_run_rows(row, None)]
    if matched:
        await nodes_data_table__asyncio.to_thread(ctx.services.store.dt_delete, tbl.id, [r["id"] for r in matched])
    return matched


def nodes_data_table___dry_run(params: nodes_data_table__Any) -> bool:
    v = params.get("options.dryRun", False)
    if not isinstance(v, bool):
        raise nodes_data_table___DtError(f"unexpected input {nodes_data_table___dumps(v)} for boolean dryRun")
    return v


# ---------- the node ----------
nodes_data_table___ROW_OPERATIONS = ("insert", "get", "update", "upsert", "deleteRows", "rowExists", "rowNotExists")


def nodes_data_table___has_complex_id(ctx: engine_executor__NodeContext) -> bool:
    """A table id that is an expression forces insert to run per item instead of as one bulk call."""
    raw = ctx.node.parameters.get("dataTableId")
    if isinstance(raw, dict):
        raw = raw.get("value")
    return isinstance(raw, str) and "{" in raw


def nodes_data_table___item_error(exc: Exception) -> dict[str, nodes_data_table__Any] | None:
    if isinstance(exc, nodes_data_table___DtError) and exc.node_error:
        err: dict[str, nodes_data_table__Any] = {"name": "NodeOperationError", "message": str(exc)}
        if exc.description:
            err["description"] = exc.description
        return err
    return None


def nodes_data_table___raise(exc: Exception) -> None:
    if isinstance(exc, nodes_data_table___DtError):
        raise engine_executor__NodeError(str(exc), exc.description) from exc
    raise exc


async def nodes_data_table___insert_bulk(ctx: engine_executor__NodeContext, plist: list[nodes_data_table__Any]) -> list[engine_model__Item]:
    """Router "Row bulk operations": every input item becomes a row, inserted in one go."""
    items = ctx.items
    try:
        tbl = nodes_data_table___resolve_table(ctx, plist[0])
        optimize = nodes_data_table___truthy(plist[0].get("options.optimizeBulk", False))
        rows = [nodes_data_table___coerce_row(nodes_data_table___get_add_row(plist[i], items[i], i), tbl) for i in range(len(items))]
        inserted = await nodes_data_table___insert_rows(ctx, tbl, rows)
    except (nodes_data_table___DtError, engine_executor__NodeError) as exc:
        if not ctx.continue_on_fail:
            nodes_data_table___raise(exc)
        # n8n maps the whole input items into json here, so an item's data sits one level deeper.
        err = nodes_data_table___item_error(exc)
        return [{"json": dict(item), **({"error": err} if err else {})} for item in items]
    if optimize:
        return [{"json": {"success": True, "insertedRows": len(inserted)}}]
    return [{"json": r, "pairedItem": {"item": n}} for n, r in enumerate(inserted)]


async def nodes_data_table___run_item(ctx: engine_executor__NodeContext, op: str, params: nodes_data_table__Any, item: engine_model__Item, index: int) -> list[engine_model__Item]:
    tbl = nodes_data_table___resolve_table(ctx, params)
    if op == "insert":  # per item only when the table id is an expression
        row = nodes_data_table___coerce_row(nodes_data_table___get_add_row(params, item, index), tbl)
        inserted = await nodes_data_table___insert_rows(ctx, tbl, [row])
        if nodes_data_table___truthy(params.get("options.optimizeBulk", False)):
            return [{"json": {"success": True, "insertedRows": 1}, "pairedItem": {"item": index}}]
        return [{"json": r, "pairedItem": {"item": n}} for n, r in enumerate(inserted)]
    if op == "get":
        rows = await nodes_data_table___op_get(ctx, tbl, params, index)
    elif op == "update":
        rows = await nodes_data_table___op_update(ctx, tbl, params, index, item)
    elif op == "upsert":
        rows = await nodes_data_table___op_upsert(ctx, tbl, params, index, item)
    elif op == "deleteRows":
        rows = await nodes_data_table___op_delete(ctx, tbl, params, index)
    else:  # rowExists / rowNotExists pass the input item on
        keep = await nodes_data_table___op_exists(ctx, tbl, params, index, wanted=(op == "rowExists"))
        return [{**item, "pairedItem": {"item": index}}] if keep else []
    return [{"json": r, "pairedItem": {"item": index}} for r in rows]


async def nodes_data_table__handler(ctx: engine_executor__NodeContext):
    items = ctx.items
    if not items:
        return [[]]
    plist = await ctx.params()
    resource = plist[0].get("resource", "row")
    operation = plist[0].get("operation", "insert")
    if resource != "row":
        raise engine_executor__NodeError(f"Data table resource '{resource}' is not supported by this engine (only row operations)")
    if operation not in nodes_data_table___ROW_OPERATIONS:
        raise engine_executor__NodeError(f'The operation "{operation}" is not supported!')
    if operation == "insert" and not nodes_data_table___has_complex_id(ctx):
        return [await nodes_data_table___insert_bulk(ctx, plist)]
    out: list[engine_model__Item] = []
    for i, item in enumerate(items):
        try:
            out.extend(await nodes_data_table___run_item(ctx, operation, plist[i], item, i))
        except (nodes_data_table___DtError, engine_executor__NodeError) as exc:
            if not ctx.continue_on_fail:
                nodes_data_table___raise(exc)
            err = nodes_data_table___item_error(exc)
            out.append({"json": item.get("json", {}), **({"error": err} if err else {})})
    return [out]


nodes_data_table__HANDLERS = {"dataTable": nodes_data_table__handler}


# ---------- reference data ----------
def nodes_data_table__seed_reference_tables_sync(store: store__Store, schemas: dict[str, dict[str, nodes_data_table__Any]], seeds_dir: nodes_data_table__Path,
                               table_ids: tuple[str, ...] = nodes_data_table__SEEDED_TABLES) -> dict[str, int]:
    """Load data/seeds/<tableId>.json into each table that has no rows yet. Returns {table_id: rows loaded}.

    Column values are kept as given; the store numbers the rows itself and stamps createdAt/updatedAt with the
    time of loading, so ids and timestamps differ from the n8n export while the order of the rows is the same.
    """
    loaded: dict[str, int] = {}
    for table_id in table_ids:
        schema = schemas.get(table_id)
        path = seeds_dir / f"{table_id}.json"
        if schema is None or not path.is_file():
            loaded[table_id] = 0
            continue
        rows = nodes_data_table__json.loads(path.read_text(encoding="utf-8")).get("rows", [])
        loaded[table_id] = store.dt_seed(table_id, rows, [c["name"] for c in schema["columns"]])
    return loaded


async def nodes_data_table__seed_reference_tables(services: nodes_data_table__Any) -> dict[str, int]:
    """Seed the model registry, handling profiles and catalogue into their empty tables (startup helper)."""
    return await nodes_data_table__asyncio.to_thread(
        nodes_data_table__seed_reference_tables_sync, services.store, services.schemas, nodes_data_table__Path(services.settings.seeds_dir))


# --- src/midas_a7/nodes/google_drive.py ---
"""The flows' Google Drive nodes, backed by this service's own file store (Drive dropped, owner, 20 Oct 2026).

The 13 Drive nodes keep their parameters and output shapes: folder create, file upload and file download.
Files live in the `files` table; `webViewLink` is a signed link to /files/<id>/view on this service. Folder ids
from "04 Settings" (the old Drive root folders) are accepted as plain parent names; nothing is read from Google.
"""













nodes_google_drive__FOLDER_MIME = "application/vnd.google-apps.folder"
nodes_google_drive__NOT_FOUND = "The resource you are requesting could not be found"


def nodes_google_drive__new_file_id() -> str:
    """Drive-like id: 33 characters of [A-Za-z0-9_-], which the flows' id checks accept."""
    return "1" + nodes_google_drive__secrets.token_urlsafe(24)


def nodes_google_drive__signing_secret(services: nodes_google_drive__Any) -> str:
    """The secret new file links are signed with: FILE_LINK_SECRET when set, else the resume secret (BE-6, PR A)."""
    secret = (services.extra.get("file_link_secret") or services.settings.file_link_secret
              or services.extra.get("signing_secret") or services.settings.resume_secret)
    if not secret:
        raise engine_executor__NodeError("File links cannot be signed: neither FILE_LINK_SECRET nor RESUME_SIGNING_SECRET is set")
    return secret


def nodes_google_drive__accepted_secrets(services: nodes_google_drive__Any) -> list[str]:
    """The secrets a file link may be signed with: the current one, and the resume secret links were signed with before."""
    accepted = services.extra.get("file_link_secrets_accepted")
    if accepted:
        return [s for s in accepted if s]
    secret = services.extra.get("signing_secret", "")
    return [secret] if secret else []


def nodes_google_drive__file_signature(secret: str, file_id: str) -> str:
    return nodes_google_drive__hmac.new(secret.encode(), f"file:{file_id}".encode(), nodes_google_drive__hashlib.sha256).hexdigest()


def nodes_google_drive__view_link(services: nodes_google_drive__Any, file_id: str) -> str:
    sig = nodes_google_drive__file_signature(nodes_google_drive__signing_secret(services), file_id)
    return f"{services.settings.public_base_url}/files/{file_id}/view?sig={sig}"


def nodes_google_drive___iso(dt) -> str:
    return dt.astimezone(nodes_google_drive__timezone.utc).isoformat(timespec="milliseconds").replace("+00:00", "Z")


def nodes_google_drive___file_resource(services: nodes_google_drive__Any, row: dict[str, nodes_google_drive__Any]) -> dict[str, nodes_google_drive__Any]:
    """The Drive v3 file fields the flows read (id, name, webViewLink, sha256Checksum) plus the usual neighbours."""
    out: dict[str, nodes_google_drive__Any] = {"kind": "drive#file", "id": row["id"], "name": row["name"], "mimeType": row["mime_type"]}
    if row.get("parent_id"):
        out["parents"] = [row["parent_id"]]
    out["webViewLink"] = nodes_google_drive__view_link(services, row["id"])
    if not row.get("is_folder"):
        out.update({"size": str(row["size"]), "md5Checksum": row.get("md5"), "sha256Checksum": row.get("sha256"),
                    "originalFilename": row["name"]})
    out["createdTime"] = out["modifiedTime"] = nodes_google_drive___iso(row["created_at"])
    return out


async def nodes_google_drive___one(ctx: engine_executor__NodeContext, item: engine_model__Item, p: nodes_google_drive__Any) -> engine_model__Item:
    store = ctx.services.store
    resource = p.get("resource", "file")
    operation = p.get("operation", "create" if resource == "folder" else "upload")
    if resource == "folder" and operation == "create":
        name = str(p.get("name") or "Untitled")
        row = await nodes_google_drive__asyncio.to_thread(store.file_create, nodes_google_drive__new_file_id(), name, nodes_google_drive__FOLDER_MIME, p.rl("folderId") or None, None)
        res = nodes_google_drive___file_resource(ctx.services, row)
        return {"json": {k: res[k] for k in ("kind", "id", "name", "mimeType")}}
    if resource == "file" and operation == "upload":
        key = p.get("inputDataFieldName") or "data"
        ref = (item.get("binary") or {}).get(key)
        if not ref:
            raise engine_executor__NodeError(f"This operation expects the node's input data to contain a binary file '{key}', but none was found")
        data = await ctx.services.binaries.get(ref)
        name = str(p.get("name") or ref.get("fileName") or "Untitled")
        mime = ref.get("mimeType") or "application/octet-stream"
        row = await nodes_google_drive__asyncio.to_thread(store.file_create, nodes_google_drive__new_file_id(), name, mime, p.rl("folderId") or None, data,
                                      nodes_google_drive__hashlib.sha256(data).hexdigest(), nodes_google_drive__hashlib.md5(data).hexdigest())
        return {"json": nodes_google_drive___file_resource(ctx.services, row)}
    if resource == "file" and operation == "download":
        file_id = str(p.rl("fileId") or "")
        row = await nodes_google_drive__asyncio.to_thread(store.file_get, file_id) if file_id else None
        if not row or row.get("is_folder") or row.get("data") is None:
            raise engine_executor__NodeError(nodes_google_drive__NOT_FOUND, description=f"File not found: {file_id}", http_code="404")
        prop = (p.get("options") or {}).get("binaryPropertyName") or "data"
        stored = await ctx.services.binaries.put(ctx.execution.id, bytes(row["data"]), row["mime_type"], row["name"])
        return {"json": item.get("json", {}), "binary": {**(item.get("binary") or {}), prop: stored}}
    raise engine_executor__NodeError(f"Drive operation '{resource}.{operation}' is not supported")


async def nodes_google_drive__google_drive(ctx: engine_executor__NodeContext):
    params = await ctx.params()
    out: list[engine_model__Item] = []
    for item, p in zip(ctx.items, params):
        try:
            out.append(await nodes_google_drive___one(ctx, item, p))
        except engine_executor__NodeError as exc:
            if not ctx.continue_on_fail:
                raise
            out.append({"json": {"error": str(exc)}})
    return [out]


nodes_google_drive__HANDLERS = {"googleDrive": nodes_google_drive__google_drive}


# --- src/midas_a7/nodes/edit_image.py ---
"""Edit Image node (n8n-nodes-base.editImage, typeVersion 1.1) with Pillow, as the A7 flows use it.

n8n (packages/nodes-base/nodes/EditImage/EditImage.node.ts) drives GraphicsMagick through the `gm` npm module:

    gm convert -background transparent [-quality Q] - -orient TopLeft <steps> FORMAT:-

with EXIF auto-orientation applied first. This module reproduces what GraphicsMagick does for the steps the flows
use (checked against GraphicsMagick 1.3.42 Q16 and its 1.3.46 source, coders/{bmp,jpeg,webp}.c, magick/resize.c):

- resize `WxH!` (and the other geometry flags): Lanczos when shrinking a full-colour opaque picture, done in
  floating point in GraphicsMagick's pass order, so pixels match GraphicsMagick to within 1 level. GraphicsMagick
  switches to its Mitchell filter for palette/grey sources, pictures with transparency and enlargements; Pillow has
  no Mitchell filter, so those cases use its bicubic filter (close, not identical).
- rotate: quarter turns are exact; the remainder (not used by the flows) is a bilinear rotation on the background.
  A rotation of 0 (the flows' "to pixels" steps) leaves the picture unchanged: the step is a format conversion.
- jpeg: the encoder settings GraphicsMagick uses (quality default 75, 4:4:4 chroma at quality 90 and above, else
  4:2:0, optimised Huffman tables, one channel for a grey source) and its JFIF density, which gives byte-identical
  files for the same pixels.
- webp: libwebp lossy at quality 75 (GraphicsMagick's default), method 4: byte-identical.
- bmp: what GraphicsMagick writes for a full-colour picture: 24-bit BI_RGB rows bottom-up, padded to 4 bytes, a
  40-byte header (108/124 bytes when the source carries colour information), or 32-bit BI_BITFIELDS (B, G, R, A
  bytes) with a version 4 header when the picture has transparency. The A7 Code nodes 18e3 and 18h parse these.
  (GraphicsMagick writes an 8-bit palette BMP for a grey or palette source that is not resampled; those nodes
  cannot read that kind, so a 24-bit file is written instead: same pixel values.)

Output binary metadata follows the node: the other binaries of the item are kept, the destination key gets
fileExtension/mimeType from the format, the file name from options.fileName, then the type sniffed from the new
bytes (n8n calls prepareBinaryData(buffer) without a name or type: jpeg -> image/jpeg, "jpg").
"""
















nodes_edit_image__VALID_FORMATS = ("bmp", "gif", "jpeg", "png", "tiff", "tif", "webp")
# Parameter defaults n8n fills into each multiStep entry (and the single-operation parameters).
nodes_edit_image__STEP_DEFAULTS: dict[str, dict[str, nodes_edit_image__Any]] = {
    "resize": {"width": 500, "height": 500, "resizeOption": "maximumArea"},
    "rotate": {"rotate": 0, "backgroundColor": "#ffffffff"},
}
nodes_edit_image__NUMERIC_PARAMS = {"resize": ("width", "height"), "rotate": ("rotate",)}
nodes_edit_image__RESIZE_FLAGS = {"ignoreAspectRatio": "!", "minimumArea": "^", "onlyIfSmaller": "<", "onlyIfLarger": ">", "percent": "%"}
nodes_edit_image__GM_DEFAULT_QUALITY = 75
nodes_edit_image__GM_DEFAULT_PPM = 75 * 39  # BMP pixels per metre when the resolution unit is not known
nodes_edit_image___GRAY_MODES = ("1", "L", "LA", "La", "I", "I;16", "I;16L", "I;16B", "I;16N", "F")
nodes_edit_image___PALETTE_MODES = ("1", "L", "P", "I", "I;16", "I;16L", "I;16B", "I;16N")
nodes_edit_image___ALPHA_MODES = ("RGBA", "RGBa", "LA", "La", "PA")


class nodes_edit_image___ImageError(Exception):
    pass


@nodes_edit_image__dataclass
class nodes_edit_image___Picture:
    """The working picture and the GraphicsMagick image state that changes how it is written."""

    im: nodes_edit_image__Image.Image  # "RGB" or "RGBA"
    source_format: str
    gray: bool  # GraphicsMagick's is_grayscale: a jpeg is written with one channel
    pseudo: bool  # palette or grey source (PseudoClass): GraphicsMagick resizes it with Mitchell
    units: str | None  # "inch", "cm" or None, with x_res/y_res as GraphicsMagick reads them
    x_res: float = 72.0
    y_res: float = 72.0
    gamma: float = 0.0
    intent: int = 0  # GraphicsMagick RenderingIntent (PNG sRGB intent + 1)
    chroma: tuple[float, ...] | None = None  # (wx, wy, rx, ry, gx, gy, bx, by)
    icc: bytes | None = None
    exif: bytes | None = None

    @property
    def matte(self) -> bool:
        return self.im.mode == "RGBA"


# ---------- reading ----------
def nodes_edit_image___f32(v: float) -> float:
    """A C float literal (GraphicsMagick stores 0.6400f etc.) as a double."""
    return nodes_edit_image__struct.unpack("<f", nodes_edit_image__struct.pack("<f", v))[0]


nodes_edit_image___SRGB_CHROMA = tuple(nodes_edit_image___f32(v) for v in (0.3127, 0.3290, 0.6400, 0.3300, 0.3000, 0.6000, 0.1500, 0.0600))


def nodes_edit_image___resolution(fmt: str, data: bytes, info: dict[str, nodes_edit_image__Any]) -> tuple[str | None, float, float]:
    """Resolution as GraphicsMagick's readers set it (default 72, unit unknown)."""
    if fmt == "BMP" and len(data) >= 46 and nodes_edit_image__struct.unpack_from("<I", data, 14)[0] >= 40:
        xp, yp = nodes_edit_image__struct.unpack_from("<ii", data, 38)
        return "cm", xp / 100.0, yp / 100.0
    if fmt == "PNG":
        if "dpi" in info:  # pHYs in pixels per metre; Pillow turned it into dpi
            px, py = (round(float(v) / 0.0254) for v in info["dpi"])
            return "cm", px / 100.0, py / 100.0
        if "aspect" in info:
            ax, ay = info["aspect"]
            return None, float(ax), float(ay)
    if fmt == "JPEG" and "jfif" in info:
        dx, dy = info.get("jfif_density", (1, 1))
        if dx != 1 and dy != 1:
            return {1: "inch", 2: "cm"}.get(int(info.get("jfif_unit", 0))), float(dx), float(dy)
    return None, 72.0, 72.0


def nodes_edit_image___decode(data: bytes) -> nodes_edit_image___Picture:
    try:
        src = nodes_edit_image__Image.open(nodes_edit_image__io.BytesIO(data))
        src.load()
    except (nodes_edit_image__UnidentifiedImageError, OSError, ValueError) as exc:
        raise nodes_edit_image___ImageError(f"The image could not be read ({exc})") from exc
    fmt = src.format or ""
    info = dict(src.info)
    mode = src.mode
    units, xr, yr = nodes_edit_image___resolution(fmt, data, info)
    pic = nodes_edit_image___Picture(im=src, source_format=fmt, gray=mode in nodes_edit_image___GRAY_MODES, pseudo=mode in nodes_edit_image___PALETTE_MODES or fmt == "GIF",
                   units=units, x_res=xr, y_res=yr, icc=info.get("icc_profile") or None)
    if fmt == "PNG":
        if info.get("srgb") is not None:
            pic.intent = int(info["srgb"]) + 1
            pic.gamma, pic.chroma = nodes_edit_image___f32(0.45455), nodes_edit_image___SRGB_CHROMA
        else:
            pic.gamma = float(info.get("gamma") or 0.0)
            if info.get("chromaticity"):
                pic.chroma = tuple(float(v) for v in info["chromaticity"])
    # gm's autoOrient: turn the picture by its EXIF orientation (Pillow drops the tag from the EXIF it keeps).
    im = nodes_edit_image__ImageOps.exif_transpose(src) or src
    exif = im.info.get("exif")
    pic.exif = exif if isinstance(exif, bytes) and exif else None
    if im.mode in ("I", "I;16", "I;16L", "I;16B", "I;16N"):
        im = im.convert("I").point(lambda v: v * (1 / 257)).convert("L")  # 16-bit grey to 8 bits
    matte = im.mode in nodes_edit_image___ALPHA_MODES or "transparency" in im.info
    pic.im = im.convert("RGBA" if matte else "RGB")
    return pic


# ---------- steps ----------
def nodes_edit_image___geometry_size(w: int, h: int, width: float, height: float, flag: str) -> tuple[int, int]:
    """GraphicsMagick GetMagickGeometry for "<width>x<height><flag>" (magick/utility.c)."""
    tw, th = nodes_edit_image__math.floor(width + 0.5), nodes_edit_image__math.floor(height + 0.5)
    if tw <= 0 or th <= 0:
        raise nodes_edit_image___ImageError(f"Invalid resize geometry {width}x{height}{flag}")
    if flag == "@":
        target, area = float(tw * th), float(w * h)
        if target <= 0.25:
            return w, h
        scale = 1.0 / nodes_edit_image__math.sqrt(area / target)
        return max(1, nodes_edit_image__math.floor(w * scale + 0.25)), max(1, nodes_edit_image__math.floor(h * scale + 0.25))
    fw, fh = w, h
    if flag == "%":
        tw, th = nodes_edit_image__math.floor(width * fw / 100.0 + 0.5), nodes_edit_image__math.floor(height * fh / 100.0 + 0.5)
        fw, fh = tw, th
    if flag != "!" and (tw != fw or th != fh):
        sw, sh = tw / fw, th / fh
        scale = (sh if sw < sh else sw) if flag == "^" else (sh if sw > sh else sw)
        tw, th = max(1, nodes_edit_image__math.floor(scale * fw + 0.5)), max(1, nodes_edit_image__math.floor(scale * fh + 0.5))
    if flag == ">":
        tw, th = min(tw, fw), min(th, fh)
    if flag == "<":
        tw, th = max(tw, fw), max(th, fh)
    return tw, th


def nodes_edit_image___clamp(band: nodes_edit_image__Image.Image) -> nodes_edit_image__Image.Image:
    return nodes_edit_image__ImageMath.lambda_eval(lambda e: e["min"](e["max"](e["x"], 0.0), 255.0), x=band)


def nodes_edit_image___filter_pass(bands: list[nodes_edit_image__Image.Image], size: tuple[int, int], filt: int, matte: bool) -> list[nodes_edit_image__Image.Image]:
    """One GraphicsMagick filter pass (HorizontalFilter or VerticalFilter) on float bands.

    With transparency the colour is weighted by opacity and divided by the summed weight again (normalize, or 1 when
    that is ~0); every pass stores clamped values, as GraphicsMagick does in its Q16 pixels.
    """
    if not matte:
        return [nodes_edit_image___clamp(b.resize(size, filt)) for b in bands]
    *rgb, a = bands
    af = nodes_edit_image__ImageMath.lambda_eval(lambda e: e["a"] / 255.0, a=a)
    prem = [nodes_edit_image__ImageMath.lambda_eval(lambda e: e["c"] * e["w"], c=c, w=af).resize(size, filt) for c in rgb]
    af = af.resize(size, filt)
    den = nodes_edit_image__ImageMath.lambda_eval(lambda e: e["w"] + (abs(e["w"]) <= 1e-12) * (1.0 - e["w"]), w=af)
    rgb = [nodes_edit_image___clamp(nodes_edit_image__ImageMath.lambda_eval(lambda e: e["p"] / e["d"], p=pm, d=den)) for pm in prem]
    return [*rgb, nodes_edit_image___clamp(nodes_edit_image__ImageMath.lambda_eval(lambda e: e["w"] * 255.0, w=af))]


def nodes_edit_image___resize(pic: nodes_edit_image___Picture, width: float, height: float, option: str) -> None:
    im = pic.im
    w, h = im.size
    W, H = nodes_edit_image___geometry_size(w, h, width, height, nodes_edit_image__RESIZE_FLAGS.get(option, "@"))
    if (W, H) == (w, h):
        return  # GraphicsMagick returns a clone: nothing is resampled
    mitchell = pic.pseudo or pic.matte or (W / w) * (H / h) > 1.0
    filt = nodes_edit_image__Image.Resampling.BICUBIC if mitchell else nodes_edit_image__Image.Resampling.LANCZOS
    # GraphicsMagick runs the cheaper pass first, in floating point (Q16) between the passes.
    first = (W, h) if W * (h + H) > H * (w + W) else (w, H)
    bands = [b.convert("F") for b in im.split()]
    bands = nodes_edit_image___filter_pass(nodes_edit_image___filter_pass(bands, first, filt, pic.matte), (W, H), filt, pic.matte)
    pic.im = nodes_edit_image__Image.merge(im.mode, [b.convert("L") for b in bands])
    pic.pseudo = False  # the resized picture is full colour (DirectClass)


def nodes_edit_image___parse_color(value: nodes_edit_image__Any) -> tuple[int, int, int, int]:
    """A colour as GraphicsMagick reads it: in #RRGGBBAA / #RGBA the last part is opacity, not alpha."""
    s = str(value or "").strip()
    if s.lower() in ("", "none", "transparent"):
        return (0, 0, 0, 0)
    if s.startswith("#") and len(s) in (5, 9):
        n = (len(s) - 1) // 4
        r, g, b, o = (int(s[1 + i * n:1 + (i + 1) * n] * (2 if n == 1 else 1), 16) for i in range(4))
        return (r, g, b, 255 - o)
    try:
        c = nodes_edit_image__ImageColor.getrgb(s)
    except ValueError as exc:
        raise nodes_edit_image___ImageError(f"Unrecognized color '{s}'") from exc
    return (c[0], c[1], c[2], c[3] if len(c) > 3 else 255)


def nodes_edit_image___rotate(pic: nodes_edit_image___Picture, degrees: float, background: nodes_edit_image__Any) -> None:
    """GraphicsMagick RotateImage: whole quarter turns (clockwise) first, then the rest up to 45 degrees."""
    angle = degrees - 360.0 * int(degrees / 360)
    if angle < -45.0:
        angle += 360.0
    turns = 0
    while angle > 45.0:
        angle -= 90.0
        turns += 1
    turns %= 4
    if turns:
        quarter = {1: nodes_edit_image__Image.Transpose.ROTATE_270, 2: nodes_edit_image__Image.Transpose.ROTATE_180, 3: nodes_edit_image__Image.Transpose.ROTATE_90}
        pic.im = pic.im.transpose(quarter[turns])
    if nodes_edit_image__math.tan(nodes_edit_image__math.radians(angle) / 2.0) == 0.0 or nodes_edit_image__math.sin(nodes_edit_image__math.radians(angle)) == 0.0:
        return
    fill = nodes_edit_image___parse_color(background)
    if fill[3] < 255 and not pic.matte:
        pic.im = pic.im.convert("RGBA")
    pic.im = pic.im.rotate(-angle, resample=nodes_edit_image__Image.Resampling.BILINEAR, expand=True,
                           fillcolor=fill if pic.matte else fill[:3])
    pic.pseudo = False


# ---------- writing ----------
def nodes_edit_image___is_gray(im: nodes_edit_image__Image.Image) -> bool:
    r, g, b = im.split()[:3]
    return nodes_edit_image__ImageChops.difference(r, g).getbbox() is None and nodes_edit_image__ImageChops.difference(g, b).getbbox() is None


def nodes_edit_image___jfif_density(data: bytes, pic: nodes_edit_image___Picture) -> bytes:
    """Write GraphicsMagick's JFIF density (unit 1 = dpi unless the resolution is per cm; (short) x_res)."""
    if len(data) < 18 or data[2:4] != b"\xff\xe0" or data[6:11] != b"JFIF\x00":
        return data
    if not (0 <= pic.x_res < 32767 and 0 <= pic.y_res < 32767):
        return data[:13] + nodes_edit_image__struct.pack(">BHH", 1, 1, 1) + data[18:]
    unit = 2 if pic.units == "cm" else 1
    return data[:13] + nodes_edit_image__struct.pack(">BHH", unit, int(pic.x_res), int(pic.y_res)) + data[18:]


def nodes_edit_image___bmp_ppm(pic: nodes_edit_image___Picture) -> tuple[int, int]:
    if pic.units == "inch":
        return int(100.0 * pic.x_res / 2.54), int(100.0 * pic.y_res / 2.54)
    if pic.units == "cm":
        return int(100.0 * pic.x_res), int(100.0 * pic.y_res)
    return nodes_edit_image__GM_DEFAULT_PPM, nodes_edit_image__GM_DEFAULT_PPM


nodes_edit_image___BMP_INTENT = {1: 1, 4: 2, 2: 4, 3: 8}  # GraphicsMagick Saturation/Relative/Perceptual/Absolute -> LCS_GM_*


def nodes_edit_image___encode_bmp(pic: nodes_edit_image___Picture) -> bytes:
    """GraphicsMagick's WriteBMPImage (type 4) for a full-colour picture."""
    im = pic.im
    w, h = im.size
    bits = 32 if pic.matte else 24
    stride = ((w * bits + 31) // 32) * 4
    have_color_info = bool(pic.intent or pic.icc or pic.gamma)
    head = 40
    if pic.matte or have_color_info:
        head = 124 if (pic.intent or pic.icc) else 108
    offset = 14 + head
    size = stride * h
    xp, yp = nodes_edit_image___bmp_ppm(pic)
    comp = 3 if pic.matte else 0
    out = bytearray(b"BM" + nodes_edit_image__struct.pack("<III", offset + size, 0, offset))
    out += nodes_edit_image__struct.pack("<IiiHHIIiiII", head, w, h, 1, bits, comp, size, xp, yp, 0, 0)
    if head > 40:
        out += nodes_edit_image__struct.pack("<IIIII", 0x00FF0000, 0x0000FF00, 0x000000FF, 0xFF000000, 1)  # masks, calibrated RGB
        wx, wy, rx, ry, gx, gy, bx, by = pic.chroma or (0.0,) * 8
        k = 0x3FFFFFF
        ends = []
        for x, y in ((rx, ry), (gx, gy), (bx, by)):
            ends += [int(x * k) & 0xFFFFFFFF, int(y * k) & 0xFFFFFFFF, int(1.0 - (x + y) * k) & 0xFFFFFFFF]
        out += nodes_edit_image__struct.pack("<9I", *ends) + nodes_edit_image__struct.pack("<III", 0, 0, 0)  # gamma scale is never written
        if head == 124:
            out += nodes_edit_image__struct.pack("<IIII", nodes_edit_image___BMP_INTENT.get(pic.intent, 0), 0, 0, 0)
    out += im.tobytes("raw", "BGRA" if pic.matte else "BGR", stride, -1)
    return bytes(out)


def nodes_edit_image___encode(pic: nodes_edit_image___Picture, fmt: str, quality: float | None) -> bytes:
    im = pic.im
    buf = nodes_edit_image__io.BytesIO()
    extra: dict[str, nodes_edit_image__Any] = {}
    if pic.icc:
        extra["icc_profile"] = pic.icc
    if fmt == "bmp":
        return nodes_edit_image___encode_bmp(pic)
    if fmt == "jpeg":
        q = nodes_edit_image__GM_DEFAULT_QUALITY if quality is None else int(quality)
        q = max(0, min(100, q))
        if pic.exif:
            extra["exif"] = pic.exif
        out = im.convert("RGB")  # a jpeg has no transparency: GraphicsMagick writes the colour channels as they are
        if pic.gray and nodes_edit_image___is_gray(out):
            out = out.convert("L")
        out.save(buf, "JPEG", quality=q, subsampling=0 if q >= 90 else 2, optimize=True, **extra)
        return nodes_edit_image___jfif_density(buf.getvalue(), pic)
    if fmt == "webp":
        q = nodes_edit_image__GM_DEFAULT_QUALITY if quality is None else int(quality)  # gm keeps the quality as a whole number
        if pic.exif:
            extra["exif"] = pic.exif
        im.save(buf, "WEBP", quality=max(0, min(100, q)), method=4, **extra)
        return buf.getvalue()
    if fmt == "png":
        q = nodes_edit_image__GM_DEFAULT_QUALITY if quality is None else int(quality)
        out = im.convert("LA" if pic.matte else "L") if pic.gray and nodes_edit_image___is_gray(im) else im
        out.save(buf, "PNG", compress_level=max(0, min(9, q // 10)), **extra)
        return buf.getvalue()
    if fmt == "gif":
        im.save(buf, "GIF")
        return buf.getvalue()
    if fmt in ("tiff", "tif"):
        im.save(buf, "TIFF", **extra)
        return buf.getvalue()
    raise nodes_edit_image___ImageError(f"Writing {fmt} is not supported")


nodes_edit_image___SOURCE_FORMATS = {"JPEG": "jpeg", "PNG": "png", "WEBP": "webp", "BMP": "bmp", "GIF": "gif", "TIFF": "tiff"}


def nodes_edit_image__sniff(data: bytes) -> tuple[str, str] | None:
    """(mimeType, extension) the way n8n's file-type package names a new image buffer."""
    if data.startswith(b"\xff\xd8\xff"):
        return "image/jpeg", "jpg"
    if data.startswith(b"\x89PNG\r\n\x1a\n"):
        return "image/png", "png"
    if data[:4] == b"RIFF" and data[8:12] == b"WEBP":
        return "image/webp", "webp"
    if data[:2] == b"BM":
        return "image/bmp", "bmp"
    if data[:6] in (b"GIF87a", b"GIF89a"):
        return "image/gif", "gif"
    if data[:4] in (b"II*\x00", b"MM\x00*"):
        return "image/tiff", "tif"
    return None


def nodes_edit_image__render(data: bytes, steps: list[dict[str, nodes_edit_image__Any]], fmt: str | None, quality: float | None) -> bytes:
    """Run the steps on an image file and write it (in `fmt`, or the source format when none is set)."""
    pic = nodes_edit_image___decode(data)
    for step in steps:
        name = step.get("operation")
        if name == "resize":
            nodes_edit_image___resize(pic, step["width"], step["height"], str(step.get("resizeOption") or "maximumArea"))
        elif name == "rotate":
            nodes_edit_image___rotate(pic, step["rotate"], step.get("backgroundColor"))
    out_fmt = fmt or nodes_edit_image___SOURCE_FORMATS.get(pic.source_format)
    if not out_fmt:
        raise nodes_edit_image___ImageError(f"Writing {pic.source_format or 'this image format'} is not supported")
    return nodes_edit_image___encode(pic, out_fmt, quality)


# ---------- the node ----------
def nodes_edit_image___number(value: nodes_edit_image__Any, name: str) -> float:
    """n8n's parseNumericParameter."""
    if isinstance(value, bool) or not isinstance(value, (int, float, str)) or (isinstance(value, str) and not value.strip()):
        raise engine_executor__NodeError(f'The value of "{name}" must be a number')
    try:
        n = float(value)
    except ValueError as exc:
        raise engine_executor__NodeError(f'The value of "{name}" must be a number') from exc
    if not nodes_edit_image__math.isfinite(n):
        raise engine_executor__NodeError(f'The value of "{name}" must be a number')
    return n


def nodes_edit_image___steps(p: nodes_edit_image__Any, operation: str) -> list[dict[str, nodes_edit_image__Any]]:
    if operation == "multiStep":
        raw = (p.get("operations") or {}).get("operations") or []
    else:
        keys = {"resize": ("width", "height", "resizeOption"), "rotate": ("rotate", "backgroundColor")}.get(operation)
        if keys is None:
            raise engine_executor__NodeError(f"Edit Image operation '{operation}' is not supported by this engine")
        raw = [{"operation": operation, **{k: p.get(k) for k in keys if p.get(k) is not None}}]
    steps: list[dict[str, nodes_edit_image__Any]] = []
    for entry in raw:
        name = (entry or {}).get("operation")
        if not isinstance(name, str) or not name:
            continue  # n8n skips an entry without an operation
        if name not in nodes_edit_image__STEP_DEFAULTS:
            raise engine_executor__NodeError(f"Edit Image step '{name}' is not supported by this engine")
        step = {**nodes_edit_image__STEP_DEFAULTS[name], **{k: v for k, v in entry.items() if v is not None}}
        for key in nodes_edit_image__NUMERIC_PARAMS[name]:
            step[key] = nodes_edit_image___number(step.get(key), key)
        steps.append(step)
    if not raw:
        raise engine_executor__NodeError("Cannot read properties of undefined (reading 'operation')")
    return steps


def nodes_edit_image___source_ref(item: engine_model__Item, key: nodes_edit_image__Any, index: int) -> dict[str, nodes_edit_image__Any]:
    """n8n's assertBinaryData."""
    if not isinstance(key, str):
        raise engine_executor__NodeError("Provided parameter is not a string or binary data object.")
    binary = item.get("binary")
    if binary is None:
        raise engine_executor__NodeError(f"This operation expects the node's input data to contain a binary file '{key}', but none was found [item {index}]",
                        "Make sure that the previous node outputs a binary file")
    ref = binary.get(key)
    if ref is None:
        raise engine_executor__NodeError(f"The item has no binary field '{key}' [item {index}]",
                        "Check that the parameter where you specified the input binary field name is correct, and that it "
                        "matches a field in the binary input")
    return ref


async def nodes_edit_image___edit_item(ctx: engine_executor__NodeContext, index: int, item: engine_model__Item, p: nodes_edit_image__Any) -> engine_model__Item:
    operation = p.get("operation", "border")
    data_key = p.get("dataPropertyName", "data")
    options = dict(p.get("options") or {})
    dest = options.get("destinationKey") or (data_key if isinstance(data_key, str) else "data")
    steps = nodes_edit_image___steps(p, operation)
    quality = nodes_edit_image___number(options["quality"], "quality") if options.get("quality") is not None else None
    ref = nodes_edit_image___source_ref(item, data_key, index)
    try:
        data = await ctx.services.binaries.get(ref)
    except KeyError as exc:
        raise engine_executor__NodeError(f"The binary data of field '{data_key}' is not available [item {index}]") from exc
    fmt = options.get("format")
    if fmt is not None and fmt not in nodes_edit_image__VALID_FORMATS:
        raise engine_executor__NodeError(f"Invalid image format: {fmt}. Valid formats are: {', '.join(nodes_edit_image__VALID_FORMATS)}")
    try:
        out = await nodes_edit_image__asyncio.to_thread(nodes_edit_image__render, data, steps, fmt, quality)
    except nodes_edit_image___ImageError as exc:
        raise engine_executor__NodeError(str(exc)) from exc
    except Exception as exc:  # anything the image library throws fails the item, as gm errors do in n8n
        raise engine_executor__NodeError(f"The image could not be processed ({exc.__class__.__name__}: {exc})") from exc

    # The binary data of the item: the other fields stay, the destination field is copied and updated.
    binary = dict(item.get("binary") or {})
    entry: dict[str, nodes_edit_image__Any] = nodes_edit_image__copy.deepcopy(binary[dest]) if dest in binary else {"data": "", "mimeType": ""}
    if fmt is not None:
        entry["fileExtension"] = fmt
        entry["mimeType"] = f"image/{fmt}"
        name = entry.get("fileName")
        if isinstance(name, str) and "." in name:
            entry["fileName"] = ".".join(name.split(".")[:-1]) + "." + fmt
    if options.get("fileName") is not None:
        entry["fileName"] = options["fileName"]
    mime, ext = nodes_edit_image__sniff(out) or (entry.get("mimeType") or "application/octet-stream", entry.get("fileExtension"))
    file_name = entry.get("fileName")
    stored = await ctx.services.binaries.put(ctx.execution.id, out, mime, str(file_name) if file_name else None, ext)
    binary[dest] = {**entry, **stored}
    return {"json": item.get("json", {}), "binary": binary, "pairedItem": {"item": index}}


async def nodes_edit_image__edit_image(ctx: engine_executor__NodeContext):
    items = ctx.items
    params = await ctx.params()
    out: list[engine_model__Item] = []
    for index, (item, p) in enumerate(zip(items, params)):
        try:
            out.append(await nodes_edit_image___edit_item(ctx, index, item, p))
        except Exception as exc:  # n8n catches every error of an item
            if not ctx.continue_on_fail:
                raise
            # n8n's error item: the message only; the item's binaries are not passed on.
            out.append({"json": {"error": str(exc) or exc.__class__.__name__}, "pairedItem": {"item": index}})
    return [out]


nodes_edit_image__HANDLERS = {"editImage": nodes_edit_image__edit_image}


# --- src/midas_a7/nodes/llm.py ---
"""LLM vendor nodes: OpenAI (v2.x), Google Gemini (v1.x) and Anthropic (v1), as the A7 flows use them.

Each handler mirrors n8n's @n8n/nodes-langchain vendor node (packages/@n8n/nodes-langchain/nodes/vendors/
OpenAi/v2, GoogleGemini, Anthropic) for the parameters the flows set:
- items run one at a time; with "continue on fail" a failed item becomes {json: {error: message}}
  (actions/router.ts of each vendor), otherwise the node fails;
- with "Simplify Output" off (every A7 node) the item is the provider's raw response, so the readers
  and budget receipts downstream find `output`/`content`/`candidates` and the token counts.
Base URLs can be redirected with OPENAI_BASE_URL, GEMINI_BASE_URL and ANTHROPIC_BASE_URL. An Anthropic key issued at
the organisation level (not scoped to a workspace) is refused with 400 unless ANTHROPIC_WORKSPACE_ID names the workspace.
"""

















nodes_llm__log = nodes_llm__logging.getLogger(__name__)

nodes_llm__OPENAI_BASE = "https://api.openai.com/v1"
nodes_llm__GEMINI_BASE = "https://generativelanguage.googleapis.com"
nodes_llm__ANTHROPIC_BASE = "https://api.anthropic.com"
nodes_llm__ANTHROPIC_HEADERS = {"anthropic-version": "2023-06-01", "anthropic-beta": "files-api-2025-04-14"}
# n8n sets no timeout on these calls; a reasoning model can take minutes for a long answer.
nodes_llm__TIMEOUT = nodes_llm__httpx.Timeout(600.0, connect=30.0)
# Gemini: n8n uploads every image to the Files API first. Inline data gives the same answer with
# fewer calls, so images go inline while the request stays well under the API's 20 MB inline limit
# (base64 adds a third); larger images take n8n's route through the Files API.
nodes_llm__GEMINI_INLINE_LIMIT = 12 * 1024 * 1024
nodes_llm__GEMINI_FILE_POLL_SECONDS = 1.0
nodes_llm__DEFAULT_IMAGE_PROMPT = "What's in this image?"
nodes_llm__JSON_MODE_SYSTEM = {"role": "system", "content": [{"type": "input_text", "text": "You are a helpful assistant designed to output JSON."}]}

# n8n's NodeApiError messages by HTTP status (packages/workflow/src/errors/node-api.error.ts).
nodes_llm__STATUS_MESSAGES = {
    "4XX": "Your request is invalid or could not be processed by the service",
    "400": "Bad request - please check your parameters",
    "401": "Authorization failed - please check your credentials",
    "402": "Payment required - perhaps check your payment details?",
    "403": "Forbidden - perhaps check your credentials?",
    "404": "The resource you are requesting could not be found",
    "405": "Method not allowed - please check you are using the right HTTP method",
    "429": "The service is receiving too many requests from you",
    "5XX": "The service failed to process your request",
    "500": "The service was not able to process your request",
    "502": "Bad gateway - the service failed to handle your request",
    "503": "Service unavailable - try again later or consider setting this node to retry automatically (in the node settings)",
    "504": "Gateway timed out - perhaps try again later?",
}
# ... and for connection failures (packages/workflow/src/errors/abstract/node.error.ts).
nodes_llm__NETWORK_MESSAGES = {
    "ECONNREFUSED": "The service refused the connection - perhaps it is offline",
    "ECONNRESET": "The connection to the server was closed unexpectedly, perhaps it is offline. "
                  "You can retry the request immediately or wait and retry later.",
    "ENOTFOUND": "The connection cannot be established, this usually occurs due to an incorrect host (domain) value",
    "ETIMEDOUT": "The connection timed out, consider setting the 'Retry on Fail' option in the node settings",
}
# OpenAI's router renames these when the node stops on the error (OpenAi/helpers/error-handling.ts).
nodes_llm__OPENAI_ERROR_MESSAGES = {
    "insufficient_quota": 'Insufficient quota detected. <a href="https://docs.n8n.io/integrations/builtin/app-nodes/'
                          'n8n-nodes-langchain.openai/common-issues/#insufficient-quota" target="_blank">Learn more</a> '
                          "about resolving this issue",
    "rate_limit_exceeded": "OpenAI: Rate limit reached",
}

nodes_llm__ItemOperation = nodes_llm__Callable[[engine_executor__NodeContext, engine_executor__Params, engine_model__Item, int], nodes_llm__Awaitable[list[engine_model__Item]]]


class nodes_llm__ApiError(engine_executor__NodeError):
    """A provider answered with an HTTP error. `raise_message` replaces the message when the node stops."""

    def __init__(self, message: str, description: str | None, http_code: str, code: str | None = None):
        super().__init__(message, description, http_code)
        self.code = code
        self.raise_message: str | None = None


# ---------- shared ----------
def nodes_llm___base(env: str, default: str) -> str:
    return (nodes_llm__os.environ.get(env) or default).rstrip("/")


async def nodes_llm___each_item(ctx: engine_executor__NodeContext, operation: nodes_llm__ItemOperation) -> list[list[engine_model__Item]]:
    """The vendor routers: one call per item; with continue-on-fail any failure becomes that item's {error}."""
    items = ctx.items
    if not items:
        return [[]]
    params = await ctx.params()
    out: list[engine_model__Item] = []
    for i, (item, p) in enumerate(zip(items, params)):
        try:
            out.extend(await operation(ctx, p, item, i))
        except Exception as exc:  # n8n catches every error here, not only API errors
            if ctx.continue_on_fail:
                # The item only carries n8n's short message; the provider's own words go to the log.
                nodes_llm__log.warning("%s: item %d failed: %s", ctx.node.name, i, engine_executor__describe_error(exc))
                out.append({"json": {"error": str(exc) or exc.__class__.__name__}})
                continue
            if isinstance(exc, nodes_llm__ApiError) and exc.raise_message:
                raise engine_executor__NodeError(exc.raise_message, exc.description, exc.http_code) from exc
            if isinstance(exc, config__MissingCredential):
                raise engine_executor__NodeError(str(exc)) from exc
            raise
    return [out]


async def nodes_llm___request(ctx: engine_executor__NodeContext, method: str, url: str, headers: dict[str, str], *,
                   json_body: nodes_llm__Any = None, content: bytes | None = None) -> nodes_llm__httpx.Response:
    client, target = ctx.services.route(url)
    try:
        resp = await client.request(method, target, headers=headers, json=json_body, content=content, timeout=nodes_llm__TIMEOUT)
    except nodes_llm__httpx.TimeoutException as exc:
        raise engine_executor__NodeError(nodes_llm__NETWORK_MESSAGES["ETIMEDOUT"]) from exc
    except nodes_llm__httpx.ConnectError as exc:
        text = str(exc)
        unknown_host = any(s in text for s in ("Name or service not known", "nodename nor servname", "getaddrinfo"))
        raise engine_executor__NodeError(nodes_llm__NETWORK_MESSAGES["ENOTFOUND" if unknown_host else "ECONNREFUSED"], text or None) from exc
    except (nodes_llm__httpx.RemoteProtocolError, nodes_llm__httpx.ReadError, nodes_llm__httpx.WriteError) as exc:
        raise engine_executor__NodeError(nodes_llm__NETWORK_MESSAGES["ECONNRESET"], str(exc) or None) from exc
    except nodes_llm__httpx.HTTPError as exc:
        raise engine_executor__NodeError(str(exc) or exc.__class__.__name__) from exc
    if resp.status_code >= 400:
        raise nodes_llm___api_error(resp)
    return resp


def nodes_llm___api_error(resp: nodes_llm__httpx.Response) -> nodes_llm__ApiError:
    """Like NodeApiError: a message from the status code, the provider's own message as description."""
    status = str(resp.status_code)
    message = nodes_llm__STATUS_MESSAGES.get(status) or nodes_llm__STATUS_MESSAGES.get(status[0] + "XX") or f"Request failed with status code {status}"
    description: str | None = None
    code: str | None = None
    try:
        data = resp.json()
    except ValueError:
        data = None
    if isinstance(data, dict):
        err = data.get("error")
        if data.get("message"):
            description = str(data["message"])
        elif isinstance(err, dict) and err.get("message"):
            description = str(err["message"])
        if isinstance(err, dict) and isinstance(err.get("code"), str):
            code = err["code"]
    elif resp.text:
        description = resp.text[:500]
    return nodes_llm__ApiError(message, description if description != message else None, status, code)


def nodes_llm___json(resp: nodes_llm__httpx.Response) -> nodes_llm__Any:
    try:
        return resp.json()
    except ValueError as exc:
        raise engine_executor__NodeError("The service returned a response that is not JSON", resp.text[:200] or None) from exc


def nodes_llm___split(value: nodes_llm__Any, drop_empty: bool = True) -> list[str]:
    if not isinstance(value, str):
        raise engine_executor__NodeError("Provided parameter is not a string or binary data object.")
    parts = [s.strip() for s in value.split(",")]
    return [s for s in parts if s] if drop_empty else parts


def nodes_llm___prompt(p: engine_executor__Params) -> str:
    text = p.get("text", nodes_llm__DEFAULT_IMAGE_PROMPT)
    if not isinstance(text, str) or not text.strip():
        raise engine_executor__NodeError("A non-empty prompt is required.")
    return text


async def nodes_llm___binary(ctx: engine_executor__NodeContext, item: engine_model__Item, i: int, name: str) -> tuple[bytes, str]:
    """Bytes and MIME type of one binary field, failing with n8n's assertBinaryData messages."""
    files = item.get("binary")
    if files is None:
        raise engine_executor__NodeError(f"This operation expects the node's input data to contain a binary file '{name}', "
                        f"but none was found [item {i}]", "Make sure that the previous node outputs a binary file")
    ref = files.get(name)
    if ref is None:
        raise engine_executor__NodeError(f"The item has no binary field '{name}' [item {i}]",
                        "Check that the parameter where you specified the input binary field name is correct, "
                        "and that it matches a field in the binary input")
    try:
        data = await ctx.services.binaries.get(ref)
    except KeyError as exc:
        raise engine_executor__NodeError(f"The file in binary field '{name}' is no longer available [item {i}]") from exc
    return data, ref.get("mimeType") or engine_binary__sniff_mime(data) or "application/octet-stream"


def nodes_llm___b64(data: bytes) -> str:
    return nodes_llm__base64.b64encode(data).decode("ascii")


def nodes_llm___parse_json_param(value: nodes_llm__Any, message: str) -> nodes_llm__Any:
    if not isinstance(value, str):
        return value
    try:
        return nodes_llm__json.loads(value)
    except ValueError as exc:
        raise engine_executor__NodeError(message) from exc


def nodes_llm___first(value: nodes_llm__Any) -> dict[str, nodes_llm__Any]:
    """A single-value fixedCollection entry (stored as an object, or as a one-element list in defaults)."""
    if isinstance(value, list):
        value = value[0] if value else {}
    return value if isinstance(value, dict) else {}


def nodes_llm___drop_empty(d: dict[str, nodes_llm__Any]) -> dict[str, nodes_llm__Any]:
    """removeEmptyProperties from OpenAi/v2/actions/text/helpers/responses.ts (and JSON dropping undefined)."""
    return {k: v for k, v in d.items() if v is not None and v != "" and not (isinstance(v, (dict, list)) and not v)}


def nodes_llm___reject(options: dict[str, nodes_llm__Any], names: tuple[str, ...], node: str) -> None:
    for name in names:
        if options.get(name):
            raise engine_executor__NodeError(f"Option '{name}' of the {node} node is not supported by this engine")


# ---------- OpenAI (v2: Responses API) ----------
async def nodes_llm___openai_post(ctx: engine_executor__NodeContext, path: str, body: dict[str, nodes_llm__Any]) -> nodes_llm__Any:
    key = ctx.services.credentials.api_key("openAiApi")
    try:
        resp = await nodes_llm___request(ctx, "POST", nodes_llm___base("OPENAI_BASE_URL", nodes_llm__OPENAI_BASE) + path, {"Authorization": f"Bearer {key}"},
                              json_body=body)
    except nodes_llm__ApiError as exc:
        exc.raise_message = nodes_llm__OPENAI_ERROR_MESSAGES.get(exc.code or "")
        raise
    data = nodes_llm___json(resp)
    # OpenAi/transport/index.ts turns `error: null` into undefined, so the key is gone from the item.
    if isinstance(data, dict) and "error" in data and data["error"] is None:
        del data["error"]
    return data


def nodes_llm___openai_input(message: dict[str, nodes_llm__Any]) -> dict[str, nodes_llm__Any]:
    """formatInputMessages for text messages (image and file messages are not used by the flows)."""
    if message["type"] != "text":
        raise engine_executor__NodeError(f"Messages of type '{message['type']}' are not supported by this engine")
    role, text = message["role"], message.get("content", "")
    part = {"type": "output_text", "text": text, "annotations": []} if role == "assistant" else {"type": "input_text", "text": text}
    return {"role": role, "content": [part]}


def nodes_llm___openai_text_config(options: dict[str, nodes_llm__Any], body: dict[str, nodes_llm__Any]) -> None:
    """Output Format option. n8n fills the fixedCollection defaults (verbosity 'medium', type '')."""
    text_options = nodes_llm___first((options.get("textFormat") or {}).get("textOptions"))
    kind = text_options.get("type", "")
    config: dict[str, nodes_llm__Any] = {"verbosity": text_options.get("verbosity", "medium")}
    if kind == "json_schema":
        config["format"] = nodes_llm___drop_empty({"type": kind, "name": text_options.get("name", "my_schema"),
                                        "schema": nodes_llm___parse_json_param(text_options.get("schema"), "Failed to parse schema")})
    elif kind == "json_object":
        config["format"] = {"type": kind}
        body["input"] = [nodes_llm__JSON_MODE_SYSTEM, *body["input"]]
    elif kind == "text":
        config["format"] = {"type": kind}
    body["text"] = config


def nodes_llm___decode_json_output(response: dict[str, nodes_llm__Any]) -> None:
    """In JSON modes n8n replaces each output_text text by its parsed value, in place, stopping at the first failure."""
    def strict(c: str) -> nodes_llm__Any:
        raise ValueError(c)  # JSON.parse has no NaN/Infinity

    try:
        for entry in response.get("output") or []:
            if entry.get("type") == "message":
                for part in entry["content"]:
                    if part.get("type") == "output_text":
                        part["text"] = nodes_llm__json.loads(part["text"], parse_constant=strict)
    except (ValueError, TypeError, KeyError, AttributeError):
        pass


async def nodes_llm___openai_response(ctx: engine_executor__NodeContext, p: engine_executor__Params, item: engine_model__Item, i: int) -> list[engine_model__Item]:
    """Text > Message a Model (actions/text/response.operation.ts + helpers/responses.ts)."""
    model = p.rl("modelId", "")
    messages = [{"type": "text", "role": "user", "content": "", **m} for m in (p.get("responses.values") or [])]
    if not any(m["type"] in ("text", None, "") and isinstance(m["content"], str) and m["content"].strip() for m in messages):
        raise engine_executor__NodeError("A non-empty prompt is required.")
    options = p.get("options") or {}
    tools = p.get("builtInTools") or {}
    if tools.get("webSearch") is not None or tools.get("fileSearch") is not None or tools.get("codeInterpreter"):
        raise engine_executor__NodeError("Built-in tools of the OpenAI node are not supported by this engine")
    nodes_llm___reject(options, ("promptConfig",), "OpenAI")
    if nodes_llm___first(((options.get("backgroundMode") or {}).get("values"))).get("enabled"):
        raise engine_executor__NodeError("Background mode of the OpenAI node is not supported by this engine")

    body: dict[str, nodes_llm__Any] = {
        "model": model,
        "input": [nodes_llm___openai_input(m) for m in messages],
        "parallel_tool_calls": options.get("parallelToolCalls", True),
        "store": options.get("store", True),
        "instructions": options.get("instructions"),
        "max_output_tokens": options.get("maxTokens"),
        "previous_response_id": options.get("previousResponseId"),
        "prompt_cache_key": options.get("promptCacheKey"),
        "safety_identifier": options.get("safetyIdentifier"),
        "service_tier": options.get("serviceTier"),
        "temperature": options.get("temperature"),
        "top_p": options.get("topP"),
        "top_logprobs": options.get("topLogprobs"),
        "max_tool_calls": options.get("maxToolCalls"),
        "background": False,
    }
    if "truncation" in options:
        body["truncation"] = "auto" if options["truncation"] else "disabled"
    if options.get("conversationId"):
        body["conversation"] = options["conversationId"]
    if isinstance(options.get("include"), list) and options["include"]:
        body["include"] = options["include"]
    if options.get("metadata"):
        body["metadata"] = nodes_llm___parse_json_param(options["metadata"], "Failed to parse metadata")
    if options.get("reasoning"):
        reasoning = nodes_llm___first((options["reasoning"] or {}).get("reasoningOptions"))
        summary = reasoning.get("summary", "auto")
        body["reasoning"] = nodes_llm___drop_empty({"effort": reasoning.get("effort", "medium"), "summary": summary if summary != "none" else None})
    if options.get("textFormat"):
        nodes_llm___openai_text_config(options, body)
    body = nodes_llm___drop_empty(body)

    response = await nodes_llm___openai_post(ctx, "/responses", body)
    if not response:
        return []
    if isinstance(response, dict) and body.get("text", {}).get("format", {}).get("type") in ("json_object", "json_schema"):
        nodes_llm___decode_json_output(response)
    if p.get("simplify", True):
        return [{"json": {"output": [o for o in response.get("output") or [] if o.get("type") == "message"]}}]
    return [{"json": response}]


async def nodes_llm___openai_analyze(ctx: engine_executor__NodeContext, p: engine_executor__Params, item: engine_model__Item, i: int) -> list[engine_model__Item]:
    """Image > Analyze Image (actions/image/analyze.operation.ts): the Responses API, prompt first, then images."""
    model = p.rl("modelId", "gpt-4o")
    text = nodes_llm___prompt(p)
    options = p.get("options") or {}
    detail = options.get("detail") or "auto"
    content: list[dict[str, nodes_llm__Any]] = [{"type": "input_text", "text": text}]
    if p.get("inputType", "url") == "url":
        for url in nodes_llm___split(p.get("imageUrls", ""), drop_empty=False):
            content.append({"type": "input_image", "detail": detail, "image_url": url})
    else:
        for name in nodes_llm___split(p.get("binaryPropertyName", "data"), drop_empty=False):
            data, mime = await nodes_llm___binary(ctx, item, i, name)
            content.append({"type": "input_image", "detail": detail, "image_url": f"data:{mime};base64,{nodes_llm___b64(data)}"})
    body = {"model": model, "input": [{"role": "user", "content": content}], "max_output_tokens": options.get("maxTokens") or 300}
    response = await nodes_llm___openai_post(ctx, "/responses", body)
    return [{"json": response.get("output") if p.get("simplify", True) else response}]


async def nodes_llm__open_ai(ctx: engine_executor__NodeContext):
    if ctx.node.type_version < 2:
        raise engine_executor__NodeError("OpenAI node versions before 2 are not supported by this engine")
    resource = ctx.node.parameters.get("resource", "text")
    operation = ctx.node.parameters.get("operation", {"text": "response", "image": "generate"}.get(resource))
    ops: dict[tuple[str, nodes_llm__Any], nodes_llm__ItemOperation] = {("text", "response"): nodes_llm___openai_response, ("image", "analyze"): nodes_llm___openai_analyze}
    if (resource, operation) not in ops:
        raise engine_executor__NodeError(f"OpenAI {resource} / {operation} is not supported by this engine")
    return await nodes_llm___each_item(ctx, ops[(resource, operation)])


# ---------- Google Gemini ----------
async def nodes_llm___gemini_upload(ctx: engine_executor__NodeContext, base: str, key: str, data: bytes, mime: str) -> dict[str, str]:
    """helpers/utils.ts uploadFile: resumable upload to the Files API, then wait until the file is ACTIVE."""
    start = await nodes_llm___request(ctx, "POST", f"{base}/upload/v1beta/files", {
        "x-goog-api-key": key, "X-Goog-Upload-Protocol": "resumable", "X-Goog-Upload-Command": "start",
        "X-Goog-Upload-Header-Content-Length": str(len(data)), "X-Goog-Upload-Header-Content-Type": mime,
        "Content-Type": "application/json"})
    upload_url = start.headers.get("x-goog-upload-url")
    if not upload_url:
        raise engine_executor__NodeError("Failed to get upload URL", "Error uploading file")
    done = await nodes_llm___request(ctx, "POST", upload_url, {"X-Goog-Upload-Offset": "0", "X-Goog-Upload-Command": "upload, finalize"},
                          content=data)
    file = (nodes_llm___json(done) or {}).get("file") or {}
    while file.get("state") not in ("ACTIVE", "FAILED"):
        await nodes_llm__asyncio.sleep(nodes_llm__GEMINI_FILE_POLL_SECONDS)
        file = nodes_llm___json(await nodes_llm___request(ctx, "GET", f"{base}/v1beta/{file.get('name')}", {"x-goog-api-key": key})) or {}
    if file["state"] == "FAILED":
        raise engine_executor__NodeError((file.get("error") or {}).get("message") or "Unknown error", "Error uploading file")
    return {"fileUri": file.get("uri", ""), "mimeType": file.get("mimeType", mime)}


async def nodes_llm___gemini_analyze(ctx: engine_executor__NodeContext, p: engine_executor__Params, item: engine_model__Item, i: int) -> list[engine_model__Item]:
    """Image > Analyze Image (helpers/baseAnalyze.ts): images first, then the prompt, in one user turn."""
    model = p.rl("modelId", "")
    text = nodes_llm___prompt(p)
    options = p.get("options") or {}
    max_tokens = options.get("maxOutputTokens")
    if max_tokens is not None and (isinstance(max_tokens, bool) or not isinstance(max_tokens, (int, float))):
        raise engine_executor__NodeError("Parameter 'maxOutputTokens' must be a number")
    # Not an n8n option: set by a flow patch (tools/n8n_to_flow.py, NODE_PATCHES) to ask for less thinking.
    thinking = str(options.get("thinkingLevel") or "").strip()
    if p.get("inputType", "url") == "url":
        raise engine_executor__NodeError("Gemini image analysis from URLs is not supported by this engine; use binary input")
    files = [await nodes_llm___binary(ctx, item, i, name) for name in nodes_llm___split(p.get("binaryPropertyName", "data"))]
    key = ctx.services.credentials.api_key("googlePalmApi")
    base = nodes_llm___base("GEMINI_BASE_URL", nodes_llm__GEMINI_BASE)
    if sum(len(data) for data, _ in files) <= nodes_llm__GEMINI_INLINE_LIMIT:
        parts: list[dict[str, nodes_llm__Any]] = [{"inlineData": {"mimeType": mime, "data": nodes_llm___b64(data)}} for data, mime in files]
    else:
        parts = [{"fileData": await nodes_llm___gemini_upload(ctx, base, key, data, mime)} for data, mime in files]
    parts.append({"text": text})
    config: dict[str, nodes_llm__Any] = {} if max_tokens is None else {"maxOutputTokens": max_tokens}
    if thinking:
        config["thinkingConfig"] = {"thinkingLevel": thinking}
    body = {"contents": [{"role": "user", "parts": parts}], "generationConfig": config}
    # n8n sends the key as ?key=; the header is equivalent and keeps the key out of logged URLs.
    url, headers = f"{base}/v1beta/{model}:generateContent", {"x-goog-api-key": key}
    try:
        resp = await nodes_llm___request(ctx, "POST", url, headers, json_body=body)
    except nodes_llm__ApiError as exc:
        # A model that does not take this thinking level is asked once more with its default, rather than failing
        # over to the paid fallback node.
        if not thinking or exc.http_code != "400" or "thinking" not in (exc.description or "").lower():
            raise
        nodes_llm__log.warning("%s: %s refused thinkingLevel=%s (%s); asked again with the model's default", ctx.node.name, model,
                    thinking, exc.description)
        config.pop("thinkingConfig")
        resp = await nodes_llm___request(ctx, "POST", url, headers, json_body=body)
    response = nodes_llm___json(resp)
    if p.get("simplify", True):
        return [{"json": c} for c in response.get("candidates") or []]
    return [{"json": response}]


async def nodes_llm__google_gemini(ctx: engine_executor__NodeContext):
    resource = ctx.node.parameters.get("resource", "text")
    operation = ctx.node.parameters.get("operation", "generate" if resource == "image" else None)
    if (resource, operation) != ("image", "analyze"):
        raise engine_executor__NodeError(f"Google Gemini {resource} / {operation} is not supported by this engine")
    return await nodes_llm___each_item(ctx, nodes_llm___gemini_analyze)


# ---------- Anthropic ----------
def nodes_llm___anthropic_headers(key: str) -> dict[str, str]:
    """The key and the fixed headers, plus the workspace an organisation-level key must name (ANTHROPIC_WORKSPACE_ID)."""
    headers = {"x-api-key": key, **nodes_llm__ANTHROPIC_HEADERS}
    workspace = nodes_llm__os.environ.get("ANTHROPIC_WORKSPACE_ID", "").strip()
    if workspace:
        headers["anthropic-workspace-id"] = workspace
    return headers


async def nodes_llm___anthropic_post(ctx: engine_executor__NodeContext, key: str, body: dict[str, nodes_llm__Any]) -> nodes_llm__Any:
    url = nodes_llm___base("ANTHROPIC_BASE_URL", nodes_llm__ANTHROPIC_BASE) + "/v1/messages"
    return nodes_llm___json(await nodes_llm___request(ctx, "POST", url, nodes_llm___anthropic_headers(key), json_body=body))


async def nodes_llm___anthropic_analyze(ctx: engine_executor__NodeContext, p: engine_executor__Params, item: engine_model__Item, i: int) -> list[engine_model__Item]:
    """Image > Analyze Image (helpers/baseAnalyze.ts): base64 images first, then the prompt."""
    model = p.rl("modelId", "")
    input_type = p.get("inputType", "url")
    text = nodes_llm___prompt(p)
    options = p.get("options") or {}
    key = ctx.services.credentials.api_key("anthropicApi")
    content: list[dict[str, nodes_llm__Any]] = []
    if input_type == "url":
        prefix = nodes_llm___base("ANTHROPIC_BASE_URL", nodes_llm__ANTHROPIC_BASE) + "/v1/files/"
        for url in nodes_llm___split(p.get("imageUrls", "")):
            source = {"type": "file", "file_id": url[len(prefix):]} if url.startswith(prefix) else {"type": "url", "url": url}
            content.append({"type": "image", "source": source})
    else:
        for name in nodes_llm___split(p.get("binaryPropertyName", "data")):
            data, mime = await nodes_llm___binary(ctx, item, i, name)
            content.append({"type": "image", "source": {"type": "base64", "media_type": mime, "data": nodes_llm___b64(data)}})
    content.append({"type": "text", "text": text})
    max_tokens = options.get("maxTokens")
    body = {"model": model, "max_tokens": 1024 if max_tokens is None else max_tokens, "messages": [{"role": "user", "content": content}]}
    response = await nodes_llm___anthropic_post(ctx, key, body)
    return [{"json": {"content": response.get("content")} if p.get("simplify", True) else response}]


async def nodes_llm___anthropic_message(ctx: engine_executor__NodeContext, p: engine_executor__Params, item: engine_model__Item, i: int) -> list[engine_model__Item]:
    """Text > Message a Model (actions/text/message.operation.ts), without tools or attachments."""
    model = p.rl("modelId", "")
    messages = [{"content": "", "role": "user", **m} for m in (p.get("messages.values") or [])]
    messages = [m for m in messages if not isinstance(m["content"], str) or m["content"].strip()]
    if p.get("addAttachments", False):
        raise engine_executor__NodeError("Attachments of the Anthropic node are not supported by this engine")
    if not messages:
        raise engine_executor__NodeError("A non-empty prompt is required.")
    options = p.get("options") or {}
    nodes_llm___reject(options, ("codeExecution", "webSearch"), "Anthropic")
    key = ctx.services.credentials.api_key("anthropicApi")
    max_tokens = options.get("maxTokens")
    body: dict[str, nodes_llm__Any] = {
        "model": model,
        "messages": messages,
        "tools": [],  # the node has a Tools input; with nothing connected n8n sends an empty list
        "max_tokens": 1024 if max_tokens is None else max_tokens,
        "system": options.get("system"),
        "temperature": options.get("temperature"),
        "top_p": options.get("topP"),
        "top_k": options.get("topK"),
    }
    caching = options.get("promptCaching")
    if caching and caching != "disabled":
        body["cache_control"] = {"type": "ephemeral", "ttl": caching}
    body = {k: v for k, v in body.items() if v is not None}
    # No tools are sent, so the answer never stops for tool_use or pause_turn: one call is the whole exchange.
    response = await nodes_llm___anthropic_post(ctx, key, body)
    extra: dict[str, nodes_llm__Any] = {}
    if options.get("includeMergedResponse"):
        extra["merged_response"] = "".join(str(c.get("text", "")) for c in response.get("content") or [] if c.get("type") == "text")
    if p.get("simplify", True):
        return [{"json": {"content": response.get("content"), **extra}}]
    return [{"json": {**response, **extra}}]


async def nodes_llm__anthropic(ctx: engine_executor__NodeContext):
    resource = ctx.node.parameters.get("resource", "text")
    operation = ctx.node.parameters.get("operation", {"text": "message", "image": "analyze"}.get(resource))
    ops: dict[tuple[str, nodes_llm__Any], nodes_llm__ItemOperation] = {("text", "message"): nodes_llm___anthropic_message, ("image", "analyze"): nodes_llm___anthropic_analyze}
    if (resource, operation) not in ops:
        raise engine_executor__NodeError(f"Anthropic {resource} / {operation} is not supported by this engine")
    return await nodes_llm___each_item(ctx, ops[(resource, operation)])


nodes_llm__HANDLERS = {
    "openAi": nodes_llm__open_ai,
    "googleGemini": nodes_llm__google_gemini,
    "anthropic": nodes_llm__anthropic,
}


# --- src/midas_a7/nodes/claude_reference_resize.py ---
"""Phase 1.6 (FL-10, owner's go 22 Oct 2026): shrink a scene reference photo in code, without AI, before the image call.

The scene request sends every reference inline. When they are above the request size set in 04 Settings (max_inline_mb),
19g Scene references asks the engine, through the Code-node helper `this.helpers.midasResizeReference(ref, longSide)`, to
shrink each reference whose long side is above 2048 px to a 2048 px long side. The Code-node runner has no image library,
so the work is done here, with the same Pillow code the Edit Image node uses (nodes/edit_image.py: EXIF orientation applied
first, GraphicsMagick's Lanczos resize). Nothing is cropped and the aspect ratio is kept; an image already at or below
2048 px is never touched. The result is written as JPEG quality 90 (4:4:4); a picture with transparency is laid on white
first, because a JPEG has none. The ICC colour profile is kept; the other EXIF data is not.
"""











nodes_claude_reference_resize__LONG_SIDE_PX = 2048
nodes_claude_reference_resize__JPEG_QUALITY = 90
nodes_claude_reference_resize__MAX_PIXELS = 50_000_000  # larger files are left as they are (never decoded): one decode must not take the whole service's memory


def nodes_claude_reference_resize___jpeg(pic: nodes_edit_image___Picture, quality: int) -> bytes:
    """JPEG at `quality`, 4:4:4 at 90 and above (as the Edit Image node writes it), with the ICC profile and no other EXIF data.
    Optimised Huffman tables first; a picture whose file would not fit Pillow's buffer for that (very noisy, e.g. a test pattern)
    is written without them."""
    out = pic.im.convert("RGB")
    if pic.gray and nodes_edit_image___is_gray(out):
        out = out.convert("L")
    extra: dict[str, nodes_claude_reference_resize__Any] = {"icc_profile": pic.icc} if pic.icc else {}
    for optimize in (True, False):
        buf = nodes_claude_reference_resize__io.BytesIO()
        try:
            out.save(buf, "JPEG", quality=quality, subsampling=0 if quality >= 90 else 2, optimize=optimize, **extra)
        except OSError:
            if not optimize:
                raise
            continue
        return buf.getvalue()
    raise AssertionError("unreachable")


def nodes_claude_reference_resize__resize_reference(data: bytes, long_side: int = nodes_claude_reference_resize__LONG_SIDE_PX, quality: int = nodes_claude_reference_resize__JPEG_QUALITY) -> dict[str, nodes_claude_reference_resize__Any]:
    """Shrink `data` to `long_side` px on its long side, or say why it was left as it is.

    Returns {"resized": False, "px": [w, h], "bytes": n, "why": ...} when nothing changed, else {"resized": True,
    "from_px", "to_px", "from_bytes", "to_bytes", "sha256", "mime": "image/jpeg", "data": <jpeg bytes>}.
    """
    if long_side < 1:
        raise ValueError("the long side must be at least 1 px")
    try:
        with nodes_claude_reference_resize__Image.open(nodes_claude_reference_resize__io.BytesIO(data)) as probe:  # reads the header only
            w, h = probe.size
    except (OSError, ValueError, nodes_claude_reference_resize__Image.DecompressionBombError) as exc:
        return {"resized": False, "px": None, "bytes": len(data), "why": f"The image could not be read ({exc})"}
    if w * h > nodes_claude_reference_resize__MAX_PIXELS:
        return {"resized": False, "px": [w, h], "bytes": len(data),
                "why": f"it has {w * h} pixels, above the {nodes_claude_reference_resize__MAX_PIXELS} this step decodes"}
    try:
        pic = nodes_edit_image___decode(data)
    except nodes_edit_image___ImageError as exc:
        return {"resized": False, "px": None, "bytes": len(data), "why": str(exc)}
    w, h = pic.im.size
    if max(w, h) <= long_side:
        return {"resized": False, "px": [w, h], "bytes": len(data), "why": f"its long side is {max(w, h)} px, not above {long_side} px"}
    nodes_edit_image___resize(pic, long_side, long_side, "onlyIfLarger")
    if pic.matte:
        flat = nodes_claude_reference_resize__Image.new("RGB", pic.im.size, (255, 255, 255))
        flat.paste(pic.im, mask=pic.im.getchannel("A"))
        pic.im = flat
    out = nodes_claude_reference_resize___jpeg(pic, quality)
    return {"resized": True, "from_px": [w, h], "to_px": list(pic.im.size), "from_bytes": len(data), "to_bytes": len(out),
            "sha256": nodes_claude_reference_resize__hashlib.sha256(out).hexdigest(), "mime": "image/jpeg", "data": out}


# --- src/midas_a7/nodes/__init__.py ---
"""Node handlers by node kind. Each module exports HANDLERS = {kind: async handler}."""







nodes___MODULES = ("core", "http_request", "data_table", "google_drive", "edit_image", "llm")


def nodes__all_handlers() -> dict[str, engine_executor__Handler]:
    handlers: dict[str, engine_executor__Handler] = {}
    for name in nodes___MODULES:
        try:
            mod = nodes__importlib.import_module(f"{__name__}.{name}")
        except ModuleNotFoundError as exc:
            if exc.name == f"{__name__}.{name}":
                continue
            raise
        handlers.update(getattr(mod, "HANDLERS", {}))
    return handlers


# --- src/midas_a7/runtime.py ---
"""Starts, parks and resumes runs, and keeps the saved state of parked runs.

Like the n8n settings of these flows (saveDataSuccessExecution / saveDataErrorExecution = none),
a finished run keeps only its status and, on failure, the failing node and message. A parked run
(waiting for go 1 / go 2) keeps its full state until it continues.
"""

















runtime__log = runtime__logging.getLogger(__name__)

runtime__REDACTED_HEADERS = {"authorization", "x-midas-key", "x-midas-owner-key", "cookie", "proxy-authorization"}


class runtime__Runtime:
    def __init__(self, services: engine_services__Services, executor: engine_executor__Executor, flows: dict[str, engine_model__Flow]):
        self.services = services
        self.executor = executor
        self.flows = flows  # by flow id
        self._tasks: set[runtime__asyncio.Task] = set()
        self._resume_secret = services.settings.resume_secret or runtime__secrets.token_hex(32)
        if not services.settings.resume_secret:
            links = "resume links" if services.settings.file_link_secret else "resume and file links"
            runtime__log.warning("RESUME_SIGNING_SECRET is not set: %s stop working after a restart", links)
        services.extra["signing_secret"] = self._resume_secret
        # File links (BE-6, PR A): signed with FILE_LINK_SECRET once it is set, so rotating either secret leaves the other's
        # links working. Links signed before it was set (with the resume secret) are still accepted.
        file_secret = services.settings.file_link_secret
        services.extra["file_link_secret"] = file_secret or self._resume_secret
        services.extra["file_link_secrets_accepted"] = [file_secret, self._resume_secret] if file_secret else [self._resume_secret]
        for header_name in self._inbound_header_names():
            runtime__REDACTED_HEADERS.add(header_name.lower())

    def _inbound_header_names(self) -> set[str]:

        return {config___env(h_env, default) for h_env, default, _ in config__HEADER_CREDENTIALS.values()}

    # ---------- resume links ----------
    def signature(self, execution_id: str, generation: int = 0) -> str:
        message = f"resume:{execution_id}" if generation == 0 else f"resume:{execution_id}:{generation}"
        return runtime__hmac.new(self._resume_secret.encode(), message.encode(), runtime__hashlib.sha256).hexdigest()

    def resume_url(self, execution_id: str, generation: int = 1) -> str:
        return f"{self.services.settings.public_base_url}/webhook-waiting/{execution_id}?signature={self.signature(execution_id, generation)}"

    def signature_ok(self, execution_id: str, signature: str, generation: int = 0, *, legacy: bool = False) -> bool:
        expected = self.signature(execution_id) if legacy else self.signature(execution_id, generation)
        return runtime__hmac.compare_digest(expected, signature or "")

    # ---------- starting runs ----------
    async def run_trigger(self, flow: engine_model__Flow, trigger: engine_model__NodeDef, items: list[engine_model__Item], wait_for_response: bool,
                          timeout_s: float = 600.0,
                          files: list[tuple[str, bytes, str | None, str | None]] | None = None) -> engine_executor__Response | None:
        """Start a run. `files` (field name, bytes, mime, file name) become the first item's binaries."""
        execution_id = await runtime__asyncio.to_thread(self.services.store.create_execution, flow.id)
        if files:
            binary: dict[str, runtime__Any] = dict(items[0].get("binary") or {})
            for name, data, mime, filename in files:
                binary[name] = await self.services.binaries.put(execution_id, data, mime, filename)
            items = [{**items[0], "binary": binary}, *items[1:]]
        execution = engine_executor__Execution(id=execution_id, flow_id=flow.id)
        execution.resume_url = self.resume_url(execution_id, execution.resume_generation + 1)
        loop = runtime__asyncio.get_running_loop()
        if wait_for_response:
            execution.responder = loop.create_future()
        task = runtime__asyncio.create_task(self._drive(flow, execution, trigger, items))
        self._tasks.add(task)
        task.add_done_callback(self._tasks.discard)
        if not wait_for_response:
            return None
        assert execution.responder is not None
        done, _ = await runtime__asyncio.wait({execution.responder, task}, timeout=timeout_s, return_when=runtime__asyncio.FIRST_COMPLETED)
        if execution.responder in done:
            return execution.responder.result()
        if task in done:
            if execution.status == "error":
                return engine_executor__Response(status=500, body={"code": 0, "message": "Error in workflow"})
            return engine_executor__Response(status=200, body={"message": "Workflow executed successfully"})
        return engine_executor__Response(status=504, body={"message": "Workflow did not respond in time"})

    async def _drive(self, flow: engine_model__Flow, execution: engine_executor__Execution, trigger: engine_model__NodeDef, items: list[engine_model__Item]) -> None:
        try:
            await self.executor.start(flow, execution, trigger, items)
        except Exception as exc:  # engine faults must not leave the run marked as running
            runtime__log.exception("run %s failed in the engine", execution.id)
            execution.status = "error"
            execution.error = {"node": execution.last_node, "message": f"engine error: {exc}"}
            self.executor._fail_responder(execution)
        await self._persist(execution, flow)

    async def _persist(self, execution: engine_executor__Execution, flow: engine_model__Flow | None = None) -> None:
        store = self.services.store
        if execution.status == "waiting":
            wait = execution.wait or {}
            till = runtime__datetime.fromisoformat(wait["till"]) if wait.get("till") else None
            await runtime__asyncio.to_thread(store.save_execution, execution.id, "waiting", execution.to_state(), till, wait.get("kind"))
            return
        error = None
        if execution.status == "error" and execution.error:
            error = {"node": execution.error.get("node"), "message": str(execution.error.get("message"))[:2000]}
            hold = (flow.settings.get("holdOnError") if flow else None) or None
            if hold:
                await self._hold_on_error(flow, execution, hold)
        await runtime__asyncio.to_thread(store.save_execution, execution.id, execution.status, None, None, None, error)
        await runtime__asyncio.to_thread(store.delete_binaries, execution.id)

    # ---------- a run that ends in an error (Phase 1.1, FL-1) ----------
    async def _hold_on_error(self, flow: engine_model__Flow, execution: engine_executor__Execution, setting: dict[str, runtime__Any]) -> None:
        """Record a run that ended in an error as a hold on its row in the runs table the site reads, naming the step.

        Set per flow (settings.holdOnError = {"runsTable": <data table id>}). Only the row this execution wrote (its
        execution_id) is changed: an execution that only read another run's row (a recovery or decision webhook) never
        touches it. A row at an open gate (awaiting_*) or already on hold is left as it is. Nothing is resumed or resent;
        if no row is found or the update fails, the failure is logged and /status still lists it."""
        table = setting.get("runsTable") if isinstance(setting, dict) else None
        if not table:
            return
        store = self.services.store
        node = str((execution.error or {}).get("node") or "an unknown step")
        reason = f"Stopped at {node}: {runtime___short_reason((execution.error or {}).get('message'))}"
        try:
            rows = await runtime__asyncio.to_thread(store.dt_select, table, {"execution_id": str(execution.id)})
            if len(rows) != 1:
                runtime__log.warning("hold on error: %s run rows found, nothing recorded [run %s, %s]", len(rows), execution.id, flow.name)
                return
            row = rows[0]
            status = str(row.get("status") or "")
            if status == "hold" or status.startswith("awaiting_"):  # the flow's own hold, or a gate the owner still decides
                runtime__log.warning("hold on error: run row %s left as %s [run %s, %s]", row["id"], status, execution.id, flow.name)
                return
            trail = runtime___trail_with(row.get("trail"), node, reason)
            await runtime__asyncio.to_thread(store.dt_update, table, [row["id"]], {
                "status": "hold", "hold_reason": reason, "trail": trail,
                "client_question": "A step stopped unexpectedly. Check the run before anything else; nothing is resent automatically."})
            runtime__log.warning("hold on error: run row %s set to hold at %s [run %s, %s]", row["id"], node, execution.id, flow.name)
        except Exception as exc:  # recording the hold must never hide the original failure
            runtime__log.warning("hold on error: the run row could not be updated (%s) [run %s, %s]", exc.__class__.__name__, execution.id, flow.name)

    # ---------- resuming parked runs ----------
    async def resume_from_webhook(self, execution_id: str, item: engine_model__Item) -> tuple[int, dict[str, runtime__Any]]:
        row = await runtime__asyncio.to_thread(self.services.store.load_execution, execution_id)
        if not row:
            return 404, {"code": 404, "message": f"The execution \"{execution_id}\" does not exist."}
        if row["status"] != "waiting" or row.get("wait_kind") != "webhook":
            return 409, {"code": 409, "message": f"The execution \"{execution_id}\" is not waiting."}
        claimed = await runtime__asyncio.to_thread(self.services.store.claim_waiting, execution_id)
        if not claimed:
            return 409, {"code": 409, "message": f"The execution \"{execution_id}\" is not waiting."}
        self._spawn_resume(claimed, [item])
        return 200, {"message": "Workflow was started"}

    async def resume_due(self) -> int:
        """Continue runs whose wait time is over: the Wait node passes its input on (go 1 / go 2 timeouts, long timers)."""
        due = await runtime__asyncio.to_thread(self.services.store.due_waits, runtime__datetime.now(runtime__timezone.utc))
        n = 0
        for execution_id in due:
            claimed = await runtime__asyncio.to_thread(self.services.store.claim_waiting, execution_id)
            if not claimed:
                continue
            state = claimed["state"] or {}
            node = (state.get("wait") or {}).get("node")
            runs = (state.get("run_data") or {}).get(node) or []
            passthrough = ((runs[-1].get("data") or [[]])[0]) if runs else []
            self._spawn_resume(claimed, passthrough)
            n += 1
        return n

    def _spawn_resume(self, row: dict[str, runtime__Any], output: list[engine_model__Item]) -> None:
        state = row["state"]
        flow = self.flows[state["flow_id"]]
        execution = engine_executor__Execution.from_state(state)
        execution.resume_generation += 1
        execution.resume_url = self.resume_url(execution.id, execution.resume_generation + 1)

        async def go() -> None:
            try:
                await self.executor.resume(flow, execution, output)
            except Exception as exc:
                runtime__log.exception("resumed run %s failed in the engine", execution.id)
                execution.status = "error"
                execution.error = {"node": execution.last_node, "message": f"engine error: {exc}"}
            await self._persist(execution, flow)

        task = runtime__asyncio.create_task(go())
        self._tasks.add(task)
        task.add_done_callback(self._tasks.discard)

    async def drain(self, timeout_s: float = 30.0) -> None:
        """Wait until no run is active, including runs started or resumed while waiting."""
        loop = runtime__asyncio.get_running_loop()
        deadline = loop.time() + timeout_s
        while self._tasks:
            remaining = deadline - loop.time()
            if remaining <= 0:
                return
            await runtime__asyncio.wait(set(self._tasks), timeout=remaining)
            await runtime__asyncio.sleep(0)  # let done-callbacks remove finished tasks


def runtime__redact_headers(headers: dict[str, str]) -> dict[str, str]:
    return {k: ("<redacted>" if k.lower() in runtime__REDACTED_HEADERS else v) for k, v in headers.items()}


runtime___LINK = runtime__re.compile(r"https?://\S+", runtime__re.IGNORECASE)
# Credentials that can appear in an error's own words (provider messages, headers), beyond query strings.
runtime___SECRET = runtime__re.compile(r"(?i)\bbearer\s+\S+|\bsk-[\w-]{6,}|\bAIza[\w-]{10,}|\bgh[pousr]_\w{10,}|"
                     r"\b((?:x-[\w-]*key|api[_-]?key|key|token|secret|password|authorization)\s*[:=]\s*)\S+")


def runtime___short_reason(message: runtime__Any) -> str:
    """The first line of an error message, without links or query secrets, cut short for the site."""

    text = str(message or "no reason recorded").strip().splitlines()[0] if str(message or "").strip() else "no reason recorded"
    text = cli___RedactSecrets.redact(runtime___LINK.sub("[link]", text))
    text = runtime___SECRET.sub(lambda m: (m.group(1) or "") + "<redacted>", text)
    return text[:160] + ("…" if len(text) > 160 else "")


def runtime___trail_with(trail: runtime__Any, node: str, reason: str) -> str:
    """The row's trail (a JSON list) with one more entry for the stop; an unreadable trail is replaced by that entry."""
    try:
        entries = runtime__json.loads(trail) if isinstance(trail, str) and trail else (trail or [])
        if not isinstance(entries, list):
            entries = []
    except ValueError:
        entries = []
    step = int(m.group(1)) if (m := runtime__re.search(r"(?:^|·\s*)(\d+)", node)) else 0
    entries.append({"step": step, "name": "Stopped", "note": reason, "at": runtime__datetime.now(runtime__timezone.utc).isoformat(timespec="milliseconds").replace("+00:00", "Z")})
    return runtime__json.dumps(entries, ensure_ascii=False, separators=(",", ":"))


# --- src/midas_a7/app.py ---
"""The web service: the same webhook addresses and contracts the n8n workflows had.

    /webhook/<path>                 every webhook node of every flow (same paths as in n8n)
    /webhook-waiting/<execution>    resume link of a run parked at a Wait node (go 1 / go 2)
    /health                         readiness and which credentials are configured (never values)
"""


























app__log = app__logging.getLogger(__name__)

app__FLOW_PACKAGES = ("a7_main", "owner_bridge", "owner_read", "owner_analysis", "analysis_only", "model_tests", "catalogue_refresh")
app__MAX_BODY_BYTES = 64 * 1024 * 1024

# One-off recovery webhooks of 18 Oct 2026, written for a single n8n run id
# (claude-a7-20261017230527-1i4fxz). That run does not exist in this service's fresh database,
# so they are not exposed. Their nodes stay in the flow untouched; nothing else reaches them.
app__RETIRED_WEBHOOKS = {("POST", "a7/approved-blind-recovery"), ("POST", "a7/approved-package-recovery")}


def app__load_flows() -> dict[str, engine_model__Flow]:
    flows = [engine_model__load_flow(f"midas_a7.flows.{pkg}") for pkg in app__FLOW_PACKAGES]
    return {f.id: f for f in flows}


def app__build_services(settings: config__Settings) -> engine_services__Services:
    store = store__Store(settings.database_url)
    return engine_services__Services(
        settings=settings, store=store, js=engine_jsrunner__JsRunner(), binaries=engine_binary__BinaryStore(store), credentials=config__Credentials(),
        schemas=store__load_schemas(settings.data_tables_path), http=app__httpx.AsyncClient(follow_redirects=False),
    )


def app__webhook_table(flows: dict[str, engine_model__Flow]) -> dict[tuple[str, str], tuple[engine_model__Flow, engine_model__NodeDef]]:
    table: dict[tuple[str, str], tuple[engine_model__Flow, engine_model__NodeDef]] = {}
    for flow in flows.values():
        for node in flow.webhook_nodes():
            method = str(node.parameters.get("httpMethod", "GET")).upper()
            path = str(node.parameters.get("path", "")).strip("/")
            key = (method, path)
            if key in app__RETIRED_WEBHOOKS:
                continue
            if key in table:
                raise RuntimeError(f"webhook {method} {path} is defined twice")
            table[key] = (flow, node)
    return table


async def app__request_item(request: app__Request, path: str) -> tuple[engine_model__Item, list[tuple[str, bytes, str | None, str | None]]]:
    """The item an n8n webhook node outputs, plus the uploaded files (stored once the run has an id)."""
    headers = {k.lower(): v for k, v in request.headers.items()}
    query = dict(request.query_params)
    body: app__Any = {}
    files: list[tuple[str, bytes, str | None, str | None]] = []
    ctype = headers.get("content-type", "")
    if ctype.startswith("multipart/form-data"):
        form = await request.form(max_files=100, max_fields=1000)
        fields: dict[str, app__Any] = {}
        per_name: dict[str, int] = {}
        uploads = [(k, v) for k, v in form.multi_items() if hasattr(v, "read")]
        multi = {k for k, _ in uploads if sum(1 for kk, _ in uploads if kk == k) > 1}
        for key, value in form.multi_items():
            if hasattr(value, "read"):
                name = key[:-2] if key.endswith("[]") else key
                if key in multi:
                    idx = per_name.get(name, 0)
                    per_name[name] = idx + 1
                    name = f"{name}{idx}"
                data = await value.read()
                files.append((name, data, value.content_type, value.filename))
            else:
                if key in fields:
                    prev = fields[key]
                    fields[key] = (prev if isinstance(prev, list) else [prev]) + [value]
                else:
                    fields[key] = value
        body = fields
    else:
        raw = await request.body()
        if raw:
            if "json" in ctype:
                try:
                    body = app__json.loads(raw)
                except app__json.JSONDecodeError:
                    body = {}
            elif ctype.startswith("application/x-www-form-urlencoded"):
                form = await request.form()
                body = {k: v for k, v in form.items()}
    item: engine_model__Item = {"json": {
        "headers": runtime__redact_headers(headers), "params": {}, "query": query, "body": body,
        "webhookUrl": f"{request.app.state.settings.public_base_url}/webhook/{path}", "executionMode": "production",
    }}
    return item, files


def app__check_header_auth(node: engine_model__NodeDef, request: app__Request) -> engine_executor__Response | None:
    if node.parameters.get("authentication", "none") != "headerAuth":
        return None
    cred = (node.credentials.get("httpHeaderAuth") or {}).get("name", "")
    try:
        expected = config__Credentials().header(cred)
    except config__MissingCredential:
        return engine_executor__Response(status=500, body={"code": 500, "message": "No authentication data defined on node!"})
    got = request.headers.get(expected.header)
    if not got or not app__hmac.compare_digest(got.encode(), expected.value.encode()):
        return engine_executor__Response(status=403, body={"code": 403, "message": "Authorization data is wrong!"})
    return None


def app__to_http(resp: engine_executor__Response) -> app__RawResponse:
    headers = dict(resp.headers or {})
    if resp.raw is not None:
        return app__RawResponse(content=resp.raw, status_code=resp.status, headers=headers, media_type=resp.content_type)
    return app__JSONResponse(content=resp.body if resp.body is not None else {}, status_code=resp.status, headers=headers)


# ---------- schedules ----------
app___DAYS = 7


def app__next_weekly(rule: dict[str, app__Any], tz: str, after: app__datetime) -> app__datetime:
    """Next firing of an n8n Schedule rule of field 'weeks' (the only kind the flows use)."""
    zone = app__ZoneInfo(tz)
    local = after.astimezone(zone)
    days = [int(d) for d in rule.get("triggerAtDay") or [0]]
    hour, minute = int(rule.get("triggerAtHour", 0)), int(rule.get("triggerAtMinute", 0))
    for add in range(0, app___DAYS + 1):
        day = (local + app__timedelta(days=add)).replace(hour=hour, minute=minute, second=0, microsecond=0)
        js_dow = (day.weekday() + 1) % 7  # n8n: 0 = Sunday
        if js_dow in days and day > local:
            return day
    return local + app__timedelta(days=app___DAYS)


async def app__scheduler(app: app__FastAPI) -> None:
    runtime: runtime__Runtime = app.state.runtime
    settings: config__Settings = app.state.settings
    next_runs: dict[str, app__datetime] = {}
    while True:
        try:
            await runtime.resume_due()
            if settings.schedules_enabled:
                now = app__datetime.now(app__ZoneInfo("UTC"))
                for flow in runtime.flows.values():
                    tz = flow.settings.get("timezone") or "UTC"
                    for node in flow.trigger_nodes():
                        if node.kind != "scheduleTrigger":
                            continue
                        for idx, rule in enumerate((node.parameters.get("rule") or {}).get("interval") or []):
                            if rule.get("field") != "weeks":
                                continue
                            key = f"{flow.id}:{node.name}:{idx}"
                            due = next_runs.setdefault(key, app__next_weekly(rule, tz, now))
                            if now >= due:
                                next_runs[key] = app__next_weekly(rule, tz, now + app__timedelta(minutes=1))
                                app__log.info("schedule %s fired", key)
                                await runtime.run_trigger(flow, node, [{"json": {"timestamp": now.isoformat()}}], False)
        except app__asyncio.CancelledError:
            raise
        except Exception:
            app__log.exception("scheduler pass failed")
        await app__asyncio.sleep(30)


def app__create_app(settings: config__Settings | None = None, services: engine_services__Services | None = None,
               flows: dict[str, engine_model__Flow] | None = None) -> app__FastAPI:
    settings = settings or config__Settings()
    flows = flows if flows is not None else app__load_flows()
    table = app__webhook_table(flows)

    @app__contextlib.asynccontextmanager
    async def lifespan(app: app__FastAPI):
        svc = services or app__build_services(settings)
        svc.self_http = app__httpx.AsyncClient(transport=app__httpx.ASGITransport(app=app), base_url="http://self.internal", timeout=None)
        executor = engine_executor__Executor(svc, nodes__all_handlers())
        runtime = runtime__Runtime(svc, executor, flows)
        app.state.services = svc
        app.state.runtime = runtime
        interrupted = await app__asyncio.to_thread(svc.store.fail_interrupted)
        if interrupted:
            app__log.warning("%d run(s) were active when the service stopped and are marked crashed", interrupted)
        try:

            seeded = await nodes_data_table__seed_reference_tables(svc)
            if any(seeded.values()):
                app__log.info("reference tables seeded: %s", seeded)
        except ImportError:
            app__log.warning("data-table node not available; reference tables not seeded")
        sched = app__asyncio.create_task(app__scheduler(app))
        try:
            yield
        finally:
            sched.cancel()
            await runtime.drain()
            await svc.self_http.aclose()
            await svc.http.aclose()
            await svc.js.close()

    app = app__FastAPI(title="Midas A7", docs_url=None, redoc_url=None, openapi_url=None, lifespan=lifespan)
    app.state.settings = settings
    app.state.flows = flows

    @app.get("/health")
    async def health() -> dict[str, app__Any]:
        return {
            "status": "ok",
            "flows": {f.name: f.version_id for f in flows.values()},
            "webhooks": sorted(f"{m} {p}" for m, p in table),
            "configured": config__Credentials().configured(),
        }

    @app.get("/status")
    async def status(request: app__Request):
        """Runs by status, active and waiting runs with their age, and the latest failures: how anyone sees a stuck run.

        Authenticated with the bridge secret the owner site already holds (Authorization = A7_BRIDGE_HEADER_VALUE).
        Shows no run state, no request data and no secret; failure messages are redacted and cut short.
        """
        try:
            expected = config__Credentials().header("A7 GPT bridge inbound")
        except config__MissingCredential:
            return app__JSONResponse(status_code=503, content={"code": 503, "message": "The status page needs A7_BRIDGE_HEADER_VALUE."})
        got = request.headers.get(expected.header) or ""
        if not got or not app__hmac.compare_digest(got.encode(), expected.value.encode()):
            return app__JSONResponse(status_code=403, content={"code": 403, "message": "Authorization data is wrong!"})


        svc: engine_services__Services = request.app.state.services
        try:
            summary = await app__asyncio.to_thread(svc.store.run_summary)
        except Exception as exc:  # the database is the first thing a stuck run points to
            app__log.warning("status: database read failed: %s", exc.__class__.__name__)
            return app__JSONResponse(status_code=503, content={"database": "unreachable"})
        names = {f.id: f.name for f in flows.values()}
        at = app__datetime.now(app__timezone.utc)

        def when(dt):
            return None if dt is None else (dt if dt.tzinfo else dt.replace(tzinfo=app__timezone.utc))

        def run(r: dict[str, app__Any]) -> dict[str, app__Any]:
            created, waits = when(r["created_at"]), when(r["wait_till"])
            out: dict[str, app__Any] = {"id": r["id"], "flow": names.get(r["flow_id"], r["flow_id"]), "status": r["status"],
                                   "ageSeconds": int((at - created).total_seconds()) if created else None,
                                   "updatedAt": when(r["updated_at"]).isoformat() if r["updated_at"] else None}
            if r["status"] == "waiting":
                out["waitKind"] = r["wait_kind"]
                out["waitTill"] = waits.isoformat() if waits else None
            if r["error"]:
                err = r["error"] if isinstance(r["error"], dict) else {"message": str(r["error"])}
                out["failedNode"] = err.get("node")
                out["message"] = cli___RedactSecrets.redact(str(err.get("message", "")))[:300]
            return out

        return {"database": "ok", "asOf": at.isoformat(), "counts": summary["counts"],
                **{k: [run(r) for r in summary[k]] for k in ("running", "waiting", "failed")}}

    @app.api_route("/webhook/{path:path}", methods=["GET", "POST", "PUT", "PATCH", "DELETE", "HEAD"])
    async def webhook(path: str, request: app__Request):
        path = path.strip("/")
        hit = table.get((request.method.upper(), path))
        if not hit:
            return app__JSONResponse(status_code=404, content={"code": 404, "message": f"The requested webhook \"{request.method} {path}\" is not registered."})
        flow, node = hit
        denied = app__check_header_auth(node, request)
        if denied:
            return app__to_http(denied)
        length = int(request.headers.get("content-length") or 0)
        if length > app__MAX_BODY_BYTES:
            return app__JSONResponse(status_code=413, content={"code": 413, "message": "Request body is too large"})
        item, files = await app__request_item(request, path)
        runtime: runtime__Runtime = request.app.state.runtime
        wants_response = node.parameters.get("responseMode", "onReceived") == "responseNode"
        resp = await runtime.run_trigger(flow, node, [item], wait_for_response=wants_response, files=files)
        if resp is None:
            return app__JSONResponse(status_code=200, content={"message": "Workflow was started"})
        return app__to_http(resp)

    @app.get("/files/{file_id}/view")
    async def view_file(file_id: str, request: app__Request):
        """A stored image or manifest, by the signed link the flows record as webViewLink."""

        svc: engine_services__Services = request.app.state.services
        sig = request.query_params.get("sig", "")
        if not any(app__hmac.compare_digest(nodes_google_drive__file_signature(secret, file_id), sig) for secret in nodes_google_drive__accepted_secrets(svc)):
            return app__JSONResponse(status_code=404, content={"code": 404, "message": "Not found"})
        row = await app__asyncio.to_thread(svc.store.file_get, file_id)
        if not row or row.get("data") is None:
            return app__JSONResponse(status_code=404, content={"code": 404, "message": "Not found"})
        safe_name = "".join(ch for ch in str(row["name"]) if ch.isalnum() or ch in "._- ")[:150] or "file"
        return app__RawResponse(content=bytes(row["data"]), media_type=row["mime_type"], headers={
            "Content-Disposition": f'inline; filename="{safe_name}"', "Cache-Control": "private, no-store",
            "X-Content-Type-Options": "nosniff", "Referrer-Policy": "no-referrer",
            "Content-Security-Policy": "default-src 'none'; img-src 'self'; style-src 'unsafe-inline'; sandbox"})

    @app.api_route("/webhook-waiting/{execution_id}", methods=["GET", "POST"])
    async def webhook_waiting(execution_id: str, request: app__Request):
        runtime: runtime__Runtime = request.app.state.runtime
        state_row = await app__asyncio.to_thread(runtime.services.store.load_execution, execution_id) if execution_id.isdigit() else None
        state = state_row.get("state") if state_row else None
        generation = state.get("resume_generation", 0) if isinstance(state, dict) else 0
        legacy = isinstance(state, dict) and "resume_generation" not in state
        if not execution_id.isdigit() or not state_row or not runtime.signature_ok(
                execution_id, request.query_params.get("signature", ""), generation + 1, legacy=legacy):
            return app__JSONResponse(status_code=401, content={"code": 401, "message": "Invalid token"})
        item, _ = await app__request_item(request, f"../webhook-waiting/{execution_id}")
        item["json"].pop("webhookUrl", None)
        item["json"].pop("executionMode", None)
        item["json"]["query"] = {k: v for k, v in item["json"]["query"].items() if k != "signature"}
        status, body = await runtime.resume_from_webhook(execution_id, item)
        return app__JSONResponse(status_code=status, content=body)

    return app




# --- src/midas_a7/cli.py ---
"""Command line: serve the API, seed reference tables, run a flow by hand, check the flows.

    midas-a7 serve                      # web service (PORT, default 8080)
    midas-a7 check                      # every node of every flow has a handler
    midas-a7 seed                       # load reference tables into an empty database
    midas-a7 run catalogue_refresh      # run a flow from its manual trigger, wait for it to finish
"""














def cli___check() -> int:



    handlers = nodes__all_handlers()
    missing: dict[str, list[str]] = {}
    for flow in app__load_flows().values():
        for node in flow.nodes.values():
            if node.kind not in handlers:
                missing.setdefault(node.kind, []).append(f"{flow.name} / {node.name}")
    for kind, where in sorted(missing.items()):
        print(f"no handler for '{kind}': {len(where)} node(s), e.g. {where[0]}")
    print("all node types handled" if not missing else f"{len(missing)} node type(s) without a handler")
    return 1 if missing else 0


async def cli___seed() -> int:



    svc = app__build_services(config__Settings())
    try:
        print(cli__json.dumps(await nodes_data_table__seed_reference_tables(svc)))
    finally:
        await svc.http.aclose()
        await svc.js.close()
    return 0


async def cli___run(package: str) -> int:






    svc = app__build_services(config__Settings())
    flow = engine_model__load_flow(f"midas_a7.flows.{package}")
    trigger = next((n for n in flow.trigger_nodes() if n.kind == "manualTrigger"), None)
    if trigger is None:
        print(f"{package} has no manual trigger", file=cli__sys.stderr)
        return 2
    runtime = runtime__Runtime(svc, engine_executor__Executor(svc, nodes__all_handlers()), {flow.id: flow})
    try:
        await runtime.run_trigger(flow, trigger, [{"json": {}}], wait_for_response=False)
        await runtime.drain(timeout_s=3 * 3600)
    finally:
        await svc.http.aclose()
        await svc.js.close()
    return 0


class cli___RedactSecrets(cli__logging.Filter):
    """Query strings carry resume and file-link signatures and, on Google calls, the API key; keep them out of every log line."""

    PATTERN = cli__re.compile(r"([?&](?:signature|sig|key|api_key|apikey|token|access_token)=)[^&\s\"']+", cli__re.IGNORECASE)

    @classmethod
    def redact(cls, text: str) -> str:
        return cls.PATTERN.sub(r"\1<redacted>", text)

    def filter(self, record: cli__logging.LogRecord) -> bool:
        if isinstance(record.msg, str):
            record.msg = self.redact(record.msg)
        if isinstance(record.args, tuple):
            record.args = tuple(self.redact(a) if isinstance(a, str) else a for a in record.args)
        return True


def cli__configure_logging() -> None:
    cli__logging.basicConfig(level=cli__os.environ.get("LOG_LEVEL", "INFO"), format="%(asctime)s %(levelname)s %(name)s: %(message)s")
    # httpx logs every request URL at INFO; Google calls carry the API key in the query (as n8n sends it).
    cli__logging.getLogger("httpx").setLevel(cli__logging.WARNING)
    cli__logging.getLogger("httpcore").setLevel(cli__logging.WARNING)
    redact = cli___RedactSecrets()
    cli__logging.getLogger("uvicorn.access").addFilter(redact)  # uvicorn's loggers do not propagate to the root
    for handler in cli__logging.getLogger().handlers:  # everything the service logs itself
        handler.addFilter(redact)


def cli__main(argv: list[str] | None = None) -> int:
    cli__configure_logging()
    parser = cli__argparse.ArgumentParser(prog="midas-a7")
    sub = parser.add_subparsers(dest="cmd", required=True)
    sub.add_parser("serve")
    sub.add_parser("check")
    sub.add_parser("seed")
    run = sub.add_parser("run")
    run.add_argument("package", help="flow package, e.g. catalogue_refresh")
    args = parser.parse_args(argv)
    if args.cmd == "serve":


        cli__uvicorn.run(app__create_app(), host="0.0.0.0", port=int(cli__os.environ.get("PORT", "8080")), proxy_headers=True,
                    forwarded_allow_ips="*", log_level=cli__os.environ.get("LOG_LEVEL", "info").lower())
        return 0
    if args.cmd == "check":
        return cli___check()
    if args.cmd == "seed":
        return cli__asyncio.run(cli___seed())
    if args.cmd == "run":
        return cli__asyncio.run(cli___run(args.package))
    return 2






